/// Reserved trust_ir custom proof tag used by the LLVM IR importer to carry
/// eligibility-based `ssp` / `sspstrong` function attributes through trust_ir
/// into LIR.
pub const LLVM_STACK_PROTECTOR_FUNCTION_ATTR_TAG: u32 = 0x0053_5350;

/// Reserved trust_ir custom proof tag used by the LLVM IR importer to carry the
/// forced `sspreq` function attribute through trust_ir into LIR.
pub const LLVM_STACK_PROTECTOR_REQUIRED_FUNCTION_ATTR_TAG: u32 = 0x0053_5351;

/// Reserved trust_ir custom proof tag ("LMP") the LLVM IR importer attaches to
/// a BODYLESS EXTERNAL libm declaration (e.g. `asin`) it synthesized while
/// rewriting `llvm.<fn>.f64/.f32` math intrinsics to libm calls.
///
/// The tag is public, producer-constructible report metadata. It cannot by
/// itself authorize call motion or elimination. The adapter keeps the tag
/// stable for importer/report compatibility, but withholds it from
/// `libm_pure_callees` until an importer-issued, module-bound capability can be
/// validated here.
pub const LLVM_LIBM_PURE_FUNCTION_ATTR_TAG: u32 = 0x004C_4D50;

const IMPORTED_STACK_PROTECTOR_BUFFER_BYTES: u32 = 8;

/// Synthetic trust_ir variable namespace for alloca-backed debug locals.
///
/// The narrow #866 bridge only creates provenance-backed source locals for
/// fixed one-element scalar allocas. The low bits carry the LIR stack slot so
/// codegen can seed a whole-function `LocationExpr::Stack` range after frame
/// lowering without guessing from the source name.
const ALLOCA_DEBUG_PROVENANCE_VAR_TAG: u32 = 0x8000_0000;

/// Synthetic trust_ir variable namespace for source-spanned scalar constant values.
///
/// The low bits carry the stable trust_ir instruction ordinal. Codegen resolves
/// that ordinal through the real trust_ir-origin provenance map after O3 and seeds
/// a bounded `LocationExpr::Const` range from the surviving materialization.
const CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG: u32 = 0x4000_0000;

/// Synthetic trust_ir variable namespace for source-spanned scalar value results.
///
/// The low bits carry the stable trust_ir instruction ordinal. Codegen resolves
/// that ordinal through the real trust_ir-origin provenance map after register
/// allocation and seeds a bounded `LocationExpr::Reg` range only when the
/// value's defining vreg remained allocated and unspilled.
const VALUE_DEBUG_PROVENANCE_VAR_TAG: u32 = 0x2000_0000;
const DEBUG_PROVENANCE_VAR_INDEX_MASK: u32 = 0x1fff_ffff;

/// Default personality routine used when a function first acquires
/// exception-handling structure (`Inst::Invoke` / `Inst::LandingPad`).
///
/// trust-ir's structural EH opcodes do not name a personality — it is a
/// property of the language runtime, not the IR. We default to the Itanium C++
/// personality `__gxx_personality_v0`, which the backend EH path validates in
/// `e2e_aarch64_eh_catch` and which links against the system
/// libc++/libc++abi unwinder + `__cxa_*` runtime.
///
/// A Rust frontend (the rustc bridge) that lowers `panic!` / `catch_unwind`
/// SELECTS the Rust personality `rust_eh_personality` instead, by declaring a
/// module function named `RUST_EH_PERSONALITY` (an external, body-less symbol).
/// `eh_personality_for_function_names` detects that declaration and threads the matching
/// personality onto the function's `eh_info` when EH first appears — so the
/// personality stays a property the frontend controls, with no trust-ir IR
/// change and no new public-API plumbing through `translate_module_for_arch`.
///
/// A module that MIXES language runtimes selects per function through the
/// producer provenance trust-ir already carries: a function stamped
/// `Producer::TRust` (the Rust frontend) unwinds under `rust_eh_personality`
/// whatever the module default, and every other function keeps the module
/// default. The object emitters bind each function's compact-unwind entry
/// (and, in DWARF fallback, one CIE per personality) to its own routine.
const DEFAULT_EH_PERSONALITY: &str = "__gxx_personality_v0";

/// The Rust language EH personality symbol. When a module DECLARES a function
/// with this name (the rustc bridge emits it as an external marker for every
/// unwinding Rust function it lowers), the adapter selects it as the EH
/// personality instead of the C++ default. The symbol itself is provided by the
/// Rust runtime (libstd, via the `eh_personality` lang item) at link time.
///
/// NOTE: this is the bare linker NAME (no `_` prefix). The codegen pipeline adds
/// the platform underscore when it relocates the CIE personality pointer
/// (`pipeline.rs`: `format!("_{}", personality)`), yielding the Mach-O symbol
/// `_rust_eh_personality` that libstd defines — exactly as `__gxx_personality_v0`
/// becomes `___gxx_personality_v0` for the C++ path.
const RUST_EH_PERSONALITY: &str = "rust_eh_personality";

/// Every personality name lowering may select
/// ([`eh_personality_for_function_names`]).
pub const EH_PERSONALITY_CANDIDATES: [&str; 2] = [RUST_EH_PERSONALITY, DEFAULT_EH_PERSONALITY];

/// The module-default EH personality of a module whose functions are named
/// `names`: `rust_eh_personality` when any function (a declaration or a
/// definition) has that name, the C++ default `__gxx_personality_v0`
/// otherwise. Every exception-handling function takes this default unless
/// its own provenance overrides it ([`eh_personality_for_function`]). The
/// default is per module, so merging modules can change it (`module_merge`
/// refuses that).
pub fn eh_personality_for_function_names<'a>(
    names: impl IntoIterator<Item = &'a str>,
) -> &'static str {
    if names.into_iter().any(|name| name == RUST_EH_PERSONALITY) {
        RUST_EH_PERSONALITY
    } else {
        DEFAULT_EH_PERSONALITY
    }
}

/// The personality `function`'s own provenance selects, whatever the module
/// default: `rust_eh_personality` for a function stamped `Producer::TRust`
/// (the Rust frontend), `None` otherwise. It depends on the function alone,
/// so it survives a module merge unchanged.
#[must_use]
pub fn eh_personality_override(function: &TrustIrFunction) -> Option<&'static str> {
    (function.producer == Some(Producer::TRust)).then_some(RUST_EH_PERSONALITY)
}

/// The EH personality lowering selects for `function` in a module whose
/// functions are named `names`: its provenance override
/// ([`eh_personality_override`]) when it has one, else the module default
/// ([`eh_personality_for_function_names`]).
pub fn eh_personality_for_function<'a>(
    function: &TrustIrFunction,
    names: impl IntoIterator<Item = &'a str>,
) -> &'static str {
    eh_personality_override(function).unwrap_or_else(|| eh_personality_for_function_names(names))
}

