    fn validate_bool_condition(&self, context: &str, cond: ValueId) -> Result<(), AdapterError> {
        let cond_ty = self
            .lookup_value_ty(cond)
            .ok_or_else(|| AdapterError::UnknownValue(cond.index()))?;
        if cond_ty != Ty::Bool {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} condition {cond:?} must have type Bool, got {cond_ty:?}"
            )));
        }
        Ok(())
    }

    fn validate_select_operands(
        &self,
        ty: &Ty,
        cond: ValueId,
        then_val: ValueId,
        else_val: ValueId,
    ) -> Result<(), AdapterError> {
        let then_ty = self
            .lookup_value_ty(then_val)
            .ok_or_else(|| AdapterError::UnknownValue(then_val.index()))?;
        // Signedness is carried by the consuming opcode, not by the SSA value's
        // type — so a same-width signed/unsigned integer operand selects the same
        // bits as the declared result type (see `validate_binary_operand_tys`,
        // which relaxes the binop operand check identically). Width/shape
        // mismatches still fail closed.
        // Pointer-like carriers (Ptr / Ref / RefMut / PtrConst / PtrMut /
        // Func) are all the same 64-bit address bits — `is_pointer_like_ty`
        // already treats them interchangeably everywhere addresses flow — so
        // selecting between two `Func(_)` references into a `Ptr` result
        // (a dispatch table of named functions) is the address analogue of
        // the integer relaxation above.
        let pointer_like_pair = |operand: &Ty, result: &Ty| {
            Self::is_pointer_like_ty(operand) && Self::is_pointer_like_ty(result)
        };
        if then_ty != *ty
            && !Self::same_width_int_scalar(&then_ty, ty)
            && !pointer_like_pair(&then_ty, ty)
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select then operand type {then_ty:?} does not match result type {ty:?}"
            )));
        }

        let else_ty = self
            .lookup_value_ty(else_val)
            .ok_or_else(|| AdapterError::UnknownValue(else_val.index()))?;
        if else_ty != *ty
            && !Self::same_width_int_scalar(&else_ty, ty)
            && !pointer_like_pair(&else_ty, ty)
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select else operand type {else_ty:?} does not match result type {ty:?}"
            )));
        }

        if Self::is_v16x8_ty(ty) || Self::is_v8x16_ty(ty) {
            return self.validate_narrow_select_condition(ty, cond);
        }

        let cond_ty = self
            .lookup_value_ty(cond)
            .ok_or_else(|| AdapterError::UnknownValue(cond.index()))?;

        if Self::is_v4x32_ty(ty) {
            if !Self::is_v4_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <4 x i32>/<4 x u32> requires canonical logical <4 x bool> condition, got {cond_ty:?}"
                )));
            }
            let is_compare_mask = self.value_is_v4i32_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v4_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <4 x i32>/<4 x u32> condition ValueId({}) must be produced by a <4 x i32> ICmp or canonical logical <4 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        if Self::is_v2x64_ty(ty) {
            if !Self::is_v2_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <2 x i64>/<2 x u64> requires canonical logical <2 x bool> condition, got {cond_ty:?}"
                )));
            }
            let is_compare_mask = self.value_is_v2i64_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v2_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <2 x i64>/<2 x u64> condition ValueId({}) must be produced by a <2 x i64> ICmp or canonical logical <2 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        if matches!(ty, Ty::Vector(_, _)) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select over unsupported vector shape {ty:?}; only 8-, 16-, 32- and 64-bit integer-lane 128-bit vector selects (<16 x i8|u8>, <8 x i16|u16>, <4 x i32|u32>, <2 x i64|u64>) are lowered today"
            )));
        }

        if cond_ty != Ty::Bool {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select scalar condition must be Bool, got {cond_ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_narrow_select_condition(
        &self,
        payload_ty: &Ty,
        cond: ValueId,
    ) -> Result<(), AdapterError> {
        let cond_ty = self
            .lookup_value_ty(cond)
            .ok_or_else(|| AdapterError::UnknownValue(cond.index()))?;

        if Self::is_v16x8_ty(payload_ty) {
            if !Self::is_v16_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <16 x i8>/<16 x u8> requires canonical logical <16 x bool> condition, got {cond_ty:?}"
                )));
            }

            let is_compare_mask = self.value_is_v16i8_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v16_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <16 x i8>/<16 x u8> condition ValueId({}) must be produced by a <16 x i8> ICmp or canonical logical <16 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        if Self::is_v8x16_ty(payload_ty) {
            if !Self::is_v8_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <8 x i16>/<8 x u16> requires canonical logical <8 x bool> condition, got {cond_ty:?}"
                )));
            }

            let is_compare_mask = self.value_is_v8i16_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v8_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <8 x i16>/<8 x u16> condition ValueId({}) must be produced by a <8 x i16> ICmp or canonical logical <8 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        Ok(())
    }

    fn constant_bool_mask_lanes(value: &Constant, lane_count: usize) -> Option<Vec<bool>> {
        let elems = match value {
            Constant::Vector(elems) | Constant::Aggregate(elems) | Constant::Array(elems) => elems,
            _ => return None,
        };
        if elems.len() != lane_count {
            return None;
        }

        elems
            .iter()
            .map(|lane| match lane {
                Constant::Bool(value) => Some(*value),
                Constant::Int(0) => Some(false),
                Constant::Int(1) => Some(true),
                _ => None,
            })
            .collect()
    }

    fn require_v4i32_lane_index(&self, index: ValueId, context: &str) -> Result<u32, AdapterError> {
        let index_ty = self.lookup_value_ty(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3, but index type is unknown"
            ))
        })?;
        if index_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3, got index type {:?}",
                index_ty
            )));
        }

        let lane = self.lookup_const_int(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3"
            ))
        })?;
        if !(0..=3).contains(&lane) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3, got {lane}"
            )));
        }

        Ok(lane as u32)
    }

    fn require_v2i64_lane_index(&self, index: ValueId, context: &str) -> Result<u32, AdapterError> {
        let index_ty = self.lookup_value_ty(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1, but index type is unknown"
            ))
        })?;
        if index_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1, got index type {:?}",
                index_ty
            )));
        }

        let lane = self.lookup_const_int(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1"
            ))
        })?;
        if !(0..=1).contains(&lane) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1, got {lane}"
            )));
        }

        Ok(lane as u32)
    }

    fn trust_ir_ty_is_pointer_carrier(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Ptr
                | Ty::FatPtr(_)
                | Ty::Func(_)
                | Ty::Ref(_)
                | Ty::RefMut(_)
                | Ty::PtrConst(_)
                | Ty::PtrMut(_)
                | Ty::Rc(_)
                | Ty::Closure(_)
        )
    }

    /// True iff `ty` is an in-memory aggregate type (struct, tuple, array,
    /// record, or tagged-union enum).
    ///
    /// A by-value aggregate CALL ARGUMENT is constructed and carried by ADDRESS:
    /// the frontend materializes the aggregate into a fresh `Alloca` and passes
    /// that pointer (a `Ty::Ptr` value), and the call lowering re-types the LIR
    /// argument Value to the aggregate so ISel applies the System V register-pair
    /// / `sret` classification (see `record_aggregate_call_arg_types`). So when a
    /// callee parameter is declared as one of these aggregate types, the matching
    /// argument's trust_ir type is legitimately a pointer carrier rather than the
    /// aggregate type itself; the signature check accepts that carrier.
    fn trust_ir_ty_is_aggregate(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Struct(_) | Ty::Tuple(_) | Ty::Array(_, _) | Ty::Record(_) | Ty::Enum(_)
        )
    }

    /// Whether an actual argument `Ty` satisfies a declared callee parameter `Ty`
    /// at the trust_ir signature-validation level.
    ///
    /// Exact equality is the common case. Two relaxations cover argument values
    /// that are legitimately carried as a single pointer in a GPR but whose
    /// trust_ir type differs nominally from the declared parameter type:
    ///
    /// 1. **By-value aggregate parameter.** The argument is the address of a
    ///    freshly materialized aggregate (a `Ty::Ptr` from an `Alloca`), while
    ///    the parameter is declared as the aggregate itself. See
    ///    `trust_ir_ty_is_aggregate`.
    /// 2. **Reference / raw-pointer parameter.** A `Ref`/`RefMut`/`Ptr*`/etc.
    ///    parameter is an ABI pointer; the matching argument is also a pointer
    ///    carrier whose specific nominal pointer type (e.g. a bare `Ty::Ptr`
    ///    address vs. a typed `Ty::Ref(..)`) may differ. All pointer carriers
    ///    occupy one GPR, so any pointer-carrier argument satisfies a
    ///    pointer-carrier parameter.
    ///
    /// Both relaxations preserve the argument's machine register class: the ABI
    /// classification is driven by the EXPECTED parameter type, seeded on a
    /// call-site-scoped `Copy` temp (`record_aggregate_call_arg_types`), never
    /// by the argument's own ValueId or actual trust_ir type, so accepting
    /// these carriers cannot change codegen.
    /// A scalar-vs-pointer / scalar-vs-aggregate mismatch (a genuine width/class
    /// error) is still rejected.
    fn call_arg_ty_satisfies_param(actual_ty: &Ty, expected_ty: &Ty) -> bool {
        if actual_ty == expected_ty {
            return true;
        }
        if Self::trust_ir_ty_is_pointer_carrier(actual_ty) {
            return Self::trust_ir_ty_is_aggregate(expected_ty)
                || Self::trust_ir_ty_is_pointer_carrier(expected_ty);
        }
        false
    }

    fn push_unique_value_id(values: &mut Vec<ValueId>, vid: ValueId) {
        if !values.contains(&vid) {
            values.push(vid);
        }
    }

    fn value_is_pointer_carrier(&self, vid: ValueId) -> bool {
        self.lookup_value_ty(vid)
            .is_some_and(|ty| Self::trust_ir_ty_is_pointer_carrier(&ty))
    }

    fn exact_in_bounds_bound(&self, node: &InstrNode) -> Option<Result<u64, ProofDropDiagnostic>> {
        if !node
            .proofs
            .iter()
            .any(|proof| matches!(proof, ProofAnnotation::InBounds))
        {
            return None;
        }

        let bound = match &node.inst {
            Inst::GEP { base, indices, .. } if indices.len() == 1 => {
                self.known_array_bound_for_value(*base)?
            }
            Inst::ExtractElement { array, .. } | Inst::InsertElement { array, .. } => {
                self.known_array_bound_for_value(*array)?
            }
            _ => return None,
        };

        // O0/O1 must be safe when the proof-only guard survives. The late carrier
        // expander materializes the bound into the runtime check, so the maximum
        // bound we may emit is per-target (the arch-aware cap): AArch64 uses
        // `CMP #imm12` (12-bit), x86 can carry any i64 via `MOV r64,imm64 ; CMP`,
        // and RISC-V reconstructs any 32-bit value via `LUI+ADDI`. A larger bound
        // intentionally fails closed with a diagnostic instead of emitting a
        // misencoded check. Defaulting to AArch64 keeps existing callers unchanged.
        let max_bound = self.guard_carrier_arch.max_exact_bound();
        if bound <= max_bound {
            Some(Ok(bound))
        } else {
            Some(Err(ProofDropDiagnostic::with_payload(
                "InBounds",
                format!("bound={bound}"),
                ProofDropCode::Unrepresentable,
                "exact InBounds guard bound exceeds the target's CMP immediate carrier range",
            )))
        }
    }

    fn known_array_bound_for_value(&self, vid: ValueId) -> Option<u64> {
        self.lookup_value_ty(vid)
            .as_ref()
            .and_then(Self::array_bound_from_ty)
    }

    fn array_bound_from_ty(ty: &Ty) -> Option<u64> {
        match ty {
            Ty::Array(_, len) => Some(*len),
            _ => None,
        }
    }

    fn record_exact_in_bounds_proof(&mut self, base: Value, index: Value, bound: u64) {
        self.proof_ctx
            .value_proofs
            .entry(index)
            .or_default()
            .push(Proof::ExactInBounds { base, index, bound });
    }

    /// The discharged-obligation id a node binds to its guard, from a `ProofAnnotation::ProofRef`,
    /// if the producer supplied one. The kernel keeps the guard when this is `None` (fail-safe).
    fn node_obligation_id(node: &InstrNode) -> Option<u64> {
        node.proofs.iter().find_map(|proof| match proof {
            ProofAnnotation::ProofRef(id) => Some(u64::from(id.index())),
            _ => None,
        })
    }

    /// Preserve the historical synthetic-discharge machinery only for this crate's structural
    /// kernel-model tests.  Non-test builds never manufacture authority from a proof label.
    fn node_obligation_id_or_test_model(&mut self, node: &InstrNode) -> Option<u64> {
        if let Some(id) = Self::node_obligation_id(node) {
            return Some(id);
        }
        #[cfg(test)]
        {
            self.proof_ctx.synthesize_discharged_obligation()
        }
        #[cfg(not(test))]
        {
            None
        }
    }

    /// Decide whether a `Load`/`Store` node carries a genuine `ProofAnnotation::NotNull` and, if so,
    /// the discharged-obligation id to bind to the emitted `GuardNull` carrier.
    ///
    /// Returns:
    ///   * `Some(obligation)` — the node IS proof-annotated `NotNull`, so emit the null guard.  The
    ///     optional id is copied only from an explicit upstream `ProofRef`; a bare label stays
    ///     unbound.
    ///   * `None` — the node is NOT proof-annotated `NotNull`; emit NO null guard.
    ///
    /// A `NotNull` label is producer-owned metadata, not a replay result.  Synthesizing a discharged
    /// obligation from it would turn a publicly constructible label into behavioral authority.
    fn memory_ptr_not_null_obligation(&mut self, node: &InstrNode) -> Option<Option<u64>> {
        if !memory_ptr_has_not_null_proof(node) {
            return None;
        }
        Some(self.node_obligation_id_or_test_model(node))
    }

    /// The discharged-obligation id to bind to a `GuardDivZero` carrier emitted for an integer
    /// division/remainder node that carries a genuine `ProofAnnotation::DivNonZero`.
    ///
    /// Bare `DivNonZero` labels remain unbound; only an explicit `ProofRef` is copied as structural
    /// metadata.  Even that reference is non-authoritative until exact validator replay is wired.
    fn divisor_not_zero_obligation(&mut self, node: &InstrNode) -> Option<u64> {
        self.node_obligation_id_or_test_model(node)
    }

    /// The discharged-obligation id to bind to a `GuardShiftRange` carrier emitted for a shift node
    /// that carries a genuine `ProofAnnotation::ShiftInRange`.
    ///
    /// Bare `ShiftInRange` labels remain unbound; see [`Self::divisor_not_zero_obligation`].
    fn shift_in_range_obligation(&mut self, node: &InstrNode) -> Option<u64> {
        self.node_obligation_id_or_test_model(node)
    }

    /// The discharged-obligation id to bind to a `GuardOverflow` carrier emitted for an
    /// `Inst::Overflow` checked add/sub node that carries a genuine, signedness-matching
    /// `ProofAnnotation::NoOverflow` (signed) or `ProofAnnotation::NoWrap` (unsigned).
    ///
    /// Bare NoOverflow/NoWrap labels remain unbound; see
    /// [`Self::divisor_not_zero_obligation`].
    fn overflow_no_overflow_obligation(&mut self, node: &InstrNode) -> Option<u64> {
        self.node_obligation_id_or_test_model(node)
    }

    /// The trust-ir `ValueId` of the INDEX an exact bounds guard is about.
    ///
    /// Mirrors the node shapes [`Self::exact_in_bounds_bound`] resolves a bound for, so the two
    /// always agree on which value the guard constrains. Anything else yields `None`, which the
    /// lattice reads as "no refinement" and therefore keeps the guard.
    fn exact_in_bounds_index_vid(node: &InstrNode) -> Option<ValueId> {
        match &node.inst {
            Inst::GEP { indices, .. } if indices.len() == 1 => indices.first().copied(),
            Inst::ExtractElement { index, .. } | Inst::InsertElement { index, .. } => Some(*index),
            _ => None,
        }
    }

    /// Require replayed authority for the INDEX value's refinement premise before deciding
    /// whether its predicate entails the guard's exact interval.
    ///
    /// Returns the minted capability, or `None` — in which case the carrier keeps whatever
    /// obligation binding it had (usually none) and expands to a real runtime check.
    ///
    /// Predicate implication alone cannot prove that an external parameter or a load satisfies
    /// the predicate. The source minter consults TrustIR's replayed-authority gate and currently
    /// rejects every premise because trust-cg has no RefinementType rechecker.
    fn certify_bounds_guard_from_refinement(
        &mut self,
        node: &InstrNode,
        bound: u64,
        base: Value,
        index: Value,
    ) -> Option<LatticeBoundsCapability> {
        let index_vid = Self::exact_in_bounds_index_vid(node)?;
        let pred = self.refinement_pred_of(index_vid)?;
        let module = self.module?;
        let function = &self.trust_ir_func?.name;
        // Build the env lazily from the module rather than from `proof_ctx.refinement_env`:
        // that field is populated at the END of `translate`, and this runs mid-translation.
        let env = RefinementEnv::from_module(module);
        let capability = lattice_guard::certify_bounds_guard_for_source_carrier(
            module, pred, bound, function, base, index,
        )?;
        // Belt and braces: a capability that does not replay against the very env it was minted
        // from is a bug in the minter, not an authorization. Refuse it.
        if !capability.replay(&env) {
            return None;
        }
        Some(capability)
    }

    fn append_exact_in_bounds_guard(
        &mut self,
        node: &InstrNode,
        base: Value,
        index: Value,
        instrs: &mut Vec<Instruction>,
    ) {
        match self.exact_in_bounds_bound(node) {
            Some(Ok(bound)) => {
                self.record_exact_in_bounds_proof(base, index, bound);
                // Copy only an explicit upstream ProofRef as structural metadata.  The public
                // InBounds label is not replay authority and never synthesizes a discharged id.
                let label_obligation = self.node_obligation_id_or_test_model(node);
                // A refinement needs replayed authority for its value/predicate premise as well
                // as the exact implication. Until a rechecker exists, the minter returns None
                // and the original label remains structural metadata on a real runtime guard.
                let obligation =
                    match self.certify_bounds_guard_from_refinement(node, bound, base, index) {
                        Some(capability) => {
                            let id = capability.obligation_id();
                            self.proof_ctx.lattice_bounds_capabilities.push(capability);
                            Some(id)
                        }
                        None => label_obligation,
                    };
                instrs.push(Instruction {
                    opcode: Opcode::GuardBoundsCheck { bound, obligation },
                    args: vec![base, index],
                    results: vec![],
                });
            }
            Some(Err(diagnostic)) => self.proof_ctx.diagnostics.push(diagnostic),
            None => {}
        }
    }

    /// OPT-6a — recognize the FRONTEND BOUNDS-CHECK PROBE and resolve its exact
    /// carrier parameters.
    ///
    /// The probe is the rustc-bridge's route into the verified Certified-
    /// Elimination Kernel for a MIR `Assert(BoundsCheck)` whose array length is
    /// a compile-time constant: an `Inst::ICmp { op: Ult, lhs: index, rhs }`
    /// node carrying `ProofAnnotation::InBounds`, where `rhs` is defined by a
    /// plain integer `Inst::Const` (the exact bound). The frontend REPLACES its
    /// eager compare+branch bounds check with this probe, trusting the adapter
    /// to emit a `GuardBoundsCheck` carrier with IDENTICAL trap semantics
    /// (`trap iff !(index <u bound)`), so recognition is a TOTAL, fail-closed
    /// contract:
    ///
    /// * `None` — the node is NOT a probe (no `InBounds` annotation): translate
    ///   as a plain compare, exactly as before.
    /// * `Some(Ok((bound, obligation)))` — emit the carrier alongside the
    ///   compare. `obligation` comes ONLY from an explicit
    ///   `ProofAnnotation::ProofRef` naming a genuine module `ProofObligation`;
    ///   a probe WITHOUT a `ProofRef` yields `obligation: None`, so the kernel
    ///   KEEPS the guard and the pipeline expands it into the real runtime
    ///   check.
    /// * `Some(Err(_))` — the node claims to be a probe but the bound cannot be
    ///   resolved (wrong compare op, vector type, non-constant bound, negative
    ///   bound, or a bound above the target carrier cap): FAIL THE COMPILE
    ///   CLOSED. The frontend already dropped its own compare+branch on the
    ///   promise of a carrier, so silently skipping would DELETE a bounds check
    ///   (the intercept shape-drift miscompile class); an error is the only
    ///   sound answer.
    ///
    /// SOUNDNESS (OPT-6a reviewer-mandated): this frontend-origin channel is
    /// NEVER dischargeable via
    /// [`ProofContext::synthesize_discharged_obligation`]. The synthesized-
    /// `Discharged` doctrine ("InBounds IS the upstream safety proof") is
    /// earned only by producers whose `InBounds` annotation is itself a proof
    /// (the LLVM importer's `getelementptr inbounds` on an array-typed base);
    /// the bridge attaches `InBounds` from its own compile-time reasoning,
    /// which is exactly the claim the kernel exists to CHECK against solver-
    /// discharged evidence, not to trust. An unproven probe therefore keeps
    /// its guard — the refutation tests in
    /// `trust-cg-codegen/tests/guard_bounds_probe_x86.rs` pin this.
    fn frontend_bounds_probe(
        &self,
        node: &InstrNode,
    ) -> Option<Result<(BoundsProbeBound, Option<u64>), AdapterError>> {
        let Inst::ICmp { op, ty, rhs, .. } = &node.inst else {
            return None;
        };
        if !node
            .proofs
            .iter()
            .any(|p| matches!(p, ProofAnnotation::InBounds))
        {
            return None;
        }
        if !matches!(op, ICmpOp::Ult) {
            return Some(Err(AdapterError::UnsupportedInstruction(format!(
                "frontend bounds probe (InBounds-annotated ICmp) must be an unsigned \
                 less-than compare, got ICmp::{op:?}; refusing to drop the carrier \
                 for a bounds check the frontend already elided"
            ))));
        }
        if matches!(ty, Ty::Vector(_, _)) {
            return Some(Err(AdapterError::UnsupportedInstruction(
                "frontend bounds probe (InBounds-annotated ICmp) must be a scalar \
                 compare, got a vector type"
                    .to_string(),
            )));
        }
        let Some(&bound_raw) = self.int_const_values.get(rhs) else {
            // DYNAMIC bound: the length is a runtime value (a heap slice or
            // `Vec`), not an `Inst::Const`. Previously this was a hard error,
            // which is why `while k < v.len() { v[k] }` could never carry a
            // proof-only guard at all and its check stayed frontend control
            // flow. It now yields a Dyn carrier over the SAME trap semantics —
            // `trap iff !(index <u len)` — with the length in a register.
            //
            // This is still fail-safe: an un-discharged obligation keeps the
            // guard exactly as the constant case does. What changes is only
            // that the check becomes VISIBLE to the kernel instead of invisible.
            return Some(Ok((
                BoundsProbeBound::Dyn(*rhs),
                Self::node_obligation_id(node),
            )));
        };
        if bound_raw < 0 {
            return Some(Err(AdapterError::UnsupportedInstruction(format!(
                "frontend bounds probe bound {bound_raw} is negative"
            ))));
        }
        let bound = match u64::try_from(bound_raw) {
            Ok(bound) => bound,
            Err(_) => {
                return Some(Err(AdapterError::UnsupportedInstruction(format!(
                    "frontend bounds probe bound {bound_raw} exceeds u64"
                ))));
            }
        };
        // Per-target carrier-expander cap (Sentinel S5): a surviving carrier must
        // be expandable into a real runtime check, so a bound the expander cannot
        // encode fails closed here rather than emitting a misencoded check.
        let max_bound = self.guard_carrier_arch.max_exact_bound();
        if bound > max_bound {
            return Some(Err(AdapterError::UnsupportedInstruction(format!(
                "frontend bounds probe bound {bound} exceeds the target's carrier \
                 immediate cap {max_bound}"
            ))));
        }
        // ProofRef ONLY. Deliberately NOT falling back to
        // `synthesize_discharged_obligation`: an unbound probe carrier stays
        // undischarged, so the kernel keeps the guard (see SOUNDNESS above).
        let obligation = Self::node_obligation_id(node);
        Some(Ok((BoundsProbeBound::Const(bound), obligation)))
    }

    fn pointer_result_value_ids(&self, node: &InstrNode) -> Vec<ValueId> {
        let mut values = Vec::new();
        for (idx, result) in node.results.iter().copied().enumerate() {
            if self
                .trust_ir_result_type(&node.inst, idx)
                .is_some_and(|ty| Self::trust_ir_ty_is_pointer_carrier(&ty))
            {
                Self::push_unique_value_id(&mut values, result);
            }
        }
        values
    }

    fn pointer_source_value_ids(&self, node: &InstrNode) -> Vec<ValueId> {
        let mut values = Vec::new();
        match &node.inst {
            Inst::Load { ptr, .. }
            | Inst::Store { ptr, .. }
            | Inst::AtomicLoad { ptr, .. }
            | Inst::AtomicStore { ptr, .. }
            | Inst::AtomicRMW { ptr, .. }
            | Inst::CmpXchg { ptr, .. }
            | Inst::Dealloc { ptr } => {
                Self::push_unique_value_id(&mut values, *ptr);
            }
            Inst::Return { values: returned } => {
                for vid in returned.iter().copied() {
                    if self.value_is_pointer_carrier(vid) {
                        Self::push_unique_value_id(&mut values, vid);
                    }
                }
            }
            Inst::Call { args, .. } | Inst::CallIndirect { args, .. } => {
                for vid in args.iter().copied() {
                    if self.value_is_pointer_carrier(vid) {
                        Self::push_unique_value_id(&mut values, vid);
                    }
                }
                if values.is_empty() {
                    values.extend(self.pointer_result_value_ids(node));
                }
            }
            // Operand classification is not permission to lower the boundary
            // as an ordinary call or infer any callee effect. The body floor
            // refuses both constructors before using attached proof facts.
            Inst::CallCannotUnwind { args, .. } => {
                for vid in args.iter().copied() {
                    if self.value_is_pointer_carrier(vid) {
                        Self::push_unique_value_id(&mut values, vid);
                    }
                }
                values.extend(self.pointer_result_value_ids(node));
            }
            Inst::CallIndirectCannotUnwind { callee, args, .. } => {
                if self.value_is_pointer_carrier(*callee) {
                    Self::push_unique_value_id(&mut values, *callee);
                }
                for vid in args.iter().copied() {
                    if self.value_is_pointer_carrier(vid) {
                        Self::push_unique_value_id(&mut values, vid);
                    }
                }
                for vid in self.pointer_result_value_ids(node) {
                    Self::push_unique_value_id(&mut values, vid);
                }
            }
            _ => values.extend(self.pointer_result_value_ids(node)),
        }
        values
    }

    fn value_fact_attachment_value_ids(&self, node: &InstrNode) -> Vec<ValueId> {
        if !node.results.is_empty() {
            return node.results.clone();
        }

        match &node.inst {
            Inst::Store { value, .. } | Inst::AtomicStore { value, .. } => vec![*value],
            Inst::Return { values } => values.clone(),
            _ => Vec::new(),
        }
    }

    fn proof_fact_attachment_value_ids(&self, node: &InstrNode, fact: ProofFact) -> Vec<ValueId> {
        match fact {
            ProofFact::InBounds
            | ProofFact::NoAlias
            | ProofFact::Aligned(_)
            | ProofFact::DataRaceFree
            | ProofFact::ValidDealloc
            | ProofFact::ReadonlyTable
            | ProofFact::AppendOnlyBuffer
            | ProofFact::AtomicSetInsert => self.pointer_source_value_ids(node),
            ProofFact::NoUndef => self.value_fact_attachment_value_ids(node),
            ProofFact::Monotonic
            | ProofFact::NoPanic
            | ProofFact::Deterministic
            | ProofFact::Terminates
            | ProofFact::ParallelMap
            | ProofFact::BoundedLoop(_)
            | ProofFact::DivergenceClass(_) => node.results.clone(),
        }
    }

    fn extend_index_to_i64_if_needed(
        &mut self,
        index_vid: ValueId,
        index_val: Value,
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        let Some(trust_ir_ty) = self.lookup_value_ty(index_vid) else {
            return Ok(index_val);
        };
        let from_ty = self.translate_ty(&trust_ir_ty)?;
        if matches!(from_ty, Type::I64) {
            return Ok(index_val);
        }
        if !matches!(from_ty, Type::B1 | Type::I8 | Type::I16 | Type::I32) {
            return Ok(index_val);
        }

        let extended = self.fresh_value();
        let opcode = if self.repr_ty(&trust_ir_ty)?.is_signed_integer() {
            Opcode::Sextend {
                from_ty,
                to_ty: Type::I64,
            }
        } else {
            Opcode::Uextend {
                from_ty,
                to_ty: Type::I64,
            }
        };
        instrs.push(Instruction {
            opcode,
            args: vec![index_val],
            results: vec![extended],
        });
        self.define_value_type(extended, Type::I64);
        Ok(extended)
    }

    /// TrustIR GEP uses one scale for every index: the authoritative extent
    /// of `pointee_ty`. It never descends into aggregate fields. Keep the
    /// original pointee for every step so `[i, j]` computes
    /// `base + i * sizeof(T) + j * sizeof(T)`, including packed layouts.
    fn translate_multi_index_gep(
        &mut self,
        pointee_ty: &Ty,
        base: ValueId,
        indices: &[ValueId],
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);
        let storage_geometry = self.storage_geometry.resolve(self.module, pointee_ty)?;
        let lir_pointee_ty = if storage_geometry.is_none() {
            Some(self.translate_ty(pointee_ty)?)
        } else {
            None
        };
        let mut instrs = Vec::new();
        let mut current_ptr = self.map_value(base);
        for (idx, index_vid) in indices.iter().copied().enumerate() {
            let next_ptr = self.gep_step_result(idx + 1 == indices.len(), dst);
            let index_val = self.map_gep_index(index_vid, &mut instrs)?;
            if let Some(geometry) = storage_geometry {
                self.emit_byte_stride_ptr(
                    geometry.size_bytes(),
                    current_ptr,
                    index_val,
                    next_ptr,
                    &mut instrs,
                );
            } else {
                self.emit_array_element_ptr(
                    pointee_ty,
                    lir_pointee_ty
                        .as_ref()
                        .expect("ordinary pointee carrier retained"),
                    current_ptr,
                    index_val,
                    next_ptr,
                    &mut instrs,
                )?;
            }
            current_ptr = next_ptr;
        }
        Ok(instrs)
    }

    fn gep_step_result(&mut self, is_final: bool, dst: Value) -> Value {
        if is_final {
            dst
        } else {
            let value = self.fresh_value();
            self.define_value_type(value, Type::I64);
            value
        }
    }

    fn map_gep_index(
        &mut self,
        index_vid: ValueId,
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        let index_val = self.map_value(index_vid);
        self.extend_index_to_i64_if_needed(index_vid, index_val, instrs)
    }

    fn aggregate_field_ty(
        &self,
        aggregate_ty: &Ty,
        field_index: usize,
    ) -> Result<Ty, AdapterError> {
        match aggregate_ty {
            Ty::Struct(sid) => {
                let sdef = self
                    .structs
                    .get(sid.as_usize())
                    .filter(|s| s.id == *sid)
                    .or_else(|| self.structs.iter().find(|s| s.id == *sid))
                    .ok_or_else(|| {
                        AdapterError::UnsupportedType(format!("unknown struct {:?}", sid))
                    })?;
                sdef.fields
                    .get(field_index)
                    .map(|field| field.ty.clone())
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "multi-index GEP struct field {} out of bounds for {:?}",
                            field_index, aggregate_ty
                        ))
                    })
            }
            Ty::Tuple(fields) => fields.get(field_index).cloned().ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "multi-index GEP tuple field {} out of bounds for {:?}",
                    field_index, aggregate_ty
                ))
            }),
            // Every element of an array has the element type; resolve it
            // through the module `types` table the `TyId` indexes.
            Ty::Array(elem_ty_id, len) => {
                if field_index as u64 >= *len {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "multi-index GEP array element {} out of bounds for {:?}",
                        field_index, aggregate_ty
                    )));
                }
                let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
                module
                    .types
                    .get(elem_ty_id.index() as usize)
                    .cloned()
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "array element TyId {:?} not in module types table",
                            elem_ty_id
                        ))
                    })
            }
            // A first-class closure is a struct of its captures (in capture
            // declaration order), so its "field" `Ty` is the capture type at
            // that index — resolved from the module `closure_types` table.
            Ty::Closure(cid) => {
                let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
                let def = module.closure_types.get(cid.as_usize()).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "multi-index GEP: closure id {:?} not found in module closure-type table",
                        cid
                    ))
                })?;
                def.captures.get(field_index).cloned().ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "multi-index GEP closure capture {} out of bounds for {:?}",
                        field_index, aggregate_ty
                    ))
                })
            }
            Ty::Record(rid) => {
                let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
                let def = module
                    .records
                    .get(rid.as_usize())
                    .filter(|def| def.id == *rid)
                    .or_else(|| module.records.iter().find(|def| def.id == *rid))
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "multi-index GEP: record id {:?} not found in module record table",
                            rid
                        ))
                    })?;
                def.fields
                    .get(field_index)
                    .map(|field| field.ty.clone())
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "multi-index GEP record field {} out of bounds for {:?}",
                            field_index, aggregate_ty
                        ))
                    })
            }
            _ => Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP expected struct, tuple, or record type, got {:?}",
                aggregate_ty
            ))),
        }
    }

    fn require_gep_struct_field_index(&self, index_vid: ValueId) -> Result<u32, AdapterError> {
        let Some(index) = self.lookup_const_int(index_vid) else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP struct field index must be a constant, got {:?}",
                index_vid
            )));
        };
        if index < 0 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP struct field index must be non-negative, got {}",
                index
            )));
        }
        u32::try_from(index).map_err(|_| {
            AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP struct field index does not fit u32: {}",
                index
            ))
        })
    }

    /// Resolve the return types for a direct `Call` to the given `FuncId`.
    ///
    /// Looks up the callee function in the module, follows its `FuncTyId`
    /// into `module.func_types`, and translates each `Ty` return to a LIR
    /// `Type`. Returns an empty vec (no type hints) if the callee is not
    /// present in the module (e.g., an imported symbol) — ISel will then
    /// fall back to `value_type()` defaults, matching pre-#381 behavior
    /// for unknown externs.
    fn lookup_callee_return_types(&self, callee: FuncId) -> Vec<Type> {
        self.translate_return_tys(&self.lookup_callee_return_tys(callee))
    }

    fn lookup_callee_return_tys(&self, callee: FuncId) -> Vec<Ty> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let Some(callee_fn) = self.functions.unique(module, callee) else {
            return Vec::new();
        };
        self.lookup_func_type_return_tys(callee_fn.ty)
    }

    /// Validate the explicitly declared ABI fact before using it. Public
    /// adapter entry points do not require every general TrustIR validation
    /// diagnostic to be fatal, so this contract is checked locally too.
    fn lookup_callee_sret_param(
        &self,
        callee: FuncId,
    ) -> Result<Option<crate::function::AbiSretParam>, AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let callee_fn = self.functions.unique(module, callee).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "[TCG-SRET-ABI] cannot resolve callee {} to validate its ABI",
                callee.index()
            ))
        })?;
        let signature = module
            .func_types
            .get(callee_fn.ty.index() as usize)
            .ok_or(AdapterError::InvalidFuncTyId(callee_fn.ty.index()))?;
        validate_sret_declaration(callee_fn, signature)
    }

    /// Record that a DIRECT call to `callee_name` passes a hidden return-buffer
    /// pointer as argument 0, or refuse the call outright when the declaration
    /// is one this pipeline cannot carry to the selector.
    ///
    /// Only a LEADING hidden parameter is expressible: the selector marker is
    /// keyed by callee SYMBOL and says "argument 0 is the buffer". A symbol has
    /// exactly one signature, so name-keying is exact for a direct call — but
    /// it cannot describe a buffer in any other argument position, and refusing
    /// is the only honest answer for one.
    fn record_sret_arg_callee(
        &mut self,
        callee: FuncId,
        callee_name: &str,
    ) -> Result<(), AdapterError> {
        if self.lookup_callee_sret_param(callee)?.is_some() {
            self.sret_arg_callees.insert(callee_name.to_owned());
        }
        Ok(())
    }

    /// Establish, for one `Inst::CallIndirect` edge, whether argument 0 is a
    /// hidden return-buffer (`sret`) pointer, and record the LIR callee value
    /// in `sret_arg_indirect_callees` when it is.
    ///
    /// The pinned trust-ir states `sret` only on a declared `Function`
    /// (`FuncAttrs::params[i].sret`); a `FuncTy` has no attribute slot and the
    /// call instruction carries none. So the only source of this fact is the
    /// callee declaration reached through trust-ir's own typed provenance
    /// analysis (`Const FnDef` through `Copy` / `ReifyFnPointer`, dominance and
    /// carrier-type checked at this exact use). A callee that does not resolve
    /// there (a parameter, a load, a block parameter) has no expressible
    /// hidden-buffer fact, and the edge is lowered as the ordinary call its
    /// signature declares: `Ok(false)`.
    ///
    /// When the declaration DOES carry the attribute, the edge must agree with
    /// it exactly — same signature shape (`validate_sret_declaration` already
    /// pins `Ptr` at index 0 and an empty return list on the declaration side),
    /// same variadic-ness and same calling convention — because the selector
    /// stages argument 0 into X8 and numbers the rest as if it were absent.
    /// Any disagreement is refused with `[TCG-SRET-ABI]` rather than lowered
    /// under whichever side happened to be consulted.
    fn resolve_static_indirect_sret_callee(
        &mut self,
        trust_ir_block: BlockId,
        instruction_index: usize,
        callee: ValueId,
        sig: FuncTyId,
        calling_conv: CallingConv,
    ) -> Result<bool, AdapterError> {
        // The same rejection-only prefilter the devirtualizer uses: a callee
        // whose producer chain visibly never reaches a `Const FnDef` cannot
        // resolve, so functions without static function pointers pay no
        // analysis construction.
        if self.static_call_state.is_none() {
            let (candidate_shape, _) = self.has_static_function_pointer_candidate_shape(callee);
            if !candidate_shape {
                return Ok(false);
            }
            let Some(function) = self.trust_ir_func else {
                return Ok(false);
            };
            self.static_call_state = Some(Box::new(StaticCallFunctionState {
                analysis: StaticFunctionPointerAnalysis::new(function),
            }));
        }
        let Some(resolution) = self.static_call_state.as_ref().and_then(|state| {
            state
                .analysis
                .resolve_typed_at(callee, trust_ir_block, instruction_index)
        }) else {
            return Ok(false);
        };
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        // An unregistered or duplicated FuncId is not a declaration this edge
        // can be checked against; the devirtualizer declines it the same way.
        let Some(target) = self.functions.unique(module, resolution.function()) else {
            return Ok(false);
        };
        let target_sig = module
            .func_types
            .get(target.ty.index() as usize)
            .ok_or(AdapterError::InvalidFuncTyId(target.ty.index()))?;
        if validate_sret_declaration(target, target_sig)?.is_none() {
            return Ok(false);
        }
        let edge_sig = module
            .func_types
            .get(sig.index() as usize)
            .ok_or(AdapterError::InvalidFuncTyId(sig.index()))?;
        let disagreement = if resolution.declared_signature() != target.ty {
            Some(format!(
                "the function-pointer constant declares FuncTyId({}) but the callee is declared with FuncTyId({})",
                resolution.declared_signature().index(),
                target.ty.index()
            ))
        } else if edge_sig != target_sig {
            Some(format!(
                "the call edge's FuncTyId({}) {edge_sig:?} differs from the callee's FuncTyId({}) {target_sig:?}",
                sig.index(),
                target.ty.index()
            ))
        } else if calling_conv != target.calling_conv {
            Some(format!(
                "the call edge declares calling convention {calling_conv:?} but the callee declares {:?}",
                target.calling_conv
            ))
        } else {
            None
        };
        if let Some(disagreement) = disagreement {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "[TCG-SRET-ABI] indirect call resolves to `{}`, whose declaration passes a hidden \
                 return-buffer pointer as argument 0, but {disagreement}; refusing rather than \
                 choosing which side of the edge names the register for that pointer",
                target.name
            )));
        }
        let callee_val = self.map_value(callee);
        self.sret_arg_indirect_callees.insert(callee_val);
        Ok(true)
    }

    fn lookup_callee_func_ty(&self, callee: FuncId) -> Option<&'a trust_ir::FuncTy> {
        let module = self.module?;
        let callee_fn = self.functions.unique(module, callee)?;
        module.func_types.get(callee_fn.ty.index() as usize)
    }

    /// Refuse a `CallIndirect` whose callee pointer visibly names a variadic
    /// function.
    ///
    /// A direct call to a variadic declaration is placed by that
    /// declaration's own fixed prefix (`CallVariadic { fixed_args }`), or
    /// refused when it states none ([`AdapterError::UnsignedVariadicCallee`]).
    /// An indirect edge carries only its own `sig`, and a variadic `sig` is
    /// already refused (`validate_call_indirect_signature`), so an indirect
    /// call that gets this far places every argument by the named-argument
    /// rules. When the pointer names a variadic callee, that placement is
    /// not how the callee reads its anonymous arguments (DarwinPCS stacks
    /// them, x86-64 SysV needs `AL`), and an unsigned `(...)` callee states
    /// no fixed prefix to compare the edge with at all. So the edge is
    /// refused: with `UnsignedVariadicCallee` for an unsigned declaration,
    /// with `[TCG-VARARG-ABI]` for one that states its fixed prefix.
    ///
    /// The walk is refusal-only and bounded by
    /// `STATIC_CALL_PREFILTER_LIMIT`: from the callee it follows `Copy` and
    /// the pointer reinterpretations (`ReifyFnPointer`, `PtrToPtr`,
    /// `PtrToInt`, `IntToPtr`, `Bitcast`, `Transmute`) to a `Const FnDef` or a
    /// zero-addend `Const SymbolAddr` that names a module function. A
    /// pointer that arrives through memory, a block parameter or a select is
    /// not seen; its producer must not type a c-variadic function pointer as
    /// a non-variadic one (Trust's `map_fn_ptr_ty` refuses c-variadic
    /// function-pointer types).
    fn refuse_indirect_call_to_variadic_declaration(
        &self,
        callee: ValueId,
    ) -> Result<(), AdapterError> {
        let Some(module) = self.module else {
            return Ok(());
        };
        let variadic_signature = |function: &'a trust_ir::Function| {
            module
                .func_types
                .get(function.ty.index() as usize)
                .filter(|signature| signature.is_vararg)
                .map(|signature| (function, signature))
        };
        let mut current = callee;
        for _ in 0..STATIC_CALL_PREFILTER_LIMIT {
            let Some(node) = self.find_value_producer(current) else {
                return Ok(());
            };
            let target = match &node.inst {
                Inst::Const {
                    value: Constant::FnDef(function),
                    ..
                } => self
                    .functions
                    .unique(module, *function)
                    .and_then(variadic_signature),
                Inst::Const {
                    value: Constant::SymbolAddr { symbol, addend: 0 },
                    ..
                } => module
                    .functions
                    .iter()
                    .filter(|function| function.name == *symbol)
                    .find_map(variadic_signature),
                Inst::Copy { operand, .. }
                | Inst::Cast {
                    op:
                        CastOp::ReifyFnPointer
                        | CastOp::PtrToPtr
                        | CastOp::PtrToInt
                        | CastOp::IntToPtr
                        | CastOp::Bitcast
                        | CastOp::Transmute,
                    operand,
                    ..
                } => {
                    current = *operand;
                    continue;
                }
                _ => return Ok(()),
            };
            let Some((function, signature)) = target else {
                return Ok(());
            };
            crate::codegen_metadata::reject_unsigned_variadic_callee(function, signature)?;
            return Err(AdapterError::UnsupportedInstruction(format!(
                "[TCG-VARARG-ABI] CallIndirect through a function pointer to variadic `{}` \
                 ({} fixed parameter(s)): the edge's own non-variadic signature places every \
                 argument by the named-argument rules, which is not how a variadic callee reads \
                 its anonymous arguments (DarwinPCS stacks them, x86-64 SysV needs `AL`); the \
                 call fails closed",
                function.name,
                signature.params.len()
            )));
        }
        Ok(())
    }

    fn validate_call_indirect_signature(
        &self,
        callee: ValueId,
        sig: FuncTyId,
        args: &[ValueId],
        results: &[ValueId],
    ) -> Result<&'a trust_ir::FuncTy, AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let func_ty = module.func_types.get(sig.index() as usize).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "CallIndirect references unregistered FuncTyId({})",
                sig.index()
            ))
        })?;
        if func_ty.is_vararg {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect over variadic FuncTyId({}) is fail-closed until indirect variadic ABI lowering is proven",
                sig.index()
            )));
        }

        let callee_ty = self.lookup_value_ty(callee).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "CallIndirect callee {callee:?} has no known trust_ir type"
            ))
        })?;
        // Accept either a statically-known function symbol (Ty::Func(sig)), a
        // runtime code pointer (Ty::Ptr), or a 64-bit integer holding a code
        // address (Ty::I64 / Ty::U64). The trust-cg frontend is the sole
        // producer of Inst::CallIndirect and emits it only from genuine code
        // pointers — a vtable method-slot load (&dyn dispatch / the std
        // `lang_start` closure vtable) or a MIR FnPtr-typed operand. Such a
        // pointer is usually carried as Ty::Ptr, but a function address loaded
        // out of a vtable / function-pointer table slot is materialized as a
        // pointer-width integer (Ty::I64 from an `Inst::Load { ty: I64 }`), and
        // an integer holding a code address is just as valid an indirect-call
        // target as a Ptr: ISel loads the callee value into a register and
        // emits `call reg` (Opcode::CallIndirect -> X86Opcode::CallR) without
        // ever inspecting the trust_ir callee type, so a Func, a Ptr, and a
        // 64-bit-integer callee all lower to byte-identical machine code. The
        // call ABI is fully constrained by the explicit `sig` plus the arity
        // and per-argument type checks below, so admitting I64/U64 cannot change
        // the emitted instruction stream — only the target address held in the
        // register, which is exactly the runtime code pointer the program
        // computed. Narrow on purpose to pointer-width (64-bit) integers: a
        // sub-64-bit integer would not hold a full code address, so anything
        // other than Func/Ptr/I64/U64 still fails closed. Rejecting Ptr (and now
        // I64) was the over-tightened contract that failed closed on ALL dynamic
        // dispatch and on function-pointer-table indirect calls.
        if callee_ty != Ty::Func(sig)
            && callee_ty != Ty::Ptr
            && callee_ty != Ty::I64
            && callee_ty != Ty::U64
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect callee must be a code pointer (Func({}), Ptr, or a 64-bit integer code address I64/U64), got {callee_ty:?}",
                sig.index()
            )));
        }

        if args.len() != func_ty.params.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect argument arity mismatch for FuncTyId({}): got {}, expected {}",
                sig.index(),
                args.len(),
                func_ty.params.len()
            )));
        }
        if results.len() != func_ty.returns.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect result arity mismatch for FuncTyId({}): got {}, expected {}",
                sig.index(),
                results.len(),
                func_ty.returns.len()
            )));
        }

        for (index, (arg, expected_ty)) in args.iter().zip(func_ty.params.iter()).enumerate() {
            let actual_ty = self.lookup_value_ty(*arg).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "CallIndirect argument {index} value {arg:?} has no known trust_ir type"
                ))
            })?;
            if !Self::call_arg_ty_satisfies_param(&actual_ty, expected_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "CallIndirect argument {index} type mismatch for FuncTyId({}): got {:?}, expected {:?}",
                    sig.index(),
                    actual_ty,
                    expected_ty
                )));
            }
            self.translate_ty(expected_ty)?;
            self.refuse_bool_mask_carrier_mismatch(
                *arg,
                expected_ty,
                format!("CallIndirect argument {index} of FuncTyId({})", sig.index()),
            )?;
        }
        for ty in &func_ty.returns {
            self.translate_ty(ty)?;
        }

        Ok(func_ty)
    }

    /// Whether `cc` passes arguments/returns using the platform C register ABI
    /// (AAPCS64 on aarch64, System V AMD64 on x86-64), so the adapter's C-ABI
    /// classification is a correct lowering for it:
    /// - `C`: the C ABI itself.
    /// - `Fast` / `Cold`: LLVM optimization-hint conventions. The LangRef lets
    ///   the compiler pick the register assignment; it does NOT mandate a layout
    ///   different from C, so lowering them via the C ABI is always correct (it
    ///   simply forgoes the optimization freedom). trust-cg compiles every edge
    ///   of such a call consistently. This reasoning is target-independent: it
    ///   appeals to the absence of a mandated layout, not to a register file.
    /// - `Rust`: `extern "Rust"` uses the platform C register sequence for
    ///   scalars/pointers on BOTH supported targets — the same AAPCS64 sequence
    ///   on aarch64 and the same SysV sequence (RDI/RSI/RDX/RCX/R8/R9, XMM0-7,
    ///   RAX/RDX, XMM0/XMM1) on x86-64. Aggregate *layout* differences are
    ///   carried by `StructRepr`, not the calling convention, and every edge of a
    ///   Rust-ABI call is compiled here consistently.
    /// - `Swift`: NOT unconditionally C-compatible, and it diverges DIFFERENTLY
    ///   per target, so it is handled separately by
    ///   [`Self::swift_signature_is_c_abi_equivalent`], which takes the target
    ///   architecture and admits only the subset that target places identically.
    ///   Use [`Self::conv_sig_uses_c_register_abi`] at call/def sites, not this
    ///   function alone.
    fn calling_conv_uses_c_register_abi(cc: CallingConv) -> bool {
        matches!(
            cc,
            CallingConv::C | CallingConv::Fast | CallingConv::Cold | CallingConv::Rust
        )
    }

    /// A non-aggregate scalar that the aarch64 C ABI (AAPCS64) and the Swift
    /// convention pass IDENTICALLY. Verified empirically by disassembling clang's
    /// `swiftcall` against `ccc`: for each of these, both emit byte-for-byte the
    /// same register / stack-spill assignment.
    /// - single-register scalars (i8..i64, u8..u64, f16/f32/f64, bool, ptr) fill
    ///   x0-x7 / v0-v7 then spill to the stack, identically in both;
    /// - `i128`/`u128` use an aligned GPR pair (x0:x1, x2:x3, ...) then a
    ///   16-aligned stack slot, identically in both (verified in-register,
    ///   spilled, and interleaved with scalars).
    ///   AGGREGATES are excluded: Swift returns a >16-byte struct directly in
    ///   x0-x3 whereas C uses sret, so that case genuinely diverges.
    fn is_swift_c_equivalent_scalar(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::I8
                | Ty::I16
                | Ty::I32
                | Ty::I64
                | Ty::I128
                | Ty::U8
                | Ty::U16
                | Ty::U32
                | Ty::U64
                | Ty::U128
                | Ty::F16
                | Ty::F32
                | Ty::F64
                | Ty::Bool
                | Ty::Ptr
        )
    }

    /// Swift RETURN register components for an all-scalar return list, split by
    /// register CLASS: `(integer_components, fp_components)`. Each scalar is one
    /// component of its class; `i128`/`u128` are two INTEGER components (a GPR
    /// pair). Returns `None` if any return is a non-scalar (aggregate) type.
    /// `Unit`/`Never` returns carry no ABI slot and are skipped.
    ///
    /// The split matters because the two supported targets bound this budget
    /// with DIFFERENT SHAPES — see [`SwiftReturnBudget`]. AAPCS64 bounds the
    /// SUM (Swift's single 4-component budget over x0-x3 / v0-v3); SysV bounds
    /// each class independently (RAX/RDX and XMM0/XMM1). Summing on x86-64, or
    /// splitting on aarch64, would each admit a shape the target does not place
    /// the way `swiftcc` places it.
    fn swift_return_register_components(returns: &[Ty]) -> Option<(u32, u32)> {
        let mut integer: u32 = 0;
        let mut fp: u32 = 0;
        for ty in returns {
            if matches!(ty, Ty::Unit | Ty::Never) {
                continue;
            }
            if !Self::is_swift_c_equivalent_scalar(ty) {
                return None;
            }
            match ty {
                Ty::I128 | Ty::U128 => integer += 2,
                Ty::F16 | Ty::F32 | Ty::F64 => fp += 1,
                _ => integer += 1,
            }
        }
        Some((integer, fp))
    }

    /// The Swift RETURN budget within which THIS target's C register ABI places
    /// results EXACTLY where `swiftcc` places them.
    ///
    /// Read this as the answer to one question per target: over what set of
    /// scalar return sequences do the C ABI's `classify_returns` and the Swift
    /// convention agree register-for-register? Outside that set the Swift
    /// convention is a genuinely different ABI and must fail closed rather than
    /// be lowered as C.
    ///
    /// * **aarch64 (AAPCS64)** — `Combined(4)`. Swift's budget is a SINGLE
    ///   combined count of 4 (integer 64-bit words + FP scalar fields) over
    ///   x0-x3 / v0-v3, and AAPCS64's `classify_returns` walks the same
    ///   independent GPR/FPR counters in field order over the same eight
    ///   result registers, so every sequence summing to `<= 4` lands
    ///   identically. A sum of `>= 5` diverges (Swift uses sret).
    ///
    /// * **x86-64 (System V AMD64)** — `PerClass { int: 2, fp: 2 }`. The C
    ///   return file `classify_x86_scalar_return_locations` allocates from first
    ///   is RAX,RDX plus XMM0,XMM1 (`trust_cg_ir::x86_64_regs::X86_RET_GPRS` /
    ///   `X86_RET_XMMS`), on two INDEPENDENT class counters. (Past it the
    ///   classifier continues into TrustCG's internal multi-result registers,
    ///   `X86_INTERNAL_RET_GPRS` / `X86_INTERNAL_RET_XMMS`, but only a Fast or
    ///   Cold edge is admitted there — `[TCG-X86-MULTI-RESULT]` — and this
    ///   budget refuses a wider Swift edge first, so a Swift edge never
    ///   reaches them; RCX is the 3rd integer result in both files only by
    ///   coincidence, not by a measured agreement.) `swiftcc` on x86-64 returns in
    ///   RAX,RDX,RCX,R8 plus XMM0-XMM3, on the same two independent counters —
    ///   MEASURED, not assumed: the (E4) target
    ///   `trust-cg-codegen/tests/e2e_x86_64_swiftcc.rs` deposits known values in
    ///   named registers in hand-written assembly and has clang read them back
    ///   through `__attribute__((swiftcall))`. It needs a clang driver, so the
    ///   Linux x86-64 floor records it decided-absent under XD-03 rather than
    ///   running it there. The
    ///   file above is a same-index PREFIX of the Swift file in each class and
    ///   both allocate in order from the front, so the two agree exactly while
    ///   neither class exceeds 2 — and diverge at the first component that
    ///   would need RCX or XMM2.
    ///   ⚠ Read "the SysV C return file" precisely: System V returns an
    ///   aggregate in registers only up to TWO EIGHTBYTES IN TOTAL, so the C
    ///   ABI itself does not express the 2-integer+2-FP corner at all (it uses
    ///   sret there, which (E4) also measures). The agreement that licenses
    ///   that corner is between trust-cg's OWN multi-scalar return placement
    ///   and `swiftcc`'s; C's register file coincides with it only for the
    ///   shapes C can express.
    ///   ⚠ This budget is keyed on the ISA but DERIVED from an ABI. It is a
    ///   statement about System V AMD64 only; Windows x64 is a different C ABI
    ///   on the same ISA (return file RAX alone / XMM0 alone) with no measured
    ///   `swiftcc` placement, and it must not reach this budget at all. The
    ///   compile driver — the only layer that knows the target OS — refuses
    ///   every Swift edge there via
    ///   [`reject_unwitnessed_swift_conv_for_x86_abi`], so an unmeasured ABI
    ///   fails closed instead of inheriting these numbers.
    ///   ⚠ This budget is deliberately NOT derived from `X86_RET_GPRS.len()`.
    ///   Widening the C return file must not silently widen the set of Swift
    ///   signatures admitted as C-equivalent: it is the AGREEMENT of the two
    ///   files that licenses the admission, not the size of one. The tripwire
    ///   control in `tests/e2e_x86_64_calling_conv.rs` fires if the file moves.
    ///
    /// * **riscv64** — `Unwitnessed`. There is no RISC-V `swiftcc` definition
    ///   in this tree and none was measured, so the honest answer is that no
    ///   Swift signature is known C-equivalent here. An unmeasured target
    ///   inheriting another target's budget would be a green with nothing
    ///   behind it.
    fn swift_return_budget(arch: GuardCarrierArch) -> SwiftReturnBudget {
        swift_return_budget_for_arch(arch)
    }

    /// True when a `Swift`-convention function with this signature is PROVABLY
    /// lowered identically by `arch`'s C register ABI, so admitting it (instead
    /// of failing closed) cannot miscompile. The subset is: not variadic, every
    /// parameter a single-register scalar
    /// ([`Self::is_swift_c_equivalent_scalar`]), and an all-scalar return
    /// sequence inside [`Self::swift_return_budget`] for that target.
    ///
    /// PARAMETERS are architecture-independent here, and that is a claim about
    /// both targets, not an omission: `swiftcc` takes its ordinary scalar
    /// argument assignment straight from the platform C convention on aarch64
    /// (AAPCS64 x0-x7 / v0-v7, then the stack) and on x86-64 (SysV
    /// RDI/RSI/RDX/RCX/R8/R9, XMM0-XMM7, then the stack). The Swift-specific
    /// registers — self/error/async, x20/x21/x22 on aarch64 and R13/R12/R14 on
    /// x86-64 — are engaged ONLY by swiftself/swifterror/swiftasync parameter
    /// attributes, which trust-ir's `ParamAttrs` cannot express, so they can
    /// never come into play from this IR. RETURNS are where the two targets
    /// differ, and that is what [`Self::swift_return_budget`] indexes.
    ///
    /// AGGREGATE params/returns are outside the subset on every target (Swift
    /// direct-returns a >16-byte struct; C uses sret). Aggregate-bearing
    /// swiftcc signatures in the sound implementable subset are SCALARIZED
    /// before the adapter runs on DARWIN AARCH64 ONLY (see `swift_agg` and
    /// `swift_rewrite_module`). Other targets retain aggregate types here and
    /// correctly reject them until their aggregate Swift ABI is witnessed. (i128/u128 do NOT diverge on either target — they
    /// are an aligned GPR pair both ways — and are admitted as two integer
    /// components.) See the empirical ABI checks in
    /// `tests/e2e_aarch64_swift_scalar.rs`, `tests/e2e_aarch64_swift_aggregate.rs`,
    /// `tests/e2e_x86_64_calling_conv.rs` and `tests/e2e_x86_64_swiftcc.rs`.
    fn swift_signature_is_c_abi_equivalent(
        func_ty: &trust_ir::FuncTy,
        arch: GuardCarrierArch,
    ) -> bool {
        !func_ty.is_vararg
            && func_ty
                .params
                .iter()
                .all(Self::is_swift_c_equivalent_scalar)
            && matches!(
                Self::swift_return_register_components(&func_ty.returns),
                Some(components)
                    if Self::swift_return_budget(arch).admits(components)
            )
    }

    /// Whether `(cc, func_ty)` is correctly lowered by `arch`'s C register ABI:
    /// the always-C conventions (C/Fast/Cold/Rust) for ANY signature, or
    /// `Swift` restricted to the subset that target places identically to C.
    fn conv_sig_uses_c_register_abi(
        cc: CallingConv,
        func_ty: &trust_ir::FuncTy,
        arch: GuardCarrierArch,
    ) -> bool {
        Self::calling_conv_uses_c_register_abi(cc)
            || (matches!(cc, CallingConv::Swift)
                && Self::swift_signature_is_c_abi_equivalent(func_ty, arch))
    }

    /// The fail-closed diagnostic for a `(cc, signature)` that `arch`'s C
    /// register ABI does not lower identically.
    ///
    /// It names the CONVENTION, the TARGET and the target's own Swift return
    /// budget. Before this was architecture-indexed, an x86-64 Swift signature
    /// outside SysV's 2-integer/2-FP return file was admitted here and refused
    /// only later by `classify_x86_scalar_return_locations`, whose message
    /// ("integer result register capacity is exhausted") is the same one a
    /// plain `extern "C"` multi-return gets — so a reader could not tell an ABI
    /// DIVERGENCE refusal from an ordinary incompleteness, and the safety
    /// depended on the x86 return file staying narrow rather than on anything
    /// stated.
    fn unsupported_conv_detail(
        cc: CallingConv,
        func_ty: &trust_ir::FuncTy,
        arch: GuardCarrierArch,
    ) -> String {
        let budget = Self::swift_return_budget(arch);
        // Name the premise that FAILED, in the order the guard evaluates them,
        // so a reader is not left to re-derive it from the signature.
        let failed = if func_ty.is_vararg {
            "the signature is variadic".to_string()
        } else if let Some(index) = func_ty
            .params
            .iter()
            .position(|ty| !Self::is_swift_c_equivalent_scalar(ty))
        {
            format!(
                "parameter {index} ({:?}) is not a single-register scalar (an aggregate, or a \
                 scalar with no witnessed identical placement)",
                func_ty.params[index]
            )
        } else {
            match Self::swift_return_register_components(&func_ty.returns) {
                Some((integer, fp)) => {
                    format!("its return is {integer} integer + {fp} FP register components")
                }
                None => "its return is not an all-scalar sequence (an aggregate, or a scalar \
                         with no witnessed identical placement)"
                    .to_string(),
            }
        };
        format!(
            "unsupported calling convention {cc:?} for target {arch}; Trust-CG lowers \
             C-register-ABI conventions (C/Fast/Cold/Rust for any signature, and the subset \
             of Swift that {arch}'s C ABI places identically to swiftcc: non-variadic, \
             single-register scalar parameters, and {}) and must not silently use the C ABI \
             for a convention/signature with a different register layout. Here {failed}",
            budget.describe()
        )
    }

    /// `[TCG-X86-MULTI-RESULT]`: admit an x86-64 edge whose scalar results
    /// exhaust System V's C return file only under a TrustCG-owned convention.
    ///
    /// A TrustIR function may return any number of independent results
    /// (`FuncTy.returns`). System V AMD64's C return file holds two per class
    /// (RAX,RDX / XMM0,XMM1); past that the x86-64 selector places results in
    /// TrustCG's internal multi-result registers (`X86_INTERNAL_RET_GPRS` /
    /// `X86_INTERNAL_RET_XMMS`: RCX,RSI,RDI,R8,R9 / XMM2-XMM7). That is
    /// TrustCG's convention, not a C ABI: a C callee never writes a third
    /// integer result to RCX and a C caller never reads one there. So the
    /// decision is the edge's CALLING CONVENTION, which trust-ir keeps
    /// consistent across the edge (a direct call uses the callee's convention;
    /// a resolved indirect call must declare it):
    ///
    /// * `Fast` and `Cold` are TrustCG-owned conventions with no mandated
    ///   layout (the adapter already lowers them through the C register ABI
    ///   for every C-shaped signature). A caller or callee of such an edge is
    ///   TrustCG code, or code that implements TrustCG's convention, so the
    ///   extension is admitted — for a definition, a direct call and an
    ///   indirect call alike, whatever the linkage, exactly as the AArch64
    ///   backend places every multi-result in X0-X7 / V0-V7.
    /// * `C`, and every other convention naming an ABI implemented outside
    ///   TrustCG (C-unwind, SysV64, Win64, Rust, ...), is refused by name:
    ///   none of them returns a third integer in RCX. (`Swift` never gets
    ///   here: its own budget is checked first.)
    ///
    /// Only signatures the C file cannot place reach the check — the answer
    /// comes from the x86 return classifier itself
    /// ([`crate::x86_64_isel::x86_sysv_returns_exceed_c_return_file`]), so
    /// every edge compiled before the extension existed is untouched. Other
    /// targets are untouched, and Windows x64 reaches no extension: its
    /// selector still refuses anything past RAX / XMM0.
    fn admit_x86_internal_multi_result(
        &self,
        site: X86MultiResultSite<'_>,
        cc: CallingConv,
        func_ty: &trust_ir::FuncTy,
    ) -> Result<(), AdapterError> {
        // A single result never exhausts the C file (an `i128` is exactly
        // RAX:RDX), so the common edge costs no translation here.
        if self.guard_carrier_arch != GuardCarrierArch::X86_64
            || matches!(cc, CallingConv::Fast | CallingConv::Cold)
            || func_ty.returns.len() < 2
        {
            return Ok(());
        }
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        // A return list that does not translate is not this rule's business:
        // the ordinary signature translation reports it by its own name.
        let Ok(returns) = translate_return_types(func_ty, module) else {
            return Ok(());
        };
        if !crate::x86_64_isel::x86_sysv_returns_exceed_c_return_file(&returns) {
            return Ok(());
        }
        let what = match site {
            X86MultiResultSite::Definition(function) => format!("function `{}`", function.name),
            X86MultiResultSite::DirectCallee(callee) => {
                format!("a direct call to `{}`", callee.name)
            }
            X86MultiResultSite::Indirect => "a CallIndirect".to_string(),
        };
        Err(AdapterError::UnsupportedInstruction(format!(
            "[TCG-X86-MULTI-RESULT] {what} returns {} results ({returns:?}) under calling \
             convention {cc:?}. That is more than System V AMD64's C return file holds \
             (RAX,RDX / XMM0,XMM1), and {cc:?} names an ABI implemented outside TrustCG, which \
             has no register placement for them (a C callee never writes a third integer result \
             to RCX). TrustCG's internal multi-result registers (RCX,RSI,RDI,R8,R9 / XMM2-XMM7) \
             are admitted only on a Fast or Cold edge; declare the edge Fast or Cold, or return \
             an aggregate through the C aggregate ABI",
            returns.len()
        )))
    }

    fn validate_direct_call_signature(
        &self,
        callee: FuncId,
        args: &[ValueId],
        results: &[ValueId],
    ) -> Result<(&'a TrustIrFunction, &'a trust_ir::FuncTy), AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let callee_fn = self.functions.unique(module, callee).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "Call references unregistered FuncId({0}) or ambiguous FuncId({0})",
                callee.index()
            ))
        })?;
        let func_ty = module
            .func_types
            .get(callee_fn.ty.index() as usize)
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call references unregistered FuncTyId({}) for FuncId({})",
                    callee_fn.ty.index(),
                    callee.index()
                ))
            })?;
        // A variadic declaration with no trustworthy fixed-argument count has
        // no known argument placement: refuse it by name before anything
        // reads its parameter list (and before intrinsic recognition in the
        // caller), on every direct call and invoke.
        crate::codegen_metadata::reject_unsigned_variadic_callee(callee_fn, func_ty)?;
        validate_sret_declaration(callee_fn, func_ty)?;
        // A byval callee parameter would need a caller-made copy in the
        // outgoing argument area; passing the pointer through is a different
        // ABI. Refuse by name on every direct call and invoke.
        crate::codegen_metadata::reject_byval_params(callee_fn)?;
        if !Self::conv_sig_uses_c_register_abi(
            callee_fn.calling_conv,
            func_ty,
            self.guard_carrier_arch,
        ) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Call to FuncId({}) uses {}",
                callee.index(),
                Self::unsupported_conv_detail(
                    callee_fn.calling_conv,
                    func_ty,
                    self.guard_carrier_arch
                )
            )));
        }
        self.admit_x86_internal_multi_result(
            X86MultiResultSite::DirectCallee(callee_fn),
            callee_fn.calling_conv,
            func_ty,
        )?;

        if func_ty.is_vararg {
            if args.len() < func_ty.params.len() {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Call argument arity mismatch for FuncId({}): got {}, expected at least {} fixed arguments",
                    callee.index(),
                    args.len(),
                    func_ty.params.len()
                )));
            }
        } else if args.len() != func_ty.params.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Call argument arity mismatch for FuncId({}): got {}, expected {}",
                callee.index(),
                args.len(),
                func_ty.params.len()
            )));
        }

        if results.len() != func_ty.returns.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Call result arity mismatch for FuncId({}): got {}, expected {}",
                callee.index(),
                results.len(),
                func_ty.returns.len()
            )));
        }

        for (index, (arg, expected_ty)) in args.iter().zip(func_ty.params.iter()).enumerate() {
            let actual_ty = self.lookup_value_ty(*arg).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call argument {index} value {arg:?} has no known trust_ir type"
                ))
            })?;
            if !Self::call_arg_ty_satisfies_param(&actual_ty, expected_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Call argument {index} type mismatch for FuncId({}): got {:?}, expected {:?}",
                    callee.index(),
                    actual_ty,
                    expected_ty
                )));
            }
            self.translate_ty(expected_ty)?;
            self.refuse_bool_mask_carrier_mismatch(
                *arg,
                expected_ty,
                format!("Call argument {index} of FuncId({})", callee.index()),
            )?;
        }
        for (index, arg) in args.iter().enumerate().skip(func_ty.params.len()) {
            let actual_ty = self.lookup_value_ty(*arg).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call variadic argument {index} value {arg:?} has no known trust_ir type"
                ))
            })?;
            self.translate_ty(&actual_ty)?;
        }
        for ty in &func_ty.returns {
            self.translate_ty(ty)?;
        }

        if func_ty.abi.is_some() {
            let native = self.native_scalar_c_abi.as_ref().ok_or_else(|| {
                AdapterError::UnsupportedSignatureAbi {
                    module: module.name.clone(),
                    signature: callee_fn.ty.as_usize(),
                }
            })?;
            let actual_types = args
                .iter()
                .map(|arg| {
                    self.lookup_value_ty(*arg).ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(
                            "[TCG-SCALAR-C-ABI] call operand has no source type".into(),
                        )
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            native.call(
                module,
                &actual_types,
                &func_ty.returns,
                func_ty.is_vararg,
                func_ty.params.len(),
            )?;
        }
        Ok((callee_fn, func_ty))
    }

    /// Resolve the return types for a function type by `FuncTyId`.
    ///
    /// Used by `CallIndirect`, where the instruction carries the callee
    /// signature explicitly. Returns an empty vec if any return type
    /// fails to translate (e.g., aggregate returns through opaque types),
    /// preserving the pre-#381 fallback behavior for those cases.
    fn lookup_func_type_returns(&self, sig: FuncTyId) -> Vec<Type> {
        self.translate_return_tys(&self.lookup_func_type_return_tys(sig))
    }

    fn lookup_func_type_return_tys(&self, sig: FuncTyId) -> Vec<Ty> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let idx = sig.index() as usize;
        let Some(func_ty) = module.func_types.get(idx) else {
            return Vec::new();
        };
        func_ty.returns.clone()
    }

    /// Resolve the declared parameter types for a direct `Call` to `callee`,
    /// translated to LIR `Type`. Returns an empty vec (no hints) for an
    /// unknown/imported callee, mirroring `lookup_callee_return_types`.
    ///
    /// Used to seed an aggregate-by-value call ARGUMENT's type on a
    /// call-site-scoped `Copy` temp (see `record_aggregate_call_arg_types`): a
    /// constructed aggregate value is carried by ADDRESS, so its producing
    /// instruction (`Alloca`, `Copy`, `InsertField`, …) leaves it typed as a
    /// pointer/I64. Without this hint ISel's SysV classifier would pass it in
    /// a single GPR instead of the eightbyte register pair / sret slot the
    /// callee's aggregate param ABI expects. The callee's param type IS the
    /// aggregate (the bridge uses the flat integer-lane tuple `slot_ty` for
    /// by-value aggregate params), so recording it here makes the caller- and
    /// callee-side ABI agree.
    fn lookup_callee_param_types(&self, callee: FuncId) -> Vec<Type> {
        let Some(func_ty) = self.lookup_callee_func_ty(callee) else {
            return Vec::new();
        };
        self.translate_param_tys(&func_ty.params)
    }

    /// Resolve the declared parameter types for an indirect call signature,
    /// translated to LIR `Type`. Same fallback semantics as
    /// `lookup_func_type_returns`.
    fn lookup_func_type_param_types(&self, sig: FuncTyId) -> Vec<Type> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let Some(func_ty) = module.func_types.get(sig.index() as usize) else {
            return Vec::new();
        };
        self.translate_param_tys(&func_ty.params)
    }

    /// Resolve the declared trust_ir parameter `Ty`s (signedness-carrying) for an
    /// indirect call signature. Empty on an unresolvable sig. Used by the
    /// `CallIndirect` caller-side narrow-int extension (audit P0/G6), which needs
    /// the source-level signedness (`Ty::I8` vs `Ty::U8`) that is lost once the
    /// param is lowered to the sign-less machine `Type`.
    fn lookup_func_type_param_tys(&self, sig: FuncTyId) -> Vec<Ty> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let Some(func_ty) = module.func_types.get(sig.index() as usize) else {
            return Vec::new();
        };
        func_ty.params.clone()
    }

    fn translate_param_tys(&self, tys: &[Ty]) -> Vec<Type> {
        let mut out = Vec::with_capacity(tys.len());
        for ty in tys {
            match self.translate_ty(ty) {
                Ok(t) => out.push(t),
                // A param type that fails to translate yields no hints at all,
                // so a partial (mis-indexed) list can never be applied to args.
                Err(_) => return Vec::new(),
            }
        }
        out
    }

    /// Seed the aggregate LIR `Type` of any call argument whose matching
    /// callee parameter type is an aggregate (`Struct`/`Array`/`Enum`) —
    /// CALL-SITE-SCOPED via a fresh `Copy` temp.
    ///
    /// A by-value aggregate argument is a constructed value carried by ADDRESS
    /// (an `Alloca`/`StructGep`/`Copy` chain typed as a pointer). ISel's call
    /// classifier reads `value_type(arg)` to choose the System V eightbyte
    /// register-pair / sret placement; without an aggregate type recorded the
    /// arg would default to a single I64 GPR and miscompile the call.
    ///
    /// The retype must NOT be applied to the argument's own ValueId: that is a
    /// whole-function (global) retype of the fat-ptr slot, and the slot's OTHER
    /// uses in the caller — its own lane-spill address arithmetic
    /// (`Add(PtrToInt(slot), 8)` chains) — then see an aggregate-typed operand
    /// and fail closed in `select_arithmetic` ([TCG-REGALLOC-063]). Instead we
    /// allocate a fresh temp, emit `temp = Copy(orig)` immediately before the
    /// call, retype ONLY the temp, and rewrite the call arg to the temp. The
    /// original slot keeps its I64 pointer-carrier type everywhere else. ISel's
    /// `select_move_reg`/`select_copy` recognize the seeded-aggregate-dest Copy
    /// and ALIAS the temp to the source address operand (zero machine
    /// instructions), so the emitted call code is unchanged.
    ///
    /// Guard (the pointer-carrier contract, see
    /// `is_aggregate_address_passed_ty`): a temp is synthesized only when the
    /// arg's currently-recorded LIR type is `None` or `Type::I64`. An arg
    /// already recorded with exactly `param_ty` (e.g. an aggregate call result
    /// chained into another call) passes through unchanged. ANY other recorded
    /// type is a genuine ABI mismatch — classifying the call by a temp typed
    /// `param_ty` while the source carries a DIFFERENT layout would load the
    /// wrong lanes/register classes — so we fail closed.
    ///
    /// We only handle aggregate params — scalar params keep whatever type their
    /// producing instruction already recorded. `param_tys` may be shorter than
    /// `arg_vals` (variadic tail) or empty (unknown callee); `zip` handles both.
    /// Returns the prologue `Copy` instructions; callers must place them
    /// immediately before the call in the same block.
    fn record_aggregate_call_arg_types(
        &mut self,
        arg_vals: &mut [Value],
        param_tys: &[Type],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let mut copies = Vec::new();
        for (val, param_ty) in arg_vals.iter_mut().zip(param_tys.iter()) {
            if !matches!(
                param_ty,
                Type::Struct(_) | Type::Array(_, _) | Type::Enum { .. }
            ) {
                continue;
            }
            match self.value_types.get(val) {
                // Arg already carries exactly this aggregate type: pass
                // through unchanged (no temp needed).
                Some(recorded) if recorded == param_ty => continue,
                // Untyped or I64 address carrier — the documented contract for
                // a by-value aggregate arg. Scope the retype to a fresh temp.
                None | Some(Type::I64) => {}
                // A different recorded type (another aggregate, F64, I128, …)
                // cannot be blessed as `param_ty` by a temp: ISel would
                // classify the call by the param lanes while the source value
                // carries a different layout/register class. Fail closed.
                Some(other) => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "call argument {val:?} has recorded LIR type {other:?} but the callee \
                         parameter expects by-value aggregate {param_ty:?}; only an I64 \
                         pointer-carrier (or an exact aggregate match) is a sound source for \
                         the System V eightbyte classification"
                    )));
                }
            }
            let temp = self.fresh_value();
            copies.push(Instruction {
                opcode: Opcode::Copy,
                args: vec![*val],
                results: vec![temp],
            });
            self.define_value_type(temp, param_ty.clone());
            *val = temp;
        }
        Ok(copies)
    }

    /// Pass every composite argument that AArch64 passes by reference as an
    /// explicit pointer to storage the callee may own for the call.
    ///
    /// AAPCS64 §6.8.2 B.4 (DarwinPCS keeps the rule) replaces a composite
    /// larger than 16 bytes that is not an HFA/HVA
    /// ([`crate::abi::AppleAArch64ABI::passes_composite_by_reference`]) by a
    /// pointer to a copy the caller allocates, and the callee may write that
    /// copy. An aggregate value here is the address of its storage, which the
    /// caller may still read after the call, so the argument becomes:
    ///
    /// * the value's own slot when [`Self::source_storage_is_reusable`]
    ///   holds for it (a `Const`, `Load` or insert allocated the slot for it
    ///   alone, this call is its only use and it is defined in this block)
    ///   and that lowering recorded the slot (`owned_aggregate_slots`):
    ///   nothing reads the slot after the callee, so its writes are harmless;
    /// * otherwise a fresh frame slot filled by a `Memcpy` of the type's
    ///   size. Selection inlines a copy of at most 32 bytes and calls
    ///   `memcpy` above that, so its code size and compile cost do not grow
    ///   with the aggregate.
    ///
    /// Either way the argument is an `I64` pointer, which the AArch64
    /// classifiers place exactly like the by-reference aggregate (the next
    /// GPR, or an 8-byte stack slot once X0-X7 are used), so selection makes
    /// no second copy. Darwin anonymous variadic arguments are left as they
    /// are: selection refuses them (`[TCG-VARARG-ABI]`). Other targets keep
    /// their own by-value lowering. `sources[i]` is the trust_ir value of
    /// `arg_vals[i]`, and arguments from `anonymous_from` on are variadic.
    ///
    /// Returns whether any argument is passed by reference.
    fn pass_composites_by_reference(
        &mut self,
        sources: &[ValueId],
        arg_vals: &mut [Value],
        anonymous_from: Option<usize>,
        instrs: &mut Vec<Instruction>,
    ) -> Result<bool, AdapterError> {
        if self.guard_carrier_arch != GuardCarrierArch::AArch64 {
            return Ok(false);
        }
        let Some(variant) = self.tls_dialect.aarch64_abi_variant() else {
            return Ok(false);
        };
        let mut any = false;
        for (index, arg) in arg_vals.iter_mut().enumerate() {
            // The argument's LIR type. A fixed aggregate parameter's argument
            // carries it (`record_aggregate_call_arg_types`), but a function or
            // block parameter has no `value_types` entry, and nothing retypes a
            // variadic argument, so such an argument is typed from its trust_ir
            // value, the same translation its block parameter got.
            let ty = match self.value_types.get(arg) {
                Some(ty) => ty.clone(),
                None => match sources
                    .get(index)
                    .and_then(|source| self.lookup_value_ty(*source))
                    .and_then(|source_ty| self.translate_ty(&source_ty).ok())
                {
                    Some(ty) => ty,
                    None => continue,
                },
            };
            if !crate::abi::AppleAArch64ABI::passes_composite_by_reference(&ty) {
                continue;
            }
            let anonymous = anonymous_from.is_some_and(|fixed| index >= fixed);
            if anonymous && variant == crate::abi::AArch64AbiVariant::Darwin {
                continue;
            }
            any = true;
            let source = sources.get(index).copied();
            let owned_slot = source.and_then(|source| {
                let same_type = self
                    .lookup_value_ty(source)
                    .and_then(|source_ty| self.translate_ty(&source_ty).ok())
                    .is_some_and(|source_ty| source_ty == ty);
                (same_type && self.source_storage_is_reusable(source))
                    .then(|| self.owned_aggregate_slots.get(&source).copied())
                    .flatten()
            });
            let pointer = self.fresh_value();
            self.define_value_type(pointer, Type::I64);
            if let Some(slot) = owned_slot {
                // The value's own slot, addressed afresh so the argument is
                // an `I64` pointer (a `Copy` would keep the aggregate type).
                instrs.push(Instruction {
                    opcode: Opcode::StackAddr { slot },
                    args: vec![],
                    results: vec![pointer],
                });
            } else {
                let slot = self.alloc_stack_slot(ty.bytes(), ty.align().max(8));
                instrs.push(Instruction {
                    opcode: Opcode::StackAddr { slot },
                    args: vec![],
                    results: vec![pointer],
                });
                let len = self.emit_iconst_i64(i64::from(ty.bytes()), instrs);
                instrs.push(Instruction {
                    opcode: Opcode::Memcpy,
                    args: vec![pointer, *arg, len],
                    results: vec![],
                });
            }
            *arg = pointer;
        }
        Ok(any)
    }

    fn translate_return_tys(&self, tys: &[Ty]) -> Vec<Type> {
        let mut out = Vec::with_capacity(tys.len());
        for ty in tys {
            match self.translate_ty(ty) {
                Ok(t) => out.push(t),
                Err(_) => return Vec::new(),
            }
        }
        out
    }

    // -----------------------------------------------------------------------
    // Top-level translation
    // -----------------------------------------------------------------------

    /// Translate a trust_ir function to an internal LIR Function + ProofContext.
    fn translate(
        &mut self,
        func: &'a TrustIrFunction,
    ) -> Result<(Function, ProofContext), AdapterError> {
        // Standalone, inline-only and body-template entries may bypass module
        // preparation, and a detached `func` is not one the module floor saw.
        // Refuse unsupported semantics before any projection, collection
        // census, intrinsic substitution or source reconstruction.
        unmodeled_body_construct_floor_with_nominals(
            func,
            self.module,
            self.native_nominal_values.as_deref(),
        )?;
        // trust-ir v74 `Inst::BoxDeref`: the same acceptance check the module
        // floor runs, for a function this entry was handed without that floor
        // having seen it. Without a module no rule of the fact can be
        // checked, and the function is refused.
        if crate::box_deref::function_has_box_deref(func) {
            match self.module {
                // `func` in place: a detached clone is judged as itself,
                // never by the module's stale entry of the same id.
                Some(module) => {
                    crate::box_deref::admit_box_derefs(
                        &module_holding_function(func, module),
                        crate::box_deref::BoxValidityFloor::MOST_PERMISSIVE,
                    )?;
                }
                None => crate::box_deref::refuse_box_deref_without_module(func)?,
            }
        }
        if self.native_scalar_c_abi.is_none() {
            signature_abi_surface::refuse_recorded(self.module.ok_or(AdapterError::ModuleNotSet)?)?;
        }
        self.value_producers.clear();
        self.closure_parameter_sources.take();
        self.value_ty_map.clear();
        self.aggregate_call_results.clear();
        self.value_use_counts.clear();
        self.value_def_blocks.clear();
        self.owned_aggregate_storage.clear();
        self.owned_aggregate_slots.clear();
        self.block_param_slots.clear();
        self.pending_extra_block_origins.clear();
        self.current_source_loc = None;
        self.current_trust_ir_origin = None;
        self.bfu_plan = None;
        self.eh_personality = Some(self.eh_personality_for(func));
        self.eh_type_table = EhTypeTable::new();
        self.sequence_result_buffer = None;
        self.sequence_result_length = None;
        self.function_has_collections = false;
        self.sequence_facts = None;
        self.pending_block_split = None;
        self.current_lir_block = None;
        // Every id the function defines is below the synthetic range; the
        // closure-application lowering mints capture temporaries above it.
        let mut max_defined_value_id = 0u32;
        let mut field_extracts = Vec::new();
        let mut has_collections = false;
        for block in &func.blocks {
            for (param, ty) in &block.params {
                max_defined_value_id = max_defined_value_id.max(param.index());
                has_collections |= sequence_layout::is_collection(ty);
                self.value_ty_map.insert(*param, ty.clone());
            }
            for node in &block.body {
                node.inst.visit_value_operands(|operand| {
                    *self.value_use_counts.entry(operand).or_insert(0) += 1;
                });
                visit_top_level_types(&node.inst, |ty| {
                    has_collections |= sequence_layout::is_collection(ty);
                });
                for result in &node.results {
                    max_defined_value_id = max_defined_value_id.max(result.index());
                    // Preserve the previous linear lookup's first-definition
                    // behavior if malformed input reuses an SSA ValueId.
                    self.value_producers.entry(*result).or_insert(node);
                    self.value_def_blocks.entry(*result).or_insert(block.id);
                }
                if matches!(node.inst, Inst::ExtractField { .. }) {
                    field_extracts.push(node);
                } else {
                    for (idx, result) in node.results.iter().enumerate() {
                        if let Some(ty) = self.trust_ir_result_type(&node.inst, idx) {
                            has_collections |= sequence_layout::is_collection(&ty);
                            self.value_ty_map.insert(*result, ty);
                        }
                    }
                }
                // OPT-6a: record plain integer-constant definitions so the
                // frontend bounds-probe recognizer can resolve its exact bound.
                if let Inst::Const {
                    value: Constant::Int(v),
                    ..
                } = &node.inst
                    && let [result] = node.results.as_slice()
                {
                    self.int_const_values.insert(*result, *v);
                }
            }
        }

        self.next_synthetic_value_id = max_defined_value_id.saturating_add(1);
        self.function_has_collections = has_collections;

        // A borrow is the one instruction whose result type follows its
        // OPERAND (`trust_ir::bridge::borrow_result_ty`: a fat operand keeps
        // its type, a thin one is `Ptr`); the pass above wrote the thin
        // default. Resolve every borrow result against the whole function
        // with trust-ir's own two-phase rule before anything reads it.
        if func
            .blocks
            .iter()
            .flat_map(|block| &block.body)
            .any(|node| matches!(node.inst, Inst::Borrow { .. } | Inst::BorrowMut { .. }))
        {
            let resolved = trust_ir::bridge::borrow_result_types(func, &|value| {
                self.value_ty_map.get(&value).cloned()
            });
            for (value, ty) in resolved {
                self.value_ty_map.insert(value, ty);
            }
        }

        self.index_field_extract_types(&field_extracts)?;
        self.bounds_assertions = bounds_assert::index(func, self.guard_carrier_arch);
        self.trust_ir_func = Some(func);
        self.proof_ctx.source_stack_allocations.function = Some(func.id);
        self.proof_ctx.source_stack_allocations.symbol = func.name.clone();
        self.next_trust_ir_origin = 0;

        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let func_ty = module
            .func_types
            .get(func.ty.index() as usize)
            .ok_or(AdapterError::InvalidFuncTyId(func.ty.index()))?;
        // Signature-level ABI refusals come first so every lowering entry
        // reports the same named diagnostic: a variadic definition has no
        // va_list lowering, and a byval parameter no caller-copy lowering.
        //
        // A variadic `Swift` DEFINITION therefore reports the variadic
        // diagnostic, not a convention-specific one, and that is deliberate:
        // the convention guard below is not absent for it, only SHADOWED. If
        // va_list lowering ever lands and this refusal is lifted, control
        // reaches `conv_sig_uses_c_register_abi`, which requires
        // `!func_ty.is_vararg`, and the swiftcc case still fails closed. The
        // unshadowed exercise of that guard is a variadic swiftcc DECLARATION
        // called directly (`validate_direct_call_signature`), where no
        // variadic-definition refusal applies at all; see
        // `e3_variadic_swift_conv_guard_is_live_where_nothing_shadows_it`.
        crate::codegen_metadata::reject_variadic_definition(func, module)?;
        let abi_sret_param = validate_sret_declaration(func, func_ty)?;
        crate::codegen_metadata::reject_byval_params(func)?;
        if !Self::conv_sig_uses_c_register_abi(func.calling_conv, func_ty, self.guard_carrier_arch)
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "function {} uses {}",
                func.name,
                Self::unsupported_conv_detail(func.calling_conv, func_ty, self.guard_carrier_arch)
            )));
        }
        self.admit_x86_internal_multi_result(
            X86MultiResultSite::Definition(func),
            func.calling_conv,
            func_ty,
        )?;
        self.refuse_undeclarable_struct_layouts(func, func_ty)?;
        let sig = translate_signature(func, module)?;
        let stack_limit = self.admit_stack_limit_request(func, module, &sig, abi_sret_param)?;
        let sequence_result = sequence_result_signature(&func.name, func_ty)?;
        if sequence_result || func_ty.params.iter().any(sequence_layout::is_collection) {
            if self.guard_carrier_arch != GuardCarrierArch::AArch64 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{SEQUENCE_DIAGNOSTIC} `{}`: the sequence/set image and ABI are defined for \
                     AArch64 targets only (crate::sequence_layout)",
                    func.name
                )));
            }
            refuse_sequence_abi_convention(&func.name, func.calling_conv)?;
        }
        // The hidden trailing result buffer is not an entry-block parameter.
        let declared_params = sig.params.len() - usize::from(sequence_result);
        let entry_block = func
            .blocks
            .iter()
            .find(|block| block.id == func.entry)
            .ok_or(AdapterError::UnknownBlock(func.entry.index()))?;
        if entry_block.params.len() != declared_params {
            return Err(AdapterError::EntryParamArityMismatch(
                func.name.clone(),
                entry_block.params.len(),
                declared_params,
            ));
        }
        for (index, ((_, entry_ty), sig_ty)) in
            entry_block.params.iter().zip(sig.params.iter()).enumerate()
        {
            let entry_ty = self.translate_ty(entry_ty)?;
            if entry_ty != *sig_ty {
                return Err(AdapterError::EntryParamTypeMismatch(
                    func.name.clone(),
                    index,
                    entry_ty,
                    sig_ty.clone(),
                ));
            }
        }

        // ISel's formal-argument convention binds signature parameter `i` to
        // internal `Value(i)`. Reserve those values from the ACTUAL entry block
        // before translating any block: trust_ir permits blocks to be stored in
        // non-layout order, and otherwise a non-entry instruction translated
        // first can steal `Value(0)` and alias a formal. The arity/type checks
        // above make this reservation an exact ABI correspondence rather than a
        // positional guess.
        let mut seen_entry_params = HashSet::new();
        for (param, _) in &entry_block.params {
            if !seen_entry_params.insert(*param) {
                return Err(AdapterError::DuplicateBlockParam(
                    entry_block.id.index(),
                    param.index(),
                ));
            }
            self.map_value(*param);
        }
        if sequence_result {
            // Signature parameter `declared_params` is the result buffer, so
            // ISel binds it to `Value(declared_params)`: reserve exactly that.
            let buffer = self.fresh_value();
            if buffer.0 as usize != declared_params {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{SEQUENCE_DIAGNOSTIC} `{}`: the result-buffer parameter could not be \
                     bound to Value({declared_params}) (got {buffer:?})",
                    func.name
                )));
            }
            self.define_value_type(buffer, Type::I64);
            self.sequence_result_buffer = Some(buffer);
            self.require_published_result_length(func)?;
        }
        let param_pointee_types = translate_param_pointee_types(func, module)?;
        self.current_returns = sig.returns.clone();
        // Drop unit/never returns to match the void machine signature (see
        // translate_signature): a `-> ()` function returns no value, so a bare
        // `ret` validates against an empty return-type list.
        self.current_return_tys = func_ty
            .returns
            .iter()
            .filter(|t| !matches!(t, Ty::Unit | Ty::Never))
            .cloned()
            .collect();
        let entry = self.map_block(func.entry);

        let mut lir_func = Function::new(func.name.clone(), sig);
        lir_func.param_pointee_types = param_pointee_types;
        lir_func.entry_block = entry;
        // Admitted against the target vocabulary by the module floor
        // (`reject_unconsumed_v41_surface*`); the pipeline decides what the
        // stated features let this function's instruction selection use.
        lir_func
            .target_features
            .clone_from(&func.attrs.target_features);
        if self.function_requires_stack_protector(func) {
            lir_func.stack_protector = StackProtectorMode::StackGuard;
        }
        lir_func.stack_limit = stack_limit;
        let source_debug = extract_source_debug_info(func, module);
        lir_func.debug_meta = FunctionDebugMeta {
            // Prefer the real path the frontend stamped (module `files` table);
            // fall back to a synthetic `<module>.rs` only when the function
            // carries no span (so DWARF still names *something*).
            source_file: source_debug
                .source_file
                .clone()
                .or_else(|| Some(format!("{}.rs", module.name))),
            // The producer's human def-path names the DWARF subprogram; the
            // object symbol may be a producer-private spelling.
            display_name: func.display_path.clone(),
            decl_line: source_debug.decl_line,
            param_names: source_debug.param_names,
            local_variables: Vec::new(),
            struct_types: source_debug.struct_types,
            enum_types: source_debug.enum_types,
        };

        // Extract function-level proof annotations and rich proof facts.
        let func_metadata = extract_function_proof_metadata(func);
        for proof in func_metadata.proofs {
            self.proof_ctx.add_function_proof(proof);
        }
        for fact in func_metadata.facts {
            self.proof_ctx.add_function_fact(fact);
        }
        self.proof_ctx.diagnostics.extend(func_metadata.diagnostics);

        // Thread `noalias` pointer-parameter attributes onto a dedicated channel
        // for the `neon-map` store vectorizer. `attrs.params[i]` describes formal
        // parameter `i` (signature order), which the ISel binds to `Value(i)`, so
        // recording the raw index is enough for the codegen pipeline to resolve
        // the machine vreg. Kept out of `value_facts` so no other proof-consuming
        // pass observes it.
        for (i, pa) in func.attrs.params.iter().enumerate() {
            if pa.noalias {
                self.proof_ctx.noalias_param_indices.push(i);
            }
        }

        // This is the locally checked source ABI declaration, not a size rule.
        lir_func.abi_sret_param = abi_sret_param;

        // The borrow / binding-frame / Undef legalization stage decides the
        // whole function before any of its instructions is lowered: a shape
        // it does not honour refuses the function by name here, and the arms
        // below lower only what this plan admitted.
        let bfu_plan =
            crate::borrow_frame_undef::plan_function(func, &self.value_ty_map, &|ty: &Ty| {
                self.translate_ty(ty)
            })?;
        self.bfu_plan = bfu_plan.map(Box::new);

        // Translate all blocks.
        let mut _blocks_time = 0;
        let mut _insts_time = 0;
        for trust_ir_block in func.blocks.iter() {
            let block_id = self.map_block(trust_ir_block.id);
            let _t = std::time::Instant::now();
            let segments = self.translate_block(trust_ir_block)?;
            _blocks_time += _t.elapsed().as_millis();
            // The trust-ir block's own LIR block comes first; a multi-block
            // expansion's blocks and continuation follow it in layout order.
            debug_assert_eq!(segments.first().map(|segment| segment.0), Some(block_id));
            for (segment_id, basic_block, trust_ir_origins) in segments {
                lir_func.block_order.push(segment_id);
                lir_func
                    .trust_ir_origins
                    .insert(segment_id, trust_ir_origins);
                lir_func.blocks.insert(segment_id, basic_block);
            }
        }
        if _blocks_time > 100 && std::env::var_os("TY_TRUST_CG_JIT_PROFILE").is_some() {
            eprintln!("[JIT Profile] translate blocks total: {}ms", _blocks_time);
        }

        // Post-pass: insert pending phi copies into predecessor blocks.
        //
        // Explicit Phi instructions were lowered to copies that need to be
        // placed at the end of each predecessor block (before terminators).
        // This mirrors how `resolve_block_args` handles block parameters.
        for (pred_trust_ir_block, src, dst) in std::mem::take(&mut self.pending_phi_copies) {
            let pred_lir_block = self.map_block(pred_trust_ir_block);
            if let Some(pred_bb) = lir_func.blocks.get_mut(&pred_lir_block) {
                let copy_inst = Instruction {
                    opcode: Opcode::Copy,
                    args: vec![src],
                    results: vec![dst],
                };
                // Insert before the terminator. Find the last instruction
                // that is a control-flow terminator and insert before it.
                let term_pos = pred_bb.instructions.iter().rposition(|inst| {
                    matches!(
                        inst.opcode,
                        Opcode::Jump { .. }
                            | Opcode::Brif { .. }
                            | Opcode::Return
                            | Opcode::Invoke { .. }
                    )
                });
                match term_pos {
                    Some(pos) => {
                        pred_bb.instructions.insert(pos, copy_inst);
                        // Keep source_locs aligned (phi copies have no source loc).
                        if !pred_bb.source_locs.is_empty() {
                            pred_bb.source_locs.insert(pos, None);
                        }
                        if let Some(origins) = lir_func.trust_ir_origins.get_mut(&pred_lir_block) {
                            origins.insert(pos.min(origins.len()), None);
                        }
                    }
                    None => {
                        pred_bb.instructions.push(copy_inst);
                        if !pred_bb.source_locs.is_empty() {
                            pred_bb.source_locs.push(None);
                        }
                        if let Some(origins) = lir_func.trust_ir_origins.get_mut(&pred_lir_block) {
                            origins.push(None);
                        }
                    }
                }
            }
        }

        // Post-pass: insert extra blocks created by condbr/switch edge splitting.
        //
        // When translate_condbr or the Inst::Switch handler encountered block arguments,
        // they created intermediate copy blocks to ensure copies only execute on
        // the correct control-flow edge (fix for issue #302/#304).
        for (block_id, basic_block) in std::mem::take(&mut self.pending_extra_blocks) {
            let insert_at = edge_copy_target(&basic_block)
                .and_then(|target| {
                    let target_pos = lir_func
                        .block_order
                        .iter()
                        .position(|existing| *existing == target)?;
                    let source_pos = lir_func.block_order.iter().position(|candidate| {
                        lir_func
                            .blocks
                            .get(candidate)
                            .is_some_and(|block| block_targets_block(block, block_id))
                    })?;
                    if source_pos < target_pos {
                        Some(target_pos)
                    } else {
                        None
                    }
                })
                .unwrap_or(lir_func.block_order.len());
            let origins = self
                .pending_extra_block_origins
                .remove(&block_id)
                .filter(|origins| origins.len() == basic_block.instructions.len())
                .unwrap_or_else(|| vec![None; basic_block.instructions.len()]);
            // Synthetic failure/invoke blocks retain the same source origin;
            // identity census must include them before the output is finalized.
            for (index, (instruction, origin)) in
                basic_block.instructions.iter().zip(&origins).enumerate()
            {
                if let Some(origin) = origin {
                    self.record_call_census(
                        block_id,
                        index,
                        std::slice::from_ref(instruction),
                        *origin,
                    );
                }
            }
            lir_func.trust_ir_origins.insert(block_id, origins);
            lir_func.block_order.insert(insert_at, block_id);
            lir_func.blocks.insert(block_id, basic_block);
        }

        // An exactly forwarded Darwin C narrow result is carried in the
        // complete W0 ABI word, not only its low i8/i16 bits. Describe that
        // physical return representation to ISel and the existing tail pass.
        // Every other return in this function still receives the ordinary
        // explicit I32 sign extension below; the source FuncTy is unchanged.
        if let [ty] = self.current_return_tys.as_slice()
            && func
                .blocks
                .iter()
                .flat_map(|block| &block.body)
                .any(|node| {
                    matches!(&node.inst, Inst::Return { values }
                    if matches!(values.as_slice(), [value]
                        if self.forwards_extended_darwin_c_result(*value, ty)))
                })
        {
            lir_func.signature.returns = vec![Type::I32];
        }

        // The typed value model, recorded on the channel the adapter already has for value facts.
        self.record_refinement_proofs();

        let proofs = self.take_output_metadata(&mut lir_func);
        // Diagnostic only, inert unless `TCG_DUMP_LIR` selects this function;
        // it reads `lir_func` and writes text. Placed at the adapter's single
        // per-function return so every translation path dumps the same stream
        // the selectors are handed.
        crate::lir_dump::dump_if_requested(&lir_func);
        Ok((lir_func, proofs))
    }

    /// Finish this one-function adapter by transferring its owned output.
    ///
    /// Each production caller constructs a fresh adapter for one function.
    /// Cloning these collections would duplicate metadata (including nested
    /// types, strings, EH tables and proof/refinement state) immediately before
    /// dropping the adapter. Compact growth buffers and move their contents
    /// instead; otherwise a move alone would retain slack that Vec::clone used
    /// to discard. The caller still
    /// needs the separate exact/imported-call authorization counters and rows
    /// to construct the module validation report; those remain untouched.
    /// This changes ownership, never what counts as proof or call authority.
    fn take_output_metadata(&mut self, function: &mut Function) -> ProofContext {
        self.compact_output_metadata();
        function.stack_slots = std::mem::take(&mut self.stack_slots);
        function.debug_meta.local_variables = std::mem::take(&mut self.debug_local_variables);
        function.debug_value_bindings = std::mem::take(&mut self.debug_value_bindings);
        function.value_types = std::mem::take(&mut self.value_types);
        function.pure_callees = std::mem::take(&mut self.pure_callees);
        function.libm_pure_callees = std::mem::take(&mut self.libm_pure_callees);
        function.sret_arg_callees = std::mem::take(&mut self.sret_arg_callees);
        function.sret_arg_indirect_callees = std::mem::take(&mut self.sret_arg_indirect_callees);
        function.eh_info = std::mem::take(&mut self.eh_info);
        function.eh_type_table = std::mem::take(&mut self.eh_type_table);
        std::mem::take(&mut self.proof_ctx)
    }

    /// Compact the growable row buffers owned by this function builder.
    ///
    /// Hash tables and nested payload objects are moved as-is, not recursively
    /// rebuilt; this is not a claim to eliminate every retained spare byte.
    /// Refinement tables were just snapshotted by record_refinement_proofs.
    fn compact_output_metadata(&mut self) {
        compact_output_vec(&mut self.stack_slots);
        compact_output_vec(&mut self.debug_local_variables);
        compact_output_vec(&mut self.debug_value_bindings);
        for pad in &mut self.eh_info.landing_pads {
            compact_output_vec(&mut pad.catch_type_indices);
        }
        compact_output_vec(&mut self.eh_info.landing_pads);
        compact_output_vec(&mut self.eh_info.call_sites);

        // Exhaustive destructuring makes a new proof-context field a review
        // point for the finalization policy, without changing proof authority.
        let ProofContext {
            value_proofs,
            function_proofs,
            value_facts,
            function_facts,
            noalias_param_indices,
            diagnostics,
            synthesized_discharged,
            synthesized_obligation_formulas,
            next_synthesized_obligation: _,
            refinement_env: _,
            lattice_bounds_capabilities,
            borrow_frame_undef,
            aggregate_call_intents,
            source_stack_allocations,
        } = &mut self.proof_ctx;
        for proofs in value_proofs.values_mut() {
            compact_output_vec(proofs);
        }
        for facts in value_facts.values_mut() {
            compact_output_vec(facts);
        }
        compact_output_vec(function_proofs);
        compact_output_vec(function_facts);
        compact_output_vec(noalias_param_indices);
        compact_output_vec(diagnostics);
        compact_output_vec(synthesized_discharged);
        compact_output_vec(synthesized_obligation_formulas);
        compact_output_vec(lattice_bounds_capabilities);
        aggregate_call_intents.compact();
        compact_output_vec(&mut source_stack_allocations.records);
        compact_output_vec(&mut borrow_frame_undef.borrows);
        compact_output_vec(&mut borrow_frame_undef.retired_borrows);
        compact_output_vec(&mut borrow_frame_undef.frames);
        compact_output_vec(&mut borrow_frame_undef.undefs);
    }

    /// Record every `Ty::Refine`-typed value's predicate on `proof_ctx.value_proofs`, and snapshot
    /// the module's interned lattice tables so a downstream consumer can resolve those ids.
    ///
    /// Runs at the very END of `translate`, deliberately: it reads `self.value_map` (already
    /// populated) instead of calling `map_value`, so it cannot allocate a fresh LIR `Value` and
    /// therefore cannot perturb value numbering, instruction selection, or a single emitted byte.
    /// A value whose `ValueId` never reached the LIR is simply skipped.
    ///
    /// REPRESENTATION PRESERVATION: nothing here touches `value_types` (the LIR type map).
    /// `translate_ty(Refine(b, p))` already produced exactly `translate_ty(b)`, so a module that
    /// adds refinements to an existing module compiles to the same machine types; only this proof
    /// metadata differs.
    fn record_refinement_proofs(&mut self) {
        let Some(module) = self.module else {
            return;
        };
        // Cheap and total: a module with no refinements snapshots two empty vectors, and the
        // scan below finds nothing because no declared type is a `Refine`.
        self.proof_ctx.refinement_env = RefinementEnv::from_module(module);

        let mut refined: Vec<(Value, PredId)> = self
            .value_ty_map
            .iter()
            .filter_map(|(vid, ty)| match ty {
                Ty::Refine(_, pred) => {
                    let value = self.value_map.get(vid).copied()?;
                    Some((value, *pred))
                }
                _ => None,
            })
            .collect();
        // `value_ty_map` is a HashMap, so fix a deterministic order before touching
        // `value_proofs`: a verified compiler's proof metadata must not depend on hash iteration
        // order (it feeds digests and reports downstream).
        refined.sort_unstable_by_key(|(value, pred)| (value.0, pred.index()));
        refined.dedup();
        for (value, pred) in refined {
            self.proof_ctx
                .value_proofs
                .entry(value)
                .or_default()
                .push(Proof::Refinement { pred });
        }
    }

    /// The refinement predicate declared on a trust-ir value's type, if any.
    ///
    /// `None` — including for a value with no recorded type, and for a value typed by a
    /// non-`Refine` `Ty` — reads as [`trust_ir::pred::Pred::Top`]: no information. That is the
    /// load-bearing direction: a DROPPED fact must never read as a satisfied one.
    fn refinement_pred_of(&self, vid: ValueId) -> Option<PredId> {
        match self.value_ty_map.get(&vid) {
            Some(Ty::Refine(_, pred)) => Some(*pred),
            _ => None,
        }
    }

    /// Translate one trust-ir block into its LIR block, followed by any blocks
    /// a multi-block expansion emitted (`pending_block_split`) and the
    /// continuation block(s) the rest of the trust-ir block lands in. The
    /// first segment is always the trust-ir block's own LIR block.
    #[allow(clippy::type_complexity)]
    fn translate_block(
        &mut self,
        trust_ir_block: &TrustIrBlock,
    ) -> Result<Vec<(Block, BasicBlock, Vec<Option<TrustIrInstId>>)>, AdapterError> {
        let mut bb = BasicBlock::default();
        let mut trust_ir_origins = Vec::new();
        let mut segments = Vec::new();

        // Record the block currently being translated so the EH lowering can
        // attribute an `Inst::Invoke`'s throwing call site to the right block.
        self.current_block_id = Some(trust_ir_block.id);
        self.current_block_has_call = false;
        let mut lir_block = self.map_block(trust_ir_block.id);
        self.current_lir_block = Some(lir_block);

        // Translate block parameters (phi-like).
        for (vid, ty) in &trust_ir_block.params {
            let val = self.map_value(*vid);
            let lir_ty = self.translate_ty(ty)?;
            bb.params.push((val, lir_ty));
        }

        // Translate each instruction in the block body.
        for (instruction_index, node) in trust_ir_block.body.iter().enumerate() {
            let origin = TrustIrInstId(self.next_trust_ir_origin);
            self.next_trust_ir_origin = self.next_trust_ir_origin.saturating_add(1);

            // Extract proof annotations from the trust_ir instruction and attach
            // them to the LIR value that carries the proven fact. Result facts
            // such as NoOverflow stay on results; operand facts such as
            // DivNonZero/ShiftInRange/NotNull/InBounds bind to the source value
            // named by the proof payload. Rich facts use a separate
            // fact-specific carrier selection below so pointer/source facts do
            // not get mis-keyed to load or call results.
            let proof_metadata = extract_proof_metadata(node);
            if !proof_metadata.proofs.is_empty() {
                for proof in &proof_metadata.proofs {
                    for vid in proof_attachment_value_ids(node, proof) {
                        if let (Some(values), Some(function)) =
                            (&self.native_nominal_values, self.trust_ir_func)
                            && values.is_semantic_value(function.id, vid)
                        {
                            return Err(AdapterError::UnsupportedInstruction(
                                "[TCG-NOMINAL-VALUE] proof metadata requires a typed non-runtime nominal carrier".into(),
                            ));
                        }
                        let val = self.map_value(vid);
                        self.proof_ctx
                            .value_proofs
                            .entry(val)
                            .or_default()
                            .push(proof.clone());
                    }
                }
            }
            if !proof_metadata.facts.is_empty() {
                for fact in proof_metadata.facts.iter().copied() {
                    let carrier_ids = self.proof_fact_attachment_value_ids(node, fact);
                    if carrier_ids.is_empty() {
                        self.proof_ctx
                            .diagnostics
                            .push(ProofDropDiagnostic::no_carrier(fact));
                        continue;
                    }

                    for vid in carrier_ids {
                        if let (Some(values), Some(function)) =
                            (&self.native_nominal_values, self.trust_ir_func)
                            && values.is_semantic_value(function.id, vid)
                        {
                            return Err(AdapterError::UnsupportedInstruction(
                                "[TCG-NOMINAL-VALUE] proof fact requires a typed non-runtime nominal carrier".into(),
                            ));
                        }
                        let val = self.map_value(vid);
                        self.proof_ctx
                            .value_facts
                            .entry(val)
                            .or_default()
                            .push(fact);
                    }
                }
            }
            self.proof_ctx
                .diagnostics
                .extend(proof_metadata.diagnostics);

            // Convert trust_ir SourceSpan to SourceLoc for DWARF line numbers.
            let source_loc = node.span.as_ref().map(|span| trust_cg_ir::SourceLoc {
                file: span.file,
                line: span.line,
                col: span.col,
            });
            if let Some(local) = const_value_debug_local(node, origin) {
                self.debug_local_variables.push(local);
            } else if let Some(local) = source_spanned_value_debug_local(node, origin) {
                if let DebugVariableStorage::ProvenanceVar(var_id) = local.storage
                    && let Some(result) = node.results.first().copied()
                {
                    let value = self.map_value(result);
                    self.debug_value_bindings
                        .push(DebugValueBinding { var_id, value });
                }
                self.debug_local_variables.push(local);
            }

            self.current_source_loc = source_loc;
            self.current_trust_ir_origin = Some(origin);
            let instrs = self.translate_instruction(node, trust_ir_block.id, instruction_index)?;
            let lir_instruction_start = bb.instructions.len();
            if let (Some(module), Some(caller)) = (self.module, self.trust_ir_func)
                && self
                    .proof_ctx
                    .aggregate_call_intents
                    .admit_source_origin(origin)
            {
                use crate::aggregate_call_transport::{AggregateCallIntent, AggregateFieldIntent};
                if let Some(intent) = AggregateCallIntent::from_adapter(
                    module,
                    caller,
                    trust_ir_block.id.index(),
                    instruction_index,
                    origin,
                    node,
                    lir_block,
                    lir_instruction_start,
                    &instrs,
                ) {
                    let result = intent.source_result();
                    if let Some(index) = self
                        .proof_ctx
                        .aggregate_call_intents
                        .record_call(caller, intent)
                    {
                        self.aggregate_call_results.insert(result, index);
                    }
                } else if let Inst::ExtractField { aggregate, .. } = &node.inst
                    && let Some(&index) = self.aggregate_call_results.get(aggregate)
                {
                    let call = &self.proof_ctx.aggregate_call_intents.calls()[index];
                    if let Some(field) = AggregateFieldIntent::from_adapter(
                        index,
                        call,
                        trust_ir_block.id.index(),
                        instruction_index,
                        origin,
                        node,
                        lir_block,
                        lir_instruction_start,
                        &instrs,
                    ) {
                        self.proof_ctx.aggregate_call_intents.record_field(field);
                    }
                }
            }

            // All LIR instructions generated from this trust_ir node share
            // the same source location (one trust_ir node -> N LIR instrs).
            // Fuse the exact-call carrier census into this mandatory sidecar
            // loop: ordinary programs get no second LIR scan or allocation.
            for _ in &instrs {
                bb.source_locs.push(source_loc);
                trust_ir_origins.push(Some(origin));
            }
            if self.record_call_census(lir_block, lir_instruction_start, &instrs, origin) {
                self.current_block_has_call = true;
            }
            bb.instructions.extend(instrs);

            // A multi-block expansion ended this LIR block with a jump into
            // blocks of its own; the rest of the trust-ir block continues in
            // the continuation block it names.
            if let Some(split) = self.pending_block_split.take() {
                segments.push((
                    lir_block,
                    std::mem::take(&mut bb),
                    std::mem::take(&mut trust_ir_origins),
                ));
                for (block, mut basic_block) in split.blocks {
                    basic_block.source_locs = vec![source_loc; basic_block.instructions.len()];
                    self.record_call_census(block, 0, &basic_block.instructions, origin);
                    let origins = vec![Some(origin); basic_block.instructions.len()];
                    segments.push((block, basic_block, origins));
                }
                lir_block = split.continuation;
                self.current_lir_block = Some(lir_block);
                // Calls in the expansion's own blocks are not in this block.
                self.current_block_has_call = false;
            }
        }

        segments.push((lir_block, bb, trust_ir_origins));
        Ok(segments)
    }

    /// Record the exact-module / declared-external call carriers among
    /// `instrs`, which occupy `block` from instruction `start` on. Returns
    /// whether any of them is a call.
    fn record_call_census(
        &mut self,
        block: Block,
        start: usize,
        instrs: &[Instruction],
        origin: TrustIrInstId,
    ) -> bool {
        let mut any_call = false;
        for (offset, instruction) in instrs.iter().enumerate() {
            if let Opcode::Call {
                binding: DirectCallBinding::ExactModuleFunction { function },
                ..
            }
            | Opcode::Invoke {
                binding: DirectCallBinding::ExactModuleFunction { function },
                ..
            }
            | Opcode::FunctionAddr { function, .. } = &instruction.opcode
            {
                self.exact_module_calls_lowered += 1;
                self.exact_module_call_authorizations.push(
                    PendingExactModuleCallAuthorization::new(
                        block,
                        start + offset,
                        origin,
                        FuncId::new(*function),
                    ),
                );
            }
            if let Opcode::Call {
                binding: DirectCallBinding::DeclaredExternalFunction { function },
                ..
            }
            | Opcode::Invoke {
                binding: DirectCallBinding::DeclaredExternalFunction { function },
                ..
            } = &instruction.opcode
            {
                self.declared_external_calls_lowered += 1;
                self.declared_external_call_authorizations.push(
                    PendingDeclaredExternalCallAuthorization::new(
                        block,
                        start + offset,
                        origin,
                        FuncId::new(*function),
                    ),
                );
            }
            if matches!(
                instruction.opcode,
                Opcode::Call { .. }
                    | Opcode::Invoke { .. }
                    | Opcode::CallIndirect
                    | Opcode::CallVariadic { .. }
            ) {
                any_call = true;
            }
        }
        any_call
    }

    fn translate_aarch64_fp_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        use crate::aarch64_fp_dialect::{self, Operation};
        let (operation, ty) =
            aarch64_fp_dialect::decode(op).map_err(AdapterError::UnsupportedInstruction)?;
        if self.guard_carrier_arch != GuardCarrierArch::AArch64 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(
                "AArch64 FP instruction requires AArch64 and one SSA result".into(),
            ));
        }
        for &input in &op.operands {
            self.require_trust_ir_operand_type("AArch64 FP", "input", input, &ty)?;
        }
        let result = self.map_result(results)?;
        let result_ty = self.translate_ty(&ty)?;
        self.define_value_type(result, result_ty);
        let opcode = match operation {
            Operation::Fmadd => Opcode::Aarch64FmaddAsm,
            Operation::Fsqrt => Opcode::Aarch64FsqrtAsm,
            Operation::Frintn => Opcode::Aarch64FrintnAsm,
        };
        let args = op.operands.iter().map(|v| self.map_value(*v)).collect();
        Ok(vec![Instruction {
            opcode,
            args,
            results: vec![result],
        }])
    }

    fn translate_trust_cg_bitfield_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode(op).map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let result_ty = self.translate_ty(&spec.ty)?;
        let operands = match spec.kind {
            BitfieldKind::Extract | BitfieldKind::Sextract => {
                let operand = op.operands[0];
                self.require_bitfield_operand_type(op, "operand", operand, &result_ty)?;
                vec![self.map_value(operand)]
            }
            BitfieldKind::Insert => {
                let dst = op.operands[0];
                let src = op.operands[1];
                self.require_bitfield_operand_type(op, "dst", dst, &result_ty)?;
                self.require_bitfield_operand_type(op, "src", src, &result_ty)?;
                vec![self.map_value(dst), self.map_value(src)]
            }
        };

        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty);
        let opcode = match spec.kind {
            BitfieldKind::Extract => Opcode::ExtractBits {
                lsb: spec.lsb,
                width: spec.width,
            },
            BitfieldKind::Sextract => Opcode::SextractBits {
                lsb: spec.lsb,
                width: spec.width,
            },
            BitfieldKind::Insert => Opcode::InsertBits {
                lsb: spec.lsb,
                width: spec.width,
            },
        };

        Ok(vec![Instruction {
            opcode,
            args: operands,
            results: vec![result],
        }])
    }

    fn translate_trust_cg_v4i32_mask_extract_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode_v4i32_mask_extract(op)
            .map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let mask_ty = self
            .lookup_value_ty(mask)
            .ok_or_else(|| AdapterError::UnknownValue(mask.index()))?;
        if !Self::is_v4i32_ty(&mask_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) has type {mask_ty:?}; expected <4 x i32>",
                op.qualified_name(),
                mask.index()
            )));
        }

        let result_ty = self.translate_ty(&spec.result_ty)?;
        debug_assert_eq!(result_ty, Type::I32);
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty);

        Ok(vec![Instruction {
            opcode: Opcode::V4I32MaskExtract,
            args: vec![self.map_value(mask)],
            results: vec![result],
        }])
    }

    fn translate_trust_cg_v2i64_mask_extract_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode_v2i64_mask_extract(op)
            .map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let mask_ty = self
            .lookup_value_ty(mask)
            .ok_or_else(|| AdapterError::UnknownValue(mask.index()))?;
        if !Self::is_v2i64_ty(&mask_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) has type {mask_ty:?}; expected <2 x i64>",
                op.qualified_name(),
                mask.index()
            )));
        }

        let result_ty = self.translate_ty(&spec.result_ty)?;
        debug_assert!(matches!(result_ty, Type::I32 | Type::I64));
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty.clone());

        Ok(vec![Instruction {
            opcode: Opcode::V2I64MaskExtract { result_ty },
            args: vec![self.map_value(mask)],
            results: vec![result],
        }])
    }

    fn translate_trust_cg_v2i64_bool_mask_extract_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode_v2i64_bool_mask_extract(op)
            .map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let mask_ty = self
            .lookup_value_ty(mask)
            .ok_or_else(|| AdapterError::UnknownValue(mask.index()))?;
        if !Self::is_v2_bool_ty(&mask_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) has type {mask_ty:?}; expected <2 x bool>",
                op.qualified_name(),
                mask.index()
            )));
        }
        if !self.value_is_v2i64_icmp_result(mask, &mut HashSet::new()) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) must be produced by a <2 x i64> ICmp",
                op.qualified_name(),
                mask.index()
            )));
        }

        let result_ty = self.translate_ty(&spec.result_ty)?;
        debug_assert!(matches!(result_ty, Type::I32 | Type::I64));
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty.clone());

        Ok(vec![Instruction {
            opcode: Opcode::V2I64MaskExtract { result_ty },
            args: vec![self.map_value(mask)],
            results: vec![result],
        }])
    }

    fn translate_trust_ir_vector_pack_lanes_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // 64-bit (D-register) `<8 x i8>` pack: hashbrown's `uint8x8_t`
        // control-byte splat (`simd_splat`). Read the DialectInst's RAW result
        // type + operands directly — the strict `decode_with_operand_tys` runs
        // the trust-ir vector-dialect shape gate, which only admits `<8 x i8>`
        // in a co-developed trust-ir; a `vector.pack_lanes` DialectInst
        // round-trips opaquely (its result type and operands survive), so this
        // lowers regardless of which trust-ir the backend links against.
        if let Some(result_ty) = op.result_tys.first()
            && Self::is_v8i8_ty(result_ty)
        {
            return self.translate_v8i8_pack_lanes(op, results);
        }
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::PackLanes(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not a pack_lanes op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let vector_ty = self.translate_ty(&spec.vector_ty)?;
        if vector_ty != Type::V128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} vector type {:?} lowers to unsupported LIR type {:?}",
                op.qualified_name(),
                spec.vector_ty,
                vector_ty
            )));
        }
        let lane_ty = self.translate_ty(&spec.elem_ty)?;

        if Self::is_v4i32_ty(&spec.vector_ty) {
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::V128);
            let args = op
                .operands
                .iter()
                .map(|lane| self.map_value(*lane))
                .collect();
            return Ok(vec![Instruction {
                opcode: Opcode::V4I32PackLanes,
                args,
                results: vec![dst],
            }]);
        }

        if Self::is_v2i64_ty(&spec.vector_ty) {
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::V128);
            let args = op
                .operands
                .iter()
                .map(|lane| self.map_value(*lane))
                .collect();
            return Ok(vec![Instruction {
                opcode: Opcode::V2I64PackLanes,
                args,
                results: vec![dst],
            }]);
        }

        // Narrow <16 x i8> / <8 x i16> pack_lanes lower to the typed
        // V16I8PackLanes / V8I16PackLanes ops: both ISels pack the scalar lanes
        // into a V128 register directly (x86-64 via dword bitfield assembly +
        // MOVD/PUNPCK; AArch64 via NEON DUP/INS), so the adapter must not
        // materialize the lanes through a stack slot.
        if Self::is_v16i8_ty(&spec.vector_ty) || Self::is_v8i16_ty(&spec.vector_ty) {
            let opcode = if Self::is_v16i8_ty(&spec.vector_ty) {
                Opcode::V16I8PackLanes
            } else {
                Opcode::V8I16PackLanes
            };
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::V128);
            let args = op
                .operands
                .iter()
                .map(|lane| self.map_value(*lane))
                .collect();
            return Ok(vec![Instruction {
                opcode,
                args,
                results: vec![dst],
            }]);
        }

        self.translate_vector_pack_lanes_stack(&op.operands, spec.lanes, lane_ty, results)
    }

    /// Lower a `<8 x i8>` `vector.pack_lanes` to the V64 (D-register)
    /// `V8I8PackLanes` op. The eight operands are the byte lanes; when they are
    /// all the same value (a splat) the AArch64 ISel collapses to a single
    /// `dup.8b`. Reads the DialectInst's raw operands (no strict decode) so the
    /// V64 shape need not be admitted by the backend's linked trust-ir.
    fn translate_v8i8_pack_lanes(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }
        if op.operands.len() != 8 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} <8 x i8> pack expects 8 lane operands, got {}",
                op.qualified_name(),
                op.operands.len()
            )));
        }
        for lane in &op.operands {
            let lane_ty = self
                .lookup_value_ty(*lane)
                .ok_or_else(|| AdapterError::UnknownValue(lane.index()))?;
            let lir = self.translate_ty(&lane_ty)?;
            if lir != Type::I8 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} <8 x i8> pack lanes must lower to I8, got {:?}",
                    op.qualified_name(),
                    lir
                )));
            }
        }
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::V64);
        let args = op
            .operands
            .iter()
            .map(|lane| self.map_value(*lane))
            .collect();
        Ok(vec![Instruction {
            opcode: Opcode::V8I8PackLanes,
            args,
            results: vec![dst],
        }])
    }

    fn translate_trust_ir_vector_extract_lane_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::ExtractLane(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not an extract_lane op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let vector = op.operands[0];
        let vector_ty = self.translate_ty(&spec.vector_ty)?;
        if vector_ty != Type::V128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} vector type {:?} lowers to unsupported LIR type {:?}",
                op.qualified_name(),
                spec.vector_ty,
                vector_ty
            )));
        }
        let lane_ty = self.translate_ty(&spec.elem_ty)?;
        let vector_val = self.map_value(vector);

        if Self::is_v4i32_ty(&spec.vector_ty) {
            return self.translate_v4i32_extract_lane_direct(vector_val, spec.lane, results);
        }
        if Self::is_v2i64_ty(&spec.vector_ty) {
            return self.translate_v2i64_extract_lane_direct(vector_val, spec.lane, results);
        }

        self.translate_vector_extract_lane_stack(vector_val, spec.lane, lane_ty, results)
    }

    fn translate_trust_ir_vector_insert_lane_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::InsertLane(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not an insert_lane op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let vector = op.operands[0];
        let value = op.operands[1];
        let vector_ty = self.translate_ty(&spec.vector_ty)?;
        if vector_ty != Type::V128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} vector type {:?} lowers to unsupported LIR type {:?}",
                op.qualified_name(),
                spec.vector_ty,
                vector_ty
            )));
        }
        let lane_ty = self.translate_ty(&spec.elem_ty)?;
        let vector_val = self.map_value(vector);
        let elem_val = self.map_value(value);

        if Self::is_v4i32_ty(&spec.vector_ty) {
            return self
                .translate_v4i32_insert_lane_direct(vector_val, elem_val, spec.lane, results);
        }
        if Self::is_v2i64_ty(&spec.vector_ty) {
            return self
                .translate_v2i64_insert_lane_direct(vector_val, elem_val, spec.lane, results);
        }

        self.translate_vector_insert_lane_stack(vector_val, elem_val, spec.lane, lane_ty, results)
    }

    fn translate_trust_ir_vector_mask_to_bits_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::MaskToBits(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not a mask_to_bits op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let result_ty = self.translate_ty(&spec.result_ty)?;
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty.clone());

        if Self::is_v16_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v16i8_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v16_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <16 x i8> ICmp or canonical logical <16 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            if result_ty != Type::I32 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} result type {:?} is unsupported for <16 x bool>; expected i32",
                    op.qualified_name(),
                    spec.result_ty
                )));
            }
            return Ok(vec![Instruction {
                opcode: Opcode::V16I8MaskExtract,
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        if Self::is_v8_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v8i16_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v8_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <8 x i16> ICmp or canonical logical <8 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            if result_ty != Type::I32 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} result type {:?} is unsupported for <8 x bool>; expected i32",
                    op.qualified_name(),
                    spec.result_ty
                )));
            }
            return Ok(vec![Instruction {
                opcode: Opcode::V8I16MaskExtract,
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        if Self::is_v4_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v4i32_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v4_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <4 x i32> ICmp or canonical logical <4 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            debug_assert_eq!(result_ty, Type::I32);
            return Ok(vec![Instruction {
                opcode: Opcode::V4I32MaskExtract,
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        if Self::is_v2_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v2i64_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v2_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <2 x i64> ICmp or canonical logical <2 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            debug_assert!(matches!(result_ty, Type::I32 | Type::I64));
            return Ok(vec![Instruction {
                opcode: Opcode::V2I64MaskExtract { result_ty },
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        Err(AdapterError::UnsupportedInstruction(format!(
            "{} supports only logical <16 x bool>, <8 x bool>, <4 x bool>, and <2 x bool> masks, got {:?}",
            op.qualified_name(),
            spec.mask_ty
        )))
    }

    fn decode_trust_ir_vector_op_with_operand_tys(
        &self,
        op: &DialectInst,
    ) -> Result<vector_dialect::VectorSpec, AdapterError> {
        let operand_tys = op
            .operands
            .iter()
            .map(|value| {
                self.lookup_value_ty(*value)
                    .ok_or_else(|| AdapterError::UnknownValue(value.index()))
            })
            .collect::<Result<Vec<_>, _>>()?;
        vector_dialect::decode_with_operand_tys(op, &operand_tys)
            .map_err(AdapterError::UnsupportedInstruction)
    }

    fn require_bitfield_operand_type(
        &self,
        op: &DialectInst,
        role: &str,
        value: ValueId,
        expected: &Type,
    ) -> Result<(), AdapterError> {
        let actual_ty = self
            .lookup_value_ty(value)
            .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
        let actual = self.translate_ty(&actual_ty)?;
        if &actual != expected {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} {role} type mismatch: operand ValueId({}) has {actual:?}, result has {expected:?}",
                op.qualified_name(),
                value.index()
            )));
        }
        Ok(())
    }

    fn require_trust_ir_operand_type(
        &self,
        context: &str,
        role: &str,
        value: ValueId,
        expected: &Ty,
    ) -> Result<(), AdapterError> {
        let actual = self
            .lookup_value_ty(value)
            .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
        if &actual != expected {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} {role} type mismatch: operand ValueId({}) has {:?}, expected {:?}",
                value.index(),
                actual,
                expected
            )));
        }
        Ok(())
    }

    fn is_integer_scalar_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::I8
                | Ty::I16
                | Ty::I32
                | Ty::I64
                | Ty::I128
                | Ty::U8
                | Ty::U16
                | Ty::U32
                | Ty::U64
                | Ty::U128
                // v25 pointer-width integers plus Char's 32-bit unsigned
                // arithmetic carrier (matching the TrustIr interpreter).
                | Ty::Isize
                | Ty::Usize
                | Ty::Char
        )
    }

    /// The integer scalars trust-ir admits for the WS3.20 bit intrinsics
    /// (`RotL`/`RotR`, `CtLz`/`CtTz`/`BSwap`/`BitReverse`): trust-ir's
    /// `Ty::is_integer`, which — unlike [`Self::is_integer_scalar_ty`] — does
    /// not count `Char`'s arithmetic carrier.
    fn is_bit_intrinsic_integer_ty(ty: &Ty) -> bool {
        Self::is_integer_scalar_ty(ty) && !matches!(ty, Ty::Char)
    }

    fn is_pointer_like_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Func(_)
        )
    }

    /// Exact typed carriers on which importer/rustc-producer `0xFADE`
    /// global-address stubs are meaningful.
    ///
    /// The rustc bridge normally uses `Ptr`, but const operands retain their
    /// faithful thin reference/raw-pointer type when passed through
    /// `emit_const_alloc_addr`. `I64` is the legacy vtable/address carrier.
    /// `Rc` is intentionally absent (its ownership ABI is unsupported), and
    /// `Func` is absent because data-global stubs are not code pointers.
    fn is_imported_global_addr_carrier(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::I64 | Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_)
        )
    }

    /// True iff a by-value parameter of trust-ir type `ty` is carried across the
    /// call boundary by ADDRESS (a constructed aggregate materialized into a stack
    /// slot whose `Ptr` is the argument value). The bridge passes every by-value
    /// aggregate (`Struct`/`Tuple`/`Record`/`Array`/`Enum`) and the boundary slice
    /// fat pointer (`FatPtr`, a `{ data, len }` slot) this way; the argument's
    /// producing instruction (`Alloca`/StructGep/`Copy`) therefore types it as a
    /// `Ptr`. ISel's SysV eightbyte classifier reads the LIR aggregate type seeded
    /// by `record_aggregate_call_arg_types` on a call-site-scoped `Copy` temp
    /// (from the callee param signature) — not the trust-ir `Ptr`, and never the
    /// argument's own ValueId — to place data+len/lanes in the register pair /
    /// sret / stack slot the callee's by-value parameter ABI expects. So a `Ptr`
    /// argument for an aggregate parameter is the established, sound
    /// representation.
    fn is_aggregate_address_passed_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Struct(_)
                | Ty::Tuple(_)
                | Ty::Record(_)
                | Ty::Array(_, _)
                | Ty::Enum(_)
                | Ty::FatPtr(_)
        )
    }

    /// Whether an argument whose producing-instruction trust-ir type is `actual`
    /// satisfies a callee parameter declared as `expected`. Beyond exact equality
    /// this admits the sound mismatches the bridge relies on, both of which the
    /// argument value carries as a plain `Ptr` (an address / pointer carrier):
    ///
    ///   * an aggregate parameter passed BY ADDRESS, where `expected` is an
    ///     aggregate type and the argument is the `Ptr` to its bytes (see
    ///     `is_aggregate_address_passed_ty`); and
    ///   * a reference / raw-pointer parameter (`Ref`/`RefMut`/`PtrConst`/`PtrMut`)
    ///     satisfied by a `Ptr` — every pointer-like type is one 64-bit pointer
    ///     carrier, so a closure env passed as a `Ptr` to a body fn whose param is
    ///     `Ref(Closure)` (the `FnOnce::call_once` ClosureOnceShim chain) is the
    ///     same bits in the same register.
    ///
    /// A `Func(_)` (code-pointer) parameter is deliberately NOT admitted from a
    /// `Ptr`: a raw data pointer must never be used as a call target without
    /// explicit code-pointer provenance (the same fail-closed stance
    /// `CallIndirect` takes). Every other mismatch still fails closed.
    fn call_arg_ty_compatible(actual: &Ty, expected: &Ty) -> bool {
        actual == expected
            || (matches!(actual, Ty::Ptr)
                && (Self::is_aggregate_address_passed_ty(expected)
                    || matches!(
                        expected,
                        Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_)
                    )))
    }

    fn is_float_scalar_ty(ty: &Ty) -> bool {
        matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
    }

    /// Reject BinOps whose operands do not match the declared scalar type, and
    /// pointer arithmetic whose operands are not (Ptr, integer). This is the
    /// fail-closed safety gate that keeps a type-confused `Iadd` over a float
    /// (or mismatched operand widths) from silently lowering.
    fn validate_binop_operand_tys(
        &self,
        op: BinOp,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
    ) -> Result<(), AdapterError> {
        if matches!((op, ty), (BinOp::Add | BinOp::Sub, Ty::Ptr)) {
            let lhs_ty = self.lookup_value_ty(lhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} lhs operand {lhs:?} has no known trust_ir type"
                ))
            })?;
            let rhs_ty = self.lookup_value_ty(rhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} rhs operand {rhs:?} has no known trust_ir type"
                ))
            })?;
            if lhs_ty != Ty::Ptr || !Self::is_integer_scalar_ty(&rhs_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} pointer arithmetic requires declared ty=Ptr, lhs Ptr, and integer scalar rhs; \
                     lhs {lhs:?} has type {lhs_ty:?}, rhs {rhs:?} has type {rhs_ty:?}"
                )));
            }
            return Ok(());
        }

        // A shift's RHS is a COUNT, not a value of the shifted type: in trust_ir
        // (as in Rust MIR and LLVM) the shift amount may be a *different* integer
        // width than the shifted operand — e.g. `i8 >> 1` carries an I32 literal
        // count, and `i64 << (x as u32)` an I32 count. x86-64 takes the count
        // from CL regardless of its declared width (and the ISel `select_shift`
        // moves the amount into the RCX subregister matching its OWN width), so
        // requiring the count to match the shifted type is wrong and would fail a
        // well-typed shift closed. Validate the shifted operand (LHS) against the
        // declared type, but only require the count (RHS) to be an integer scalar.
        if matches!(op, BinOp::Shl | BinOp::LShr | BinOp::AShr) {
            let lhs_ty = self.lookup_value_ty(lhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} lhs operand {lhs:?} has no known trust_ir type"
                ))
            })?;
            if lhs_ty != *ty {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} lhs operand type mismatch: declared ty={ty:?}, \
                     operand {lhs:?} has type {lhs_ty:?}"
                )));
            }
            let rhs_ty = self.lookup_value_ty(rhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} rhs (shift count) operand {rhs:?} has no known trust_ir type"
                ))
            })?;
            if !Self::is_integer_scalar_ty(&rhs_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} shift count {rhs:?} must be an integer scalar, has type {rhs_ty:?}"
                )));
            }
            return Ok(());
        }

        self.validate_binary_operand_tys(&format!("BinOp::{op:?}"), ty, lhs, rhs)
    }

    fn validate_binary_operand_tys(
        &self,
        context: &str,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
    ) -> Result<(), AdapterError> {
        for (side, value) in [("lhs", lhs), ("rhs", rhs)] {
            let actual_ty = self.lookup_value_ty(value).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "{context} {side} operand {value:?} has no known trust_ir type"
                ))
            })?;

            // Accept an operand whose declared integer type differs from `ty`
            // ONLY in signedness (same bit width, both pure integer scalars):
            // trust_ir carries the bits identically (U64 and I64 are one 64-bit
            // register value) and the signedness of an operation lives in the
            // OPCODE (Sdiv vs Udiv, signed vs unsigned Icmp condition), never the
            // operand type. A width mismatch, or a Bool / pointer vs. integer
            // mismatch, is still rejected.
            if actual_ty != *ty && !Self::same_width_int_scalar(&actual_ty, ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{context} {side} operand type mismatch: declared ty={ty:?}, \
                     operand {value:?} has type {actual_ty:?}"
                )));
            }
        }

        Ok(())
    }

    /// Whether `a` and `b` are pure integer scalar types of the SAME bit width,
    /// differing at most in signedness (e.g. U64 vs I64). Pointers, `Bool`, and
    /// references are deliberately excluded — they require an exact type match.
    fn same_width_int_scalar(a: &Ty, b: &Ty) -> bool {
        fn pure_int_bits(ty: &Ty) -> Option<u32> {
            match ty {
                Ty::I8 | Ty::U8 => Some(8),
                Ty::I16 | Ty::U16 => Some(16),
                Ty::I32 | Ty::U32 => Some(32),
                Ty::I64 | Ty::U64 => Some(64),
                Ty::I128 | Ty::U128 => Some(128),
                Ty::Isize | Ty::Usize => Some(64),
                Ty::Char => Some(32),
                _ => None,
            }
        }
        matches!((pure_int_bits(a), pure_int_bits(b)), (Some(x), Some(y)) if x == y)
    }

    /// Reject scalar BinOps whose declared type is incompatible with the opcode
    /// family (e.g. integer/shift ops over a float type, float ops over an
    /// integer type). Vector shapes are validated by their dedicated typed
    /// lowering arms before this is reached.
    fn validate_scalar_binop_shape(&self, op: BinOp, ty: &Ty) -> Result<(), AdapterError> {
        let supported = match op {
            BinOp::Add | BinOp::Sub if matches!(ty, Ty::Ptr) => true,
            BinOp::Add
            | BinOp::Sub
            | BinOp::Mul
            | BinOp::UDiv
            | BinOp::SDiv
            | BinOp::URem
            | BinOp::SRem
            | BinOp::Shl
            | BinOp::LShr
            | BinOp::AShr => Self::is_integer_scalar_ty(ty),
            BinOp::And | BinOp::Or | BinOp::Xor => {
                matches!(ty, Ty::Bool) || Self::is_integer_scalar_ty(ty)
            }
            // Trust: the BOOLEAN connectives (trust-ir 4b06918). STRICTER than the
            // overloaded And/Or/Xor above, matching trust-ir's own validator, which
            // admits BAnd/BOr/BXor on Bool only -- an integer operand means the
            // frontend picked the wrong opcode.
            BinOp::BAnd | BinOp::BOr | BinOp::BXor => matches!(ty, Ty::Bool),
            // FRem is handled entirely by its dedicated lowering arm above
            // (which returns before this shape gate): f32/f64 call fmod/fmodf,
            // and f16 promotes to f32, calls fmodf, and demotes (fmod is exact).
            // This arm is unreachable for FRem but kept width-accurate.
            BinOp::FRem => matches!(ty, Ty::F16 | Ty::F32 | Ty::F64),
            // FAdd/FSub/FMul/FDiv are correctly-rounded in binary16 on FEAT_FP16
            // (native FADD/FSUB/FMUL/FDIV Hd,Hn,Hm; F32 is exactly 2p+2 wide so
            // even a promote/compute/demote lowering rounds once), and FMin/FMax
            // (FMINNM/FMAXNM Hd) are exact. Width is carried by the Fpr16 operand
            // class in isel; the verifier models binary16 via fp_bitmodel::F16.
            BinOp::FAdd | BinOp::FSub | BinOp::FMul | BinOp::FDiv | BinOp::FMin | BinOp::FMax => {
                matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
            }
            // trust-ir WS3.20 (F-057). The rotates are integer-only like the
            // shifts, and `Char` is not an integer to trust-ir's validator, so
            // it is refused here too. Lowered by `translate_scalar_rotate`.
            BinOp::RotL | BinOp::RotR => Self::is_bit_intrinsic_integer_ty(ty),
            // IEEE copySign is float-only like FMin/FMax. Lowered by
            // `translate_scalar_copysign` as a sign-bit merge.
            BinOp::FCopySign => matches!(ty, Ty::F16 | Ty::F32 | Ty::F64),
        };

        if !supported {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "BinOp::{op:?} declared type is not supported for scalar lowering: {ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_unop_shape(&self, op: UnOp, ty: &Ty, operand: ValueId) -> Result<(), AdapterError> {
        let actual_ty = self.lookup_value_ty(operand).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "UnOp::{op:?} operand {operand:?} has no known trust_ir type"
            ))
        })?;
        if actual_ty != *ty {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "UnOp::{op:?} operand type mismatch: declared ty={ty:?}, \
                 operand {operand:?} has type {actual_ty:?}"
            )));
        }

        let supported = match op {
            UnOp::Neg | UnOp::CtPop => Self::is_integer_scalar_ty(ty),
            // All F16 unary FP ops have native FEAT_FP16 encodings and are exact
            // (FNEG/FABS sign-bit ops; FRINTM/FRINTP/FRINTZ round-to-integral) or
            // correctly-rounded (FSQRT Hd). Width is carried by the Fpr16 operand
            // class; the verifier models binary16 via fp_bitmodel::F16.
            UnOp::FNeg | UnOp::FAbs | UnOp::FSqrt | UnOp::FFloor | UnOp::FCeil | UnOp::FTrunc => {
                matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
            }
            // Never a scalar `Bool`: trust-ir's validator refuses it by name
            // (`UnOpNotOnScalarBool`, WS2.21) and its interpreter has no
            // scalar `Bool` arm for `not`. A `bool` negation is `bxor b, true`
            // (the ratified spelling) or `icmp eq b, false`, which keep the
            // 0/1 value.
            UnOp::Not => Self::is_integer_scalar_ty(ty),
            // trust-ir WS3.20 (F-057): integer-only like CtPop, and not over
            // `Char` (not an integer to trust-ir's validator). Lowered by
            // `translate_scalar_bit_intrinsic`.
            UnOp::CtLz | UnOp::CtTz | UnOp::BSwap | UnOp::BitReverse => {
                Self::is_bit_intrinsic_integer_ty(ty)
            }
        };

        if !supported {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "UnOp::{op:?} declared type is not supported for scalar lowering: {ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_icmp_shape(&self, op: ICmpOp, ty: &Ty) -> Result<(), AdapterError> {
        let supported = if Self::is_integer_scalar_ty(ty) {
            true
        } else if matches!(ty, Ty::Bool) {
            matches!(op, ICmpOp::Eq | ICmpOp::Ne)
        } else if Self::is_pointer_like_ty(ty) {
            // A pointer carries its address in an integer register of pointer
            // width, so Eq/Ne AND the UNSIGNED orderings (Ult/Ule/Ugt/Uge) are
            // all meaningful address comparisons — e.g. hashbrown's
            // `RawIterRange::next_impl` computes `current >= end` over two data
            // pointers. Each lowers to the same unsigned-condition `Icmp` over
            // the pointer-width operands as an integer scalar of pointer width;
            // this matches the trust-ir reference semantics, which compares the
            // pointers by address. The SIGNED orderings (Slt/Sle/Sgt/Sge) are
            // deliberately NOT admitted: an address is an unsigned quantity, so
            // a signed pointer ordering is never a well-formed frontend emission
            // — fail closed.
            matches!(
                op,
                ICmpOp::Eq | ICmpOp::Ne | ICmpOp::Ult | ICmpOp::Ule | ICmpOp::Ugt | ICmpOp::Uge
            )
        } else {
            false
        };

        if !supported {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "ICmp::{op:?} declared type must be an integer scalar, Bool Eq/Ne, \
                 pointer-like Eq/Ne, or pointer-like unsigned ordering (Ult/Ule/Ugt/Uge); got {ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_fcmp_shape(&self, ty: &Ty, lhs: ValueId, rhs: ValueId) -> Result<(), AdapterError> {
        if !Self::is_float_scalar_ty(ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "FCmp declared type must be a scalar float, got {ty:?}"
            )));
        }

        for (side, value) in [("lhs", lhs), ("rhs", rhs)] {
            let actual_ty = self.lookup_value_ty(value).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "FCmp {side} operand {value:?} has no known trust_ir type"
                ))
            })?;

            if actual_ty != *ty {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "FCmp {side} operand type mismatch: declared ty={ty:?}, \
                     operand {value:?} has type {actual_ty:?}"
                )));
            }
        }

        Ok(())
    }

    fn is_float_ty(ty: &Ty) -> bool {
        matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
    }

    fn switch_selector_bits(ty: &Ty) -> Result<u32, AdapterError> {
        match ty {
            // A Rust `bool` is a 1-byte value (guaranteed 0 or 1), and rustc
            // lowers `if` / loop / `assert!` conditions to `switchInt(bool)`.
            // Treat it as an 8-bit selector: the x86 ISel zero-extends the
            // loaded byte and masks it to {0,1} (normalize_condition_operand's
            // B1 path) before the per-case equality compare, so the undefined
            // high bits of the byte are never read. Without this the backend
            // fails closed on essentially every branch/loop in a debug build.
            Ty::Bool => Ok(8),
            Ty::I8 | Ty::U8 => Ok(8),
            Ty::I16 | Ty::U16 => Ok(16),
            Ty::I32 | Ty::U32 => Ok(32),
            Ty::I64 | Ty::U64 => Ok(64),
            Ty::Isize | Ty::Usize => Ok(64),
            Ty::Char => Ok(32),
            // 128-bit selectors never reach the 64-bit `Opcode::Switch`
            // directly: `translate_i128_switch` splits the selector into its
            // 64-bit halves and dispatches on both (see
            // `validate_i128_switch_case_values`).
            Ty::I128 | Ty::U128 => Ok(128),
            _ => Err(AdapterError::UnsupportedInstruction(format!(
                "non-integer switch selector type: {:?}",
                ty
            ))),
        }
    }

    /// The full 128-bit pattern of one I128/U128 switch case constant.
    ///
    /// Every case is honored as a complete 128-bit value: an `I128` selector
    /// takes any `Constant::Int` as its two's-complement pattern; a `U128`
    /// selector takes the non-negative `Constant::Int` half and the canonical
    /// `Constant::U128` half of trust-ir's one-spelling rule
    /// (`validate_canonical_u128`). Everything else is refused by name:
    /// a `Constant::U128` on an `I128` selector exceeds `i128::MAX`, a negative
    /// `Constant::Int` on a `U128` selector is not a raw bit pattern, and a
    /// non-canonical `Constant::U128` would give one value two spellings.
    fn normalize_i128_switch_case_value(
        selector_ty: &Ty,
        value: &Constant,
    ) -> Result<u128, AdapterError> {
        match (selector_ty, value) {
            (Ty::I128, Constant::Int(raw)) => Ok(*raw as u128),
            (Ty::U128, Constant::Int(raw)) if *raw >= 0 => Ok(*raw as u128),
            (Ty::U128, Constant::Int(raw)) => Err(AdapterError::UnsupportedInstruction(format!(
                "negative switch case value {raw} overflows the U128 selector: values above \
                 i128::MAX must use Constant::U128 and negative Int values are not raw bits"
            ))),
            (Ty::U128, Constant::U128(v)) => {
                Self::validate_canonical_u128(selector_ty, *v)?;
                Ok(*v)
            }
            (Ty::I128, Constant::U128(v)) => Err(AdapterError::UnsupportedInstruction(format!(
                "switch case value Constant::U128({v}) overflows the I128 selector (exceeds \
                 i128::MAX)"
            ))),
            (_, other) => Err(AdapterError::UnsupportedInstruction(format!(
                "non-integer switch case value: {:?}",
                other
            ))),
        }
    }

    /// Normalize every case of an I128/U128 switch to its 128-bit pattern and
    /// refuse a duplicate by name. Two constants that agree in their low 64
    /// bits but differ in their high 64 bits are distinct cases, never a
    /// duplicate: the whole pattern is the key.
    fn validate_i128_switch_case_values(
        selector_ty: &Ty,
        cases: &[trust_ir::SwitchCase],
    ) -> Result<Vec<u128>, AdapterError> {
        let mut seen = HashSet::with_capacity(cases.len());
        let mut patterns = Vec::with_capacity(cases.len());
        for case in cases {
            let pattern = Self::normalize_i128_switch_case_value(selector_ty, &case.value)?;
            if !seen.insert(pattern) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "duplicate 128-bit switch case value: {:?} repeats the pattern {pattern:#034x}",
                    case.value
                )));
            }
            patterns.push(pattern);
        }
        Ok(patterns)
    }

    /// The LIR block a switch edge jumps to: the target itself when the edge
    /// carries no block arguments, otherwise a fresh copy block that performs
    /// the edge's copies and jumps on (issue #304: copies must execute only
    /// on their own edge).
    fn switch_edge_dest(
        &mut self,
        target: BlockId,
        args: &[ValueId],
    ) -> Result<Block, AdapterError> {
        let copies = self.resolve_block_args(target, args)?;
        let real_dest = self.map_block(target);
        if copies.is_empty() {
            return Ok(real_dest);
        }
        let copy_block_id = self.fresh_block();
        let mut copy_bb = BasicBlock {
            instructions: copies,
            ..Default::default()
        };
        copy_bb.instructions.push(Instruction {
            opcode: Opcode::Jump { dest: real_dest },
            args: vec![],
            results: vec![],
        });
        self.pending_extra_blocks.push((copy_block_id, copy_bb));
        Ok(copy_block_id)
    }

    /// Lower `Inst::Switch` over an I128/U128 selector.
    ///
    /// The 64-bit `Opcode::Switch` cannot carry a 128-bit case constant, so the
    /// selector is split into its two 64-bit halves and BOTH are dispatched on:
    ///
    /// ```text
    /// lo = Trunc(I64, sel)                 // low half
    /// hi = Trunc(I64, Ushr(sel, 64))       // high half
    /// <compare tree over the distinct high halves of the case constants>
    ///   leaf(H): Switch lo { lo_i -> dest_i | hi_i == H } default
    ///   miss   : default
    /// ```
    ///
    /// A case constant `c` dispatches to its target iff `hi == hi(c)` AND
    /// `lo == lo(c)`, i.e. iff the selector equals `c` as a full 128-bit value.
    /// When every case shares one high half the tree is a single equality
    /// check guarding one low-half `Switch`, which ISel lowers as a jump table
    /// when the low halves are dense and as a compare chain otherwise; several
    /// distinct high halves get a balanced unsigned compare tree whose leaves
    /// are per-group low-half switches. A selector whose high half matches no
    /// case constant's high half goes straight to the default edge, so a
    /// low-half collision between cases of different high halves can never
    /// mis-dispatch. Every emitted operation is an existing lowered primitive
    /// (i128 `Trunc`/constant `Ushr`, 64-bit `Iconst`/`Icmp`, `Brif`, and the
    /// 64-bit `Switch`); no new opcode or proof form is introduced.
    fn translate_i128_switch(
        &mut self,
        value: &ValueId,
        selector_ty: &Ty,
        default: &BlockId,
        default_args: &[ValueId],
        cases: &[trust_ir::SwitchCase],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let patterns = Self::validate_i128_switch_case_values(selector_ty, cases)?;
        let selector = self.map_value(*value);
        let default_dest = self.switch_edge_dest(*default, default_args)?;

        // Group the cases by high half; within a group the low halves are the
        // 64-bit `Switch` constants (bit-exact two's-complement reinterpretation,
        // compared at native 64-bit width like any 64-bit selector).
        let mut groups: BTreeMap<u64, Vec<(i64, Block)>> = BTreeMap::new();
        for (case, pattern) in cases.iter().zip(patterns) {
            let dest = self.switch_edge_dest(case.target, &case.args)?;
            let hi = (pattern >> 64) as u64;
            let lo = pattern as u64 as i64;
            groups.entry(hi).or_default().push((lo, dest));
        }

        // Split the selector.
        let mut instrs = Vec::new();
        let lo = self.fresh_value();
        self.define_value_type(lo, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Trunc { to_ty: Type::I64 },
            args: vec![selector],
            results: vec![lo],
        });
        let sixty_four = self.fresh_value();
        self.define_value_type(sixty_four, Type::I128);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I128,
                imm: 64,
            },
            args: vec![],
            results: vec![sixty_four],
        });
        let shifted = self.fresh_value();
        self.define_value_type(shifted, Type::I128);
        instrs.push(Instruction {
            opcode: Opcode::Ushr,
            args: vec![selector, sixty_four],
            results: vec![shifted],
        });
        let hi = self.fresh_value();
        self.define_value_type(hi, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Trunc { to_ty: Type::I64 },
            args: vec![shifted],
            results: vec![hi],
        });

        // One leaf block per distinct high half: the low-half switch.
        let mut leaves: Vec<(u64, Block)> = Vec::with_capacity(groups.len());
        for (hi_pattern, lo_cases) in groups {
            let leaf = self.fresh_block();
            let leaf_bb = BasicBlock {
                instructions: vec![Instruction {
                    opcode: Opcode::Switch {
                        cases: lo_cases,
                        default: default_dest,
                    },
                    args: vec![lo],
                    results: vec![],
                }],
                ..Default::default()
            };
            self.pending_extra_blocks.push((leaf, leaf_bb));
            leaves.push((hi_pattern, leaf));
        }

        if leaves.is_empty() {
            // No cases at all: every selector takes the default edge.
            instrs.push(Instruction {
                opcode: Opcode::Jump { dest: default_dest },
                args: vec![],
                results: vec![],
            });
            return Ok(instrs);
        }

        self.emit_i128_switch_hi_tree(&mut instrs, hi, &leaves, default_dest);
        Ok(instrs)
    }

    /// Emit the balanced unsigned compare tree over the sorted distinct high
    /// halves `leaves` into `instrs` (the current block); interior subtrees go
    /// to fresh pending blocks. A single leaf is an equality test against its
    /// high half with the default edge as the miss target.
    fn emit_i128_switch_hi_tree(
        &mut self,
        instrs: &mut Vec<Instruction>,
        hi: Value,
        leaves: &[(u64, Block)],
        default_dest: Block,
    ) {
        debug_assert!(!leaves.is_empty());
        debug_assert!(leaves.windows(2).all(|w| w[0].0 < w[1].0));
        let iconst = |this: &mut Self, instrs: &mut Vec<Instruction>, imm: u64| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: imm as i64,
                },
                args: vec![],
                results: vec![v],
            });
            v
        };
        if let [(hi_pattern, leaf)] = leaves {
            let expected = iconst(self, instrs, *hi_pattern);
            let eq = self.fresh_value();
            self.define_value_type(eq, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::Icmp { cond: IntCC::Equal },
                args: vec![hi, expected],
                results: vec![eq],
            });
            instrs.push(Instruction {
                opcode: Opcode::Brif {
                    cond: eq,
                    then_dest: *leaf,
                    else_dest: default_dest,
                },
                args: vec![eq],
                results: vec![],
            });
            return;
        }
        let mid = leaves.len() / 2;
        let pivot = iconst(self, instrs, leaves[mid].0);
        let below = self.fresh_value();
        self.define_value_type(below, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp {
                cond: IntCC::UnsignedLessThan,
            },
            args: vec![hi, pivot],
            results: vec![below],
        });
        let left_block = self.fresh_block();
        let right_block = self.fresh_block();
        instrs.push(Instruction {
            opcode: Opcode::Brif {
                cond: below,
                then_dest: left_block,
                else_dest: right_block,
            },
            args: vec![below],
            results: vec![],
        });
        let mut left_instrs = Vec::new();
        self.emit_i128_switch_hi_tree(&mut left_instrs, hi, &leaves[..mid], default_dest);
        self.pending_extra_blocks.push((
            left_block,
            BasicBlock {
                instructions: left_instrs,
                ..Default::default()
            },
        ));
        let mut right_instrs = Vec::new();
        self.emit_i128_switch_hi_tree(&mut right_instrs, hi, &leaves[mid..], default_dest);
        self.pending_extra_blocks.push((
            right_block,
            BasicBlock {
                instructions: right_instrs,
                ..Default::default()
            },
        ));
    }

    fn normalize_switch_case_value(
        value: &Constant,
        selector_bits: u32,
    ) -> Result<i64, AdapterError> {
        let Constant::Int(raw) = value else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "non-integer switch case value: {:?}",
                value
            )));
        };

        debug_assert!(matches!(selector_bits, 8 | 16 | 32 | 64));
        let modulus = 1_i128 << selector_bits;
        let sign_bit = 1_i128 << (selector_bits - 1);
        let normalized = raw.rem_euclid(modulus);
        let signed = if selector_bits <= 16 {
            // A narrow (I8/I16) selector is ZERO-extended to a full GPR before
            // the per-case equality compare: `select_switch` runs the selector
            // through `normalize_condition_operand` under the signedness-agnostic
            // `Equal` condition, which selects `Movzx`/`MovzxW`. The case
            // constant must therefore be its ZERO-extended bit pattern, not a
            // sign-extended value — a high-bit case like a `u8` 0xFF (or, in the
            // same byte, an `i8` -1) must compare as 255, the value the widened
            // selector actually holds. Sign-extending it to -1 would emit a
            // `cmp r64, -1` (0xFFFF_FFFF_FFFF_FFFF) that never matches the
            // zero-extended selector (MISCOMPILE #62). `normalized` is already in
            // [0, 2^bits) and fits i64.
            normalized
        } else if normalized >= sign_bit {
            // 32/64-bit selectors are compared at their native width with no
            // widening, so the 2's-complement i64 reinterpretation is bit-exact.
            normalized - modulus
        } else {
            normalized
        };

        i64::try_from(signed).map_err(|_| {
            AdapterError::UnsupportedInstruction(format!(
                "switch case value {} cannot be represented after {}-bit selector normalization",
                raw, selector_bits
            ))
        })
    }

    fn validate_switch_case_values(
        cases: &[trust_ir::SwitchCase],
        selector_bits: u32,
    ) -> Result<Vec<i64>, AdapterError> {
        let mut seen = HashSet::with_capacity(cases.len());
        let mut normalized_values = Vec::with_capacity(cases.len());
        for case in cases {
            let normalized = Self::normalize_switch_case_value(&case.value, selector_bits)?;
            if !seen.insert(normalized) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "duplicate switch case value after {}-bit selector normalization: {:?} normalizes to {}",
                    selector_bits, case.value, normalized
                )));
            }
            normalized_values.push(normalized);
        }
        Ok(normalized_values)
    }

    fn is_integer_like_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Bool
                | Ty::I8
                | Ty::I16
                | Ty::I32
                | Ty::I64
                | Ty::I128
                | Ty::U8
                | Ty::U16
                | Ty::U32
                | Ty::U64
                | Ty::U128
                // v25 pointer-width integers and Char's 32-bit unsigned
                // arithmetic/cast carrier.
                | Ty::Isize
                | Ty::Usize
                | Ty::Char
        )
    }

    fn cast_scalar_bits(ty: &Ty) -> Option<u32> {
        match ty {
            Ty::Bool | Ty::I8 | Ty::U8 => Some(8),
            Ty::I16 | Ty::U16 | Ty::F16 => Some(16),
            Ty::I32 | Ty::U32 | Ty::F32 => Some(32),
            Ty::I64 | Ty::U64 | Ty::F64 | Ty::Ptr => Some(64),
            Ty::I128 | Ty::U128 => Some(128),
            Ty::Isize | Ty::Usize => Some(64),
            Ty::Char => Some(32),
            Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Func(_) => Some(64),
            _ => None,
        }
    }

    /// Fail-closed safety gate for casts. Rejects operand/declared-source
    /// mismatches and any cast whose source/destination shapes are invalid for
    /// the requested cast family (wrong-direction resize, non-pointer pointer
    /// casts, etc.). `Transmute`/`ReifyFnPointer` carry their own provenance
    /// checks in `translate_cast` and are passed through here.
    fn validate_cast_shape(
        &self,
        op: &CastOp,
        src_ty: &Ty,
        dst_ty: &Ty,
        operand: ValueId,
    ) -> Result<(), AdapterError> {
        if matches!(op, CastOp::Transmute | CastOp::ReifyFnPointer) {
            return Ok(());
        }

        let actual_ty = self.lookup_value_ty(operand).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "CastOp::{op:?} operand {operand:?} has no known trust_ir type"
            ))
        })?;
        if actual_ty != *src_ty {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CastOp::{op:?} source type mismatch: declared src_ty={src_ty:?}, \
                 operand {operand:?} has type {actual_ty:?}"
            )));
        }

        let src_bits = Self::cast_scalar_bits(src_ty);
        let dst_bits = Self::cast_scalar_bits(dst_ty);
        let valid = match op {
            CastOp::Trunc => {
                Self::is_integer_like_ty(src_ty)
                    && Self::is_integer_like_ty(dst_ty)
                    && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst < src)
            }
            CastOp::ZExt | CastOp::SExt => {
                if matches!(src_ty, Ty::Bool) {
                    // A `Bool` source is a logical 1-bit value (machine `Type::B1`);
                    // it zero/sign-extends to ANY wider integer, lowering to the
                    // SAME `Uextend`/`Sextend` (from `B1`) already used for
                    // `Bool -> I16/I32/I64`. `cast_scalar_bits` widens `Bool` to 8
                    // for byte-level reasoning, which would spuriously reject the
                    // genuine widening `Bool(B1) -> I8` (both look like 8 bits), so
                    // treat a `Bool` source as the narrowest integer here. `dst`
                    // must be a non-`Bool` integer (a `Bool -> Bool` "extension" is
                    // not a real cast).
                    Self::is_integer_like_ty(dst_ty) && !matches!(dst_ty, Ty::Bool)
                } else {
                    Self::is_integer_like_ty(src_ty)
                        && Self::is_integer_like_ty(dst_ty)
                        && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst > src)
                }
            }
            CastOp::FPTrunc => {
                Self::is_float_ty(src_ty)
                    && Self::is_float_ty(dst_ty)
                    && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst < src)
            }
            CastOp::FPExt => {
                Self::is_float_ty(src_ty)
                    && Self::is_float_ty(dst_ty)
                    && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst > src)
            }
            CastOp::FPToSI | CastOp::FPToUI => {
                Self::is_float_ty(src_ty) && Self::is_integer_like_ty(dst_ty)
            }
            // Saturating float->int casts share the FPToSI/FPToUI shape rule.
            // Translation below selects a destination-width-specific audited
            // expansion; this validation must not collapse them into the raw
            // non-saturating cast variants.
            CastOp::FPToSISat | CastOp::FPToUISat => {
                Self::is_float_ty(src_ty) && Self::is_integer_like_ty(dst_ty)
            }
            CastOp::SIToFP | CastOp::UIToFP => {
                Self::is_integer_like_ty(src_ty) && Self::is_float_ty(dst_ty)
            }
            CastOp::PtrToInt => {
                Self::is_pointer_like_ty(src_ty)
                    && Self::is_integer_like_ty(dst_ty)
                    && dst_bits == Some(64)
            }
            CastOp::IntToPtr => {
                Self::is_integer_like_ty(src_ty)
                    && src_bits == Some(64)
                    && Self::is_pointer_like_ty(dst_ty)
            }
            CastOp::PtrToPtr => {
                Self::is_pointer_like_ty(src_ty) && Self::is_pointer_like_ty(dst_ty)
            }
            CastOp::Bitcast => {
                // Scalar-only, on purpose. A vector reinterpretation
                // (`<2 x f64>` -> `<2 x i64>`, `<2 x u64>` -> `<4 x i32>`,
                // `<8 x u8>` -> `<1 x u64>`) is refused even at equal total
                // width, and `cast_scalar_bits` returning `None` for
                // `Ty::Vector` is what refuses it.
                //
                // Ruling (2026-09-21): a shape enters the lowering lane only
                // if (a) trust-ir's semantic model defines its meaning AND
                // (b) trust-cg's translation-validation / proof lane covers
                // the lowering. Vector bitcast fails (a) at the pinned
                // trust-ir (283f1747): the Lean model's `semCast` `.Bitcast`
                // arm ends in `Sem.throwTypeError "Bitcast: unsupported
                // operand type"` for a `.vector` operand and `Ty.Vector` has
                // no `byteSize`/`encodeValue` at all
                // (`lean/trust_ir-semantics/TrustIr/Semantics/Cast.lean`,
                // `Semantics/Memory.lean`); the reference interpreter's
                // `eval_bitcast` ends in `type_error("Bitcast: unsupported
                // destination type")` (`crates/trust-ir/src/interpret.rs`).
                // The validator admits it on total width alone and the
                // lowering-target subset lists `Bitcast` by name with no
                // lane/byte mapping stated, so nothing defines which lane of
                // the destination holds which bytes of the source. It fails
                // (b) too: the only `Bitcast_*` obligations in
                // trust-cg-verify are the scalar I8/I16/I32/I64 and
                // I32<->F32/I64<->F64 rows, `encode_trust_ir_bitcast`
                // ignores both types, and the `MOVDQA xmm,xmm` the x86-64
                // selector emits for an Fpr128 bitcast has no
                // `opcode_to_proof_query` row, so it lands per-instruction
                // `Unverified` with no certificate (the AArch64 selector
                // would emit the GPR-only `MovR` for it). That the selectors
                // emit one register move is a claim about the emitter, not a
                // proof about the semantics. `vector_type_admission.rs` pins
                // this refusal; `e2e_x86_64_vector_fp.rs` expects it.
                //
                // A `Bool` destination is admitted only from `Bool`. trust-ir
                // refuses a reinterpretation into a bool lane
                // (`CastLayoutUnsupported`, `BoolLaneReinterpret`) and its
                // interpreter's `eval_bitcast` has no `Bool` destination:
                // `cast_scalar_bits` sizes `Bool` as its storage byte, but
                // the machine `B1` holds exactly 0 or 1, which a byte's other
                // 254 values are not.
                !Self::is_pointer_like_ty(src_ty)
                    && !Self::is_pointer_like_ty(dst_ty)
                    && src_bits.is_some()
                    && src_bits == dst_bits
                    && (!matches!(dst_ty, Ty::Bool) || matches!(src_ty, Ty::Bool))
            }
            // These producer-level casts have no generic scalar shape beyond
            // the dedicated translation checks below.
            CastOp::Transmute | CastOp::ReifyFnPointer => true,
        };

        if valid {
            Ok(())
        } else {
            Err(AdapterError::UnsupportedInstruction(format!(
                "CastOp::{op:?} source/destination shape is invalid or unsupported: \
                 src_ty={src_ty:?} dst_ty={dst_ty:?}; replacement lowering requires \
                 explicit integer/float width, pointer-width, and provenance-compatible cast rules"
            )))
        }
    }

    /// Rejection-only shape filter over the adapter's pre-existing producer
    /// index. Returning `false` can only retain the original indirect call;
    /// returning `true` grants no authority and still requires the complete
    /// TrustIR dominance/type/duplicate proof below.
    fn has_static_function_pointer_candidate_shape(&self, value: ValueId) -> (bool, usize) {
        let mut current = value;
        let mut visited = 0;
        for _ in 0..STATIC_CALL_PREFILTER_LIMIT {
            visited += 1;
            let Some(node) = self.find_value_producer(current) else {
                return (false, visited);
            };
            match &node.inst {
                Inst::Const {
                    value: Constant::FnDef(_),
                    ..
                } => return (true, visited),
                Inst::Copy { operand, .. }
                | Inst::Cast {
                    op: CastOp::ReifyFnPointer,
                    operand,
                    ..
                } => current = *operand,
                _ => return (false, visited),
            }
        }
        // Bound exhaustion proves nothing. Defer to TrustIR's authoritative
        // duplicate/type/dominance/provenance analysis.
        (true, visited)
    }

    /// Resolve one indirect call to an exact named target, if and only if the
    /// shared TrustIR provenance proof and TrustCG's complete edge contract
    /// both hold. Analysis construction is deliberately inside this method:
    /// functions without `CallIndirect` pay no additional scan or allocation.
    #[allow(clippy::too_many_arguments)]
    fn static_indirect_call_target(
        &mut self,
        trust_ir_block: BlockId,
        instruction_index: usize,
        callee: ValueId,
        sig: FuncTyId,
        args: &[ValueId],
        calling_conv: CallingConv,
        results: &[ValueId],
    ) -> Option<FuncId> {
        if !self.allow_exact_module_calls && self.static_call_devirtualization_stats.is_none() {
            return None;
        }
        self.record_static_call_stat(|stats| {
            stats.indirect_calls_seen += 1;
        });

        let (candidate_shape, prefilter_producer_probes) = if self.static_call_state.is_some() {
            // Once authoritative TrustIR indices exist, another adapter-local
            // chain walk can reject nothing they do not already decide and
            // would add up to eight redundant hash probes per warm call.
            (true, 0)
        } else {
            self.has_static_function_pointer_candidate_shape(callee)
        };
        self.record_static_call_stat(|stats| {
            stats.prefilter_producer_probes += prefilter_producer_probes;
        });
        if !candidate_shape {
            self.record_static_call_stat(|stats| {
                stats.prefilter_rejections += 1;
                stats.unresolved_callees += 1;
            });
            return None;
        }

        if self.static_call_state.is_none() {
            let function = self.trust_ir_func?;
            self.static_call_state = Some(Box::new(StaticCallFunctionState {
                analysis: StaticFunctionPointerAnalysis::new(function),
            }));
            self.record_static_call_stat(|stats| {
                stats.provenance_analyses_built += 1;
            });
        }
        let resolution = if self.static_call_devirtualization_stats.is_some() {
            let (resolution, before, after, census) = {
                let analysis = &self.static_call_state.as_ref()?.analysis;
                let before = analysis.cache_state();
                let (resolution, census) = analysis.resolve_typed_at_with_census(
                    callee,
                    trust_ir_block,
                    instruction_index,
                );
                let after = analysis.cache_state();
                (resolution, before, after, census)
            };
            self.record_static_call_stat(|stats| {
                stats.record_trust_ir_query(before, after, census);
            });
            resolution
        } else {
            self.static_call_state.as_ref().and_then(|state| {
                state
                    .analysis
                    .resolve_typed_at(callee, trust_ir_block, instruction_index)
            })
        };
        let Some(resolution) = resolution else {
            self.record_static_call_stat(|stats| {
                stats.unresolved_callees += 1;
            });
            return None;
        };
        self.record_static_call_stat(|stats| {
            stats.resolved_static_targets += 1;
        });

        let module = self.module?;
        let target = exact_static_call_target(
            module,
            &self.functions,
            &self.value_ty_map,
            resolution,
            self.trust_ir_func?.id,
            callee,
            trust_ir_block,
            instruction_index,
            sig,
            args,
            calling_conv,
            results,
        );
        self.record_static_call_stat(|stats| match target {
            Some(_) if self.allow_exact_module_calls => {
                stats.devirtualized_calls += 1;
            }
            Some(_) => {
                stats.authorization_withheld_calls += 1;
            }
            None => {
                stats.incompatible_calls += 1;
            }
        });
        self.allow_exact_module_calls.then_some(target).flatten()
    }

    // -----------------------------------------------------------------------
    // Instruction translation
    // -----------------------------------------------------------------------

    /// Translate a single trust_ir instruction node into one or more LIR instructions.
    ///
    /// All operands in real trust_ir are ValueId (no inline constants),
    /// so there is no operand resolution step.
    fn translate_instruction(
        &mut self,
        node: &InstrNode,
        trust_ir_block: BlockId,
        instruction_index: usize,
    ) -> Result<Vec<Instruction>, AdapterError> {
        // TrustIR's RegionHavocStore contract requires invalidating at least
        // every location the pointer may reach. LIR Store models one concrete
        // location, so lowering the marker as an ordinary store would
        // under-approximate a bulk write and could preserve stale values.
        // Reject every occurrence, including malformed placement on a
        // non-Store instruction, until this backend owns whole-region havoc.
        if node
            .proofs
            .iter()
            .any(|proof| matches!(proof, ProofAnnotation::RegionHavocStore))
        {
            return Err(AdapterError::UnsupportedInstruction(
                "ProofAnnotation::RegionHavocStore requires whole-region havoc semantics; \
                 Trust Codegen has no sound lowering"
                    .to_owned(),
            ));
        }

        if self.function_has_collections {
            self.refuse_collection_outside_value_positions(node)?;
        }

        let nominal_action = match (&self.native_nominal_values, self.trust_ir_func) {
            (Some(values), Some(function)) => {
                values.action(function, trust_ir_block, instruction_index, node)?
            }
            _ => None,
        };
        let nominal_call;
        let instruction = match nominal_action {
            Some(crate::native_nominal_values::Action::Value { .. }) => return Ok(vec![]),
            Some(crate::native_nominal_values::Action::PrivateMemory) => return Ok(vec![]),
            Some(crate::native_nominal_values::Action::Reify { target, signature }) => {
                return self.translate_function_symbol_const(
                    &Ty::Func(signature),
                    target,
                    &node.results,
                );
            }
            Some(crate::native_nominal_values::Action::Call { target }) => {
                let Inst::CallIndirect { args, .. } = &node.inst else {
                    return Err(AdapterError::UnsupportedInstruction(
                        "nominal call transport lost its actual source operation".into(),
                    ));
                };
                // Reuse the complete direct-call validator, argument/result
                // marshalling, symbol binding and relocation path below.
                nominal_call = Inst::Call {
                    callee: target,
                    args: args.clone(),
                };
                &nominal_call
            }
            None => &node.inst,
        };
        // Real trust_ir uses block parameters for phi semantics, so there is no Inst::Phi arm here.
        match instruction {
            // v47: the shared floor refuses a drop first; refused here too so
            // no entry that skips the floor lowers a destructor as nothing.
            Inst::Drop { .. } => Err(AdapterError::UnmodeledTrustIrConstruct {
                location: "Drop lowering".to_owned(),
                construct: "Inst::Drop",
                reason: DROP_UNMODELED,
            }),
            // v53: the shared floor refuses a non-propagating call boundary
            // first; refused here too so no entry that skips the floor
            // lowers it as an ordinary call, which would let an unwind cross.
            Inst::CallCannotUnwind { .. } => Err(AdapterError::UnmodeledTrustIrConstruct {
                location: "CallCannotUnwind lowering".to_owned(),
                construct: "Inst::CallCannotUnwind",
                reason: CALL_UNWIND_BOUNDARY_UNMODELED,
            }),
            Inst::CallIndirectCannotUnwind { .. } => Err(AdapterError::UnmodeledTrustIrConstruct {
                location: "CallIndirectCannotUnwind lowering".to_owned(),
                construct: "Inst::CallIndirectCannotUnwind",
                reason: CALL_UNWIND_BOUNDARY_UNMODELED,
            }),
            // v55: the drop with an unwind edge. The shared floor refuses it
            // first; refused here too so no entry that skips the floor
            // lowers a destructor as a branch to its normal edge.
            Inst::DropInvoke { .. } => Err(AdapterError::UnmodeledTrustIrConstruct {
                location: "DropInvoke lowering".to_owned(),
                construct: "Inst::DropInvoke",
                reason: DROP_INVOKE_UNMODELED,
            }),
            // v56: the indirect call with an unwind edge. The shared floor
            // refuses it first; refused here too so no entry that skips the
            // floor lowers it as an ordinary indirect call, whose unwind
            // would skip the landing pad.
            Inst::InvokeIndirect { .. } => Err(AdapterError::UnmodeledTrustIrConstruct {
                location: "InvokeIndirect lowering".to_owned(),
                construct: "Inst::InvokeIndirect",
                reason: INVOKE_INDIRECT_UNMODELED,
            }),
            // trust-ir WS3.5 `Inst::MakeAggregate` (F-049): a register-level
            // aggregate seed. Struct / tuple / record / array values lower to
            // a fresh slot filled lane by lane; an enum variant and every shape
            // trust-ir refuses stay refused by name.
            Inst::MakeAggregate {
                ty,
                variant,
                fields,
            } => self.translate_make_aggregate(ty, *variant, fields, &node.results),
            Inst::MakeClosure { ty, func, captures } => {
                self.translate_make_closure(*ty, *func, captures, &node.results)
            }
            // trust-ir v74 `Inst::BoxDeref`, admitted by the ONE acceptance
            // check (`crate::box_deref::admit_box_derefs`, run by `translate`
            // and by the module floor before any body is lowered). The result
            // IS the operand: one pointer copy. The pointee and the fact are
            // deliberately unread here: the fact is a named assumption, and
            // nothing is derived from it or from the instruction's undefined
            // behaviour. No check is removed and no memory access is emitted,
            // moved or annotated (section 28, "No licence").
            Inst::BoxDeref {
                ptr_ty,
                pointee: _,
                operand,
                fact: _,
            } => self.translate_box_deref(ptr_ty, *operand, &node.results),
            // trust-ir v50 `Inst::ArraySplat`: the register array `[value; n]`.
            // A fresh slot filled by one memset (byte-uniform element) or one
            // store plus a doubling copy — constant-size in `n`, never a store
            // per lane.
            Inst::ArraySplat { ty, value } => self.translate_array_splat(ty, *value, &node.results),
            Inst::BinOp { op, ty, lhs, rhs } => {
                // `<8 x i8>` (V64 / D-register) bitwise ops — hashbrown's
                // `simd_or` of two `uint8x8_t` control masks lowers here to
                // NEON `orr.8b`. Only the lane-agnostic bitwise ops are
                // covered (the group scan needs OR); arithmetic on V64 has no
                // consumer yet and fails closed below.
                if Self::is_v8x8_ty(ty) {
                    let shape = Self::int_vector_shape(ty);
                    let opcode = match op {
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{op:?} is not supported by V64 vector lowering \
                                 (only And/Or/Xor are covered)"
                            )));
                        }
                    };
                    self.require_trust_ir_operand_type(shape, "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type(shape, "rhs", *rhs, ty)?;
                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V64);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v16x8_ty(ty) || Self::is_v8x16_ty(ty) {
                    let shape = Self::int_vector_shape(ty);
                    let (add_opcode, sub_opcode, mul_opcode) = if Self::is_v16x8_ty(ty) {
                        (Opcode::V16I8Add, Opcode::V16I8Sub, Opcode::V16I8Mul)
                    } else {
                        (Opcode::V8I16Add, Opcode::V8I16Sub, Opcode::V8I16Mul)
                    };
                    self.require_trust_ir_operand_type(shape, "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type(shape, "rhs", *rhs, ty)?;
                    let opcode = match op {
                        BinOp::Add => add_opcode,
                        BinOp::Sub => sub_opcode,
                        BinOp::Mul => mul_opcode,
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{op:?} is not supported by typed narrow vector lowering"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v2x64_ty(ty) {
                    let shape = Self::int_vector_shape(ty);
                    let opcode = match op {
                        BinOp::Add => Opcode::V2I64Add,
                        BinOp::Sub => Opcode::V2I64Sub,
                        // <2 x i64> has no single-instruction packed multiply on
                        // SSE2 or NEON; the typed `V2I64Mul` op is lowered by both
                        // ISels through scalar lane extraction, two 64-bit scalar
                        // multiplies, and a vector repack. Emitting the typed op
                        // keeps the adapter free of lane-scalarization memory.
                        BinOp::Mul => Opcode::V2I64Mul,
                        // Bitwise ops are lane-width-agnostic over the 128-bit
                        // register, so they reuse the same covered NEON
                        // AND/ORR/EOR as the V4I32/V16I8 shapes (select_logic
                        // V128 -> NeonAndV/NeonOrrV/NeonEorV).
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{op:?} is not supported by typed vector lowering"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty) {
                    let shape = if Self::is_v4f32_ty(ty) {
                        "<4 x f32>"
                    } else {
                        "<2 x f64>"
                    };
                    self.require_trust_ir_operand_type(shape, "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type(shape, "rhs", *rhs, ty)?;
                    // Packed IEEE copySign (trust-ir WS3.20) is a per-lane
                    // sign-bit merge, so it lowers over the whole V128 with the
                    // same lane-agnostic AND/BIC/ORR the packed FNeg/FAbs use.
                    if *op == BinOp::FCopySign {
                        return self.translate_packed_fp_copysign(ty, *lhs, *rhs, &node.results);
                    }
                    // Packed FMin/FMax/FRem have no single SSE/NEON opcode wired
                    // here, but the per-lane scalar op IS the packed semantics —
                    // lower lane-wise via a stack round-trip (reusing only proven
                    // opcodes: scalar Fmin/Fmax for min/max, a per-lane fmod/fmodf
                    // CALL for remainder), exactly like packed FSqrt. std::simd
                    // min/max and vectorized fmod reach this.
                    if matches!(op, BinOp::FMin | BinOp::FMax | BinOp::FRem) {
                        return self.translate_packed_fp_binary_via_stack(
                            *op,
                            ty,
                            *lhs,
                            *rhs,
                            &node.results,
                        );
                    }
                    let opcode = match (Self::is_v4f32_ty(ty), op) {
                        (true, BinOp::FAdd) => Opcode::V4F32Fadd,
                        (true, BinOp::FSub) => Opcode::V4F32Fsub,
                        (true, BinOp::FMul) => Opcode::V4F32Fmul,
                        (true, BinOp::FDiv) => Opcode::V4F32Fdiv,
                        (false, BinOp::FAdd) => Opcode::V2F64Fadd,
                        (false, BinOp::FSub) => Opcode::V2F64Fsub,
                        (false, BinOp::FMul) => Opcode::V2F64Fmul,
                        (false, BinOp::FDiv) => Opcode::V2F64Fdiv,
                        // Fail closed for any non-FP / unimplemented packed-FP
                        // shape (e.g. FRem, integer ops on FP vectors): never
                        // silently miscompile.
                        (_, other) => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{other:?} has no packed SSE floating-point lowering; \
                                 only FAdd/FSub/FMul/FDiv are lowered for packed FP vectors"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v4x32_ty(ty) {
                    let shape = Self::int_vector_shape(ty);
                    self.require_trust_ir_operand_type(shape, "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type(shape, "rhs", *rhs, ty)?;
                    let opcode = match op {
                        BinOp::Add => Opcode::V4I32Add,
                        BinOp::Sub => Opcode::V4I32Sub,
                        BinOp::Mul => Opcode::V4I32Mul,
                        // Bitwise And/Or/Xor over a V128-typed vector are lane
                        // width-agnostic: the scalar Band/Bor/Bxor opcodes
                        // operate bit-for-bit over the whole 128-bit register
                        // (lowered to SSE2 PAND/POR/PXOR), so they correctly
                        // implement the packed <4 x i32> bitwise op.
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        // Lane-wise `<4 x i32>` shifts. trust_ir vector
                        // `BinOp::{Shl,LShr,AShr}` carries a vector RHS (one
                        // count per lane); we emit the generic Ishl/Ushr/Sshr
                        // opcode with both operands typed V128 and let each
                        // backend lower it lane-wise:
                        //   * x86-64 isel recognises a uniform-constant RHS
                        //     (built from a `pack_lanes` of one constant) and
                        //     emits the SMT-verified SSE2 packed-immediate shift
                        //     PSLLD/PSRLD/PSRAD (`proof_x86_v4i32_*_uniform_*`);
                        //     a non-uniform RHS scalarises per lane.
                        //   * AArch64 isel emits the SMT-verified NEON SIMD
                        //     shift-by-immediate SHL/USHR/SSHR.4S for a
                        //     uniform-constant RHS (`proof_vector_{shl,ushr,sshr}_4s`)
                        //     and otherwise fails closed (it never silently
                        //     reinterprets a packed shift as a scalar one).
                        BinOp::Shl => Opcode::Ishl,
                        BinOp::LShr => Opcode::Ushr,
                        BinOp::AShr => Opcode::Sshr,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{op:?} is not supported by typed vector lowering"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if matches!(ty, Ty::Vector(_, _)) && !Self::is_v4x32_ty(ty) {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "BinOp::{op:?} over unsupported vector shape {ty:?}; \
                         only <16 x i8|u8>, <8 x i16|u16>, <4 x i32|u32>, <2 x i64|u64>, <4 x f32>, and <2 x f64> vector arithmetic is lowered today"
                    )));
                }

                // Scalar floating-point remainder has no native machine
                // instruction: lower it to a call to the libm `fmod`/`fmodf`
                // symbol (resolved by the linker), matching how scalar FRem is
                // defined for C/Rust. The ISel lowers `Opcode::Call` to BL/CALL.
                if *op == BinOp::FRem {
                    self.validate_binop_operand_tys(*op, ty, *lhs, *rhs)?;
                    // f16 has no dedicated fmod libcall, but `fmod` is EXACT — its
                    // remainder is exactly representable in the source format — so
                    // `f16 rem(a,b) = f16(fmodf(f32(a), f32(b)))`: promote both
                    // operands to f32 (exact, f16 subset f32), call the existing
                    // `fmodf`, demote the result to f16 (exact, the remainder is
                    // f16-representable). No f16 fmod ABI is required.
                    if matches!(ty, Ty::F16) {
                        let lhs_val = self.map_value(*lhs);
                        let rhs_val = self.map_value(*rhs);
                        let a32 = self.fresh_value();
                        self.define_value_type(a32, Type::F32);
                        let b32 = self.fresh_value();
                        self.define_value_type(b32, Type::F32);
                        let r32 = self.fresh_value();
                        self.define_value_type(r32, Type::F32);
                        let result = self.map_result(&node.results)?;
                        self.define_value_type(result, Type::F16);
                        return Ok(vec![
                            Instruction {
                                opcode: Opcode::FPExt,
                                args: vec![lhs_val],
                                results: vec![a32],
                            },
                            Instruction {
                                opcode: Opcode::FPExt,
                                args: vec![rhs_val],
                                results: vec![b32],
                            },
                            Instruction {
                                opcode: self.runtime_call_opcode(RuntimeSymbol::Fmodf)?,
                                args: vec![a32, b32],
                                results: vec![r32],
                            },
                            Instruction {
                                opcode: Opcode::FPTrunc,
                                args: vec![r32],
                                results: vec![result],
                            },
                        ]);
                    }
                    let (callee, result_ty) = match ty {
                        Ty::F32 => (RuntimeSymbol::Fmodf, Type::F32),
                        Ty::F64 => (RuntimeSymbol::Fmod, Type::F64),
                        other => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "BinOp::FRem requires f16, f32, or f64 operands, got {other:?}"
                            )));
                        }
                    };

                    let lhs_val = self.map_value(*lhs);
                    let rhs_val = self.map_value(*rhs);
                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, result_ty);
                    return Ok(vec![Instruction {
                        opcode: self.runtime_call_opcode(callee)?,
                        args: vec![lhs_val, rhs_val],
                        results: vec![result],
                    }]);
                }

                // Fail-closed safety gates: reject operands that do not match the
                // declared scalar type, and reject opcode/type-family mismatches
                // (e.g. integer/shift ops over a float type) before lowering.
                self.validate_binop_operand_tys(*op, ty, *lhs, *rhs)?;
                self.validate_scalar_binop_shape(*op, ty)?;

                let opcode = match op {
                    BinOp::Add => Opcode::Iadd,
                    BinOp::Sub => Opcode::Isub,
                    BinOp::Mul => Opcode::Imul,
                    BinOp::UDiv => Opcode::Udiv,
                    BinOp::SDiv => Opcode::Sdiv,
                    BinOp::URem => Opcode::Urem,
                    BinOp::SRem => Opcode::Srem,
                    BinOp::FAdd => Opcode::Fadd,
                    BinOp::FSub => Opcode::Fsub,
                    BinOp::FMul => Opcode::Fmul,
                    BinOp::FDiv => Opcode::Fdiv,
                    BinOp::FRem => {
                        unreachable!(
                            "FRem is lowered to an fmod/fmodf libcall before generic arithmetic lowering"
                        )
                    }
                    BinOp::FMin => Opcode::Fmin,
                    BinOp::FMax => Opcode::Fmax,
                    BinOp::And => Opcode::Band,
                    BinOp::Or => Opcode::Bor,
                    BinOp::Xor => Opcode::Bxor,
                    // Trust: the BOOLEAN connectives lower to the SAME machine
                    // opcodes. That is exact, not an approximation: the shape gate
                    // above admits them on `Ty::Bool` only, whose carrier is 0/1, and
                    // on 0/1 the bitwise instruction computes the logical result. The
                    // distinction these opcodes carry is a VERIFICATION one -- it buys
                    // a reducing denotation instead of an opaque one -- and has no
                    // machine-level consequence here.
                    BinOp::BAnd => Opcode::Band,
                    BinOp::BOr => Opcode::Bor,
                    BinOp::BXor => Opcode::Bxor,
                    BinOp::Shl => Opcode::Ishl,
                    BinOp::LShr => Opcode::Ushr,
                    BinOp::AShr => Opcode::Sshr,
                    // trust-ir WS3.20 (F-057). No single LIR opcode carries
                    // these, so each expands into already-covered opcodes. The
                    // operand and shape gates above have admitted them.
                    BinOp::RotL | BinOp::RotR => {
                        return self.translate_scalar_rotate(*op, ty, *lhs, *rhs, &node.results);
                    }
                    BinOp::FCopySign => {
                        return self.translate_scalar_copysign(ty, *lhs, *rhs, &node.results);
                    }
                };

                let lhs_val = self.map_value(*lhs);
                let rhs_val = self.map_value(*rhs);
                let result = self.map_result(&node.results)?;

                let mut insts = Vec::new();
                if integer_div_or_rem_has_nonzero_proof(*op, node) {
                    // DivNonZero IS the upstream safety proof: synthesize (or reuse a ProofRef's)
                    // Discharged obligation so the kernel-gated proof pass can authorize eliminating
                    // the div-zero guard, exactly as NotNull does for the null guard.
                    let obligation = self.divisor_not_zero_obligation(node);
                    insts.push(Instruction {
                        opcode: Opcode::GuardDivZero { obligation },
                        args: vec![rhs_val],
                        results: vec![],
                    });
                }
                if let Some(bitwidth) = shift_has_in_range_proof(*op, ty, node) {
                    // ShiftInRange IS the upstream safety proof: synthesize (or reuse a ProofRef's)
                    // Discharged obligation so the kernel-gated proof pass can authorize eliminating
                    // the shift-range guard, exactly as InBounds does for the bounds guard.
                    let obligation = self.shift_in_range_obligation(node);
                    insts.push(Instruction {
                        opcode: Opcode::GuardShiftRange {
                            bitwidth,
                            obligation,
                        },
                        args: vec![rhs_val],
                        results: vec![],
                    });
                }
                insts.push(Instruction {
                    opcode,
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                });

                Ok(insts)
            }

            Inst::UnOp { op, ty, operand } => {
                // Packed FP negate / abs on a supported FP vector shape lower as
                // a bitwise sign-mask op over the V128 lanes, reusing the
                // already-covered NEON EOR (Bxor) / BIC (BandNot) — no new
                // opcode. `Fneg` flips each lane's sign bit (EOR mask); `Fabs`
                // clears it (BIC mask). Bit-flip negation is the correct IEEE
                // semantics (it yields -0.0 from +0.0, unlike `0 - x`).
                if matches!(op, UnOp::FNeg | UnOp::FAbs)
                    && (Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty))
                {
                    return self.translate_packed_fp_sign_op(*op, ty, *operand, &node.results);
                }
                // Packed integer negate = `0 - v`, reusing the covered per-shape
                // packed subtract. No new opcode.
                if matches!(op, UnOp::Neg)
                    && (Self::is_v16x8_ty(ty)
                        || Self::is_v8x16_ty(ty)
                        || Self::is_v4x32_ty(ty)
                        || Self::is_v2x64_ty(ty))
                {
                    return self.translate_packed_int_neg(ty, *operand, &node.results);
                }
                // Packed bitwise NOT = `v XOR all-ones`, reusing the covered
                // type-agnostic 128-bit EOR (Bxor) — same machinery as packed
                // FNeg's sign-bit EOR. No new opcode.
                if matches!(op, UnOp::Not)
                    && (Self::is_v16x8_ty(ty)
                        || Self::is_v8x16_ty(ty)
                        || Self::is_v4x32_ty(ty)
                        || Self::is_v2x64_ty(ty))
                {
                    return self.translate_packed_int_not(ty, *operand, &node.results);
                }
                // Packed FP sqrt / round (floor/ceil/trunc) over <4 x f32> /
                // <2 x f64>: lane-wise via a stack round-trip (store the vector,
                // apply the SCALAR FP op to each lane in memory, reload). Reuses
                // only already-proven opcodes (StackAddr/Store/ArrayGep/Load +
                // scalar Fsqrt/Ffloor/Fceil/Ftrunc) — per-lane application IS the
                // packed semantics, so no new vector opcode or lowering proof is
                // needed. A later pass may fuse it to NEON FSQRT/FRINTx.
                if matches!(op, UnOp::FSqrt | UnOp::FFloor | UnOp::FCeil | UnOp::FTrunc)
                    && (Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty))
                {
                    return self.translate_packed_unary_via_stack(*op, ty, *operand, &node.results);
                }
                // Packed integer population count over <16 x i8> / <8 x i16> /
                // <4 x i32> / <2 x i64>: same lane-wise stack round-trip, applying
                // the scalar CtPop per lane. Reuses only proven opcodes.
                if matches!(op, UnOp::CtPop)
                    && (Self::is_v16i8_ty(ty)
                        || Self::is_v8i16_ty(ty)
                        || Self::is_v4i32_ty(ty)
                        || Self::is_v2i64_ty(ty))
                {
                    return self.translate_packed_unary_via_stack(*op, ty, *operand, &node.results);
                }
                // Fail closed for the REMAINING vector unary ops. Packed FNeg/FAbs,
                // packed FP sqrt/round, packed integer Neg, and packed integer Not
                // (on their supported lane shapes) are already lowered by the
                // early-returns above. The scalar Fneg/Ineg/Bnot/CtPop opcodes
                // operate on a single scalar lane, so emitting them for a V128-typed
                // operand would silently miscompile a packed vector. The still-
                // unlowered packed unary op — integer CtPop — plus any unsupported
                // lane shape are rejected here rather than lowered incorrectly.
                if matches!(ty, Ty::Vector(_, _)) {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "UnOp::{op:?} over vector type {ty:?} has no packed lowering \
                         for this lane shape (packed FNeg/FAbs, FSqrt/floor/ceil/trunc, \
                         integer Neg/Not, and integer CtPop are handled above for their \
                         supported lane shapes; other op/shape combinations are rejected)"
                    )));
                }
                // Fail-closed safety gate: reject operand/declared-type mismatch
                // and opcode/type-family mismatch before scalar lowering.
                self.validate_unop_shape(*op, ty, *operand)?;
                let opcode = match op {
                    UnOp::Neg => Opcode::Ineg,
                    UnOp::FNeg => Opcode::Fneg,
                    UnOp::FAbs => Opcode::Fabs,
                    UnOp::FSqrt => Opcode::Fsqrt,
                    UnOp::FFloor => Opcode::Ffloor,
                    UnOp::FCeil => Opcode::Fceil,
                    UnOp::FTrunc => Opcode::Ftrunc,
                    UnOp::Not => Opcode::Bnot,
                    UnOp::CtPop => Opcode::CtPop,
                    // trust-ir WS3.20 (F-057): expanded into covered shift,
                    // mask and population-count opcodes. `validate_unop_shape`
                    // above has admitted the operand.
                    UnOp::CtLz | UnOp::CtTz | UnOp::BSwap | UnOp::BitReverse => {
                        return self.translate_scalar_bit_intrinsic(
                            *op,
                            ty,
                            *operand,
                            &node.results,
                        );
                    }
                };

                let src = self.map_value(*operand);
                let dst = self.map_result(&node.results)?;

                Ok(vec![Instruction {
                    opcode,
                    args: vec![src],
                    results: vec![dst],
                }])
            }

            Inst::Overflow { op, ty, lhs, rhs } => {
                self.translate_overflow(op, ty, *lhs, *rhs, &node.results, node)
            }

            Inst::ICmp { op, ty, lhs, rhs } => {
                if let [result] = node.results.as_slice()
                    && self.bounds_assertions.contains_key(result)
                {
                    self.validate_icmp_shape(*op, ty)?;
                    self.validate_binary_operand_tys("ICmp", ty, *lhs, *rhs)?;
                    return Ok(vec![]);
                }
                // OPT-6a: the frontend bounds-check probe (an `InBounds`-annotated
                // `Ult` compare against a constant bound) ADDITIONALLY emits a
                // proof-only `GuardBoundsCheck` carrier bound to the probe's module
                // obligation (if any) — the rustc-bridge's route into the verified
                // Certified-Elimination Kernel. The compare itself still lowers
                // below (its result is typically dead and DCE-able); the carrier is
                // what the kernel either deletes (obligation discharged) or the
                // pipeline expands into the real CMP+Jcc+UD2 runtime check.
                // Recognition is total and fail-closed: see
                // `frontend_bounds_probe`.
                let probe_carrier = match self.frontend_bounds_probe(node) {
                    Some(Ok((bound, obligation))) => {
                        let index_val = self.map_value(*lhs);
                        Some(match bound {
                            BoundsProbeBound::Const(bound) => Instruction {
                                opcode: Opcode::GuardBoundsCheck { bound, obligation },
                                args: vec![index_val, index_val],
                                results: vec![],
                            },
                            // DYNAMIC length: the bound rides as a third ARG
                            // rather than an opcode field, and lowers to a
                            // TrapBoundsCheckExact whose bound slot is a
                            // register. Same trap semantics, same fail-safe
                            // contract; the only difference is that `v.len()`
                            // is not knowable until runtime.
                            BoundsProbeBound::Dyn(len) => {
                                let len_val = self.map_value(len);
                                Instruction {
                                    opcode: Opcode::GuardBoundsCheckDyn { obligation },
                                    args: vec![index_val, index_val, len_val],
                                    results: vec![],
                                }
                            }
                        })
                    }
                    Some(Err(err)) => return Err(err),
                    None => None,
                };
                // OPT-6b: a RESULT-LESS probe is PROOF-ONLY — the frontend declared
                // the compare's value unobservable (nothing consumes it; the eager
                // bounds branch was replaced by the carrier channel), so lowering a
                // dead flag-materialization (`cmp` + `setcc`, which the machine DCE
                // conservatively keeps as a flag-writer) would tax every loop
                // iteration for nothing. Emit ONLY the carrier: the carrier alone
                // carries the check's full trap semantics — KEPT, it expands into a
                // complete CMP+Jcc+UD2 runtime check with its own compare; DELETED,
                // that deletion is licensed by the kernel against the discharged
                // obligation exactly as for a result-carrying probe. A result-less
                // ICmp that is NOT a recognized probe still fails closed below
                // (`map_result` on an empty result list), unchanged.
                if node.results.is_empty()
                    && let Some(carrier) = probe_carrier
                {
                    return Ok(vec![carrier]);
                }
                let cond = crate::instructions::intcc_of_icmp(*op);

                if Self::is_v16x8_ty(ty) || Self::is_v8x16_ty(ty) {
                    return self.translate_narrow_int_vector_icmp(
                        cond,
                        ty,
                        *lhs,
                        *rhs,
                        &node.results,
                    );
                }
                if Self::is_v4x32_ty(ty) {
                    return self.translate_v4i32_icmp(cond, *lhs, *rhs, &node.results);
                }
                if Self::is_v2x64_ty(ty) {
                    return self.translate_v2i64_icmp(cond, *lhs, *rhs, &node.results);
                }
                if Self::is_v8x8_ty(ty) {
                    return self.translate_v8i8_icmp(cond, *lhs, *rhs, &node.results);
                }
                if matches!(ty, Ty::Vector(_, _)) && !Self::is_v4x32_ty(ty) {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "ICmp::{op:?} over unsupported vector shape {ty:?}; \
                         only <16 x i8|u8>, <8 x i16|u16>, <4 x i32|u32>, <2 x i64|u64>, and <8 x i8|u8> vector compares are lowered today"
                    )));
                }

                // Fail-closed safety gate for scalar compares: reject non-integer
                // (and non Bool/pointer Eq/Ne) declared types and operand/declared
                // type mismatches before lowering to a raw Icmp.
                if !matches!(ty, Ty::Vector(_, _)) {
                    self.validate_icmp_shape(*op, ty)?;
                    self.validate_binary_operand_tys("ICmp", ty, *lhs, *rhs)?;
                }

                let lhs_val = self.map_value(*lhs);
                let rhs_val = self.map_value(*rhs);
                let result = self.map_result(&node.results)?;

                let mut instrs = Vec::with_capacity(2);
                // OPT-6a: the probe's carrier precedes its compare, mirroring the
                // GEP channel where the guard precedes the address computation.
                instrs.extend(probe_carrier);
                instrs.push(Instruction {
                    opcode: Opcode::Icmp { cond },
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                });
                Ok(instrs)
            }

            Inst::FCmp { op, ty, lhs, rhs } => {
                let cond = match op {
                    FCmpOp::OEq => FloatCC::Equal,
                    FCmpOp::ONe => FloatCC::NotEqual,
                    FCmpOp::OLt => FloatCC::LessThan,
                    FCmpOp::OLe => FloatCC::LessThanOrEqual,
                    FCmpOp::OGt => FloatCC::GreaterThan,
                    FCmpOp::OGe => FloatCC::GreaterThanOrEqual,
                    FCmpOp::UEq => FloatCC::UnorderedEqual,
                    FCmpOp::UNe => FloatCC::UnorderedNotEqual,
                    FCmpOp::ULt => FloatCC::UnorderedLessThan,
                    FCmpOp::ULe => FloatCC::UnorderedLessThanOrEqual,
                    FCmpOp::UGt => FloatCC::UnorderedGreaterThan,
                    FCmpOp::UGe => FloatCC::UnorderedGreaterThanOrEqual,
                };

                // Fail-closed safety gate: reject non-float declared types and
                // operand/declared type mismatches before lowering to Fcmp.
                self.validate_fcmp_shape(ty, *lhs, *rhs)?;

                let lhs_val = self.map_value(*lhs);
                let rhs_val = self.map_value(*rhs);
                let result = self.map_result(&node.results)?;

                Ok(vec![Instruction {
                    opcode: Opcode::Fcmp { cond },
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                }])
            }

            Inst::Cast {
                op,
                src_ty,
                dst_ty,
                operand,
            } => self.translate_cast(op, src_ty, dst_ty, operand, &node.results),

            Inst::Load {
                ty,
                ptr,
                volatile,
                align,
            } => {
                // Compute the NotNull obligation (synthesizing a Discharged id from the NotNull proof,
                // exactly as InBounds does) BEFORE the `&mut self` call below. `Some(_)` => emit the
                // guard bound to that obligation; `None` => no NotNull proof, emit no guard.
                let not_null = self.memory_ptr_not_null_obligation(node);
                self.translate_load(ty, ptr, *volatile, *align, &node.results, not_null)
            }

            Inst::Store {
                ty,
                ptr,
                value,
                volatile,
                align,
            } => {
                let not_null = self.memory_ptr_not_null_obligation(node);
                self.translate_store(ty, ptr, value, *volatile, *align, not_null)
            }

            // trust-ir WS3.20 (F-057): the dynamic-count bulk-memory pair.
            Inst::MemCopy {
                dst,
                src,
                bytes,
                overlap,
            } => self.translate_mem_copy(*dst, *src, *bytes, *overlap, &node.results),
            Inst::MemSet { dst, byte, bytes } => {
                self.translate_mem_set(*dst, *byte, *bytes, &node.results)
            }

            Inst::Alloca { ty, count, align } => self.translate_alloc(
                ty,
                count,
                *align,
                &node.results,
                node.span.as_ref().map(|s| s.line),
                (trust_ir_block, instruction_index),
            ),

            // GEP stride contract (ABI-critical; see `trust-cg-ir` crate docs
            // and issue #475):
            //   result = base + sum(indices) * sizeof(pointee_ty)
            // Empty `indices` => Copy (identity). Every index has the same scale;
            // field projections use ExtractField/InsertField or byte offsets. External consumers (ay, ty) depend on this stride
            // convention — changing it is a P0 ABI break.
            Inst::GEP {
                pointee_ty,
                base,
                indices,
                // `inbounds` is an LLVM-style no-wrap optimization hint
                // (trust-ir inst.rs: "backend hint enabling no-wrap GEP
                // folding"). Ignoring it is always sound: lowering already
                // computes `base + index * sizeof(pointee_ty)` with full,
                // conservative integer arithmetic. Honoring the hint could
                // only enable *additional* folding optimizations, never change
                // the required address; declining them is the fail-safe
                // direction. Do not specialize codegen on this flag without an
                // ay-verified no-wrap lowering.
                inbounds: _,
            } => {
                // A GEP strides by the pointee's emitted size; a bool-lane
                // pointee has no emitted size that is the referee's.
                self.refuse_bool_lane_layout(pointee_ty, "GEP pointee")?;
                let storage_geometry = self.storage_geometry.resolve(self.module, pointee_ty)?;
                if storage_geometry.is_some() {
                    for index in indices {
                        let ty = self.lookup_value_ty(*index).ok_or_else(|| {
                            AdapterError::UnsupportedInstruction(
                                "Storage GEP index has no source type".into(),
                            )
                        })?;
                        let pointer_bits = self.module.map_or(64, TrustIrModule::pointer_bits);
                        if !ty.is_integer()
                            || ty.bit_width_with(pointer_bits).is_none_or(|bits| bits > 64)
                        {
                            return Err(AdapterError::UnsupportedInstruction(
                                "Storage GEP index requires an actual integer of at most 64 bits"
                                    .into(),
                            ));
                        }
                    }
                }
                match indices.as_slice() {
                    [] => {
                        let src = self.map_value(*base);
                        let dst = self.map_result(&node.results)?;
                        Ok(vec![Instruction {
                            opcode: Opcode::Copy,
                            args: vec![src],
                            results: vec![dst],
                        }])
                    }
                    [index] => {
                        let base_ptr = self.map_value(*base);
                        let index_val = self.map_value(*index);
                        let dst = self.map_result(&node.results)?;
                        // Propagate the type error rather than falling back to a
                        // 1-byte stride: a GEP over a pointee with no defined CPU
                        // layout (e.g. Ty::Set/Ty::Sequence) must fail closed, not
                        // silently emit byte-stride pointer arithmetic at a
                        // fabricated element size.
                        //
                        // The stride is the AUTHORITATIVE element size: the
                        // producer's declared size when it stated an emittable
                        // layout, the PACKED size for a `#[repr(packed)]` struct
                        // (e.g. `{u8,u32}` is 5 bytes, not 8), and only otherwise
                        // the natural-C `translate_ty(..).bytes()` — otherwise
                        // `&arr[i]` strides past the element (audit P0/G5).
                        let elem_size = if let Some(geometry) = storage_geometry {
                            geometry.size_bytes()
                        } else {
                            let lir_pointee_ty = self.translate_ty(pointee_ty)?;
                            self.aggregate_value_extent(pointee_ty, &lir_pointee_ty)?
                        } as i64;

                        let mut instrs = Vec::new();
                        let index_val =
                            self.extend_index_to_i64_if_needed(*index, index_val, &mut instrs)?;
                        self.append_exact_in_bounds_guard(node, base_ptr, index_val, &mut instrs);
                        let scaled_index = if elem_size == 1 {
                            index_val
                        } else {
                            let size_val = self.fresh_value();
                            instrs.push(Instruction {
                                opcode: Opcode::Iconst {
                                    ty: Type::I64,
                                    imm: elem_size,
                                },
                                args: vec![],
                                results: vec![size_val],
                            });

                            let scaled = self.fresh_value();
                            instrs.push(Instruction {
                                opcode: Opcode::Imul,
                                args: vec![index_val, size_val],
                                results: vec![scaled],
                            });
                            scaled
                        };

                        instrs.push(Instruction {
                            opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
                            args: vec![base_ptr, scaled_index],
                            results: vec![dst],
                        });

                        Ok(instrs)
                    }
                    _ => self.translate_multi_index_gep(pointee_ty, *base, indices, &node.results),
                }
            }

            Inst::PtrData { ptr_ty, ptr } => self.translate_ptr_data(ptr_ty, ptr, &node.results),

            Inst::PtrMetadata {
                ptr_ty,
                metadata_ty,
                ptr,
            } => self.translate_ptr_metadata(ptr_ty, metadata_ty, ptr, &node.results),

            Inst::PtrFromParts {
                ptr_ty,
                metadata_ty,
                data,
                metadata,
            } => self.translate_ptr_from_parts(ptr_ty, metadata_ty, data, metadata, &node.results),

            Inst::AtomicLoad { ty, ptr, ordering } => {
                self.translate_atomic_load(ty, ptr, ordering, &node.results)
            }

            Inst::AtomicStore {
                ty,
                ptr,
                value,
                ordering,
            } => self.translate_atomic_store(ty, ptr, value, ordering),

            Inst::AtomicRMW {
                op,
                ty,
                ptr,
                value,
                ordering,
            } => self.translate_atomic_rmw(op, ty, ptr, value, ordering, &node.results),

            Inst::CmpXchg {
                ty,
                ptr,
                expected,
                desired,
                success,
                failure,
                weak,
            } => {
                // v48: the shared floor refuses a weak CAS first; refused here
                // too so no entry that skips the floor lowers it as strong.
                if *weak {
                    return Err(AdapterError::UnmodeledTrustIrConstruct {
                        location: "CmpXchg lowering".to_owned(),
                        construct: "Inst::CmpXchg { weak: true }",
                        reason: WEAK_CMPXCHG_UNMODELED,
                    });
                }
                self.refuse_bool_lane_layout(ty, "CmpXchg")?;
                let lir_ty = self.translate_ty(ty)?;
                let ptr_val = self.map_value(*ptr);
                let exp_val = self.map_value(*expected);
                let des_val = self.map_value(*desired);
                let old_val = self.map_result(&node.results)?;
                let success_ordering = translate_ordering(success);
                let failure_ordering = translate_ordering(failure);

                // Fail closed for the truly invalid cmpxchg failure orderings —
                // THE rule (Rust/LLVM), shared with both ISel gates via
                // `AtomicOrdering::is_valid_cmpxchg_failure`: the failure
                // (load-only) ordering must not be Release/AcqRel, and there is
                // NO other constraint.
                //
                // THREADS: a failure ordering STRONGER than the success ordering
                // is LEGAL Rust/C++17 (`compare_exchange(.., AcqRel, SeqCst)` in
                // std's mutex/rwlock). The isel's opcode choice assumes
                // `failure <= success`, so LIFT the success ordering to cover
                // the failure ordering (`lift_for_cmpxchg_failure`) — a strictly
                // STRONGER single ordering, never weaker, so the emitted machine
                // sequence over-satisfies both paths (on AArch64 LSE the AcqRel
                // and SeqCst mappings are the same `CASAL` family anyway).
                if !failure_ordering.is_valid_cmpxchg_failure() {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CmpXchg failure ordering {failure_ordering:?} is invalid; the \
                         failure ordering must not be Release/AcqRel"
                    )));
                }
                let success_ordering = success_ordering.lift_for_cmpxchg_failure(failure_ordering);
                debug_assert!(success_ordering.allows_cmpxchg_failure(failure_ordering));

                let mut instrs = vec![Instruction {
                    opcode: Opcode::CmpXchg {
                        ty: lir_ty,
                        success: success_ordering,
                        failure: failure_ordering,
                    },
                    args: vec![exp_val, des_val, ptr_val],
                    results: vec![old_val],
                }];

                if let Some(success_vid) = node.results.get(1) {
                    let success_val = self.map_value(*success_vid);
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp { cond: IntCC::Equal },
                        args: vec![old_val, exp_val],
                        results: vec![success_val],
                    });
                }

                Ok(instrs)
            }

            Inst::Fence { ordering } => self.translate_fence(ordering),

            Inst::Br { target, args } => self.translate_br(target, args),

            Inst::CondBr {
                cond,
                then_target,
                then_args,
                else_target,
                else_args,
            } => self.translate_condbr(cond, then_target, then_args, else_target, else_args),

            Inst::Switch {
                value,
                default,
                default_args,
                cases,
                // `exhaustive_enum_unreachable` is a trust-side hint for the
                // native CHC translator (it conjoins `selector ∈ {case values}`
                // into the default arm to prove it UNSAT). It is a VERIFICATION
                // fact, not a codegen change: the CPU `Opcode::Switch` carries no
                // exhaustiveness field and always emits the default fallthrough
                // edge, so the lowered machine code is identical whether the flag
                // is set or not. Bound and intentionally ignored here.
                exhaustive_enum_unreachable: _,
            } => {
                // BUG FIX (issue #304): Same pattern as condbr (#302) — copies
                // for each case must only execute on the correct edge. Create
                // intermediate copy blocks when block arguments are present.

                let mut instrs = Vec::new();
                let selector_ty = self
                    .lookup_value_ty(*value)
                    .ok_or(AdapterError::UnknownValue(value.index()))?;
                let selector_bits = Self::switch_selector_bits(&selector_ty)?;
                if selector_bits == 128 {
                    return self.translate_i128_switch(
                        value,
                        &selector_ty,
                        default,
                        default_args,
                        cases,
                    );
                }
                let normalized_case_values =
                    Self::validate_switch_case_values(cases, selector_bits)?;
                let selector = self.map_value(*value);

                let default_copies = self.resolve_block_args(*default, default_args)?;

                // Default case: create copy block if there are copies.
                let default_block = if !default_copies.is_empty() {
                    let copy_block_id = self.fresh_block();
                    let real_default_dest = self.map_block(*default);
                    let mut copy_bb = BasicBlock {
                        instructions: default_copies,
                        ..Default::default()
                    };
                    copy_bb.instructions.push(Instruction {
                        opcode: Opcode::Jump {
                            dest: real_default_dest,
                        },
                        args: vec![],
                        results: vec![],
                    });
                    self.pending_extra_blocks.push((copy_block_id, copy_bb));
                    copy_block_id
                } else {
                    self.map_block(*default)
                };

                let mut lir_cases = Vec::with_capacity(cases.len());

                for (case, case_value) in cases.iter().zip(normalized_case_values) {
                    let case_copies = self.resolve_block_args(case.target, &case.args)?;

                    // Each case: create copy block if there are copies.
                    let case_dest = if !case_copies.is_empty() {
                        let copy_block_id = self.fresh_block();
                        let real_case_dest = self.map_block(case.target);
                        let mut copy_bb = BasicBlock {
                            instructions: case_copies,
                            ..Default::default()
                        };
                        copy_bb.instructions.push(Instruction {
                            opcode: Opcode::Jump {
                                dest: real_case_dest,
                            },
                            args: vec![],
                            results: vec![],
                        });
                        self.pending_extra_blocks.push((copy_block_id, copy_bb));
                        copy_block_id
                    } else {
                        self.map_block(case.target)
                    };

                    lir_cases.push((case_value, case_dest));
                }

                instrs.push(Instruction {
                    opcode: Opcode::Switch {
                        cases: lir_cases,
                        default: default_block,
                    },
                    args: vec![selector],
                    results: vec![],
                });

                Ok(instrs)
            }

            Inst::Call { callee, args } => {
                let (callee_function, callee_signature) =
                    self.validate_direct_call_signature(*callee, args, &node.results)?;
                // A collection result travels through a caller-provided
                // buffer: the extra trailing argument (`crate::sequence_layout`).
                let sequence_result_buffer = self.prepare_sequence_result_buffer(
                    *callee,
                    callee_function,
                    args,
                    trust_ir_block,
                )?;
                let requires_exact_module_binding =
                    is_module_local_function_definition(callee_function);
                let is_declared_external = callee_function.blocks.is_empty()
                    && callee_function.linkage == Linkage::External;
                let mut arg_vals: Vec<Value> =
                    args.iter().map(|vid| self.map_value(*vid)).collect();
                let result_vals = self.map_results(&node.results);
                let callee_name = self
                    .functions
                    .name(*callee)
                    .map(str::to_string)
                    .unwrap_or_else(|| callee_function.name.clone());

                // One exhaustive name classifier owns both direct-call
                // semantics and the static-call refusal gate. Adding another
                // name-recognized intrinsic therefore cannot accidentally let
                // recovered source-indirect calls acquire those semantics.
                // The name's claim stands only with the declared prototype
                // that claim needs (`classify_direct_call`): a module-local
                // definition keeps its body, a C library name declared
                // otherwise is an ordinary call of that symbol, and an LLVM
                // intrinsic name declared otherwise is refused by name.
                let named_semantics =
                    classify_direct_call(&callee_name, callee_function, callee_signature)
                        .map_err(AdapterError::UnsupportedInstruction)?;
                if sequence_result_buffer.is_some()
                    && !matches!(named_semantics, NamedCallSemantics::Ordinary)
                {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "{SEQUENCE_DIAGNOSTIC} `{callee_name}` returns a collection but its name \
                         selects intrinsic call semantics; the result buffer would be dropped"
                    )));
                }
                match named_semantics {
                    NamedCallSemantics::Ordinary => {}
                    NamedCallSemantics::Memcpy => {
                        return Ok(self.mem_intrinsic_instrs(
                            Opcode::Memcpy,
                            arg_vals,
                            &result_vals,
                        ));
                    }
                    NamedCallSemantics::Memmove => {
                        return Ok(self.mem_intrinsic_instrs(
                            Opcode::Memmove,
                            arg_vals,
                            &result_vals,
                        ));
                    }
                    NamedCallSemantics::Memset => {
                        return Ok(self.mem_intrinsic_instrs(
                            Opcode::Memset,
                            arg_vals,
                            &result_vals,
                        ));
                    }
                    NamedCallSemantics::Bitreverse(bitwidth) => {
                        return self.translate_bitreverse_intrinsic(
                            bitwidth,
                            &arg_vals,
                            &result_vals,
                        );
                    }
                    NamedCallSemantics::Objectsize(bitwidth) => {
                        return self.translate_objectsize_intrinsic(bitwidth, args, &result_vals);
                    }
                    NamedCallSemantics::Fma { fp_ty, may_unfuse } => {
                        return self.translate_fma_intrinsic(
                            fp_ty,
                            may_unfuse,
                            &arg_vals,
                            &result_vals,
                        );
                    }
                    NamedCallSemantics::PackedFma(opcode) => {
                        return self.translate_packed_fma_intrinsic(
                            opcode,
                            &callee_name,
                            &arg_vals,
                            &result_vals,
                        );
                    }
                    NamedCallSemantics::Crc32 { bytes, castagnoli } => {
                        return self.translate_crc32_intrinsic(
                            bytes,
                            castagnoli,
                            &callee_name,
                            &arg_vals,
                            &result_vals,
                        );
                    }
                }

                // Propagate callee return types onto the Call result Values
                // so ISel's `value_type()` returns the true type instead of
                // the I64 fallback (#381). The lookup yields an empty Vec
                // for unknown/extern callees; in that case we leave the
                // types unrecorded and preserve pre-#381 behavior.
                let ret_tys = self.lookup_callee_return_types(*callee);
                for (val, ty) in result_vals.iter().zip(ret_tys.iter()) {
                    self.define_value_type(*val, ty.clone());
                }

                // Seed aggregate callee PARAMETER types onto call-site-scoped
                // Copy temps so a by-value aggregate (carried by address,
                // hence typed as a pointer) is classified by ISel as a System V
                // register-pair / sret argument instead of a single GPR. The
                // returned Copies must execute immediately before the Call.
                let param_tys = self.lookup_callee_param_types(*callee);
                let mut insts = self.record_aggregate_call_arg_types(&mut arg_vals, &param_tys)?;
                // By-reference composites become pointers to storage the
                // callee may own (see `pass_composites_by_reference`).
                let anonymous_from = self
                    .lookup_callee_func_ty(*callee)
                    .filter(|func_ty| func_ty.is_vararg)
                    .map(|func_ty| func_ty.params.len());
                self.pass_composites_by_reference(args, &mut arg_vals, anonymous_from, &mut insts)?;

                // Propagate callee purity onto the LIR Call name so ISel can
                // tag the emitted `Bl` MachInst with `ProofAnnotation::Pure`.
                // Extern/unknown callees (callee not in `pure_func_ids`)
                // default to non-pure. Memory intrinsics above are handled
                // separately and are never tagged pure. (#456)
                if self.pure_func_ids.contains(callee) {
                    self.pure_callees.insert(callee_name.clone());
                }
                // The callee's INDIRECT-RETURN convention. Read from the
                // callee's own declaration so the caller and the callee body
                // cannot drift apart: whoever declared the hidden parameter
                // declared it once, and both sides read that one declaration.
                self.record_sret_arg_callee(*callee, &callee_name)?;
                // Extern callees carrying validated libm-purity authority.
                // Disjoint from `pure_func_ids` (which excludes bodyless
                // externals); currently empty because raw Custom tags are not
                // authority.
                if self.libm_pure_func_ids.contains(callee) {
                    self.libm_pure_callees.insert(callee_name.clone());
                }

                let opcode = if let Some(func_ty) = self.lookup_callee_func_ty(*callee) {
                    if func_ty.is_vararg {
                        if requires_exact_module_binding && self.allow_exact_module_calls {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "direct call to non-preemptible variadic module function \
                                 `{callee_name}` cannot carry exact-module binding through \
                                 CallVariadic"
                            )));
                        }
                        if is_declared_external && self.retain_declared_external_function_ids {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "direct call to variadic external declaration `{callee_name}` cannot retain imported FuncId through CallVariadic"
                            )));
                        }
                        // `params` is the declaration's stated fixed prefix:
                        // `validate_direct_call_signature` has already refused
                        // every variadic declaration that states none
                        // (`AdapterError::UnsignedVariadicCallee`), so this
                        // count is never a guess of zero.
                        Opcode::CallVariadic {
                            name: callee_name,
                            fixed_args: func_ty.params.len() as u32,
                        }
                    } else {
                        Opcode::Call {
                            name: callee_name,
                            binding: self.source_direct_call_binding(
                                *callee,
                                requires_exact_module_binding,
                                is_declared_external,
                            ),
                        }
                    }
                } else {
                    Opcode::Call {
                        name: callee_name,
                        binding: self.source_direct_call_binding(
                            *callee,
                            requires_exact_module_binding,
                            is_declared_external,
                        ),
                    }
                };

                // Apple arm64 ABI: the CALLER must sign/zero-extend a sub-word
                // integer argument to 32 bits before the call — the mirror of the
                // callee-side return extension (translate_return). Extend each
                // narrow fixed argument per the callee's DECLARED param signedness
                // (Ty::I8 vs Ty::U8), which is lost once lowered to the machine
                // Type; an LLVM-compiled callee at -O2 trusts the extension and
                // reads the register directly. Variadic tail args are promoted by
                // the frontend and left alone. See e2e_aarch64_call_arg_signext.rs.
                //
                // This extension applies ONLY to arguments passed in registers.
                // A narrow argument passed on the STACK is stored at its natural
                // width and packed offset, UNEXTENDED (the callee sign/zero-
                // extends it on load) — clang does exactly this. Extending a
                // stack argument would widen it into a 4-byte slot at the wrong
                // packed offset and clobber the neighbouring argument, so classify
                // against the callee's machine param types and skip stack args.
                // See e2e_aarch64_stack_narrow_args.rs.
                //
                // The extension instructions are appended to `insts`, which
                // already carries THEIRS' aggregate-by-value Copy temps from
                // record_aggregate_call_arg_types; both precede the Call. The
                // param classes are disjoint (aggregate vs narrow-int) so the
                // relative order of the two groups does not matter.
                let callee_param_tys: Vec<Ty> = self
                    .lookup_callee_func_ty(*callee)
                    .map(|ft| ft.params.clone())
                    .unwrap_or_default();
                // The hidden result pointer consumes X8, not an ordinary GPR
                // slot. Use the same effective argument list as the selector;
                // otherwise the eighth real GPR argument looks stack-passed
                // here and incorrectly misses its narrow extension.
                let arg_locs = if self.lookup_callee_sret_param(*callee)?.is_some() {
                    let ordinary_params = param_tys.get(1..).ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(
                            "[TCG-SRET-ABI] translated call signature lost its hidden parameter"
                                .to_string(),
                        )
                    })?;
                    let mut locations =
                        vec![crate::abi::ArgLocation::Reg(trust_cg_ir::aarch64_regs::X8)];
                    locations.extend(self.caller_extension_locations(ordinary_params)?);
                    locations
                } else {
                    self.caller_extension_locations(&param_tys)?
                };
                for (idx, param_ty) in callee_param_tys.iter().enumerate() {
                    // Only register arguments are caller-extended; stack args keep
                    // their natural width (stored via StrbRI/StrhRI in ISel).
                    if !matches!(arg_locs.get(idx), Some(crate::abi::ArgLocation::Reg(_))) {
                        continue;
                    }
                    let ext = self.repr_ty(param_ty)?.narrow_extension();
                    if let (Some((from_ty, signed)), Some(&arg_slot)) = (ext, arg_vals.get(idx)) {
                        let widened = self.fresh_value();
                        self.define_value_type(widened, Type::I32);
                        let ext_opcode = if signed {
                            Opcode::Sextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        } else {
                            Opcode::Uextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        };
                        insts.push(Instruction {
                            opcode: ext_opcode,
                            args: vec![arg_slot],
                            results: vec![widened],
                        });
                        arg_vals[idx] = widened;
                    }
                }

                let sequence_result_check = match sequence_result_buffer {
                    Some(prepared) => {
                        if !matches!(opcode, Opcode::Call { .. }) {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{SEQUENCE_DIAGNOSTIC} a collection-returning call must lower to \
                                 one ordinary direct call, got {opcode:?}"
                            )));
                        }
                        insts.extend(prepared.instrs);
                        arg_vals.push(prepared.buffer);
                        Some((result_vals.first().copied(), prepared.buffer, prepared.len))
                    }
                    None => None,
                };
                insts.push(Instruction {
                    opcode,
                    args: arg_vals,
                    results: result_vals,
                });
                if let Some((result, buffer, len)) = sequence_result_check {
                    self.emit_sequence_call_result_check(result, buffer, len, &mut insts);
                }
                Ok(insts)
            }

            // `calling_conv` (trust_ir v12+) declares the expected ABI of the
            // dynamically-resolved callee. trust-cg lowering currently supports
            // only the C convention for every call edge. The direct `Call` arm
            // already fails closed on non-C edges (via
            // `validate_direct_call_signature`'s callee-convention check and the
            // per-function guard), so the indirect path mirrors those guards
            // here rather than silently using the target default ABI. Revisit
            // when cg grows per-edge ABI selection.
            Inst::CallIndirect {
                callee,
                sig,
                args,
                calling_conv,
            } => {
                // A collection result needs the callee's published result
                // length to size its buffer; an indirect edge names none.
                if let Some(result) = self
                    .lookup_func_type_return_tys(*sig)
                    .into_iter()
                    .find(sequence_layout::is_collection)
                {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "{SEQUENCE_DIAGNOSTIC} CallIndirect through functy.{} returns {result:?}: \
                         an indirect edge names no callee whose published result length could \
                         size the result buffer (crate::sequence_layout, \"The ABI\")",
                        sig.index()
                    )));
                }
                // G18-2 closure application: a `Ty::Closure` callee is a
                // separate arm, reached only on the callee's DECLARED type. The
                // function-pointer rules below are not consulted for it.
                if let Some(Ty::Closure(closure_id)) = self.lookup_value_ty(*callee) {
                    return self.translate_closure_application(
                        trust_ir_block,
                        instruction_index,
                        *callee,
                        closure_id,
                        *sig,
                        args,
                        *calling_conv,
                        &node.results,
                    );
                }
                if let Some(target) = self.static_indirect_call_target(
                    trust_ir_block,
                    instruction_index,
                    *callee,
                    *sig,
                    args,
                    *calling_conv,
                    &node.results,
                ) {
                    // Re-enter the one canonical direct-call arm instead of
                    // duplicating intrinsic recognition, aggregate ABI
                    // typing, narrow-argument extension, purity propagation,
                    // or result typing. This tiny node is allocated only on a
                    // successful devirtualization; the source node still owns
                    // all proof/span/origin metadata already attached by
                    // `translate_block`.
                    self.record_static_call_stat(|stats| {
                        stats.synthetic_direct_nodes_built += 1;
                    });
                    let mut direct_node = InstrNode::new(Inst::Call {
                        callee: target,
                        args: args.clone(),
                    });
                    direct_node.results.extend_from_slice(&node.results);
                    let mut instructions = self.translate_instruction(
                        &direct_node,
                        trust_ir_block,
                        instruction_index,
                    )?;
                    let mut exact_calls = 0usize;
                    for instruction in &mut instructions {
                        if let Opcode::Call { binding, .. } = &mut instruction.opcode {
                            *binding = DirectCallBinding::ExactModuleFunction {
                                function: target.index(),
                            };
                            exact_calls += 1;
                        }
                    }
                    if exact_calls != 1 {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "authenticated static call to FuncId({}) did not lower to exactly one ordinary direct-call carrier",
                            target.index(),
                        )));
                    }
                    return Ok(instructions);
                }

                // Admit the Swift scalar subset here too (mirrors the direct-call
                // and per-function guards): a C-ABI lowering is correct for both
                // edges when the signature is scalar-only. Fall back to the
                // convention-only check if the sig can't be resolved.
                let sig_func_ty = self
                    .module
                    .and_then(|m| m.func_types.get(sig.index() as usize));
                let arch = self.guard_carrier_arch;
                let uses_c_abi = match sig_func_ty {
                    Some(ft) => Self::conv_sig_uses_c_register_abi(*calling_conv, ft, arch),
                    None => Self::calling_conv_uses_c_register_abi(*calling_conv),
                };
                if !uses_c_abi {
                    let detail = match sig_func_ty {
                        Some(ft) => Self::unsupported_conv_detail(*calling_conv, ft, arch),
                        None => format!(
                            "unsupported calling convention {calling_conv:?} for target {arch}; \
                             the signature FuncTyId({}) could not be resolved, so only the \
                             convention-only rule applies and no Swift subset can be established",
                            sig.index()
                        ),
                    };
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CallIndirect uses {detail}"
                    )));
                }
                if let Some(ft) = sig_func_ty {
                    self.admit_x86_internal_multi_result(
                        X86MultiResultSite::Indirect,
                        *calling_conv,
                        ft,
                    )?;
                }
                // The hidden return-buffer identity of this edge, from the
                // callee declaration its pointer provenance names (or none).
                let edge_passes_sret = self.resolve_static_indirect_sret_callee(
                    trust_ir_block,
                    instruction_index,
                    *callee,
                    *sig,
                    *calling_conv,
                )?;
                self.validate_call_indirect_signature(*callee, *sig, args, &node.results)?;
                self.refuse_indirect_call_to_variadic_declaration(*callee)?;
                let callee_val = self.map_value(*callee);
                let mut arg_vals = vec![callee_val];
                arg_vals.extend(args.iter().map(|vid| self.map_value(*vid)));
                let result_vals = self.map_results(&node.results);

                // Propagate callee return types onto the CallIndirect result
                // Values using the explicit `sig` carried on the trust_ir
                // instruction (#381). Same fallback semantics as Call.
                let ret_tys = self.lookup_func_type_returns(*sig);
                for (val, ty) in result_vals.iter().zip(ret_tys.iter()) {
                    self.define_value_type(*val, ty.clone());
                }

                // Seed aggregate-by-value argument types from the explicit
                // signature (same rationale as the direct-`Call` arm: scoped
                // Copy temps, prepended so they precede the call). The
                // first `arg_vals` entry is the callee pointer, not a call
                // argument, so the param types align with `arg_vals[1..]`.
                let param_tys = self.lookup_func_type_param_types(*sig);
                let mut insts =
                    self.record_aggregate_call_arg_types(&mut arg_vals[1..], &param_tys)?;
                // By-reference composites become pointers to storage the
                // callee may own (see `pass_composites_by_reference`).
                self.pass_composites_by_reference(args, &mut arg_vals[1..], None, &mut insts)?;

                // Apple arm64 ABI caller-side narrow-int extension for register
                // args — the SAME extension the direct `Call` arm performs, which
                // the indirect path previously omitted (audit P0/G6). The callee
                // pointer occupies `arg_vals[0]`, so the declared params align with
                // the argument tail: param `idx` is `arg_vals[idx + 1]`. Extend
                // each narrow fixed argument per the signature's declared
                // signedness (`Ty::I8` vs `Ty::U8`); an LLVM-compiled callee at
                // -O2 trusts the extension and reads the register directly, so a
                // non-canonical narrow value would be read wrong. Only REGISTER
                // args are extended — a narrow STACK arg keeps its natural width
                // (the callee extends it on load), exactly like clang; extending
                // it would clobber the neighbouring packed argument.
                //
                // Appended to `insts` (THEIRS' aggregate Copy temps); both
                // precede the CallIndirect and the param classes are disjoint.
                let callee_param_tys = self.lookup_func_type_param_tys(*sig);
                // The hidden result pointer consumes X8, not an ordinary GPR
                // slot (the direct-call arm's rule): classify the ordinary tail
                // exactly as the selector will, or the eighth real GPR argument
                // looks stack-passed here and misses its narrow extension.
                let arg_locs = if edge_passes_sret {
                    let ordinary_params = param_tys.get(1..).ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(
                            "[TCG-SRET-ABI] indirect call signature lost its hidden parameter"
                                .to_string(),
                        )
                    })?;
                    let mut locations =
                        vec![crate::abi::ArgLocation::Reg(trust_cg_ir::aarch64_regs::X8)];
                    locations.extend(self.caller_extension_locations(ordinary_params)?);
                    locations
                } else {
                    self.caller_extension_locations(&param_tys)?
                };
                for (idx, param_ty) in callee_param_tys.iter().enumerate() {
                    if !matches!(arg_locs.get(idx), Some(crate::abi::ArgLocation::Reg(_))) {
                        continue;
                    }
                    let ext = self.repr_ty(param_ty)?.narrow_extension();
                    if let (Some((from_ty, signed)), Some(&arg_slot)) = (ext, arg_vals.get(idx + 1))
                    {
                        let widened = self.fresh_value();
                        self.define_value_type(widened, Type::I32);
                        let ext_opcode = if signed {
                            Opcode::Sextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        } else {
                            Opcode::Uextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        };
                        insts.push(Instruction {
                            opcode: ext_opcode,
                            args: vec![arg_slot],
                            results: vec![widened],
                        });
                        arg_vals[idx + 1] = widened;
                    }
                }

                insts.push(Instruction {
                    opcode: Opcode::CallIndirect,
                    args: arg_vals,
                    results: result_vals,
                });
                Ok(insts)
            }

            Inst::Return { values } => self.translate_return(values),

            // One coroutine `yield`: save the next resume state into the frame
            // and return the yielded value. Macro-expands into the verified
            // I64 store + return primitives (see `translate_coro_suspend`).
            Inst::CoroSuspend {
                frame,
                state_slot,
                next_state,
                value,
            } => self.translate_coro_suspend(frame, *state_slot, *next_state, value),

            // Exception handling. `Invoke` is a call that may unwind to a
            // landing pad; `LandingPad` reads the unwinder-provided exception
            // pointer + selector; `Resume` re-raises. These lower onto the
            // existing, verified MachIR EH backend (LSDA + compact unwind) via
            // the LIR `Opcode::Invoke`/`LandingPad`/`Resume` and the function's
            // `eh_info`, which ISel forwards to `MachFunction.eh_metadata`.
            Inst::Invoke {
                callee,
                args,
                normal_dest,
                normal_args,
                unwind_dest,
            } => self.translate_invoke(
                *callee,
                args,
                *normal_dest,
                normal_args,
                *unwind_dest,
                &node.results,
            ),
            Inst::LandingPad {
                is_cleanup,
                catch_type_indices,
            } => self.translate_landing_pad(*is_cleanup, catch_type_indices, &node.results),
            Inst::Resume { exn } => self.translate_resume(exn),

            Inst::ExtractField {
                ty,
                aggregate,
                field,
            } => self.translate_field_extract(ty, aggregate, *field, &node.results),

            Inst::InsertField {
                ty,
                aggregate,
                field,
                value,
            } => {
                let struct_ty = self.translate_ty(ty)?;
                // Trust (WS7.1(c)): set by the direct-tag enum arm below to the byte offset
                // its read-side resolver authorised. `None` for every other carrier, which
                // keeps `explicit_field_offset` the sole authority for them.
                let mut direct_enum_payload_offset: Option<u64> = None;
                // ... and the field's MACHINE type, which the `field_ty` match below cannot
                // read off a `Type::Enum` carrier. The read-side resolver already answers it.
                let mut direct_enum_payload_lir: Option<Type> = None;
                // THE INDEX SHIFT, the write-side mirror of the one in
                // `translate_field_extract`: trust-ir indexes a niche enum
                // flatly (element 0 is the discriminant) while its carrier holds
                // the payload at `0..n`. Getting this wrong here STORES to the
                // wrong field. `niche_field_access` also answers the field's
                // trust-ir `Ty`, which `aggregate_field_ty` cannot — it refuses
                // `Ty::Enum` outright, and must keep doing so for the multi-index
                // GEP path that shares it.
                //
                // The v37 UNTAGGED carrier shifts the same way and is answered
                // first. Element 0 parts from the read side: `ExtractField`
                // materialises the sole variant's discriminant as a constant
                // because no byte of the image participates in the answer, but a
                // WRITE has nowhere to land — the image has no tag lane — and
                // there is no lane for a disagreeing value to be caught in
                // either. Discarding the store would make an unsatisfiable write
                // silently succeed, so refuse.
                let inserted_ty = self.lookup_value_ty(*value);
                let typed_niche = if let Some(declared) = inserted_ty.as_ref() {
                    self.niche_typed_field_access(ty, *field, declared, true)?
                } else {
                    None
                };
                let (field, expected_field_ty) = if let Some(DirectEnumFieldAccess::Payload {
                    offset,
                    field_ty,
                    field_lir,
                }) = typed_niche
                {
                    direct_enum_payload_offset = Some(offset);
                    direct_enum_payload_lir = Some(field_lir);
                    (*field, field_ty)
                } else {
                    match self.untagged_field_access(ty, *field)? {
                        Some(UntaggedFieldAccess::Discriminant {
                            value: sole,
                            enum_id,
                            enum_name,
                            variant_name,
                            ..
                        }) => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "element 0 of untagged enum {enum_id:?} (`{enum_name}`) is its \
                             DISCRIMINANT, and a v37 untagged image stores no tag at all — its \
                             sole variant (`{variant_name}`, discriminant {sole}) is a static \
                             fact of the type. There is no lane to write and no lane in which a \
                             disagreeing value could be detected, so refusing rather than \
                             dropping the store; ExtractField at element 0 answers the constant"
                            )));
                        }
                        Some(UntaggedFieldAccess::Payload { index, payload_ty }) => {
                            (index, payload_ty)
                        }
                        None => match self.niche_field_access(ty, *field)? {
                            // Canonical InsertField never changes an enum's
                            // variant, including one encoded in a niche lane.
                            Some(NicheFieldAccess::Discriminant(codec)) => {
                                return Err(AdapterError::EnumTagWriteUnsupported {
                                    enum_id: codec.enum_id.index(),
                                    enum_name: codec.enum_name.clone(),
                                });
                            }
                            Some(NicheFieldAccess::Payload { index, payload_ty }) => {
                                (index, payload_ty)
                            }
                            // Verify the inserted value's trust_ir type matches
                            // the declared field type. Mismatches (e.g. storing an
                            // I32 into an I64 field) are a frontend bug; fail closed
                            // rather than silently emitting a wrong-width store.
                            // `aggregate_field_ty` resolves the field's trust_ir
                            // `Ty` for struct/tuple/record aggregates.
                            //
                            // A DIRECT-TAG enum is refused by name (WS7.6), whether
                            // it lowers to `Type::Enum` or to the byte-image carrier
                            // of a producer layout (L05-P5) — the carrier's own
                            // field walk must never see trust-ir's flat index.
                            // Element 0 would re-tag the value, which trust-ir makes
                            // undefined behaviour and its validator refuses. A
                            // payload element stays refused: the value-semantic
                            // insert (`insert_destination`) is not wired to the
                            // direct-tag carrier's field walk.
                            None => {
                                if let Ty::Enum(eid) = ty
                                    && direct_enum_def(ty, self.enums).is_some()
                                {
                                    let enum_name = self.enum_def(ty)?.name.clone();
                                    if *field == 0 {
                                        // Canonical `InsertField` never changes a variant.
                                        return Err(AdapterError::EnumTagWriteUnsupported {
                                            enum_id: eid.index(),
                                            enum_name,
                                        });
                                    }
                                    // Trust (WS7.1(c), 2026-09-26): the direct-tag carrier's
                                    // payload insert is WIRED now. The two halves it needed
                                    // already existed and were simply never connected:
                                    //
                                    //  * the OFFSET AUTHORITY, on the read side.
                                    //    `direct_enum_field_access` resolves element `i > 0` to
                                    //    the byte offset every candidate variant places payload
                                    //    field `i - 1` at, and refuses by name when they
                                    //    disagree (`EnumProjectionOffsetAmbiguous`) or when no
                                    //    variant has that field at that type
                                    //    (`EnumProjectionNoCandidate`). Those refusals are the
                                    //    reason this is safe to wire: an ambiguous or ill-typed
                                    //    lane never reaches the store.
                                    //  * the FRESH SLOT, on the write side. `insert_destination`
                                    //    already copies a non-reusable source into new storage
                                    //    before the store, which is what makes the insert
                                    //    value-semantic; updating the operand in place would
                                    //    alias every other value sharing it. That is the same
                                    //    defect trust-cg fixed for struct, array and sequence
                                    //    values in `fda1c5e5c` ("fresh storage for insert
                                    //    results"), and the enum carrier was the fourth carrier
                                    //    that fix did not reach.
                                    //
                                    // The offset is threaded to the store below rather than
                                    // going through `explicit_field_offset`, because that reads
                                    // `emitted_layout(ty).offsets[index]` — indexed by the
                                    // CARRIER's field order, which for an enum is not trust-ir's
                                    // flat element index. Handing it the flat index would store
                                    // to the wrong lane, silently.
                                    // The lane alone does not name the variant, so the resolver
                                    // needs the DECLARED type of the value being inserted to pick
                                    // the candidate variants — exactly as the read side passes
                                    // `ExtractField`'s declared result type.
                                    let declared = self.lookup_value_ty(*value).ok_or_else(|| {
                                    AdapterError::UnsupportedInstruction(format!(
                                        "InsertField into enum `{enum_name}` element {}: the \
                                         inserted value {value:?} has no known trust_ir type, \
                                         so the payload lane cannot be resolved",
                                        *field
                                    ))
                                })?;
                                    match self.direct_enum_field_access(ty, *field, &declared)? {
                                        Some(DirectEnumFieldAccess::Payload {
                                            offset,
                                            field_ty,
                                            field_lir,
                                        }) => {
                                            direct_enum_payload_offset = Some(offset);
                                            direct_enum_payload_lir = Some(field_lir);
                                            (*field, field_ty)
                                        }
                                        // A tag access here would re-tag the value; refused
                                        // above by element index, and again by shape.
                                        Some(DirectEnumFieldAccess::Tag { .. }) => {
                                            return Err(AdapterError::EnumTagWriteUnsupported {
                                                enum_id: eid.index(),
                                                enum_name,
                                            });
                                        }
                                        None => {
                                            return Err(
                                                AdapterError::EnumPayloadInsertUnsupported {
                                                    enum_id: eid.index(),
                                                    enum_name,
                                                    lane: *field,
                                                },
                                            );
                                        }
                                    }
                                } else {
                                    (*field, self.aggregate_field_ty(ty, *field as usize)?)
                                }
                            }
                        },
                    }
                };
                // A direct-tag enum payload lane: the carrier is `Type::Enum`, whose fields
                // the arms below cannot index, and the read-side resolver already gave us the
                // lane's machine type. Taking it here is what lets the shared store path run
                // unchanged for an enum.
                let field_ty = match direct_enum_payload_lir {
                    Some(field_lir) => field_lir,
                    None => match &struct_ty {
                        Type::Struct(fields) => {
                            fields.get(field as usize).cloned().ok_or_else(|| {
                                AdapterError::UnsupportedInstruction(format!(
                                    "struct field {} out of bounds for {:?}",
                                    field, struct_ty
                                ))
                            })?
                        }
                        // `Array(t, n)` is the compact spelling of `Struct([t; n])`:
                        // every element has type `t`, and `Type::offset_of` places
                        // element `k` where field `k` of the struct spelling sits.
                        Type::Array(elem, count) => {
                            // `field` was rebound above by `niche_field_access`, so
                            // it is a value here, not the original `&u32` operand —
                            // same binding the `Type::Struct` arm uses.
                            if field >= *count {
                                return Err(AdapterError::UnsupportedInstruction(format!(
                                    "array element {} out of bounds for {:?}",
                                    field, struct_ty
                                )));
                            }
                            (**elem).clone()
                        }
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "InsertField expected struct type, got {:?}",
                                struct_ty
                            )));
                        }
                    },
                };
                let value_ty = self.lookup_value_ty(*value).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "InsertField requires field value type, but value {:?} has unknown type",
                        value
                    ))
                })?;
                if value_ty != expected_field_ty {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "InsertField value type {:?} does not match field type {:?} for {:?}",
                        value_ty, expected_field_ty, ty
                    )));
                }
                // WS7.1 (b): only the VALUE form is trust-ir. An operand that is
                // a POINTER to the aggregate (the "store form", an in-place
                // write through memory) or of unknown type is refused by name:
                // under value semantics its write would land in the result's
                // private copy and be silently lost.
                self.require_value_form_insert("insertfield", ty, *aggregate)?;
                let source_ptr = self.map_value(*aggregate);
                let field_val = self.map_value(*value);
                let dst = self.map_result(&node.results)?;
                // VALUE SEMANTICS. An aggregate is pointer-represented, so the
                // result must not share storage with a source that is still
                // live: `swap(s) = insert(insert(s, 0, s.1), 1, s.0)` reads
                // `s.0` after the first insert. `insert_destination` copies the
                // source into a fresh slot, reusing the source's own slot only
                // when that slot is provably unshared and dead after this
                // instruction.
                let mut instrs = Vec::new();
                let base_ptr = self.insert_destination(
                    ty,
                    &struct_ty,
                    *aggregate,
                    source_ptr,
                    &node.results,
                    &mut instrs,
                )?;
                let field_ptr = self.fresh_value();

                // Byte-stride GEP reads the aggregate's storage address. Numeric
                // Iadd cannot take its logical aggregate type as an integer.
                // The field sits at the AUTHORITATIVE offset — the producer's
                // declared one, or the PACKED one — which `StructGep` cannot
                // express (symmetric to the field READ in
                // translate_field_extract). A SCALAR field is written with a
                // byte-offset Store, possibly UNALIGNED when the struct is
                // packed; an AGGREGATE field is pointer-represented, so it is
                // byte-copied with Memmove of the field's own authoritative
                // extent from the source aggregate — the write-side mirror of
                // the read, which addresses a nested aggregate field at
                // base+offset. The inner aggregate keeps its own layout, so
                // copying its byte image to that offset is correct, and Memmove
                // is byte-granular (no alignment requirement) and
                // self-copy-safe.
                // Trust (WS7.1(c)): a direct-tag enum payload lane uses the offset its
                // read-side resolver authorised; everything else asks
                // `explicit_field_offset`, unchanged.
                let authoritative_offset = match direct_enum_payload_offset {
                    Some(offset) => Some(offset),
                    None => self.explicit_field_offset(ty, &struct_ty, field)?,
                };
                if let Some(offset) = authoritative_offset {
                    let store_align = if self.is_packed_struct_ty(ty) {
                        Some(1)
                    } else {
                        None
                    };
                    let off_val = self.fresh_value();
                    self.define_value_type(off_val, Type::I64);
                    instrs.push(Instruction {
                        opcode: Opcode::Iconst {
                            ty: Type::I64,
                            imm: offset as i64,
                        },
                        args: vec![],
                        results: vec![off_val],
                    });
                    instrs.push(Instruction {
                        opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
                        args: vec![base_ptr, off_val],
                        results: vec![field_ptr],
                    });
                    // `is_aggregate`, not Struct|Array: an ENUM field
                    // (`Type::Enum`) is pointer-represented too, and a scalar
                    // Store would write 8 bytes of its ADDRESS (WS7.6 review).
                    if field_ty.is_aggregate() {
                        // The copy length is the field's own AUTHORITATIVE
                        // extent, because that is what the containing struct's
                        // authority advanced its running offset by when it
                        // placed the NEXT sibling. `field_ty.bytes()`
                        // (natural-C) would reach past this field and clobber
                        // that sibling — see `aggregate_value_extent`.
                        let len =
                            self.aggregate_value_extent(&expected_field_ty, &field_ty)? as i64;
                        let len_val = self.emit_iconst_i64(len, &mut instrs);
                        instrs.push(Instruction {
                            opcode: Opcode::Memmove,
                            args: vec![field_ptr, field_val, len_val],
                            results: vec![],
                        });
                    } else {
                        instrs.push(Instruction {
                            opcode: Opcode::Store {
                                ty: field_ty,
                                align: store_align,
                            },
                            args: vec![field_val, field_ptr],
                            results: vec![],
                        });
                    }
                    instrs.push(Instruction {
                        opcode: Opcode::Copy,
                        args: vec![base_ptr],
                        results: vec![dst],
                    });
                    return Ok(instrs);
                }

                // Non-packed path: an aggregate FIELD (Struct/Array/Enum) is
                // pointer-represented, so `field_val` is the ADDRESS of the source
                // aggregate — a scalar `Store` would write 8 bytes of that address
                // instead of copying the field's DATA. Lower it as a byte copy:
                // StructGep to the destination field slot, then `Memmove` of
                // `field_ty.bytes()` from the source aggregate. Memmove (not
                // Memcpy) because the source may alias the destination — e.g.
                // `s.f = s.f` extracts a pointer INTO `s` and reinserts it at the
                // same slot (dst == src); memmove is defined for that, memcpy is
                // not. All opcodes used (StructGep/Iconst/Memmove/Copy) are proven.
                if field_ty.is_aggregate() {
                    // The copy length is the field's own AUTHORITATIVE extent,
                    // for the same reason as the explicit-offset arm above: it
                    // is what placed the next sibling.
                    let field_bytes =
                        self.aggregate_value_extent(&expected_field_ty, &field_ty)? as i64;
                    instrs.push(Instruction {
                        opcode: Opcode::StructGep {
                            struct_ty,
                            field_index: field,
                        },
                        args: vec![base_ptr],
                        results: vec![field_ptr],
                    });
                    let len_val = self.emit_iconst_i64(field_bytes, &mut instrs);
                    instrs.push(Instruction {
                        opcode: Opcode::Memmove,
                        args: vec![field_ptr, field_val, len_val],
                        results: vec![],
                    });
                    instrs.push(Instruction {
                        opcode: Opcode::Copy,
                        args: vec![base_ptr],
                        results: vec![dst],
                    });
                    return Ok(instrs);
                }

                instrs.push(Instruction {
                    opcode: Opcode::StructGep {
                        struct_ty,
                        field_index: field,
                    },
                    args: vec![base_ptr],
                    results: vec![field_ptr],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Store {
                        ty: field_ty,
                        align: None,
                    },
                    args: vec![field_val, field_ptr],
                    results: vec![],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Copy,
                    args: vec![base_ptr],
                    results: vec![dst],
                });
                Ok(instrs)
            }

            Inst::ExtractElement { ty, array, index } => {
                if let Some(array_ty) = self.lookup_value_ty(*array)
                    && matches!(array_ty, Ty::Vector(_, _))
                {
                    if Self::is_v2i64_ty(&array_ty) {
                        return self.translate_v2i64_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    if Self::is_v16i8_ty(&array_ty) {
                        return self.translate_v16i8_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    if Self::is_v8i16_ty(&array_ty) {
                        return self.translate_v8i16_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    if Self::is_v4f32_ty(&array_ty) || Self::is_v2f64_ty(&array_ty) {
                        return self.translate_fp_vector_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    return self.translate_v4i32_extract_element(ty, *array, *index, &node.results);
                }

                // Non-vector ExtractElement dispatches on the SOURCE value's
                // type. An array source uses the bare-pointer array layout; a
                // sequence source uses the length-prefixed stack-buffer layout
                // and fails closed unless the value carries materialized layout
                // provenance. A scalar/pointer or set/record/closure source is
                // rejected so we never lower an element load as bare pointer
                // arithmetic over an unknown layout.
                let array_ty = self.lookup_value_ty(*array).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "ExtractElement requires array or vector source type, but source {:?} has unknown type",
                        array
                    ))
                })?;
                match &array_ty {
                    Ty::Array(elem_ty_id, _) => {
                        let actual_elem_ty =
                            self.types.get(elem_ty_id.as_usize()).ok_or_else(|| {
                                AdapterError::UnsupportedInstruction(format!(
                                    "ExtractElement array element TyId {:?} is not in the module types table",
                                    elem_ty_id
                                ))
                            })?;
                        if actual_elem_ty != ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "ExtractElement declared element type {:?} does not match array element type {:?} for source {:?}",
                                ty, actual_elem_ty, array_ty
                            )));
                        }
                    }
                    // trust-ir's codegen gate: no element of a sequence is
                    // addressable, whatever the operand's provenance.
                    Ty::Sequence(_) | Ty::Set(_, _) => {
                        return Err(sequence_element_op_refusal("ExtractElement", &array_ty));
                    }
                    // A first-class closure is a struct of its captures, so an
                    // ExtractElement over a closure source is a fixed-offset
                    // struct field access (NOT scaled array arithmetic). The
                    // capture index must be a compile-time constant — the
                    // struct-layout byte offset comes from `Type::offset_of` via
                    // `Opcode::StructGep` — so reuse the StructGep + Load path
                    // that struct/tuple/record field extraction uses. The
                    // declared element `ty` is checked against the capture type
                    // so a wrong-width load is never emitted.
                    Ty::Closure(_) => {
                        let field_index = self.require_gep_struct_field_index(*index)?;
                        let capture_ty =
                            self.aggregate_field_ty(&array_ty, field_index as usize)?;
                        if &capture_ty != ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "ExtractElement declared element type {:?} does not match closure capture type {:?} (index {}) for source {:?}",
                                ty, capture_ty, field_index, array_ty
                            )));
                        }
                        return self.translate_field_extract(
                            &array_ty,
                            array,
                            field_index,
                            &node.results,
                        );
                    }
                    Ty::Record(_) => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "ExtractElement over trust_ir#30 aggregate source {:?} is not yet lowered; no CPU layout or element ABI exists",
                            array_ty
                        )));
                    }
                    other => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "ExtractElement requires array or vector source type, got {:?}",
                            other
                        )));
                    }
                }

                let elem_ty = self.translate_ty(ty)?;
                let base_ptr = self.map_value(*array);
                let index_val = self.map_value(*index);
                let dst = self.map_result(&node.results)?;
                let mut instrs = Vec::new();
                let index_val =
                    self.extend_index_to_i64_if_needed(*index, index_val, &mut instrs)?;
                self.append_exact_in_bounds_guard(node, base_ptr, index_val, &mut instrs);

                // An AGGREGATE element (array of structs/arrays) is pointer-
                // represented: its value IS the element's address, so use the
                // ArrayGep result directly with NO Load — symmetric to
                // translate_field_extract's nested-aggregate handling. A scalar
                // Load of a struct type would read only the first 8 bytes (its
                // address image), a silent miscompile.
                if elem_ty.is_aggregate() {
                    self.emit_array_element_ptr(
                        ty,
                        &elem_ty,
                        base_ptr,
                        index_val,
                        dst,
                        &mut instrs,
                    )?;
                    self.define_value_type(dst, elem_ty);
                    return Ok(instrs);
                }

                let elem_ptr = self.fresh_value();
                self.emit_array_element_ptr(
                    ty,
                    &elem_ty,
                    base_ptr,
                    index_val,
                    elem_ptr,
                    &mut instrs,
                )?;

                instrs.push(Instruction {
                    opcode: Opcode::Load {
                        ty: elem_ty,
                        align: None,
                    },
                    args: vec![elem_ptr],
                    results: vec![dst],
                });

                Ok(instrs)
            }

            Inst::InsertElement {
                ty,
                array,
                index,
                value,
            } => {
                if matches!(ty, Ty::Vector(_, _)) {
                    if Self::is_v2i64_ty(ty) {
                        return self.translate_v2i64_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    if Self::is_v16i8_ty(ty) {
                        return self.translate_v16i8_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    if Self::is_v8i16_ty(ty) {
                        return self.translate_v8i16_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    if Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty) {
                        return self.translate_fp_vector_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    return self.translate_v4i32_insert_element(
                        ty,
                        *array,
                        *index,
                        *value,
                        &node.results,
                    );
                }

                // Non-vector InsertElement dispatches on the SOURCE value's type
                // (not the declared result `ty`): the source layout is what
                // determines how the element is addressed. A sequence source uses
                // the length-prefixed stack-buffer layout; an array source uses
                // the bare-pointer array layout. Anything else (scalar/pointer,
                // set/record/closure) is rejected here so we never lower an
                // element insert as bare pointer arithmetic over an unknown
                // layout.
                let array_ty = self.lookup_value_ty(*array).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "InsertElement requires array or vector source type, but source {:?} has unknown type",
                        array
                    ))
                })?;
                match &array_ty {
                    Ty::Array(_, _) => {
                        if ty != &array_ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "InsertElement declared result type {:?} does not match source aggregate type {:?} for source {:?}",
                                ty, array_ty, array
                            )));
                        }
                    }
                    // trust-ir's codegen gate: no element of a sequence is
                    // addressable, whatever the operand's provenance.
                    Ty::Sequence(_) | Ty::Set(_, _) => {
                        return Err(sequence_element_op_refusal("InsertElement", &array_ty));
                    }
                    Ty::Vector(_, _) => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertElement declared result type {:?} does not match source aggregate type {:?} for source {:?}",
                            ty, array_ty, array
                        )));
                    }
                    Ty::Record(_) | Ty::Closure(_) => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertElement over trust_ir#30 aggregate/closure source {:?} is not yet lowered; no CPU layout or element ABI exists",
                            array_ty
                        )));
                    }
                    other => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertElement requires array or vector source type, got {:?}",
                            other
                        )));
                    }
                };
                let Ty::Array(elem_ty_id, _) = &array_ty else {
                    unreachable!("InsertElement non-array source rejected above");
                };
                let elem_ty = self
                    .types
                    .get(elem_ty_id.as_usize())
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "InsertElement array element TyId {:?} is not in the module types table",
                            elem_ty_id
                        ))
                    })?
                    .clone();
                let value_ty = self.lookup_value_ty(*value).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "InsertElement requires element value type, but value {:?} has unknown type",
                        value
                    ))
                })?;
                if value_ty != elem_ty {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "InsertElement value type {:?} does not match array element type {:?} for source {:?}",
                        value_ty, elem_ty, array_ty
                    )));
                }

                let lir_elem_ty = self.translate_ty(&elem_ty)?;
                let source_ptr = self.map_value(*array);
                let index_val = self.map_value(*index);
                let elem_val = self.map_value(*value);
                let dst = self.map_result(&node.results)?;
                let mut instrs = Vec::new();
                let index_val =
                    self.extend_index_to_i64_if_needed(*index, index_val, &mut instrs)?;
                // VALUE SEMANTICS, as for `InsertField`: the element is written
                // into a fresh copy of the source array unless the source's own
                // slot is provably unshared and dead after this instruction.
                // The bounds guard and the element address use that
                // destination, which has the source's type and so its bound.
                let array_lir_ty = self.translate_ty(&array_ty)?;
                let base_ptr = self.insert_destination(
                    &array_ty,
                    &array_lir_ty,
                    *array,
                    source_ptr,
                    &node.results,
                    &mut instrs,
                )?;
                self.append_exact_in_bounds_guard(node, base_ptr, index_val, &mut instrs);

                let elem_ptr = self.fresh_value();
                self.emit_array_element_ptr(
                    &elem_ty,
                    &lir_elem_ty,
                    base_ptr,
                    index_val,
                    elem_ptr,
                    &mut instrs,
                )?;

                // An AGGREGATE element is pointer-represented, so `elem_val` is
                // the ADDRESS of the source aggregate — a scalar Store would write
                // 8 bytes of that address instead of the element's data (a silent
                // miscompile). Byte-copy it with Memmove (self-copy-safe), exactly
                // as the aggregate InsertField path does.
                //
                // The LENGTH is the AUTHORITATIVE extent, and it HAD to move with
                // the stride above rather than after it: once element `i` sits at
                // `i * 9` for `P = #[repr(C,packed)] { a: u8, b: u64 }`, a
                // natural-C 16-byte copy into element 0 covers bytes 0..16 and
                // CLOBBERS the first seven bytes of element 1. (c) MEASURED —
                // this site emitted `Iconst 16` + `Memmove` for a value rustc
                // sizes at 9, and was the last aggregate copy length in the
                // adapter still reading `Type::bytes()`.
                if lir_elem_ty.is_aggregate() {
                    let extent = self.aggregate_value_extent(&elem_ty, &lir_elem_ty)?;
                    let len_val = self.emit_iconst_i64(extent as i64, &mut instrs);
                    instrs.push(Instruction {
                        opcode: Opcode::Memmove,
                        args: vec![elem_ptr, elem_val, len_val],
                        results: vec![],
                    });
                } else {
                    instrs.push(Instruction {
                        opcode: Opcode::Store {
                            ty: lir_elem_ty,
                            align: None,
                        },
                        args: vec![elem_val, elem_ptr],
                        results: vec![],
                    });
                }
                instrs.push(Instruction {
                    opcode: Opcode::Copy,
                    args: vec![base_ptr],
                    results: vec![dst],
                });

                Ok(instrs)
            }

            Inst::Const { ty, value } => match value {
                Constant::Ext(e) => e.unreachable(),
                Constant::FnItem(_) => Err(AdapterError::UnmodeledTrustIrConstruct {
                    location: "Const lowering".to_owned(),
                    construct: "Constant::FnItem",
                    reason: FN_ITEM_UNMODELED,
                }),
                Constant::TensorBlob { .. } => Err(AdapterError::UnmodeledTrustIrConstruct {
                    location: "Const lowering".to_owned(),
                    construct: "Constant::TensorBlob",
                    reason: TENSOR_BLOB_UNMODELED,
                }),
                Constant::Int(v) => self.translate_int_const(ty, *v, &node.results),
                // trust-ir v24: the 128-bit-faithful unsigned carrier
                // (canonical iff value > i128::MAX). Validate that spelling,
                // then materialize both physical u64 halves directly so the
                // unsigned value never passes through signed range checking.
                Constant::U128(v) => self.translate_u128_const(ty, *v, &node.results),
                // trust-ir v25 Bytes: the byte-array carrier (string/byte-string
                // literals). Per the reference interpreter, a bytes constant is
                // executable EXACTLY as an `Array` of `U8` ints for a `[u8; N]`
                // declared type — so we reuse the proven aggregate-const path.
                Constant::Bytes { data, utf8 } => {
                    self.translate_bytes_const(ty, data, *utf8, &node.results)
                }
                Constant::Float(v) => self.translate_fconst(ty, *v, &node.results),
                Constant::Bool(b) => {
                    self.translate_const(ty, if *b { 1 } else { 0 }, &node.results)
                }
                Constant::Vector(elems) => self.translate_vector_const(ty, elems, &node.results),
                Constant::Aggregate(elems) | Constant::Array(elems) => {
                    if matches!(ty, Ty::Vector(_, _)) {
                        self.translate_vector_const(ty, elems, &node.results)
                    } else {
                        self.translate_aggregate_const(ty, elems, &node.results)
                    }
                }
                // trust-ir v50: `len` copies of `elem`, materialized in
                // constant size (`fill_splat_at_ptr`).
                Constant::Splat { elem, len } => {
                    self.translate_splat_const(ty, elem, *len, &node.results)
                }
                // The legacy capture-free spelling at `Ty::Func` is a bare
                // function symbol (rustc `lang_start`). Every closure constant
                // at `Ty::Closure` — captured or not — is a first-class closure
                // VALUE: its environment is materialized as the struct of its
                // captures and its code identity stays static (see
                // `translate_closure_const`).
                Constant::Closure { func, captures }
                    if captures.is_empty() && matches!(ty, Ty::Func(_)) =>
                {
                    self.translate_function_symbol_const(ty, *func, &node.results)
                }
                Constant::Closure { func, captures } => {
                    self.translate_closure_const(ty, *func, captures, &node.results)
                }
                Constant::FnDef(func) => {
                    self.translate_function_symbol_const(ty, *func, &node.results)
                }
                // trust_ir#30 aggregate constants — ty-style records, sets and
                // sequences.
                // `SymbolAddr` is the relocatable address of a named symbol. As
                // a global-initializer element it lowers to a data relocation in
                // the object writer; as a FUNCTION-BODY constant it materializes
                // that address into an SSA register via a GlobalRef (defined) /
                // ExternRef (external) relocation — the raw-name counterpart of
                // the `FnDef` and `GlobalAddr` paths.
                Constant::SymbolAddr { symbol, addend } => {
                    self.translate_symbol_addr_const(symbol, *addend, &node.results)
                }
                Constant::Record(fields) => self.translate_record_const(ty, fields, &node.results),
                // `crate::sequence_layout` images; a set keeps the
                // constructor's canonical order and may not repeat.
                Constant::Sequence(elems) | Constant::Set(elems) => {
                    self.translate_collection_const(ty, value, elems, &node.results)
                }
                // `phantomdata` is trust-ir's one spelling of the value of
                // `()` (`shape_matches_ty` admits it at `Ty::Unit` only, and
                // typed admission refuses the empty aggregate there). It is the
                // same zero-sized value the empty aggregate at `Ty::Unit`
                // lowers to, so it lowers through that arm.
                Constant::PhantomData if matches!(ty, Ty::Unit) => {
                    self.translate_aggregate_const(ty, &[], &node.results)
                }
                // At any other type its value-level consumers are unmodeled;
                // refused by name.
                Constant::PhantomData => Err(AdapterError::UnsupportedInstruction(format!(
                    "trust_ir#30 aggregate/closure constant not yet lowered: {:?}",
                    value
                ))),
                // v49: never a whole constant (trust-ir refuses that shape too).
                Constant::Uninit => Err(AdapterError::UnmodeledTrustIrConstruct {
                    location: "Const lowering".to_owned(),
                    construct: "Constant::Uninit",
                    reason: UNINIT_UNMODELED,
                }),
            },

            Inst::NullPtr => self.translate_const(&Ty::Ptr, 0, &node.results),

            // A unit `()` or never `!` undef is a ZERO-SIZED value with no
            // machine representation and no bits to be poison — emit nothing.
            // Its type is recorded (value-type inference), so the sole consumer
            // (a `ret`) drops it via the zero-sized-value filter.
            Inst::Undef {
                ty: Ty::Unit | Ty::Never,
            } => Ok(vec![]),
            // Every other undef is poison. The legalization stage admitted it
            // only if it is a scalar whose poison never reaches an inspecting
            // use; it materializes under the NoUndef zero model.
            Inst::Undef { ty } => self.translate_legalized_undef(node, ty),

            // Materialize Assume as a CHECKED runtime assertion (traps if the
            // assumed condition is false) rather than dropping it: a verified
            // backend must not blindly trust a possibly-wrong assumption (which
            // would be a soundness hole). origin/main dropped it to `Ok(vec![])`.
            Inst::Assume { cond } => {
                self.validate_bool_condition("Inst::Assume", *cond)?;
                Ok(vec![Instruction {
                    opcode: Opcode::Assert,
                    args: vec![self.map_value(*cond)],
                    results: vec![],
                }])
            }

            Inst::Assert {
                cond,
                kind,
                site: Some(site),
            } => {
                self.translate_sited_assert(*cond, *kind, *site, trust_ir_block, instruction_index)
            }
            Inst::Assert {
                cond,
                kind,
                site: None,
            } => {
                self.validate_bool_condition("Inst::Assert", *cond)?;
                Err(assert_panics::unsupported(
                    *kind,
                    "Assert lowering backstop".to_owned(),
                ))
            }
            Inst::AssertInvoke {
                cond,
                kind,
                site,
                normal_dest,
                normal_args,
                unwind_dest,
            } => self.translate_sited_assert_invoke(
                *cond,
                *kind,
                *site,
                *normal_dest,
                normal_args,
                *unwind_dest,
                trust_ir_block,
                instruction_index,
            ),

            Inst::Unreachable => Ok(vec![Instruction {
                opcode: Opcode::Trap,
                args: vec![],
                results: vec![],
            }]),

            Inst::Copy { ty: _, operand } => {
                // Direct 1:1 mapping: trust_ir Copy -> LIR Copy.
                let src = self.map_value(*operand);
                let dst = self.map_result(&node.results)?;
                Ok(vec![Instruction {
                    opcode: Opcode::Copy,
                    args: vec![src],
                    results: vec![dst],
                }])
            }

            Inst::Select {
                ty,
                cond,
                then_val,
                else_val,
            } => {
                self.validate_select_operands(ty, *cond, *then_val, *else_val)?;
                let is_narrow_select = Self::is_v16x8_ty(ty) || Self::is_v8x16_ty(ty);
                let cond_val = self.map_value(*cond);
                let then_v = self.map_value(*then_val);
                let else_v = self.map_value(*else_val);
                let dst = self.map_result(&node.results)?;
                if is_narrow_select {
                    self.define_value_type(dst, Type::V128);
                }

                Ok(vec![Instruction {
                    opcode: Opcode::Select {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![cond_val, then_v, else_v],
                    results: vec![dst],
                }])
            }

            // Borrows (Rust ownership model; trust-ir `interpret.rs`): the
            // result is the operand pointer verbatim, `EndBorrow` has no
            // runtime effect. Lowered as a value-preserving copy with the
            // borrowed root recorded, once the legalization stage admitted
            // the shape; liveness stays the producer's obligation.
            Inst::Borrow { ptr } | Inst::BorrowMut { ptr } => {
                self.translate_legalized_borrow(node, *ptr)
            }
            Inst::EndBorrow { borrow_ptr } => self.translate_legalized_end_borrow(*borrow_ptr),

            // ARC instructions (Perceus/Swift-style reference counting). In the
            // trust-ir operational model these gate on the `arcRef` permission
            // installed by the producer's RC runtime, so the machine-level
            // lowering is a CALL into that runtime. Retain/Release carry no
            // origin field (unlike `HeapAlloc`), so the adapter routes by the
            // module's own declared RC-runtime imports: a Clean-produced module
            // declares the `clean_inc`/`clean_dec`/`clean_is_exclusive`
            // bodyless-external triple (P1 native ARC; the Clean frontend
            // emits native ARC ops and keeps the triple declared as its
            // RC-runtime provenance). A module that declares no RC runtime
            // fails closed — retaining through the wrong runtime would
            // silently corrupt another runtime's refcount discipline. When a
            // second RC-runtime producer lands (Swift), this routing must
            // grow its triple and fail closed on ambiguity.
            Inst::Retain { ptr } => {
                self.translate_arc_op("Retain", RuntimeSymbol::CleanInc, *ptr, &node.results)
            }
            Inst::Release { ptr } => {
                self.translate_arc_op("Release", RuntimeSymbol::CleanDec, *ptr, &node.results)
            }
            Inst::IsUnique { ptr } => self.translate_arc_op(
                "IsUnique",
                RuntimeSymbol::CleanIsExclusive,
                *ptr,
                &node.results,
            ),

            // Heap allocation (trust_ir B2). Box/Vec/String backing and
            // `malloc` route through here. Lowered to a CALL of the allocator
            // function selected by `origin`: the Rust global allocator
            // (`__rust_alloc(size, align)`) or libc (`malloc(size)`). Swift
            // heap allocation has no portable two-argument shim yet and stays
            // fail-closed. See `translate_heap_alloc`.
            Inst::HeapAlloc {
                ty,
                count,
                align,
                origin,
            } => self.translate_heap_alloc(ty, count, *align, *origin, &node.results),

            // Address of a module global (trust_ir B1): the relocatable address
            // of the global's data/rodata symbol, materialized exactly like the
            // imported `Constant::Int` global-address stub via
            // `Opcode::GlobalRef`. See `translate_global_addr`.
            Inst::GlobalAddr { global } => self.translate_global_addr(*global, &node.results),

            // Deallocation (G18-1, re-decided 2026-09-27; trust-ir
            // `docs/SPEC_RATIFICATIONS.md` "Deallocation is refused for
            // codegen, whatever its provenance"). TrustIR `Dealloc` names only
            // a pointer: neither the `AllocOrigin` whose runtime owns the
            // region nor the layout being released. trust-ir refuses EVERY
            // `Dealloc` in EVERY body for codegen (`UnlowerableForCodegen`,
            // must-refuse row `refuse/dealloc_instruction`), and a backend
            // MUST NOT recover either from dataflow. This backend conforms:
            // it refuses unconditionally, in a licensed, claim-less or
            // `Ungated` body alike, and has no provenance analysis to fall
            // back on (the retired lowering, 2887cbf01, recovered both from
            // same-function `HeapAlloc` sites).
            Inst::Dealloc { .. } => Err(dealloc_refusal(
                "TrustIR Dealloc names only a pointer, so it carries no allocator origin or \
                 layout; trust-ir refuses every Dealloc for codegen in every body \
                 (UnlowerableForCodegen, G18-1, refuse/dealloc_instruction) and this backend \
                 conforms: it does not recover either from dataflow. Spell the release the way \
                 the owning runtime pins it: Release for a reference-counted cell, or a call to \
                 the runtime's deallocation entry point paired with its allocation call",
            )),

            // Structural sequence maps (trust-ir interpret.rs semantics: `+k`
            // wrapping at the element width, `Bool.not`, or `fwd(&mut elem)`
            // per element), each lowered as a counted loop over the source
            // image into a fresh result image (`translate_seq_map`).
            Inst::SeqMapAddK { ty, seq, k } => self.translate_seq_map(
                SeqMapOp::AddK(*k),
                ty,
                *seq,
                &node.results,
                trust_ir_block,
                instruction_index,
            ),
            Inst::SeqMapNot { ty, seq } => self.translate_seq_map(
                SeqMapOp::Not,
                ty,
                *seq,
                &node.results,
                trust_ir_block,
                instruction_index,
            ),
            Inst::SeqMap { ty, seq, fwd } => self.translate_seq_map(
                SeqMapOp::Map(*fwd),
                ty,
                *seq,
                &node.results,
                trust_ir_block,
                instruction_index,
            ),

            // Binding frames (trust_ir#30 §R4) — typed SSA frames for
            // quantifier lowering. The legalization stage admitted the
            // function only after its liveness check found no superseded
            // handle live after a rebind (a static check exercised by tests,
            // not a proof), so one zero-filled stack slot per `OpenFrame`
            // honours the functional `BindSlot` there: bind stores in place,
            // load reads, close emits nothing (trust-ir gives it no runtime
            // effect).
            Inst::OpenFrame { .. } => self.translate_legalized_open_frame(node),
            Inst::BindSlot { frame, slot, value } => {
                self.translate_legalized_bind_slot(node, *frame, *slot, *value)
            }
            Inst::LoadSlot { frame, slot, .. } => {
                self.translate_legalized_load_slot(node, *frame, *slot)
            }
            Inst::CloseFrame { frame } => {
                self.legalized_frame_slot(*frame, None, "Inst::CloseFrame")?;
                Ok(vec![])
            }

            // Trust Codegen-owned typed dialect ops can lower directly here. Other
            // dialects must be rewritten by the pre-adapter dialect pipeline.
            Inst::DialectOp(op) if vector_dialect::is_pack_lanes_op(op) => {
                self.translate_trust_ir_vector_pack_lanes_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if vector_dialect::is_extract_lane_op(op) => {
                self.translate_trust_ir_vector_extract_lane_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if vector_dialect::is_insert_lane_op(op) => {
                self.translate_trust_ir_vector_insert_lane_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if vector_dialect::is_mask_to_bits_op(op) => {
                self.translate_trust_ir_vector_mask_to_bits_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if op.dialect == crate::aarch64_fp_dialect::DIALECT => {
                self.translate_aarch64_fp_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_bitfield_op(op) => {
                self.translate_trust_cg_bitfield_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_v4i32_mask_extract_op(op) => {
                self.translate_trust_cg_v4i32_mask_extract_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_v2i64_mask_extract_op(op) => {
                self.translate_trust_cg_v2i64_mask_extract_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_v2i64_bool_mask_extract_op(op) => {
                self.translate_trust_cg_v2i64_bool_mask_extract_dialect_op(op, &node.results)
            }
            Inst::TensorContract { .. } => Err(AdapterError::UnsupportedInstruction(
                "Inst::TensorContract has no native tensor lowering".into(),
            )),
            Inst::TensorMap { .. } => Err(AdapterError::UnsupportedInstruction(
                "Inst::TensorMap has no native tensor lowering".into(),
            )),
            Inst::TensorReduce { .. } => Err(AdapterError::UnsupportedInstruction(
                "Inst::TensorReduce has no native tensor lowering".into(),
            )),
            Inst::TensorView { .. } => Err(AdapterError::UnsupportedInstruction(
                "Inst::TensorView has no native tensor lowering".into(),
            )),
            Inst::TensorGather { .. } => Err(AdapterError::UnsupportedInstruction(
                "Inst::TensorGather has no native tensor lowering".into(),
            )),
            Inst::TensorScatter { .. } => Err(AdapterError::UnsupportedInstruction(
                "Inst::TensorScatter has no native tensor lowering".into(),
            )),
            Inst::DialectOp(_) => Err(AdapterError::UnsupportedInstruction(
                "DialectOp reached the Trust Codegen adapter without prior \
                     dialect lowering"
                    .to_string(),
            )),
        }
    }

    // Legacy per-kind translation helpers (`translate_binop`, `translate_unop`,
    // `translate_cmp`) were removed during the 2026-04-19 zero-warnings
    // cleanup. trust_ir BinOp / UnOp / ICmp / FCmp are now lowered inline in
    // `translate_instruction` above; the free `translate_int_cmp` /
    // `translate_float_cmp` predicate mappers were removed for the same
    // reason (they only served the deleted `translate_cmp`).

    /// Validate source pointer semantics before their shared machine-word
    /// representation can erase the distinction between a length and a vtable.
    /// Compatibility callers do not require every upstream validator finding,
    /// so these operations own their local type checks. This adapter currently
    /// uses 64-bit pointer carriers; this is not admission for 32-bit layouts.
    fn validate_pointer_operation(
        &self,
        context: &str,
        ptr_ty: &Ty,
        metadata_ty: Option<&Ty>,
        results: &[ValueId],
    ) -> Result<(), AdapterError> {
        // Unit metadata has one source SSA result even though no machine
        // value is emitted. Check before that path can return early.
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} result arity mismatch: got {}, expected 1",
                results.len()
            )));
        }
        if !ptr_ty.is_pointer_like() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires a pointer-like type, got {ptr_ty:?}"
            )));
        }
        if let Some(metadata_ty) = metadata_ty {
            let expected = ptr_ty.pointer_metadata_ty(64).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "{context} has no supported pointer metadata for {ptr_ty:?}"
                ))
            })?;
            if metadata_ty != &expected {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{context} metadata type mismatch for {ptr_ty:?}: \
                     declared {metadata_ty:?}, expected {expected:?}"
                )));
            }
        }
        // Upstream pointer-like classification includes ownership-bearing Rc.
        // Preserve this adapter's existing unsupported-type refusal even when
        // the type occurs only in a body and no signature layout visits it.
        self.translate_ty(ptr_ty).map(|_| ())
    }

    fn translate_ptr_data(
        &mut self,
        ptr_ty: &Ty,
        ptr: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        self.validate_pointer_operation("PtrData", ptr_ty, None, results)?;
        self.require_trust_ir_operand_type("PtrData", "ptr", *ptr, ptr_ty)?;
        let src = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        if matches!(ptr_ty, Ty::FatPtr(_)) {
            return self.load_fat_ptr_lane(src, 0, Type::I64, dst);
        }
        Ok(vec![Instruction {
            opcode: Opcode::Copy,
            args: vec![src],
            results: vec![dst],
        }])
    }

    fn translate_ptr_metadata(
        &mut self,
        ptr_ty: &Ty,
        metadata_ty: &Ty,
        ptr: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        self.validate_pointer_operation("PtrMetadata", ptr_ty, Some(metadata_ty), results)?;
        self.require_trust_ir_operand_type("PtrMetadata", "ptr", *ptr, ptr_ty)?;
        if matches!(metadata_ty, Ty::Unit) {
            return Ok(vec![]);
        }

        let src = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        let metadata_lir_ty = self.translate_ty(metadata_ty)?;
        self.define_value_type(dst, metadata_lir_ty.clone());
        self.load_fat_ptr_lane(src, 1, metadata_lir_ty, dst)
    }

    fn translate_ptr_from_parts(
        &mut self,
        ptr_ty: &Ty,
        metadata_ty: &Ty,
        data: &ValueId,
        metadata: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        self.validate_pointer_operation("PtrFromParts", ptr_ty, Some(metadata_ty), results)?;
        self.require_trust_ir_operand_type("PtrFromParts", "data", *data, &Ty::Ptr)?;
        self.require_trust_ir_operand_type("PtrFromParts", "metadata", *metadata, metadata_ty)?;
        let data_value = self.map_value(*data);
        let dst = self.map_result(results)?;

        if matches!(metadata_ty, Ty::Unit) {
            self.define_value_type(dst, Type::I64);
            return Ok(vec![Instruction {
                opcode: Opcode::Copy,
                args: vec![data_value],
                results: vec![dst],
            }]);
        }

        let metadata_value = self.map_value(*metadata);
        let metadata_lir_ty = self.translate_ty(metadata_ty)?;
        let fat_ptr_ty = Type::Struct(vec![Type::I64, metadata_lir_ty.clone()]);
        let slot = self.alloc_stack_slot(fat_ptr_ty.bytes(), fat_ptr_ty.align());
        self.define_value_type(dst, fat_ptr_ty.clone());

        let metadata_ptr = self.fresh_value();
        self.define_value_type(metadata_ptr, Type::I64);

        Ok(vec![
            Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![dst],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: Type::I64,
                    align: None,
                },
                args: vec![data_value, dst],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::StructGep {
                    struct_ty: fat_ptr_ty,
                    field_index: 1,
                },
                args: vec![dst],
                results: vec![metadata_ptr],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: metadata_lir_ty,
                    align: None,
                },
                args: vec![metadata_value, metadata_ptr],
                results: vec![],
            },
        ])
    }

    fn load_fat_ptr_lane(
        &mut self,
        base_ptr: Value,
        field_index: u32,
        field_ty: Type,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if field_index > 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "fat pointer lane {field_index} is out of bounds"
            )));
        }
        let aggregate_ty = Type::Struct(vec![Type::I64, field_ty.clone()]);
        let field_ptr = self.fresh_value();
        self.define_value_type(field_ptr, Type::I64);
        Ok(vec![
            Instruction {
                opcode: Opcode::StructGep {
                    struct_ty: aggregate_ty,
                    field_index,
                },
                args: vec![base_ptr],
                results: vec![field_ptr],
            },
            Instruction {
                opcode: Opcode::Load {
                    ty: field_ty,
                    align: None,
                },
                args: vec![field_ptr],
                results: vec![dst],
            },
        ])
    }

    // -----------------------------------------------------------------------
    // Cast operations
    // -----------------------------------------------------------------------

    /// Lower a NARROW saturating float->int cast (`f as i8/i16/i32` or
    /// `f as u8/u16/u32`, LLVM fptosi.sat/fptoui.sat). AArch64 FCVTZS/FCVTZU
    /// saturate at the REGISTER width, so a narrow destination needs an explicit
    /// destination-width clamp. The lowering is a proven-op expansion:
    ///
    ///   tmp   = FcvtToInt/FcvtToUint(f -> i64)     ; NaN->0, saturate i64 range
    ///   min   = (tmp < hi) ? tmp : hi              ; clamp above (signed/unsigned)
    ///   clamp = signed ? ((min > lo) ? min : lo)   ; clamp below (signed only;
    ///                  : min                       ;  FCVTZU already gives >= 0)
    ///   dst   = Trunc(clamp -> dst_width)          ; exact (clamp fits dst)
    ///
    /// Equivalent to Rust's saturating `as`: NaN -> 0, out-of-range clamps to
    /// `dst::MIN`/`dst::MAX`, else round toward zero. Validated exhaustively for
    /// f16 -> i8 (all 65536 inputs) and against a saturating oracle for
    /// f32/f64 -> i8/i16/i32.
    fn translate_narrow_saturating_cast(
        &mut self,
        op: &CastOp,
        src: Value,
        dst_ty: &Ty,
        to: Type,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let signed = matches!(op, CastOp::FPToSISat);
        let (lo, hi): (i64, i64) = match dst_ty {
            Ty::I8 => (i64::from(i8::MIN), i64::from(i8::MAX)),
            Ty::I16 => (i64::from(i16::MIN), i64::from(i16::MAX)),
            Ty::I32 => (i64::from(i32::MIN), i64::from(i32::MAX)),
            Ty::U8 => (0, i64::from(u8::MAX)),
            Ty::U16 => (0, i64::from(u16::MAX)),
            Ty::U32 => (0, i64::from(u32::MAX)),
            other => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "narrow saturating cast: unexpected destination {other:?}"
                )));
            }
        };

        let mut instrs = Vec::new();
        let i64c = |this: &mut Self, imm: i64| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I64);
            (v, imm)
        };

        // tmp = saturating fcvt to i64 (NaN -> 0, saturate at the i64 range).
        let tmp = self.fresh_value();
        self.define_value_type(tmp, Type::I64);
        let fcvt = if signed {
            Opcode::FcvtToInt { dst_ty: Type::I64 }
        } else {
            Opcode::FcvtToUint { dst_ty: Type::I64 }
        };
        instrs.push(Instruction {
            opcode: fcvt,
            args: vec![src],
            results: vec![tmp],
        });

        // min = (tmp <(s/u) hi) ? tmp : hi
        let (hi_c, hi_imm) = i64c(self, hi);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: hi_imm,
            },
            args: vec![],
            results: vec![hi_c],
        });
        let lt_cc = if signed {
            IntCC::SignedLessThan
        } else {
            IntCC::UnsignedLessThan
        };
        let cmp_hi = self.fresh_value();
        self.define_value_type(cmp_hi, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp { cond: lt_cc },
            args: vec![tmp, hi_c],
            results: vec![cmp_hi],
        });
        let min_hi = self.fresh_value();
        self.define_value_type(min_hi, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![cmp_hi, tmp, hi_c],
            results: vec![min_hi],
        });

        // Signed: clamp below by lo. Unsigned: FCVTZU already yields >= 0.
        let clamped = if signed {
            let (lo_c, lo_imm) = i64c(self, lo);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lo_imm,
                },
                args: vec![],
                results: vec![lo_c],
            });
            let cmp_lo = self.fresh_value();
            self.define_value_type(cmp_lo, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedGreaterThan,
                },
                args: vec![min_hi, lo_c],
                results: vec![cmp_lo],
            });
            let max_lo = self.fresh_value();
            self.define_value_type(max_lo, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![cmp_lo, min_hi, lo_c],
                results: vec![max_lo],
            });
            max_lo
        } else {
            min_hi
        };

        // dst = Trunc(clamped -> dst_width). The clamp guarantees the value fits,
        // so the truncation is exact (no wrap).
        instrs.push(Instruction {
            opcode: Opcode::Trunc { to_ty: to },
            args: vec![clamped],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// Saturating float -> i128/u128: NaN becomes zero, out-of-range values
    /// clamp to the destination bounds, and in-range values truncate.
    /// Raw runtime helpers have no portable saturation contract. Every helper
    /// call receives a finite value in its conversion domain; comparisons of
    /// the original source select the required saturated result afterward.
    fn translate_i128_saturating_cast(
        &mut self,
        op: &CastOp,
        src_ty: &Ty,
        dst_ty: &Ty,
        src: Value,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !matches!(src_ty, Ty::F16 | Ty::F32 | Ty::F64) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "saturating {op:?} {src_ty:?} -> {dst_ty:?}: source must be a float (f16/f32/f64)"
            )));
        }
        let signed = matches!(op, CastOp::FPToSISat);
        let dst_lir = self.translate_ty(dst_ty)?;
        let mut instrs = Vec::new();
        let (src, src_lir) = if matches!(src_ty, Ty::F16) {
            let widened = self.fresh_value();
            self.define_value_type(widened, Type::F32);
            instrs.push(Instruction {
                opcode: Opcode::FPExt,
                args: vec![src],
                results: vec![widened],
            });
            (widened, Type::F32)
        } else {
            (src, self.translate_ty(src_ty)?)
        };
        let upper = self.fresh_value();
        let lower = self.fresh_value();
        let fp_zero = self.fresh_value();
        let limit = 2.0_f64.powi(if signed { 127 } else { 128 });
        for (value, imm) in [
            (upper, limit),
            (lower, if signed { -limit } else { 0.0 }),
            (fp_zero, 0.0),
        ] {
            self.define_value_type(value, src_lir.clone());
            instrs.push(Instruction {
                opcode: Opcode::Fconst {
                    ty: src_lir.clone(),
                    imm,
                },
                args: vec![],
                results: vec![value],
            });
        }
        // For unsigned f32, 2^128 rounds to +infinity: every finite f32 is
        // below that bound, and +infinity must saturate. The signed 2^127
        // bound is exactly representable in both f32 and f64.
        let is_nan = self.fresh_value();
        let too_small = self.fresh_value();
        let too_big = self.fresh_value();
        for (result, cond, rhs) in [
            (is_nan, FloatCC::UnorderedNotEqual, src),
            (
                too_small,
                if signed {
                    FloatCC::LessThan
                } else {
                    FloatCC::LessThanOrEqual
                },
                lower,
            ),
            (too_big, FloatCC::GreaterThanOrEqual, upper),
        ] {
            self.define_value_type(result, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::Fcmp { cond },
                args: vec![src, rhs],
                results: vec![result],
            });
        }
        let select = |instrs: &mut Vec<Instruction>, cond, then_v, else_v, result| {
            instrs.push(Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![cond, then_v, else_v],
                results: vec![result],
            });
        };
        // Never pass NaN, infinity, or an out-of-range value to __fix*ti.
        // A later select cannot undo an invalid runtime conversion call.
        let mut safe_src = src;
        for condition in [is_nan, too_small, too_big] {
            let next = self.fresh_value();
            self.define_value_type(next, src_lir.clone());
            select(&mut instrs, condition, fp_zero, safe_src, next);
            safe_src = next;
        }
        let callee = match (signed, matches!(src_ty, Ty::F64)) {
            (true, false) => RuntimeSymbol::Fixsfti,
            (true, true) => RuntimeSymbol::Fixdfti,
            (false, false) => RuntimeSymbol::Fixunssfti,
            (false, true) => RuntimeSymbol::Fixunsdfti,
        };
        let raw = self.fresh_value();
        self.define_value_type(raw, dst_lir.clone());
        instrs.push(Instruction {
            opcode: self.runtime_call_opcode(callee)?,
            args: vec![safe_src],
            results: vec![raw],
        });
        let zero = self.fresh_value();
        let minimum = self.fresh_value();
        let maximum = self.fresh_value();
        for (result, lo, hi) in [
            (zero, 0, 0),
            (minimum, 0, if signed { i64::MIN } else { 0 }),
            (maximum, -1, if signed { i64::MAX } else { -1 }),
        ] {
            self.define_value_type(result, dst_lir.clone());
            instrs.push(Instruction {
                opcode: Opcode::Iconst128 { lo, hi },
                args: vec![],
                results: vec![result],
            });
        }
        let lower_clamped = self.fresh_value();
        let clamped = self.fresh_value();
        self.define_value_type(lower_clamped, dst_lir.clone());
        self.define_value_type(clamped, dst_lir);
        select(&mut instrs, too_small, minimum, raw, lower_clamped);
        select(&mut instrs, too_big, maximum, lower_clamped, clamped);
        select(&mut instrs, is_nan, zero, clamped, dst);
        Ok(instrs)
    }

    /// Lower an admitted trust-ir `Inst::BoxDeref` as the pointer-preserving
    /// conversion it is: the same single `Copy` pseudo a `PtrToPtr` cast
    /// lowers to, so every target's instruction selection and per-instruction
    /// verifier sees an ordinary pointer copy. Shape is re-checked here as a
    /// backstop behind trust-ir's rule 1.
    fn translate_box_deref(
        &mut self,
        ptr_ty: &Ty,
        operand: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if *ptr_ty != Ty::Ptr {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::BoxDeref ptr_ty {ptr_ty:?}: only the thin pointer of a sized pointee is lowered"
            )));
        }
        self.require_trust_ir_operand_type("Inst::BoxDeref", "operand", operand, ptr_ty)?;
        let src = self.map_value(operand);
        let dst = self.map_result(results)?;
        let to = self.translate_ty(ptr_ty)?;
        self.define_value_type(dst, to);
        Ok(vec![Instruction {
            opcode: Opcode::Copy,
            args: vec![src],
            results: vec![dst],
        }])
    }

    fn translate_cast(
        &mut self,
        op: &CastOp,
        src_ty: &Ty,
        dst_ty: &Ty,
        operand: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let src = self.map_value(*operand);
        let dst = self.map_result(results)?;
        let from = self.translate_ty(src_ty)?;
        let to = self.translate_ty(dst_ty)?;
        // Fail-closed safety gate: reject operand/declared-source mismatches and
        // structurally invalid cast shapes before emitting any lowering.
        self.validate_cast_shape(op, src_ty, dst_ty, *operand)?;
        self.define_value_type(dst, to.clone());

        // Float -> i128/u128: FCVTZS/FCVTZU cannot target a 128-bit register, so
        // route through the compiler-rt `__fix*ti` libcalls (the reverse of the
        // __floattidf/__floattisf `sitofp i128` path). Raw fptosi/fptoui is UB
        // out of range, matching the libcall's out-of-range behavior.
        if matches!(op, CastOp::FPToSI | CastOp::FPToUI) && matches!(dst_ty, Ty::I128 | Ty::U128) {
            let mut instrs = Vec::new();
            // An f16 source is first widened to f32 (a LOSSLESS conversion — every
            // f16 is exactly representable in f32), then converted via the f32
            // libcall. f16 -> f32 -> i128 is exact: the widening rounds nothing,
            // so only the single f32 -> i128 truncation happens, identical to a
            // direct f16 -> i128. (The reverse, i128 -> f16, is NOT done this way:
            // i128 -> f32 -> f16 would double-round.)
            let call_src = if matches!(src_ty, Ty::F16) {
                let widened = self.fresh_value();
                self.define_value_type(widened, Type::F32);
                instrs.push(Instruction {
                    opcode: Opcode::FPExt,
                    args: vec![src],
                    results: vec![widened],
                });
                widened
            } else {
                src
            };
            let callee = match (op, src_ty) {
                (CastOp::FPToSI, Ty::F32 | Ty::F16) => RuntimeSymbol::Fixsfti,
                (CastOp::FPToSI, Ty::F64) => RuntimeSymbol::Fixdfti,
                (CastOp::FPToUI, Ty::F32 | Ty::F16) => RuntimeSymbol::Fixunssfti,
                (CastOp::FPToUI, Ty::F64) => RuntimeSymbol::Fixunsdfti,
                _ => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CastOp::{op:?} {src_ty:?} -> {dst_ty:?}: only f16/f32/f64 -> i128/u128 \
                         are supported"
                    )));
                }
            };
            instrs.push(Instruction {
                opcode: self.runtime_call_opcode(callee)?,
                args: vec![call_src],
                results: vec![dst],
            });
            return Ok(instrs);
        }

        // i128/u128 -> float: SCVTF/UCVTF cannot SOURCE a 128-bit value — a
        // native `scvtf d0, x0` reads only the LOW 64 bits and silently drops
        // the high half, so `x as f64` was wrong for every i128 outside the
        // i64 range. Route through the compiler-rt `__float*ti` libcalls (the
        // exact reverse of the `__fix*ti` float->i128 path above). The i128
        // argument is passed in the x0:x1 register pair and the float result
        // returned in d0/s0, matching the libcall's ABI.
        if matches!(op, CastOp::SIToFP | CastOp::UIToFP) && matches!(src_ty, Ty::I128 | Ty::U128) {
            // The libcall target width. An f16 destination goes through the f32
            // libcall (there is no __float*ihf) and then demotes f32 -> f16. This
            // is EXACT, not double-rounded: every i128 that yields a FINITE f16
            // (|v| < 65520) is < 2^17, so it is represented exactly in the f32
            // intermediate — only the single f32 -> f16 rounding happens; larger
            // magnitudes overflow to infinity through either width. (Verified
            // equal to the f64-intermediate reference over the boundary region.)
            let call_dst_ty = if matches!(dst_ty, Ty::F16) {
                Ty::F32
            } else {
                dst_ty.clone()
            };
            let callee = match (op, &call_dst_ty) {
                (CastOp::SIToFP, Ty::F32) => RuntimeSymbol::Floattisf,
                (CastOp::SIToFP, Ty::F64) => RuntimeSymbol::Floattidf,
                (CastOp::UIToFP, Ty::F32) => RuntimeSymbol::Floatuntisf,
                (CastOp::UIToFP, Ty::F64) => RuntimeSymbol::Floatuntidf,
                _ => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CastOp::{op:?} {src_ty:?} -> {dst_ty:?}: only i128/u128 -> f16/f32/f64 \
                         are supported"
                    )));
                }
            };
            if matches!(dst_ty, Ty::F16) {
                // i128 -> f32 (libcall), then demote f32 -> f16.
                let f32_val = self.fresh_value();
                self.define_value_type(f32_val, Type::F32);
                return Ok(vec![
                    Instruction {
                        opcode: self.runtime_call_opcode(callee)?,
                        args: vec![src],
                        results: vec![f32_val],
                    },
                    Instruction {
                        opcode: Opcode::FPTrunc,
                        args: vec![f32_val],
                        results: vec![dst],
                    },
                ]);
            }
            return Ok(vec![Instruction {
                opcode: self.runtime_call_opcode(callee)?,
                args: vec![src],
                results: vec![dst],
            }]);
        }

        let opcode = match op {
            CastOp::SExt => Opcode::Sextend {
                from_ty: from,
                to_ty: to,
            },
            CastOp::ZExt => Opcode::Uextend {
                from_ty: from,
                to_ty: to,
            },
            CastOp::Trunc => Opcode::Trunc { to_ty: to },
            CastOp::FPToSI => Opcode::FcvtToInt { dst_ty: to },
            CastOp::FPToUI => Opcode::FcvtToUint { dst_ty: to },
            // Saturating float->int casts implement Rust `as` semantics:
            // NaN -> 0 and out-of-range values clamp at the DESTINATION width.
            // Select the audited expansion for each supported width; never
            // substitute a raw non-saturating Fcvt operation.
            CastOp::FPToSISat | CastOp::FPToUISat => {
                // Register-width (i64/u64) saturating float->int is EXACTLY the
                // native FCVTZS/FCVTZU: round-toward-zero, NaN -> 0, and saturate
                // at the i64/u64 range — which IS the destination range. So it
                // lowers to the same FcvtToInt/FcvtToUint as the raw cast, with
                // the identical instruction and proof (`f as u64`/`as usize`/
                // `as i64`/`as isize`). Narrow destinations use the explicit
                // audited clamp expansion below because FCVTZS/FCVTZU saturate
                // at register width rather than i8/i16/i32 width.
                match (op, dst_ty) {
                    // isize/usize are pointer-width (64-bit): `f as isize` /
                    // `f as usize` saturate at the i64/u64 range exactly like
                    // the I64/U64 forms.
                    (CastOp::FPToSISat, Ty::I64 | Ty::Isize) => Opcode::FcvtToInt { dst_ty: to },
                    (CastOp::FPToUISat, Ty::U64 | Ty::Usize) => Opcode::FcvtToUint { dst_ty: to },
                    // Narrow (i8/i16/i32 or u8/u16/u32): FCVTZS/FCVTZU to i64
                    // (saturating + NaN->0), then clamp to the destination range,
                    // then truncate. See translate_narrow_saturating_cast.
                    (CastOp::FPToSISat, Ty::I8 | Ty::I16 | Ty::I32)
                    | (CastOp::FPToUISat, Ty::U8 | Ty::U16 | Ty::U32) => {
                        return self.translate_narrow_saturating_cast(op, src, dst_ty, to, dst);
                    }
                    // i128/u128 saturating: no native 128-bit fcvt, so use the
                    // __fix*ti libcall plus explicit float-compare bounds.
                    (CastOp::FPToSISat, Ty::I128) | (CastOp::FPToUISat, Ty::U128) => {
                        return self.translate_i128_saturating_cast(op, src_ty, dst_ty, src, dst);
                    }
                    _ => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "CastOp::{op:?} to {dst_ty:?} fail-closed: unsupported saturating \
                             float->int destination; src_ty={src_ty:?}"
                        )));
                    }
                }
            }
            CastOp::SIToFP => Opcode::FcvtFromInt { src_ty: from },
            CastOp::UIToFP => Opcode::FcvtFromUint { src_ty: from },
            CastOp::FPExt => Opcode::FPExt,
            CastOp::FPTrunc => Opcode::FPTrunc,
            CastOp::PtrToInt | CastOp::IntToPtr | CastOp::PtrToPtr => {
                // No-op: pointers are already I64. Emit a single Copy pseudo.
                return Ok(vec![Instruction {
                    opcode: Opcode::Copy,
                    args: vec![src],
                    results: vec![dst],
                }]);
            }
            CastOp::Bitcast => Opcode::Bitcast { to_ty: to },
            CastOp::Transmute => {
                return self
                    .translate_transmute(src_ty, dst_ty, *operand, src, dst, &from, &to, results);
            }
            CastOp::ReifyFnPointer => {
                let actual_ty = self.lookup_value_ty(*operand).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "CastOp::ReifyFnPointer operand {operand:?} has no known trust_ir type"
                    ))
                })?;
                if actual_ty != *src_ty {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CastOp::ReifyFnPointer source type mismatch: declared src_ty={src_ty:?}, \
                         operand {operand:?} has type {actual_ty:?}"
                    )));
                }
                // Direction 1 — `Func(_) -> Ptr`: turn a materialized
                // function-symbol/code-pointer value into a raw pointer. Requires
                // the operand to carry materialized code-pointer provenance (a
                // `GlobalRef`/`ExternRef` relocation).
                if matches!(src_ty, Ty::Func(_)) && *dst_ty == Ty::Ptr {
                    if !self.materialized_code_pointer_values.contains(operand) {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "CastOp::ReifyFnPointer fail-closed: operand {operand:?} has Ty::Func \
                             but no materialized function-symbol/code-pointer provenance; arbitrary \
                             function identity materialization still requires code-pointer ABI, \
                             symbol relocation, and proof provenance before lowering"
                        )));
                    }
                    return Ok(vec![Instruction {
                        opcode: Opcode::Copy,
                        args: vec![src],
                        results: vec![dst],
                    }]);
                }
                // Direction 2 — `Ptr -> Func(sig)`: assert that an incoming raw
                // pointer IS a code pointer of `sig`. The bridge emits this ONLY
                // for a callee whose Rust type is a genuine `ty::FnPtr` (a `fn(..)`
                // value the type system guarantees points at code) — the
                // `FnOnce::call_once` FnPtrShim receiver that `lang_start`'s chain
                // invokes to run `main`. `ReifyFnPointer` is the explicit
                // provenance-carrying cast, so trusting that frontend assertion is
                // consistent with `Transmute`/`ReifyFnPointer`'s provenance model.
                // Lower as a register move (both carriers are a 64-bit pointer); the
                // result is now a `Func(sig)` value `CallIndirect` accepts, and we
                // record its code-pointer provenance.
                if matches!(src_ty, Ty::Ptr) && matches!(dst_ty, Ty::Func(_)) {
                    if let Some(result) = results.first() {
                        self.materialized_code_pointer_values.insert(*result);
                    }
                    return Ok(vec![Instruction {
                        opcode: Opcode::Copy,
                        args: vec![src],
                        results: vec![dst],
                    }]);
                }
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "CastOp::ReifyFnPointer fail-closed: src_ty={src_ty:?} src_lir={from:?} \
                     dst_ty={dst_ty:?} dst_lir={to:?}; supported only for Ty::Func(_) <-> Ty::Ptr \
                     code-pointer reification"
                )));
            }
        };

        Ok(vec![Instruction {
            opcode,
            args: vec![src],
            results: vec![dst],
        }])
    }

    /// Lower `CastOp::Transmute`: an EQUAL-SIZE reinterpretation of the
    /// source's byte image as the destination type.
    ///
    /// The size rule is trust-ir's own: `Module::layout_sensitive_cast_evidence`
    /// must answer `SameSize` (it refuses an opaque handle or a bool lane on
    /// either side and any size mismatch, over trust-ir's declared layouts), so
    /// this backend never decides the byte image of a layout itself. The
    /// meaning is the memory lane trust-ir's reference interpreter executes:
    /// store the source, load the destination from the same address. The
    /// lowering IS that lane (a `Store`/byte copy into a fresh slot, then a
    /// `Load` or the slot itself), except that a same-width scalar pair keeps
    /// its value in registers (`Copy` for one carrier, `Bitcast` for an
    /// integer/float pair), which moves the same bits.
    ///
    /// The interpreter executes the `Transmute` spelling itself only over the
    /// integer/pointer scalars (trust-ir's lowering-target subset); for every
    /// other admitted shape the reference is its store/load twin (for an
    /// integer/float pair, equivalently, its `Bitcast` twin). Refused by
    /// name, beyond trust-ir's layout refusals: a leaf whose values carry a
    /// validity invariant or provenance the byte image cannot establish (bool,
    /// char, references, `Rc`, function pointers, fat pointers, enums, records,
    /// closures, refinements, handles), a source with padding bytes (they hold
    /// no value), and a struct whose emitted layout disagrees with trust-ir's.
    #[allow(clippy::too_many_arguments)]
    fn translate_transmute(
        &mut self,
        src_ty: &Ty,
        dst_ty: &Ty,
        operand: ValueId,
        src: Value,
        dst: Value,
        from: &Type,
        to: &Type,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let refuse = |detail: String| {
            AdapterError::UnsupportedInstruction(format!(
                "CastOp::Transmute fail-closed: {detail}; src_ty={src_ty:?} src_lir={from:?} \
                 dst_ty={dst_ty:?} dst_lir={to:?}"
            ))
        };
        let actual = self.lookup_value_ty(operand);
        if actual.as_ref() != Some(src_ty) {
            return Err(refuse(format!(
                "operand {operand:?} has type {actual:?}, not the declared source type"
            )));
        }
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let size_bits =
            match module.layout_sensitive_cast_evidence(CastOp::Transmute, src_ty, dst_ty) {
                Ok(trust_ir::CastLayoutEvidence::SameSize { size_bits, .. }) => size_bits,
                Ok(other) => {
                    return Err(refuse(format!(
                        "trust-ir answered `{other}` instead of equal-size evidence"
                    )));
                }
                Err(trust_ir::LayoutError::CastSizeMismatch { src_bits, dst_bits }) => {
                    return Err(refuse(format!(
                        "source and destination layout sizes differ (trust-ir layout: \
                         src_size={} dst_size={} bytes)",
                        src_bits / 8,
                        dst_bits / 8
                    )));
                }
                Err(error) => {
                    return Err(refuse(format!(
                        "trust-ir layout evidence refuses it: {error}"
                    )));
                }
            };
        for (side, ty) in [("source", src_ty), ("destination", dst_ty)] {
            if let Some(leaf) = transmute_unreinterpretable_leaf(module, ty) {
                return Err(refuse(format!(
                    "the {side} reaches {leaf}, whose values carry a validity invariant or \
                     provenance that a byte reinterpretation cannot establish"
                )));
            }
            if let Some(mismatch) = self.transmute_struct_layout_mismatch(ty)? {
                return Err(refuse(format!("the {side} {mismatch}")));
            }
        }
        let padding = transmute_padding_bytes(module, src_ty)
            .map_err(|error| refuse(format!("the source layout is unavailable: {error}")))?;
        if padding != 0 {
            return Err(refuse(format!(
                "the source has {padding} padding byte(s), which hold no value to reinterpret"
            )));
        }
        let size = size_bits / 8;
        let from_extent = if from.is_aggregate() {
            self.aggregate_value_extent(src_ty, from)?
        } else {
            u64::from(from.bytes())
        };
        let to_extent = if to.is_aggregate() {
            self.aggregate_value_extent(dst_ty, to)?
        } else {
            u64::from(to.bytes())
        };
        if from_extent != size || to_extent != size {
            return Err(refuse(format!(
                "the carriers hold {from_extent} and {to_extent} byte(s) where trust-ir's layout \
                 states {size}"
            )));
        }

        // Register lane: one carrier moves unchanged; an integer/float pair of
        // one width moves the same bits across register files.
        let register_scalar = |ty: &Type| {
            matches!(
                ty,
                Type::I8
                    | Type::I16
                    | Type::I32
                    | Type::I64
                    | Type::I128
                    | Type::F16
                    | Type::F32
                    | Type::F64
            )
        };
        if register_scalar(from) && register_scalar(to) {
            let opcode = if from == to {
                Opcode::Copy
            } else if matches!(
                (from, to),
                (Type::I16, Type::F16)
                    | (Type::F16, Type::I16)
                    | (Type::I32, Type::F32)
                    | (Type::F32, Type::I32)
                    | (Type::I64, Type::F64)
                    | (Type::F64, Type::I64)
            ) {
                Opcode::Bitcast { to_ty: to.clone() }
            } else {
                return Err(refuse(
                    "the register carriers differ in width although trust-ir states equal sizes"
                        .to_string(),
                ));
            };
            return Ok(vec![Instruction {
                opcode,
                args: vec![src],
                results: vec![dst],
            }]);
        }

        // Memory lane: the source's byte image in a fresh slot aligned for
        // both carriers, read back at the destination type.
        let size32 = u32::try_from(size)
            .map_err(|_| refuse(format!("a {size}-byte image exceeds a stack slot")))?;
        let slot_size = size32.max(from.bytes()).max(to.bytes()).max(1);
        let align = from.align().max(to.align()).max(1);
        let mut instrs = Vec::new();
        let (image, slot) = if from.is_aggregate() {
            let (fresh, slot) = self.copy_into_fresh_slot(src, slot_size, align, size, &mut instrs);
            self.define_value_type(fresh, Type::I64);
            (fresh, slot)
        } else {
            let slot = self.alloc_stack_slot(slot_size, align);
            let image = self.fresh_value();
            self.define_value_type(image, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![image],
            });
            instrs.push(Instruction {
                opcode: Opcode::Store {
                    ty: from.clone(),
                    align: None,
                },
                args: vec![src, image],
                results: vec![],
            });
            (image, slot)
        };
        if to.is_aggregate() {
            // Pointer-represented: the value IS the image, owned by it alone.
            instrs.push(Instruction {
                opcode: Opcode::Copy,
                args: vec![image],
                results: vec![dst],
            });
            if let Some(result) = results.first().copied() {
                self.owned_aggregate_storage.insert(result);
                self.owned_aggregate_slots.insert(result, slot);
            }
        } else {
            instrs.push(Instruction {
                opcode: Opcode::Load {
                    ty: to.clone(),
                    align: None,
                },
                args: vec![image],
                results: vec![dst],
            });
        }
        Ok(instrs)
    }

    /// For a `Transmute` side: where a struct it holds BY VALUE is emitted at
    /// other offsets or another size than trust-ir's declared layout states,
    /// a description of the first disagreement. The reinterpretation reads
    /// the bytes where this backend put them, so the two must coincide.
    fn transmute_struct_layout_mismatch(&self, ty: &Ty) -> Result<Option<String>, AdapterError> {
        let mut pending = vec![ty.clone()];
        let mut visited = 0usize;
        while let Some(ty) = pending.pop() {
            visited += 1;
            if visited > TRANSMUTE_LAYOUT_WALK_LIMIT {
                return Ok(Some(format!(
                    "nests more than {TRANSMUTE_LAYOUT_WALK_LIMIT} by-value lanes"
                )));
            }
            match &ty {
                Ty::Struct(sid) => {
                    let Some(sdef) = self.structs.iter().find(|s| s.id == *sid) else {
                        return Ok(Some(format!(
                            "names struct {sid:?}, absent from the module"
                        )));
                    };
                    let declared: Option<Vec<u64>> =
                        sdef.fields.iter().map(|field| field.offset).collect();
                    let emitted = self.emitted_layout(&ty)?;
                    let agrees = match (&emitted, declared, sdef.size) {
                        (Some(layout), Some(offsets), Some(size)) => {
                            layout.offsets == offsets && layout.size == size
                        }
                        _ => false,
                    };
                    if !agrees {
                        return Ok(Some(format!(
                            "holds struct {sid:?} (`{}`), whose emitted layout {emitted:?} is not \
                             its declared one",
                            sdef.name
                        )));
                    }
                    pending.extend(sdef.fields.iter().map(|field| field.ty.clone()));
                }
                Ty::Array(elem, _) => {
                    if let Some(elem_ty) = self.types.get(elem.as_usize()) {
                        pending.push(elem_ty.clone());
                    }
                }
                Ty::Tuple(lanes) => pending.extend(lanes.iter().cloned()),
                _ => {}
            }
        }
        Ok(None)
    }

    /// Lower `llvm.fma` / `llvm.fmuladd` to distinct LIR contracts. Both select
    /// an initial single-rounding AArch64 `FMADD`, but only fusion-licensed
    /// `llvm.fmuladd` may later become separate `Fmul` + `Fadd`; strict IEEE
    /// `llvm.fma` must remain fused.
    fn translate_fma_intrinsic(
        &mut self,
        fp_ty: Type,
        may_unfuse: bool,
        args: &[Value],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if args.len() != 3 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(
                "llvm.fma/fmuladd expects three arguments and one result".to_string(),
            ));
        }
        let dst = results[0];
        self.define_value_type(dst, fp_ty);
        Ok(vec![Instruction {
            opcode: if may_unfuse {
                Opcode::Fmuladd
            } else {
                Opcode::Fma
            },
            args: vec![args[0], args[1], args[2]],
            results: vec![dst],
        }])
    }

    /// Rewrite a PACKED `llvm.fmuladd.v*` call into its lane-wise LIR opcode.
    ///
    /// The result is typed `V128` — the LIR vector type erases the lane width,
    /// which is exactly why the element precision rides the OPCODE (`V4F32…`
    /// vs `V2F64…`) rather than the type.
    fn translate_packed_fma_intrinsic(
        &mut self,
        opcode: Opcode,
        callee_name: &str,
        args: &[Value],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if args.len() != 3 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{callee_name} expects three arguments and one result"
            )));
        }
        let dst = results[0];
        self.define_value_type(dst, Type::V128);
        Ok(vec![Instruction {
            opcode,
            args: vec![args[0], args[1], args[2]],
            results: vec![dst],
        }])
    }

    /// Rewrite an `llvm.aarch64.crc32*` call into `Opcode::Crc32`.
    ///
    /// The declared callee is LLVM's intrinsic signature, `(i32 crc, i32
    /// data) -> i32` (`i64 data` for the doubleword forms): the prototype gate
    /// of every name-classified call (`classify_direct_call`) refused any
    /// other declaration before this runs. Which instruction the call becomes
    /// is the AArch64 selector's decision per function (FEAT_CRC32 when
    /// admitted, a shift/XOR expansion otherwise); the x86-64 and RISC-V
    /// selectors have no lowering for it and refuse.
    fn translate_crc32_intrinsic(
        &mut self,
        bytes: u8,
        castagnoli: bool,
        callee_name: &str,
        args: &[Value],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if args.len() != 2 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "[TCG-CRC32-INTRINSIC] `{callee_name}` must be called with two arguments and \
                 one result; got {} argument(s) and {} result(s)",
                args.len(),
                results.len()
            )));
        }
        let dst = results[0];
        self.define_value_type(dst, Type::I32);
        Ok(vec![Instruction {
            opcode: Opcode::Crc32 { bytes, castagnoli },
            args: vec![args[0], args[1]],
            results: vec![dst],
        }])
    }

    fn translate_bitreverse_intrinsic(
        &mut self,
        bitwidth: u16,
        args: &[Value],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if args.len() != 1 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "llvm.bitreverse.i{} expects one argument and one result",
                bitwidth
            )));
        }

        let ty = match bitwidth {
            32 => Type::I32,
            64 => Type::I64,
            other => {
                return Err(AdapterError::UnsupportedBitWidth(other));
            }
        };
        let dst = results[0];
        self.define_value_type(dst, ty.clone());

        let (swap_steps, final_shift): (&[(u8, i64)], u8) = match bitwidth {
            32 => (
                &[
                    (1, 0x5555_5555),
                    (2, 0x3333_3333),
                    (4, 0x0f0f_0f0f),
                    (8, 0x00ff_00ff),
                ],
                16,
            ),
            64 => (
                &[
                    (1, 0x5555_5555_5555_5555),
                    (2, 0x3333_3333_3333_3333),
                    (4, 0x0f0f_0f0f_0f0f_0f0f),
                    (8, 0x00ff_00ff_00ff_00ff),
                    (16, 0x0000_ffff_0000_ffff),
                ],
                32,
            ),
            _ => unreachable!(),
        };

        let mut instrs = Vec::new();
        let mut current = args[0];
        for &(shift, mask) in swap_steps {
            let shift_val = self.bitreverse_iconst(&mut instrs, &ty, i64::from(shift));
            let mask_val = self.bitreverse_iconst(&mut instrs, &ty, mask);
            let right = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Ushr,
                args: vec![current, shift_val],
                results: vec![right],
            });
            let right_masked = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![right, mask_val],
                results: vec![right_masked],
            });
            let left_masked = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![current, mask_val],
                results: vec![left_masked],
            });
            let left = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Ishl,
                args: vec![left_masked, shift_val],
                results: vec![left],
            });
            let combined = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![right_masked, left],
                results: vec![combined],
            });
            current = combined;
        }

        let final_shift_val = self.bitreverse_iconst(&mut instrs, &ty, i64::from(final_shift));
        let right = self.bitreverse_tmp(&ty);
        instrs.push(Instruction {
            opcode: Opcode::Ushr,
            args: vec![current, final_shift_val],
            results: vec![right],
        });
        let left = self.bitreverse_tmp(&ty);
        instrs.push(Instruction {
            opcode: Opcode::Ishl,
            args: vec![current, final_shift_val],
            results: vec![left],
        });
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![right, left],
            results: vec![dst],
        });

        Ok(instrs)
    }

    fn translate_objectsize_intrinsic(
        &mut self,
        bitwidth: u16,
        args: &[ValueId],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if bitwidth != 64 {
            return Err(AdapterError::UnsupportedBitWidth(bitwidth));
        }
        if args.len() != 4 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(
                "llvm.objectsize.i64.p0 expects one pointer argument, three i1 mode bits, and one result"
                    .to_string(),
            ));
        }

        let min = self.lookup_const_bool(args[1]).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "llvm.objectsize min mode bit must be a constant i1".to_string(),
            )
        })?;
        let null_unknown = self.lookup_const_bool(args[2]).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "llvm.objectsize null_unknown mode bit must be a constant i1".to_string(),
            )
        })?;
        let dynamic = self.lookup_const_bool(args[3]).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "llvm.objectsize dynamic mode bit must be a constant i1".to_string(),
            )
        })?;

        if dynamic {
            return Err(AdapterError::UnsupportedInstruction(
                "llvm.objectsize dynamic=true mode is unsupported".to_string(),
            ));
        }
        if min || !null_unknown {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "unsupported llvm.objectsize mode bits: min={}, null_unknown={}, dynamic={}; \
                 only min=false, null_unknown=true, dynamic=false is lowered",
                min, null_unknown, dynamic
            )));
        }

        let dst = results[0];
        self.define_value_type(dst, Type::I64);
        Ok(vec![Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: -1,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    fn bitreverse_iconst(&mut self, instrs: &mut Vec<Instruction>, ty: &Type, imm: i64) -> Value {
        let value = self.bitreverse_tmp(ty);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: ty.clone(),
                imm,
            },
            args: vec![],
            results: vec![value],
        });
        value
    }

    fn bitreverse_tmp(&mut self, ty: &Type) -> Value {
        let value = self.fresh_value();
        self.define_value_type(value, ty.clone());
        value
    }

    // -----------------------------------------------------------------------
    // trust-ir WS3.20 (F-057) bit intrinsics and IEEE copySign
    //
    // None of these has a single LIR opcode. Each expands into opcodes this
    // backend already lowers and verifies one at a time (Iconst/Iconst128,
    // Ishl/Ushr, Band/Bor/Bnot, Ineg/Isub, CtPop, Bitcast), each at the
    // operand's own width, so the expansion is correct exactly when those
    // opcodes are: narrow (I8/I16) logical right shifts zero-extend first and
    // CtPop masks to the logical width in both instruction selectors.
    // -----------------------------------------------------------------------

    /// Logical width and LIR carrier of an integer operand of a WS3.20 bit
    /// intrinsic. The width is read from the carrier the operand actually
    /// lowers to, so a pointer-width integer gets the target's width.
    fn bit_intrinsic_carrier(&self, what: &str, ty: &Ty) -> Result<(u32, Type), AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let bits = match lir_ty {
            Type::I8 => 8,
            Type::I16 => 16,
            Type::I32 => 32,
            Type::I64 => 64,
            Type::I128 => 128,
            ref other => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{what} over {ty:?} (carrier {other:?}): the bit intrinsics are lowered for \
                     integer scalars only"
                )));
            }
        };
        Ok((bits, lir_ty))
    }

    /// Materialize the low `width(lir_ty)` bits of `bits` as a fresh value:
    /// `Iconst` carries the raw pattern up to 64 bits (the same raw-bit
    /// convention `translate_int_const_into` uses for a u64 above i64::MAX),
    /// `Iconst128` both halves of a 128-bit pattern.
    fn emit_bit_pattern_const(
        &mut self,
        instrs: &mut Vec<Instruction>,
        lir_ty: &Type,
        bits: u128,
    ) -> Value {
        let value = self.bitreverse_tmp(lir_ty);
        let opcode = if *lir_ty == Type::I128 {
            Opcode::Iconst128 {
                lo: bits as u64 as i64,
                hi: (bits >> 64) as u64 as i64,
            }
        } else {
            Opcode::Iconst {
                ty: lir_ty.clone(),
                imm: bits as u64 as i64,
            }
        };
        instrs.push(Instruction {
            opcode,
            args: vec![],
            results: vec![value],
        });
        value
    }

    /// Push `opcode(args)` into a fresh value of `lir_ty` and return it.
    fn emit_bit_op(
        &mut self,
        instrs: &mut Vec<Instruction>,
        opcode: Opcode,
        lir_ty: &Type,
        args: Vec<Value>,
    ) -> Value {
        let value = self.bitreverse_tmp(lir_ty);
        instrs.push(Instruction {
            opcode,
            args,
            results: vec![value],
        });
        value
    }

    /// The constant value of a trust-ir integer `Const` operand, read from
    /// its producer only. Deliberately NOT `lookup_const_int`: that folder
    /// evaluates arithmetic over unbounded integers (it serves Alloca counts),
    /// so it can disagree with the operand's modular value at its width.
    fn direct_int_const(&self, vid: ValueId) -> Option<i128> {
        match self.find_value_producer(vid).map(|node| &node.inst) {
            Some(Inst::Const {
                value: Constant::Int(value),
                ..
            }) => Some(*value),
            _ => None,
        }
    }

    /// `BinOp::RotL` / `BinOp::RotR` over an integer scalar of width `w`.
    ///
    /// trust-ir's semantics are TOTAL: the amount is reduced modulo `w`
    /// (`rotate_at_width` in the reference interpreter), so no shift-range
    /// guard is involved. With `a = n mod w` and `b = (-n) mod w`:
    /// `rotl(x, n) = (x << a) | (x >>u b)` and `rotr(x, n) = (x >>u a) | (x << b)`;
    /// when `a == 0` both halves are `x` and the OR is `x`. `w` is a power of
    /// two, so `mod w` of the operand's two's-complement value is `& (w - 1)`
    /// and both shift amounts stay in `[0, w)`. A constant amount is reduced
    /// here instead, so the shifts are the immediate forms.
    fn translate_scalar_rotate(
        &mut self,
        op: BinOp,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let what = format!("BinOp::{op:?}");
        let (bits, lir_ty) = self.bit_intrinsic_carrier(&what, ty)?;
        let left = match op {
            BinOp::RotL => true,
            BinOp::RotR => false,
            other => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{other:?} is not a rotate"
                )));
            }
        };
        let x = self.map_value(lhs);
        let n = self.map_value(rhs);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, lir_ty.clone());

        let mut instrs = Vec::new();
        let width = u128::from(bits);
        let (shl_amount, ushr_amount) = match self.direct_int_const(rhs) {
            Some(amount) => {
                // `rem_euclid` of the signed spelling agrees with the unsigned
                // one because `w` divides `2^w`.
                let a = amount.rem_euclid(i128::from(bits)) as u128;
                if a == 0 {
                    instrs.push(Instruction {
                        opcode: Opcode::Copy,
                        args: vec![x],
                        results: vec![dst],
                    });
                    return Ok(instrs);
                }
                let b = width - a;
                let (shl, ushr) = if left { (a, b) } else { (b, a) };
                (
                    self.emit_bit_pattern_const(&mut instrs, &lir_ty, shl),
                    self.emit_bit_pattern_const(&mut instrs, &lir_ty, ushr),
                )
            }
            None => {
                let mask = self.emit_bit_pattern_const(&mut instrs, &lir_ty, width - 1);
                let a = self.emit_bit_op(&mut instrs, Opcode::Band, &lir_ty, vec![n, mask]);
                let negated = self.emit_bit_op(&mut instrs, Opcode::Ineg, &lir_ty, vec![n]);
                let b = self.emit_bit_op(&mut instrs, Opcode::Band, &lir_ty, vec![negated, mask]);
                if left { (a, b) } else { (b, a) }
            }
        };
        let high = self.emit_bit_op(&mut instrs, Opcode::Ishl, &lir_ty, vec![x, shl_amount]);
        let low = self.emit_bit_op(&mut instrs, Opcode::Ushr, &lir_ty, vec![x, ushr_amount]);
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![high, low],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// Scalar `BinOp::FCopySign`: the magnitude bits of `lhs` with the sign
    /// bit of `rhs`, merged in the same-width integer carrier. Exact, quiet
    /// and NaN-payload preserving — the IEEE `copySign` trust-ir defines (its
    /// interpreter does exactly this for `F16`).
    fn translate_scalar_copysign(
        &mut self,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let (int_ty, fp_ty, sign): (Type, Type, u128) = match ty {
            Ty::F16 => (Type::I16, Type::F16, 1 << 15),
            Ty::F32 => (Type::I32, Type::F32, 1 << 31),
            Ty::F64 => (Type::I64, Type::F64, 1 << 63),
            other => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::FCopySign over {other:?}: only f16, f32 and f64 are lowered"
                )));
            }
        };
        let x = self.map_value(lhs);
        let y = self.map_value(rhs);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, fp_ty.clone());

        let mut instrs = Vec::new();
        let x_bits = self.emit_bit_op(
            &mut instrs,
            Opcode::Bitcast {
                to_ty: int_ty.clone(),
            },
            &int_ty,
            vec![x],
        );
        let y_bits = self.emit_bit_op(
            &mut instrs,
            Opcode::Bitcast {
                to_ty: int_ty.clone(),
            },
            &int_ty,
            vec![y],
        );
        let magnitude_mask = self.emit_bit_pattern_const(&mut instrs, &int_ty, sign - 1);
        let sign_mask = self.emit_bit_pattern_const(&mut instrs, &int_ty, sign);
        let magnitude = self.emit_bit_op(
            &mut instrs,
            Opcode::Band,
            &int_ty,
            vec![x_bits, magnitude_mask],
        );
        let sign_bit =
            self.emit_bit_op(&mut instrs, Opcode::Band, &int_ty, vec![y_bits, sign_mask]);
        let merged = self.emit_bit_op(&mut instrs, Opcode::Bor, &int_ty, vec![magnitude, sign_bit]);
        instrs.push(Instruction {
            opcode: Opcode::Bitcast { to_ty: fp_ty },
            args: vec![merged],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// Packed `BinOp::FCopySign` over `<4 x f32>` / `<2 x f64>`:
    /// `(lhs BIC signmask) ORR (rhs AND signmask)` over the whole V128, the
    /// lane-agnostic bitwise ops (and the sign-bit lane constant) that packed
    /// FNeg/FAbs already use.
    fn translate_packed_fp_copysign(
        &mut self,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let (mask_ty, mask_lane, lanes): (Ty, i128, u32) = if Self::is_v4f32_ty(ty) {
            (Ty::Vector(Box::new(Ty::I32), 4), i32::MIN as i128, 4)
        } else if Self::is_v2f64_ty(ty) {
            (Ty::Vector(Box::new(Ty::I64), 2), i64::MIN as i128, 2)
        } else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "BinOp::FCopySign over vector type {ty:?}: only <4 x f32> and <2 x f64> are lowered"
            )));
        };
        let mask_elems: Vec<Constant> = (0..lanes).map(|_| Constant::Int(mask_lane)).collect();
        let mask = self.fresh_value();
        let mut instrs = self.translate_vector_const_into(&mask_ty, &mask_elems, mask)?;

        let x = self.map_value(lhs);
        let y = self.map_value(rhs);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::V128);
        let magnitude = self.emit_bit_op(&mut instrs, Opcode::BandNot, &Type::V128, vec![x, mask]);
        let sign_bit = self.emit_bit_op(&mut instrs, Opcode::Band, &Type::V128, vec![y, mask]);
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![magnitude, sign_bit],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// Scalar `UnOp::{CtLz, CtTz, BSwap, BitReverse}` over an integer of width
    /// `w`, with trust-ir's TOTAL semantics (`ctlz 0 = cttz 0 = w`):
    ///
    /// * `ctlz(x) = ctpop(~smear(x))`, `smear(x)` ORing `x >> s` into `x` for
    ///   `s = 1, 2, 4, …, w/2` so every bit below the leading one is set;
    /// * `cttz(x) = ctpop(~x & (x - 1))`, the mask of the trailing zeros
    ///   (all ones for `x = 0`);
    /// * `bswap` / `bitreverse` reverse the order of the `w/8` bytes / `w`
    ///   bits with the swap network of [`Self::emit_group_reverse`]; `bswap`
    ///   of an 8-bit value is the identity.
    fn translate_scalar_bit_intrinsic(
        &mut self,
        op: UnOp,
        ty: &Ty,
        operand: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let what = format!("UnOp::{op:?}");
        let (bits, lir_ty) = self.bit_intrinsic_carrier(&what, ty)?;
        let x = self.map_value(operand);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, lir_ty.clone());

        let mut instrs = Vec::new();
        match op {
            UnOp::CtLz => {
                let mut smeared = x;
                let mut shift = 1u32;
                while shift < bits {
                    let amount =
                        self.emit_bit_pattern_const(&mut instrs, &lir_ty, u128::from(shift));
                    let moved =
                        self.emit_bit_op(&mut instrs, Opcode::Ushr, &lir_ty, vec![smeared, amount]);
                    smeared =
                        self.emit_bit_op(&mut instrs, Opcode::Bor, &lir_ty, vec![smeared, moved]);
                    shift <<= 1;
                }
                let zeros = self.emit_bit_op(&mut instrs, Opcode::Bnot, &lir_ty, vec![smeared]);
                instrs.push(Instruction {
                    opcode: Opcode::CtPop,
                    args: vec![zeros],
                    results: vec![dst],
                });
            }
            UnOp::CtTz => {
                let one = self.emit_bit_pattern_const(&mut instrs, &lir_ty, 1);
                let below = self.emit_bit_op(&mut instrs, Opcode::Isub, &lir_ty, vec![x, one]);
                let inverted = self.emit_bit_op(&mut instrs, Opcode::Bnot, &lir_ty, vec![x]);
                let trailing =
                    self.emit_bit_op(&mut instrs, Opcode::Band, &lir_ty, vec![inverted, below]);
                instrs.push(Instruction {
                    opcode: Opcode::CtPop,
                    args: vec![trailing],
                    results: vec![dst],
                });
            }
            UnOp::BSwap if bits == 8 => instrs.push(Instruction {
                opcode: Opcode::Copy,
                args: vec![x],
                results: vec![dst],
            }),
            UnOp::BSwap => self.emit_group_reverse(&mut instrs, &lir_ty, bits, 8, x, dst),
            UnOp::BitReverse => self.emit_group_reverse(&mut instrs, &lir_ty, bits, 1, x, dst),
            other => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "UnOp::{other:?} is not a WS3.20 bit intrinsic"
                )));
            }
        }
        Ok(instrs)
    }

    /// Reverse the order of the `granule`-bit groups of the `bits`-wide `x`
    /// into `dst` (`granule` 1 = bit reverse, 8 = byte swap; `2 * granule <=
    /// bits`). Each round swaps adjacent `s`-bit groups,
    /// `((v >> s) & m_s) | ((v & m_s) << s)` with `m_s` the low `s` bits of
    /// every `2s`-bit chunk, for `s = granule, 2·granule, …`; the last round,
    /// `s = bits/2`, swaps the two halves and needs no mask because both
    /// shifts already discard the other half at this width.
    fn emit_group_reverse(
        &mut self,
        instrs: &mut Vec<Instruction>,
        lir_ty: &Type,
        bits: u32,
        granule: u32,
        x: Value,
        dst: Value,
    ) {
        let mut current = x;
        let mut shift = granule;
        while 2 * shift < bits {
            let mut mask = 0u128;
            let mut chunk = 0u32;
            while chunk < bits {
                mask |= ((1u128 << shift) - 1) << chunk;
                chunk += 2 * shift;
            }
            let amount = self.emit_bit_pattern_const(instrs, lir_ty, u128::from(shift));
            let mask = self.emit_bit_pattern_const(instrs, lir_ty, mask);
            let down = self.emit_bit_op(instrs, Opcode::Ushr, lir_ty, vec![current, amount]);
            let down = self.emit_bit_op(instrs, Opcode::Band, lir_ty, vec![down, mask]);
            let kept = self.emit_bit_op(instrs, Opcode::Band, lir_ty, vec![current, mask]);
            let up = self.emit_bit_op(instrs, Opcode::Ishl, lir_ty, vec![kept, amount]);
            current = self.emit_bit_op(instrs, Opcode::Bor, lir_ty, vec![down, up]);
            shift *= 2;
        }
        let half = self.emit_bit_pattern_const(instrs, lir_ty, u128::from(bits / 2));
        let down = self.emit_bit_op(instrs, Opcode::Ushr, lir_ty, vec![current, half]);
        let up = self.emit_bit_op(instrs, Opcode::Ishl, lir_ty, vec![current, half]);
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![down, up],
            results: vec![dst],
        });
    }

    // -----------------------------------------------------------------------
    // Memory operations
    // -----------------------------------------------------------------------

    fn translate_load(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        volatile: bool,
        align: Option<u64>,
        results: &[ValueId],
        not_null_guard: Option<Option<u64>>,
    ) -> Result<Vec<Instruction>, AdapterError> {
        self.refuse_bool_lane_layout(ty, if volatile { "VolatileLoad" } else { "Load" })?;
        let lir_ty = self.translate_ty(ty)?;
        let explicit_align = validate_explicit_memory_align("Load", align, lir_ty.align())?;
        let ptr_val = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        let mut insts = Vec::new();

        if let Some(obligation) = not_null_guard {
            insts.push(Instruction {
                opcode: Opcode::GuardNull { obligation },
                args: vec![ptr_val],
                results: vec![],
            });
        }

        if volatile {
            // A volatile load is an observable access (MMIO / signal
            // visibility): emit the distinct `VolatileLoad` opcode, which isel
            // lowers to a byte-identical machine load classified as a memory
            // barrier so the optimizer never elides/CSEs/forwards/hoists it.
            // A 128-bit integer is represented as a pair of 64-bit GPRs by
            // both native backends. Lowering it would therefore turn one
            // source volatile event into two architectural accesses, which is
            // observably wrong for MMIO. Reject it at the public boundary
            // until a target has an exact single-access scalar lowering.
            let representation = self.repr_ty(ty)?;
            if representation.is_i128() {
                let ty = representation.ty();
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Load of {ty:?} is not supported: the native \
                     backends would split one volatile event into two 64-bit accesses"
                )));
            }
            // Aggregates aren't a volatile-scalar shape — reject them.
            if lir_ty.is_aggregate() {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Load of an aggregate type {lir_ty:?} is not supported; \
                     volatile applies to scalar MMIO-style accesses"
                )));
            }
            let mut vinsts = insts;
            vinsts.push(Instruction {
                opcode: Opcode::VolatileLoad {
                    ty: lir_ty,
                    align: explicit_align,
                },
                args: vec![ptr_val],
                results: vec![dst],
            });
            return Ok(vinsts);
        }

        // Loading an AGGREGATE is a BY-VALUE copy: aggregates are pointer-
        // represented, so allocate a fresh stack slot, Memmove the aggregate's
        // bytes into it, and return the slot address. A scalar Load would read
        // only the first 8 bytes (its address image), and returning the SOURCE
        // pointer would alias the source (mutating the loaded value would corrupt
        // memory). The fresh slot gives correct value semantics. Rust decomposes
        // aggregate loads upstream, so this only affects producers that emit
        // `Load { ty: <aggregate> }` directly.
        if lir_ty.is_aggregate() {
            // The SLOT keeps the natural-C size: `emitted <= natural` holds for
            // every layout authority (the domination gate in
            // [`crate::declared_layout`]), so the natural size always has room.
            // The COPY LENGTH is the authoritative extent — reading the natural
            // length out of a value the authority sizes smaller would read past
            // it, and `ptr_val` may be a FIELD address handed back by the
            // explicit-offset `ExtractField` arm.
            let slot = self.alloc_stack_slot(lir_ty.bytes(), lir_ty.align());
            self.define_value_type(dst, lir_ty.clone());
            insts.push(Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![dst],
            });
            let len = self.aggregate_value_extent(ty, &lir_ty)? as i64;
            let len_val = self.emit_iconst_i64(len, &mut insts);
            insts.push(Instruction {
                opcode: Opcode::Memmove,
                args: vec![dst, ptr_val, len_val],
                results: vec![],
            });
            if let Some(result) = results.first().copied() {
                self.owned_aggregate_storage.insert(result);
                self.owned_aggregate_slots.insert(result, slot);
            }
            return Ok(insts);
        }

        insts.push(Instruction {
            opcode: Opcode::Load {
                ty: lir_ty,
                align: explicit_align,
            },
            args: vec![ptr_val],
            results: vec![dst],
        });
        Ok(insts)
    }

    fn translate_store(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        value: &ValueId,
        volatile: bool,
        align: Option<u64>,
        not_null_guard: Option<Option<u64>>,
    ) -> Result<Vec<Instruction>, AdapterError> {
        // A bool-lane vector never reaches memory: the referee's image is one
        // byte per lane and the value's register carrier is its producer's
        // lane width, so writing the carrier (what this arm did until
        // 2026-09-22: `str q` for an `<8 x bool>` from an `<8 x i16>` compare,
        // `str d` for one from an `<8 x i8>` compare) is a measured divergence.
        self.refuse_bool_lane_layout(ty, if volatile { "VolatileStore" } else { "Store" })?;
        let annotated_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let val = self.map_value(*value);
        // A vector store's WIDTH follows the stored value's LIR type, not the
        // annotation: a V64-typed value stores as `str d`, a V128-typed value
        // as `str q`. For every integer / float vector the producer's carrier
        // is the annotation's carrier, and for every non-vector store the
        // value type equals the annotation (trust-ir validation guarantees
        // it), so this is a no-op there; the one type whose carrier the
        // annotation could not recover, `<N x bool>`, is refused above.
        let lir_ty = match self.value_types.get(&val) {
            Some(vt @ (Type::V64 | Type::V128)) => vt.clone(),
            _ => annotated_ty,
        };
        let explicit_align = validate_explicit_memory_align("Store", align, lir_ty.align())?;
        let mut insts = Vec::new();

        if let Some(obligation) = not_null_guard {
            insts.push(Instruction {
                opcode: Opcode::GuardNull { obligation },
                args: vec![ptr_val],
                results: vec![],
            });
        }

        if volatile {
            // A volatile store is an observable access — emit the distinct
            // `VolatileStore` barrier opcode (see the volatile Load path).
            let representation = self.repr_ty(ty)?;
            if representation.is_i128() {
                let ty = representation.ty();
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Store of {ty:?} is not supported: the native \
                     backends would split one volatile event into two 64-bit accesses"
                )));
            }
            if lir_ty.is_aggregate() {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Store of an aggregate type {lir_ty:?} is not supported; \
                     volatile applies to scalar MMIO-style accesses"
                )));
            }
            let mut vinsts = insts;
            vinsts.push(Instruction {
                opcode: Opcode::VolatileStore {
                    ty: lir_ty,
                    align: explicit_align,
                },
                args: vec![val, ptr_val],
                results: vec![],
            });
            return Ok(vinsts);
        }

        // An AGGREGATE value is pointer-represented, so `val` is the ADDRESS of
        // the source aggregate — a scalar Store would write 8 bytes of that
        // address rather than the aggregate's DATA (a silent miscompile). Copy
        // the bytes with Memmove (self-copy-safe). Rust decomposes aggregate
        // stores into scalar/memcpy ops upstream, so this only affects producers
        // that emit `Store { ty: <aggregate> }` directly; it is a proven-opcode
        // byte copy, symmetric to the aggregate InsertField/InsertElement paths.
        //
        // The length is the PACKED extent for a packed struct: `ptr_val` may be
        // a packed FIELD address (the packed `ExtractField` arm hands back
        // `base + packed_offset` for an aggregate field), and a natural-C length
        // there would reach past the field into the sibling
        // `packed_struct_layout` now places at the packed offset — see
        // `aggregate_value_extent`.
        if lir_ty.is_aggregate() {
            let len = self.aggregate_value_extent(ty, &lir_ty)? as i64;
            let len_val = self.emit_iconst_i64(len, &mut insts);
            insts.push(Instruction {
                opcode: Opcode::Memmove,
                args: vec![ptr_val, val, len_val],
                results: vec![],
            });
            return Ok(insts);
        }

        insts.push(Instruction {
            opcode: Opcode::Store {
                ty: lir_ty,
                align: explicit_align,
            },
            args: vec![val, ptr_val],
            results: vec![],
        });
        Ok(insts)
    }

    fn translate_atomic_load(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        ordering: &MemoryOrdering,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        validate_atomic_load_ordering(ordering)?;
        self.refuse_bool_lane_layout(ty, "AtomicLoad")?;
        let lir_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        let lir_ordering = translate_ordering(ordering);

        Ok(vec![Instruction {
            opcode: Opcode::AtomicLoad {
                ty: lir_ty,
                ordering: lir_ordering,
            },
            args: vec![ptr_val],
            results: vec![dst],
        }])
    }

    fn translate_atomic_store(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        value: &ValueId,
        ordering: &MemoryOrdering,
    ) -> Result<Vec<Instruction>, AdapterError> {
        validate_atomic_store_ordering(ordering)?;
        self.refuse_bool_lane_layout(ty, "AtomicStore")?;
        let lir_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let val = self.map_value(*value);
        let lir_ordering = translate_ordering(ordering);

        Ok(vec![Instruction {
            opcode: Opcode::AtomicStore {
                ty: lir_ty,
                ordering: lir_ordering,
            },
            args: vec![val, ptr_val],
            results: vec![],
        }])
    }

    fn translate_atomic_rmw(
        &mut self,
        op: &TrustIrAtomicRmwOp,
        ty: &Ty,
        ptr: &ValueId,
        value: &ValueId,
        ordering: &MemoryOrdering,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        self.refuse_bool_lane_layout(ty, "AtomicRMW")?;
        let lir_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let val = self.map_value(*value);
        let dst = self.map_result(results)?;
        let lir_ordering = translate_ordering(ordering);
        let lir_op = translate_atomic_rmw_op(op)?;

        Ok(vec![Instruction {
            opcode: Opcode::AtomicRmw {
                op: lir_op,
                ty: lir_ty,
                ordering: lir_ordering,
            },
            args: vec![val, ptr_val],
            results: vec![dst],
        }])
    }

    // `translate_cmpxchg` was removed during the 2026-04-19 zero-warnings
    // cleanup — CmpXchg is lowered inline in `translate_instruction` above.

    fn translate_fence(
        &mut self,
        ordering: &MemoryOrdering,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ordering = translate_ordering(ordering);

        Ok(vec![Instruction {
            opcode: Opcode::Fence {
                ordering: lir_ordering,
            },
            args: vec![],
            results: vec![],
        }])
    }

    /// A named refusal from the borrow / binding-frame / `Undef` stage.
    fn bfu_refusal(&self, construct: &'static str, reason: impl Into<String>) -> AdapterError {
        AdapterError::LegalizationRefused {
            stage: crate::borrow_frame_undef::STAGE,
            construct,
            function: self
                .trust_ir_func
                .map(|function| function.name.clone())
                .unwrap_or_default(),
            reason: reason.into(),
        }
    }

    /// The frame plan of `frame` and, for `Some(slot)`, that slot's
    /// `(carrier, offset)`. Refused by name when the construct reached
    /// lowering without an admitting plan.
    fn legalized_frame_slot(
        &self,
        frame: ValueId,
        slot: Option<u32>,
        construct: &'static str,
    ) -> Result<(crate::borrow_frame_undef::FramePlan, Option<(Type, u32)>), AdapterError> {
        let plan = self
            .bfu_plan
            .as_deref()
            .and_then(|plan| plan.frame(frame))
            .cloned()
            .ok_or_else(|| {
                self.bfu_refusal(
                    construct,
                    format!("frame handle {frame:?} reached lowering without a legalization plan"),
                )
            })?;
        let slot = match slot {
            None => None,
            Some(index) => {
                let slot = plan.slots.get(index as usize).ok_or_else(|| {
                    self.bfu_refusal(construct, format!("slot {index} is not planned"))
                })?;
                Some((slot.carrier.clone(), slot.offset))
            }
        };
        Ok((plan, slot))
    }

    /// `base + offset` as an I64 address (the frame base itself at 0).
    fn frame_slot_address(
        &mut self,
        base: Value,
        offset: u32,
        instrs: &mut Vec<Instruction>,
    ) -> Value {
        if offset == 0 {
            return base;
        }
        let offset = self.emit_iconst_i64(i64::from(offset), instrs);
        let address = self.fresh_value();
        self.define_value_type(address, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iadd,
            args: vec![base, offset],
            results: vec![address],
        });
        address
    }

    /// `Inst::Borrow` / `Inst::BorrowMut`: a value-preserving copy of the
    /// borrowed address, recorded with its root and kind.
    fn translate_legalized_borrow(
        &mut self,
        node: &InstrNode,
        ptr: ValueId,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let construct = if matches!(node.inst, Inst::BorrowMut { .. }) {
            "Inst::BorrowMut"
        } else {
            "Inst::Borrow"
        };
        let result = node
            .results
            .first()
            .copied()
            .ok_or(AdapterError::MissingResult)?;
        let plan = self
            .bfu_plan
            .as_deref()
            .and_then(|plan| plan.borrow(result))
            .ok_or_else(|| {
                self.bfu_refusal(construct, "reached lowering without a legalization plan")
            })?;
        let result_ty = self
            .lookup_value_ty(result)
            .ok_or(AdapterError::UnknownValue(result.index()))?;
        let carrier = self.translate_ty(&result_ty)?;
        let operand = self.map_value(ptr);
        let dst = self.map_result(&node.results)?;
        self.define_value_type(dst, carrier);
        self.proof_ctx
            .borrow_frame_undef
            .borrows
            .push(crate::borrow_frame_undef::BorrowRecord {
                source: result,
                root: plan.root,
                kind: plan.kind,
                result: dst,
                operand,
            });
        Ok(vec![Instruction {
            opcode: Opcode::Copy,
            args: vec![operand],
            results: vec![dst],
        }])
    }

    /// `Inst::EndBorrow`: no runtime effect; the retirement is recorded.
    fn translate_legalized_end_borrow(
        &mut self,
        borrow_ptr: ValueId,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if self
            .bfu_plan
            .as_deref()
            .and_then(|plan| plan.borrow(borrow_ptr))
            .is_none()
        {
            return Err(self.bfu_refusal(
                "Inst::EndBorrow",
                format!("retires {borrow_ptr:?}, which no admitted borrow defines"),
            ));
        }
        let borrow = self.map_value(borrow_ptr);
        self.proof_ctx.borrow_frame_undef.retired_borrows.push(
            crate::borrow_frame_undef::RetiredBorrowRecord {
                source: borrow_ptr,
                borrow,
            },
        );
        Ok(vec![])
    }

    /// `Inst::OpenFrame`: the frame's stack slot, zero-filled (every slot of
    /// a fresh frame is unbound: poison, materialized under the NoUndef zero
    /// model).
    fn translate_legalized_open_frame(
        &mut self,
        node: &InstrNode,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let result = node
            .results
            .first()
            .copied()
            .ok_or(AdapterError::MissingResult)?;
        let (frame, _) = self.legalized_frame_slot(result, None, "Inst::OpenFrame")?;
        let stack_slot = self.alloc_stack_slot(frame.bytes, frame.align);
        let handle = self.map_result(&node.results)?;
        self.define_value_type(handle, Type::I64);
        let mut instrs = vec![Instruction {
            opcode: Opcode::StackAddr { slot: stack_slot },
            args: vec![],
            results: vec![handle],
        }];
        let zero = self.emit_iconst_i64(0, &mut instrs);
        for offset in (0..frame.bytes).step_by(8) {
            let address = self.frame_slot_address(handle, offset, &mut instrs);
            instrs.push(Instruction {
                opcode: Opcode::Store {
                    ty: Type::I64,
                    align: None,
                },
                args: vec![zero, address],
                results: vec![],
            });
        }
        self.proof_ctx
            .borrow_frame_undef
            .frames
            .push(crate::borrow_frame_undef::FrameRecord {
                source: result,
                frame_id: frame.frame_id,
                handle,
                stack_slot,
                bytes: frame.bytes,
                align: frame.align,
                slots: frame
                    .slots
                    .iter()
                    .map(|slot| crate::borrow_frame_undef::FrameSlotRecord {
                        offset: slot.offset,
                        carrier: slot.carrier.clone(),
                    })
                    .collect(),
            });
        Ok(instrs)
    }

    /// `Inst::BindSlot`: store in place; the new handle is the same address.
    fn translate_legalized_bind_slot(
        &mut self,
        node: &InstrNode,
        frame: ValueId,
        slot: u32,
        value: ValueId,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let (_, planned) = self.legalized_frame_slot(frame, Some(slot), "Inst::BindSlot")?;
        let (carrier, offset) = planned.ok_or_else(|| {
            self.bfu_refusal("Inst::BindSlot", format!("slot {slot} is not planned"))
        })?;
        let base = self.map_value(frame);
        let value = self.map_value(value);
        let mut instrs = Vec::new();
        let address = self.frame_slot_address(base, offset, &mut instrs);
        instrs.push(Instruction {
            opcode: Opcode::Store {
                ty: carrier,
                align: None,
            },
            args: vec![value, address],
            results: vec![],
        });
        let handle = self.map_result(&node.results)?;
        self.define_value_type(handle, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Copy,
            args: vec![base],
            results: vec![handle],
        });
        Ok(instrs)
    }

    /// `Inst::LoadSlot`: a load from the slot's planned offset.
    fn translate_legalized_load_slot(
        &mut self,
        node: &InstrNode,
        frame: ValueId,
        slot: u32,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let (_, planned) = self.legalized_frame_slot(frame, Some(slot), "Inst::LoadSlot")?;
        let (carrier, offset) = planned.ok_or_else(|| {
            self.bfu_refusal("Inst::LoadSlot", format!("slot {slot} is not planned"))
        })?;
        let base = self.map_value(frame);
        let mut instrs = Vec::new();
        let address = self.frame_slot_address(base, offset, &mut instrs);
        let dst = self.map_result(&node.results)?;
        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: carrier,
                align: None,
            },
            args: vec![address],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// A scalar `Inst::Undef` the stage admitted: the all-zero bit pattern of
    /// its carrier (the NoUndef model,
    /// [`crate::borrow_frame_undef::NO_UNDEF_MODEL`]).
    fn translate_legalized_undef(
        &mut self,
        node: &InstrNode,
        ty: &Ty,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let result = node
            .results
            .first()
            .copied()
            .ok_or(AdapterError::MissingResult)?;
        if !self
            .bfu_plan
            .as_deref()
            .is_some_and(|plan| plan.undef_admitted(result))
        {
            return Err(self.bfu_refusal(
                "Inst::Undef",
                format!("undef {result:?} of type {ty} reached lowering without being admitted"),
            ));
        }
        let carrier = self.translate_ty(ty)?;
        let instrs = if matches!(ty, Ty::F32 | Ty::F64) {
            self.translate_fconst(ty, 0.0, &node.results)?
        } else {
            self.translate_int_const(ty, 0, &node.results)?
        };
        let value = self.map_value(result);
        self.proof_ctx
            .borrow_frame_undef
            .undefs
            .push(crate::borrow_frame_undef::UndefRecord {
                source: result,
                result: value,
                carrier,
            });
        Ok(instrs)
    }

    fn translate_alloc(
        &mut self,
        ty: &Ty,
        count: &Option<ValueId>,
        explicit_align: Option<u64>,
        results: &[ValueId],
        decl_line: Option<u32>,
        source_site: (BlockId, usize),
    ) -> Result<Vec<Instruction>, AdapterError> {
        let explicit_align = validate_explicit_alloca_align(explicit_align)?;
        self.refuse_bool_lane_layout(ty, "Alloca")?;
        let storage_geometry = self.storage_geometry.resolve(self.module, ty)?;
        if storage_geometry.is_some()
            && let Some(count) = count
        {
            let source_ty = self.lookup_value_ty(*count).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(
                    "Storage allocation count has no source type".into(),
                )
            })?;
            if !source_ty.is_integer() || self.lookup_const_int(*count).is_none() {
                return Err(AdapterError::UnsupportedInstruction(
                    "Storage allocation count requires a statically known integer; dynamic extent/ownership is not qualified for this address-only route".into()));
            }
        }
        let (element_size, element_align) = if let Some(geometry) = storage_geometry {
            geometry.stack_slot()?
        } else {
            let lir_ty = self.translate_ty(ty)?;
            (lir_ty.bytes(), lir_ty.align())
        };
        let alloca_result_vid = results
            .first()
            .copied()
            .ok_or(AdapterError::MissingResult)?;
        let dst = self.map_result(results)?;
        // `StackAddr` materializes an address regardless of the allocated
        // element type. Seed the carrier explicitly so an aggregate alloca can
        // never reach a memory opcode typed as the aggregate itself.
        self.define_value_type(dst, Type::I64);

        // Compute allocation size metadata. For `count: None`, allocate one
        // element. For `count: Some(vid)`, look up `vid`'s producer in the
        // trust_ir function: if it is an Inst::Const with a non-negative integer,
        // fold it statically and allocate `count * element_size` bytes. If the
        // count is dynamic but every observed use has a bounded footprint, keep
        // the existing fixed-slot escape hatch. Otherwise record runtime-size
        // provenance so lower-layer consumers can distinguish this from an
        // ordinary fixed frame slot.
        //
        // #339 Finding 2: the previous implementation always allocated exactly
        // one element's worth of bytes, so a `count = 10` request received
        // only 8 bytes. Storing to element 2+ stomped adjacent stack slots.
        //
        // Most tla-trust_ir aggregate allocations still use constant counts, so the
        // constant-folding path handles the default case. Runtime counts are
        // accepted in two stages: bounded-use inference keeps producing fixed
        // slots (Issue #520 escape hatch), while the general case now produces
        // explicit runtime-sized metadata for the later frame/runtime work.
        //
        // Runtime-sized code generation now depends on preserving this slot
        // metadata through the downstream StackAddr paths. AArch64 and x86-64
        // ISel inspect `StackSlotAllocationKind` to choose between fixed frame
        // addresses and runtime StackAlloc cursor materialization, and the
        // public compiler dispatchers must seed that metadata before ISel.
        // For value-capable types THE EXTENT HERE IS DELIBERATELY NATURAL-C,
        // NOT THE LAYOUT AUTHORITY. Storage-only objects take their exact shared
        // IR geometry above and have no by-value ABI/LIR image at all.
        //
        // Every ADDRESS the byte path computes now comes from
        // [`crate::declared_layout`] — declared offsets, packed offsets, packed
        // array strides — and every by-value COPY length comes from
        // `aggregate_value_extent`. This slot does not, and the gap is measured,
        // one-directional and safe: the authority only ever SHRINKS an object
        // relative to natural C (`Alloca { ty: [P; 2] }` reserves 32 while the
        // packed image is 18), so every authoritative address lands strictly
        // inside the slot. That is the domination invariant, pinned in
        // `tests/packed_array_stride.rs` and `tests/packed_nested_layout.rs`.
        //
        // Moving it is an OVER-ALLOCATION traded for a possible OUT-OF-BOUNDS
        // write, and it cannot be done at these four sites alone
        // (`translate_alloc`'s size and align here, `translate_heap_alloc`'s
        // below). The blocker is STRUCTURAL, not a missed call site:
        //
        //   `abi.rs::classify_params` / `classify_returns` take `&[Type]` — the
        //   LIR types off `sig.params`, after the `StructId` and the module
        //   tables are gone. They size every by-value aggregate with
        //   `ty.bytes()` and decide reg-pair vs stack on `size <= 16`. There is
        //   nothing left there to resolve against a layout authority, so a
        //   value passed by value out of a SHRUNK slot would be read at its
        //   natural-C width — an out-of-bounds READ, and for `__rust_alloc` a
        //   heap one.
        //
        // So the order is: give the ABI classifier an authority-aware input
        // FIRST (a cross-crate signature change), then move all four extents in
        // one commit. A benign over-allocation is strictly better than a
        // partial change that trades it for memory corruption.
        let align = explicit_align
            .map(|explicit| element_align.max(explicit))
            .unwrap_or(element_align);
        if storage_geometry.is_some() {
            // A newly addressable class must not escape the existing 1 MiB
            // static frame bound through count=None or extreme alignment.
            self.checked_static_alloca_size(element_size.max(align), 1)?;
        }
        use crate::source_stack_allocations::{
            AllocationExtent, AllocationGeometryBasis, SourceStackAllocation,
        };
        let (slot, extent) = match count {
            None => (
                self.alloc_stack_slot(element_size, align),
                AllocationExtent::One,
            ),
            Some(vid) => {
                if let Some(n) = self.lookup_const_int(*vid) {
                    let size = self.checked_static_alloca_size(element_size, n)?;
                    (
                        self.alloc_stack_slot(size, align),
                        AllocationExtent::Constant(i128::from(n)),
                    )
                } else if let Some(bytes) =
                    self.infer_bounded_alloca_size_from_uses(alloca_result_vid)
                {
                    (
                        self.alloc_stack_slot(bytes, align),
                        AllocationExtent::BoundedUses,
                    )
                } else {
                    let lir_count = self.map_value(*vid);
                    (
                        self.alloc_runtime_stack_slot(
                            StackSlotSizeSource::Value(lir_count.0),
                            element_size,
                            align,
                        ),
                        AllocationExtent::Runtime,
                    )
                }
            }
        };

        self.proof_ctx
            .source_stack_allocations
            .records
            .push(SourceStackAllocation {
                block: source_site.0,
                origin: self.current_trust_ir_origin.ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(
                        "Alloca has no source instruction origin".into(),
                    )
                })?,
                instruction: u32::try_from(source_site.1).map_err(|_| {
                    AdapterError::UnsupportedInstruction(
                        "Alloca source instruction index overflows".into(),
                    )
                })?,
                source: alloca_result_vid,
                ty: ty.clone(),
                count: *count,
                explicit_align: explicit_align.map(u64::from),
                result: dst,
                slot,
                element_bytes: element_size,
                element_align,
                extent,
                geometry_basis: if storage_geometry.is_some() {
                    AllocationGeometryBasis::StorageLayout
                } else {
                    AllocationGeometryBasis::ValueCarrier
                },
                geometry: self.stack_slots[slot as usize],
            });

        match self.fixed_scalar_alloca_debug_local(ty, count, slot) {
            Ok((debug_ty, var_id)) => {
                self.debug_local_variables.push(DebugLocalVariable {
                    name: format!("local_{}", slot),
                    ty: debug_ty,
                    storage: DebugVariableStorage::ProvenanceVar(var_id),
                    decl_line: decl_line.unwrap_or(0),
                });
            }
            Err(_reason) => {}
        }

        Ok(vec![Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Build the LIR for a libc `mem*` intrinsic (`Memcpy`/`Memmove`/`Memset`).
    ///
    /// The C library `memcpy`/`memmove`/`memset` all RETURN the destination
    /// pointer (`args[0]`). When the trust-ir call binds a result value, define
    /// it as a `Copy` of the destination AFTER the memory op, so a downstream
    /// use of `%r = call @memcpy(dst, …)` sees the correct pointer instead of an
    /// undefined vreg. The void `llvm.mem*.*` intrinsic form carries no result
    /// (`result_vals` empty), so no `Copy` is emitted and its lowering is
    /// unchanged. Precondition for a named call: `classify_direct_call`
    /// admitted the callee's declaration (C's prototype, whose one result is
    /// that pointer, or LLVM's, which has none); a call of a function only
    /// named so never reaches here.
    fn mem_intrinsic_instrs(
        &mut self,
        opcode: Opcode,
        arg_vals: Vec<Value>,
        result_vals: &[Value],
    ) -> Vec<Instruction> {
        let dest = arg_vals.first().copied();
        let mut instrs = vec![Instruction {
            opcode,
            args: arg_vals,
            results: vec![],
        }];
        if let (Some(&dst), Some(dest)) = (result_vals.first(), dest) {
            // The returned dest pointer is an I64 address.
            self.define_value_type(dst, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Copy,
                args: vec![dest],
                results: vec![dst],
            });
        }
        instrs
    }

    /// Operand gate shared by the trust-ir WS3.20 bulk-memory pair: the
    /// pointer operands are pointer-like and the byte count is the
    /// pointer-width unsigned integer (`Usize`, or `U64` in a module that pins
    /// no target) — trust-ir-build's own operand typing, re-checked here so a
    /// malformed module is refused instead of lowered.
    fn require_bulk_memory_operands(
        &self,
        what: &str,
        pointers: &[(&str, ValueId)],
        bytes: ValueId,
    ) -> Result<(), AdapterError> {
        for &(role, pointer) in pointers {
            let ty = self
                .lookup_value_ty(pointer)
                .ok_or_else(|| AdapterError::UnknownValue(pointer.index()))?;
            if !Self::is_pointer_like_ty(&ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{what} {role} operand ValueId({}) has {ty:?}, not a pointer",
                    pointer.index()
                )));
            }
        }
        let count_ty = self
            .lookup_value_ty(bytes)
            .ok_or_else(|| AdapterError::UnknownValue(bytes.index()))?;
        if !matches!(count_ty, Ty::Usize | Ty::U64) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{what} byte count ValueId({}) has {count_ty:?}; expected Usize (or U64 without \
                 a target)",
                bytes.index()
            )));
        }
        Ok(())
    }

    /// `Inst::MemCopy` (trust-ir WS3.20): `overlap: false` is `memcpy` (an
    /// overlapping copy is UB in the source, so the non-overlapping libcall
    /// refines it) and `overlap: true` is `memmove`. The count is dynamic and
    /// byte-granular; a zero count is a no-op for any pointer, which is the
    /// contract the libc calls (and this backend's inline expansion of a
    /// small constant `memcpy`) already have for the named-call lowering.
    fn translate_mem_copy(
        &mut self,
        dst: ValueId,
        src: ValueId,
        bytes: ValueId,
        overlap: bool,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let what = if overlap {
            "Inst::MemCopy(overlap)"
        } else {
            "Inst::MemCopy"
        };
        if !results.is_empty() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{what} produces no value, but {} result(s) are bound",
                results.len()
            )));
        }
        self.require_bulk_memory_operands(what, &[("dst", dst), ("src", src)], bytes)?;
        let opcode = if overlap {
            Opcode::Memmove
        } else {
            Opcode::Memcpy
        };
        let args = vec![
            self.map_value(dst),
            self.map_value(src),
            self.map_value(bytes),
        ];
        Ok(self.mem_intrinsic_instrs(opcode, args, &[]))
    }

    /// `Inst::MemSet` (trust-ir WS3.20): fill `bytes` bytes at `dst` with the
    /// `U8` `byte`. `Opcode::Memset` takes the libc `int` fill, so the byte is
    /// zero-extended to I32 first (libc stores `(unsigned char)c`, so the
    /// extension is value-exact).
    fn translate_mem_set(
        &mut self,
        dst: ValueId,
        byte: ValueId,
        bytes: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !results.is_empty() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::MemSet produces no value, but {} result(s) are bound",
                results.len()
            )));
        }
        self.require_bulk_memory_operands("Inst::MemSet", &[("dst", dst)], bytes)?;
        self.require_trust_ir_operand_type("Inst::MemSet", "fill byte", byte, &Ty::U8)?;
        let fill = self.fresh_value();
        self.define_value_type(fill, Type::I32);
        // A constant fill is materialized directly, so instruction selection
        // still sees an `Iconst` fill (its inline zeroing path keys on one).
        let mut instrs = vec![match self.direct_int_const(byte) {
            Some(value) => Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: i64::from(value as u8),
                },
                args: vec![],
                results: vec![fill],
            },
            None => Instruction {
                opcode: Opcode::Uextend {
                    from_ty: Type::I8,
                    to_ty: Type::I32,
                },
                args: vec![self.map_value(byte)],
                results: vec![fill],
            },
        }];
        let args = vec![self.map_value(dst), fill, self.map_value(bytes)];
        instrs.extend(self.mem_intrinsic_instrs(Opcode::Memset, args, &[]));
        Ok(instrs)
    }

    /// Lower `Inst::GlobalAddr { global }` to the address of the named module
    /// global symbol.
    ///
    /// This is the in-body counterpart of the imported `Constant::Int`
    /// global-address stub handled by `decode_imported_global_addr`/
    /// `translate_int_const`: it resolves the `GlobalId` to the global's
    /// symbol name and emits `Opcode::GlobalRef { name }`, which x86-64 ISel
    /// (`select_global_ref`) materializes as a RIP-relative `LeaRip` against a
    /// dedicated GlobalRef relocation. The address is linker-resolved, so this
    /// is verified by link+run rather than an SMT proof.
    fn translate_global_addr(
        &mut self,
        global: GlobalId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let idx = global.index() as usize;
        let global_def = module.globals.get(idx).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "GlobalAddr references missing global index {}",
                idx
            ))
        })?;
        let name = global_def.name.clone();
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        // Thread-local globals resolve through the target's TLS access path, not
        // a plain symbol reference. The access dialect is object-format policy
        // ([`TlsDialect`], set by the compiler driver from the target triple):
        //
        //  * Mach-O (Darwin/AArch64): the TLV-descriptor sequence
        //    (`select_tls_ref`, `TlsModel::Tlv`) — ADRP/LDR to the
        //    `tlv_descriptor`, load the thunk, and call it (returns the
        //    variable's address). The object emitter materializes the
        //    descriptor in `__thread_vars`.
        //  * ELF (Linux/AArch64), selected by the relocation model: an
        //    executable image (`ElfExecutable`) reads a thread-local it
        //    DEFINES with local-exec (MRS TPIDR_EL0 plus two linker-patched
        //    TPREL adds) and a thread-local IMPORT with initial-exec
        //    (GOT-indirect TPREL); a shared object (`ElfSharedObject`) reads
        //    every thread-local with general-dynamic through a TLS
        //    descriptor. Definitions land in `.tdata` (all-zero templates in
        //    `.tbss`), imports become undefined `STT_TLS` symbols. The fixed
        //    `ElfLocalExec` / `ElfInitialExec` dialects remain for callers
        //    that pin one model.
        //
        // Either way a backend without the corresponding TLS object path
        // fails closed on the resulting `Opcode::TlsRef`/fixup, so a TLS
        // global is never silently miscompiled into a non-TLS reference.
        if global_def.tls.is_some() {
            let model = match self.tls_dialect {
                TlsDialect::MachOTlv => TlsModel::Tlv,
                TlsDialect::ElfLocalExec => TlsModel::LocalExec,
                TlsDialect::ElfInitialExec => TlsModel::InitialExec,
                TlsDialect::ElfExecutable if global_is_thread_local_import(global_def) => {
                    TlsModel::InitialExec
                }
                TlsDialect::ElfExecutable => TlsModel::LocalExec,
                TlsDialect::ElfSharedObject => TlsModel::GeneralDynamic,
                TlsDialect::RejectThreadLocals => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "target TLS policy rejects thread-local global `{name}`"
                    )));
                }
            };
            return Ok(vec![Instruction {
                opcode: Opcode::TlsRef {
                    name,
                    model,
                    local_exec_offset: None,
                },
                args: vec![],
                results: vec![dst],
            }]);
        }

        // An initializer-less global with external visibility is a cross-object
        // DATA IMPORT (e.g. `extern { static FOO: i32 }` resolved from another
        // object or a dylib). The object emitter marks it an undefined-external
        // symbol (compiler.rs `is_import: true`), so a DIRECT page reference
        // (`GlobalRef` -> ADRP@PAGE + ADD@PAGEOFF) is a relocation against an
        // undefined/interposable symbol: a static-link error, or the wrong
        // address under two-level-namespace interposition. macOS requires such a
        // reference to be GOT-INDIRECT (@GOTPAGE/@GOTPAGEOFF) — exactly the
        // `ExternRef` sequence (`select_extern_ref`) already used for imported
        // FUNCTIONS. An Internal/Private initializer-less global is a local
        // zero-initialized DEFINITION, not an import: object emission admits it
        // as its type's size in zero bytes (Mach-O `__data`; ELF places
        // writable all-zero definitions in SHT_NOBITS `.bss`).
        //
        // A DEFINED global keeps the direct `GlobalRef` unless the relocation
        // model makes it PREEMPTIBLE: in shared-object (`pic`) code a
        // default-visibility, non-local definition may be replaced by another
        // module's definition (for example the executable's), so a direct
        // page reference would both bypass that definition and be refused by
        // the static linker for `-shared`. Its address is loaded from the GOT
        // exactly like an import's.
        if self.global_address_is_got_indirect(global_def) {
            return Ok(vec![Instruction {
                opcode: Opcode::ExternRef { name },
                args: vec![],
                results: vec![dst],
            }]);
        }

        Ok(vec![Instruction {
            opcode: Opcode::GlobalRef { name },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Lower `Inst::HeapAlloc { ty, count, align, origin }` to a CALL of the
    /// allocator function selected by `origin`.
    ///
    /// Computes `size = count * sizeof(ty)` (constant-folded when `count` is a
    /// statically known integer, otherwise an emitted `Imul`) and `align`
    /// (`align` override or the natural alignment of `ty`), then calls:
    ///
    ///   * `AllocOrigin::RustHeap` -> `__rust_alloc(size: usize, align: usize)
    ///     -> *mut u8` (the Rust global allocator; the bridge/test driver
    ///     provides the shim forwarding to the system allocator).
    ///   * `AllocOrigin::CMalloc`  -> `malloc(size: usize) -> *mut void`
    ///     (libc; `align` is dropped — libc `malloc` already returns memory
    ///     suitably aligned for any fundamental type, so a natural-alignment
    ///     request is satisfied).
    ///   * `AllocOrigin::SwiftHeap` -> fail-closed: there is no portable
    ///     two-argument Swift heap-allocation shim yet, and we must never
    ///     miscompile by routing a Swift allocation to the wrong runtime.
    ///   * `AllocOrigin::CleanHeap` -> fail-closed for the same reason: Clean's
    ///     Perceus RC cells are allocated through the `clean_alloc_ctor`
    ///     runtime (refcount-managed, freed on `Release`->zero exactly like
    ///     `SwiftHeap`), and no portable shim is wired into this path yet.
    ///
    /// The returned pointer is the call's I64 result vreg. Correctness of the
    /// allocation itself rests on trusting the external allocator (exactly like
    /// the i128-division compiler-rt libcall and the memcpy/memmove/memset
    /// intrinsic calls); the abstract heap semantics are covered by the
    /// trust-ir Lean spec, so there is no per-call SMT proof for the external
    /// CALL. A `malloc`/`__rust_alloc` request for `0` bytes is implementation
    /// defined but never miscompiled — the size is passed through unchanged.
    fn translate_heap_alloc(
        &mut self,
        ty: &Ty,
        count: &Option<ValueId>,
        align: Option<u64>,
        origin: AllocOrigin,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let (element_size, effective_align) = self.heap_alloc_layout(ty, align)?;

        // Select the allocator symbol from the allocation origin. Unsupported
        // origins fail closed rather than route an allocation to the wrong
        // runtime.
        let alloc_symbol = match origin {
            AllocOrigin::RustHeap => RuntimeSymbol::RustAlloc,
            AllocOrigin::CMalloc => RuntimeSymbol::Malloc,
            AllocOrigin::SwiftHeap => {
                return Err(AdapterError::UnsupportedInstruction(
                    "HeapAlloc with AllocOrigin::SwiftHeap not yet lowered (fail-closed): \
                     Swift ARC heap allocation has no portable shim yet"
                        .to_string(),
                ));
            }
            AllocOrigin::CleanHeap => {
                // Clean's Perceus RC cells are allocated through the
                // `clean_alloc_ctor` runtime (refcount-managed, freed on
                // `Release`→zero exactly like SwiftHeap), not via a single
                // portable alloc symbol. No direct shim yet: fail closed
                // rather than route the allocation to the wrong runtime.
                return Err(AdapterError::UnsupportedInstruction(
                    "HeapAlloc with AllocOrigin::CleanHeap not yet lowered (fail-closed): \
                     Clean Perceus RC heap cells use the clean_alloc_ctor runtime, \
                     which has no portable shim yet"
                        .to_string(),
                ));
            }
        };

        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        let mut instrs = Vec::new();
        let size_val = self.emit_heap_alloc_size(element_size, count, &mut instrs)?;

        // Build the allocator call argument list per the selected ABI:
        // `__rust_alloc(size, align)`, or libc `malloc(size)` whose alignment
        // is satisfied by malloc's fundamental alignment guarantee.
        let mut call_args = vec![size_val];
        if origin == AllocOrigin::RustHeap {
            call_args.push(self.emit_iconst_i64(i64::from(effective_align), &mut instrs));
        }

        // Reuse the external-CALL relocation path (same machinery as the
        // i128-division compiler-rt libcall and memcpy/memmove/memset
        // intrinsics): a direct call by symbol name resolved by the linker.
        instrs.push(Instruction {
            opcode: self.runtime_call_opcode(alloc_symbol)?,
            args: call_args,
            results: vec![dst],
        });

        Ok(instrs)
    }

    /// The per-element byte size and effective alignment that a `HeapAlloc`
    /// hands its allocator. trust-ir states no allocator layout for
    /// `HeapAlloc`: this is THIS backend's convention, and a release spelled
    /// as a `__rust_dealloc` call is sound only if it repeats it (`Dealloc`
    /// itself is refused for codegen, G18-1).
    fn heap_alloc_layout(&self, ty: &Ty, align: Option<u64>) -> Result<(u32, u32), AdapterError> {
        self.refuse_bool_lane_layout(ty, "HeapAlloc element type")?;
        let lir_ty = self.translate_ty(ty)?;
        // NATURAL-C, deliberately — the other half of the extent bundle
        // documented at `translate_alloc`'s slot computation. `__rust_alloc`
        // over-allocates (32 bytes for a `[P; 2]` whose real extent is 18)
        // exactly as the stack slot does, and for exactly the same reason: the
        // C register-ABI classifier in `abi.rs` sizes by-value aggregates from
        // the bare LIR `Type` and would read a shrunk allocation at its
        // natural-C width. Shrinking here without giving that classifier an
        // authority-aware input turns a benign over-allocation into a heap
        // out-of-bounds read. These two lines move with those four, or not at
        // all. (The retired `Dealloc` lowering, 2887cbf01, reused this helper;
        // no release of a `HeapAlloc` result is lowered from it any more.)
        let element_size = lir_ty.bytes();
        let natural_align = lir_ty.align();
        // The effective alignment is the explicit override or the element's
        // natural alignment, whichever applies. `align` from trust_ir is the
        // requested allocation alignment.
        let effective_align = align
            .map(|a| {
                u32::try_from(a).map_err(|_| {
                    AdapterError::UnsupportedInstruction(format!(
                        "HeapAlloc alignment {a} exceeds u32 range"
                    ))
                })
            })
            .transpose()?
            .unwrap_or(natural_align);
        Ok((element_size, effective_align))
    }

    /// The total byte size of a `HeapAlloc` when its count is absent or a
    /// statically known integer; `None` for a dynamic count.
    fn heap_alloc_static_bytes(
        &self,
        element_size: u32,
        count: &Option<ValueId>,
    ) -> Result<Option<u64>, AdapterError> {
        let Some(vid) = count else {
            return Ok(Some(u64::from(element_size)));
        };
        let Some(n) = self.lookup_const_int(*vid) else {
            return Ok(None);
        };
        if n < 0 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "HeapAlloc with negative count {n}"
            )));
        }
        let total = (element_size as u128)
            .checked_mul(n as u128)
            .filter(|t| *t <= u64::MAX as u128)
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "HeapAlloc size overflow: {element_size} * {n}"
                ))
            })?;
        Ok(Some(total as u64))
    }

    /// Emit the byte-size operand of a `HeapAlloc`. A static size is folded; a
    /// dynamic count is extended to i64 and multiplied by the element size.
    fn emit_heap_alloc_size(
        &mut self,
        element_size: u32,
        count: &Option<ValueId>,
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        if let Some(total) = self.heap_alloc_static_bytes(element_size, count)? {
            return Ok(self.emit_iconst_i64(total as i64, instrs));
        }
        let Some(vid) = *count else {
            return Ok(self.emit_iconst_i64(i64::from(element_size), instrs));
        };
        // `extend_index_to_i64_if_needed` produces a 64-bit count regardless
        // of the source integer width so the multiply matches the usize size
        // argument.
        let count_val = self.map_value(vid);
        let count_i64 = self.extend_index_to_i64_if_needed(vid, count_val, instrs)?;
        if element_size == 1 {
            return Ok(count_i64);
        }
        let size_const = self.emit_iconst_i64(i64::from(element_size), instrs);
        let scaled = self.fresh_value();
        self.define_value_type(scaled, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![count_i64, size_const],
            results: vec![scaled],
        });
        Ok(scaled)
    }

    /// Emit an i64 `Iconst` into `instrs` and return its result Value.
    fn emit_iconst_i64(&mut self, imm: i64, instrs: &mut Vec<Instruction>) -> Value {
        let v = self.fresh_value();
        self.define_value_type(v, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iconst { ty: Type::I64, imm },
            args: vec![],
            results: vec![v],
        });
        v
    }

    /// True iff the module declares the Clean RC-runtime import triple as
    /// bodyless externals with the exact expected signatures:
    ///
    ///   * `clean_inc(ptr) -> ()`          — retain: refcount +1
    ///   * `clean_dec(ptr) -> ()`          — release: refcount −1, frees at zero
    ///   * `clean_is_exclusive(ptr) -> u8` — unique? (same polarity as `IsUnique`)
    ///
    /// The triple is all-or-nothing: a partial match is not an RC runtime and
    /// the ARC ops keep failing closed. Signatures are checked (not just
    /// names) so an unrelated same-named import cannot claim the contract.
    fn module_declares_clean_rc_runtime(&self) -> bool {
        let Some(module) = self.module else {
            return false;
        };
        let declares = |name: &str, params: &[Ty], returns: &[Ty]| {
            module.functions.iter().any(|func| {
                func.name == name
                    && is_bodyless_external_declaration(func)
                    && module
                        .func_types
                        .get(func.ty.index() as usize)
                        .is_some_and(|sig| {
                            !sig.is_vararg
                                && sig.params.as_slice() == params
                                && sig.returns.as_slice() == returns
                        })
            })
        };
        declares(CLEAN_RC_RETAIN, &[Ty::Ptr], &[])
            && declares(CLEAN_RC_RELEASE, &[Ty::Ptr], &[])
            && declares(CLEAN_RC_IS_UNIQUE, &[Ty::Ptr], &[Ty::U8])
    }

    /// Lower one ARC op (`Retain`/`Release`/`IsUnique`) to a CALL of the
    /// module-declared Clean RC runtime (see [`Self::module_declares_clean_rc_runtime`]).
    ///
    /// `Retain`/`Release` are void calls of `clean_inc`/`clean_dec`. `IsUnique`
    /// calls `clean_is_exclusive` — the SAME predicate (refcount == 1), so no
    /// negation happens here; Clean's frontend expresses `IsShared` as
    /// `!IsUnique` itself — and normalizes the C `bool` return to a canonical
    /// 0/1 with an explicit `!= 0` byte compare (the same byte-compare idiom
    /// the Clean frontend used pre-native-ARC), so a strict-ABI callee's
    /// unspecified upper bits can never leak into a Bool consumer.
    ///
    /// Like the allocator/memcpy/i128-libcall externals, correctness of the
    /// call target rests on trusting the runtime symbol; the refcount
    /// semantics themselves are covered by the trust-ir Lean ARC model, so
    /// there is no per-call SMT proof for the external CALL.
    fn translate_arc_op(
        &mut self,
        op_name: &str,
        symbol: RuntimeSymbol,
        ptr: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !self.module_declares_clean_rc_runtime() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "ARC {op_name} not lowered: the module declares no RC runtime \
                 (a Clean-produced module declares the bodyless-external \
                 {CLEAN_RC_RETAIN}/{CLEAN_RC_RELEASE}/{CLEAN_RC_IS_UNIQUE} import \
                 triple); routing reference-count ops to an undeclared runtime \
                 would corrupt its refcount discipline, so this fails closed"
            )));
        }
        let ptr_val = self.map_value(ptr);
        if symbol != RuntimeSymbol::CleanIsExclusive {
            // Retain/Release: a void runtime call.
            return Ok(vec![Instruction {
                opcode: self.runtime_call_opcode(symbol)?,
                args: vec![ptr_val],
                results: vec![],
            }]);
        }
        // IsUnique: call + normalize the C `bool` (byte) to the Bool result.
        let dst = self.map_result(results)?;
        let raw = self.fresh_value();
        self.define_value_type(raw, Type::I8);
        let zero = self.fresh_value();
        self.define_value_type(zero, Type::I8);
        Ok(vec![
            Instruction {
                opcode: self.runtime_call_opcode(symbol)?,
                args: vec![ptr_val],
                results: vec![raw],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I8,
                    imm: 0,
                },
                args: vec![],
                results: vec![zero],
            },
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::NotEqual,
                },
                args: vec![raw, zero],
                results: vec![dst],
            },
        ])
    }

    /// Returns the debug type and synthetic provenance var for the one fixed
    /// scalar alloca shape handled by the #866 bridge. Other shapes are skipped
    /// with typed reasons so later recovery work can widen this deliberately.
    fn fixed_scalar_alloca_debug_local(
        &self,
        ty: &Ty,
        count: &Option<ValueId>,
        slot: u32,
    ) -> Result<(DebugBaseType, TrustIrVarId), AllocaDebugLocalSkipReason> {
        let debug_ty =
            debug_base_type_from_trust_ir(ty).ok_or(AllocaDebugLocalSkipReason::UnsupportedType)?;
        match count {
            None => {}
            Some(vid) => match self.lookup_const_int(*vid) {
                Some(1) => {}
                Some(_) => return Err(AllocaDebugLocalSkipReason::NonScalarElementCount),
                None => return Err(AllocaDebugLocalSkipReason::RuntimeElementCount),
            },
        }
        let var_id = alloca_debug_provenance_var_id(slot)
            .ok_or(AllocaDebugLocalSkipReason::SyntheticVarIdOverflow)?;
        Ok((debug_ty, var_id))
    }

    /// Decode and bind `func`'s U10 stack-limit tags
    /// ([`crate::stack_limit::decode_function_request`]) and check the
    /// requested parameter against the lowered signature: it must lower to
    /// one 64-bit integer value (`Type::I64`), in a function with no hidden
    /// `sret` parameter. Which register carries it is the target's signature
    /// lowering, resolved by the backend that emits the check.
    fn admit_stack_limit_request(
        &self,
        func: &TrustIrFunction,
        module: &TrustIrModule,
        sig: &Signature,
        abi_sret_param: Option<crate::function::AbiSretParam>,
    ) -> Result<Option<crate::function::StackLimitRequest>, AdapterError> {
        let refuse = |reason: String| AdapterError::StackLimitRequest {
            function: func.name.clone(),
            reason,
        };
        let Some(request) = crate::stack_limit::decode_function_request(func, module)
            .map_err(|error| refuse(error.to_string()))?
        else {
            return Ok(None);
        };
        // Only the AArch64 backend emits and verifies the check. The x86-64
        // and RISC-V lowerings refuse the request here rather than compile
        // the function without it.
        if self.guard_carrier_arch != GuardCarrierArch::AArch64 {
            return Err(refuse(format!(
                "the {:?} backend has no prologue stack-limit lowering (v1 is AArch64 only)",
                self.guard_carrier_arch
            )));
        }
        if abi_sret_param.is_some() {
            return Err(refuse(
                "a function with a hidden sret parameter cannot request a stack limit in v1"
                    .to_string(),
            ));
        }
        match sig.params.get(usize::from(request.param)) {
            Some(Type::I64) => Ok(Some(request)),
            Some(other) => Err(refuse(format!(
                "parameter {} lowers to {other:?}; the limit source must be one 64-bit integer \
                 or pointer parameter",
                request.param
            ))),
            None => Err(refuse(format!(
                "parameter {} is not in the lowered signature ({} parameters)",
                request.param,
                sig.params.len()
            ))),
        }
    }

    fn function_requires_stack_protector(&self, func: &TrustIrFunction) -> bool {
        match imported_stack_protector_request(func) {
            ImportedStackProtectorRequest::None => false,
            ImportedStackProtectorRequest::Required => true,
            ImportedStackProtectorRequest::Eligible => {
                self.imported_ssp_body_requires_stack_guard(func)
            }
        }
    }

    fn imported_ssp_body_requires_stack_guard(&self, func: &TrustIrFunction) -> bool {
        for block in &func.blocks {
            for node in &block.body {
                let Inst::Alloca { ty, count, .. } = &node.inst else {
                    continue;
                };
                let Some(alloca_result) = node.results.first().copied() else {
                    return true;
                };
                if self.imported_ssp_alloca_requires_stack_guard(alloca_result, ty, count) {
                    return true;
                }
            }
        }
        false
    }

    fn imported_ssp_alloca_requires_stack_guard(
        &self,
        alloca_result: ValueId,
        ty: &Ty,
        count: &Option<ValueId>,
    ) -> bool {
        let Some(static_size) = self.static_alloca_size_bytes(ty, count) else {
            return true;
        };
        if self.is_protected_imported_ssp_alloca(ty, count, static_size) {
            return true;
        }
        self.alloca_pointer_has_unsafe_stack_protector_use(alloca_result, static_size)
    }

    fn static_alloca_size_bytes(&self, ty: &Ty, count: &Option<ValueId>) -> Option<u32> {
        let element_size = self.translate_ty(ty).ok()?.bytes();
        let element_count = match count {
            None => 1,
            Some(vid) => self.lookup_const_int(*vid)?,
        };
        if element_count < 0 {
            return None;
        }
        let element_count = u32::try_from(element_count).ok()?;
        element_size.checked_mul(element_count)
    }

    fn is_protected_imported_ssp_alloca(
        &self,
        ty: &Ty,
        count: &Option<ValueId>,
        static_size: u32,
    ) -> bool {
        let element_count = count
            .and_then(|vid| self.lookup_const_int(vid))
            .unwrap_or(1);
        let fixed_scalar = element_count <= 1 && is_stack_protector_scalar_alloca_ty(ty);
        !fixed_scalar && static_size >= IMPORTED_STACK_PROTECTOR_BUFFER_BYTES
    }

    fn alloca_pointer_has_unsafe_stack_protector_use(
        &self,
        alloca_result: ValueId,
        static_size: u32,
    ) -> bool {
        let Some(func) = self.trust_ir_func else {
            return true;
        };
        let static_size = i128::from(static_size);

        for block in &func.blocks {
            for node in &block.body {
                match &node.inst {
                    Inst::Load { ty, ptr, .. } | Inst::AtomicLoad { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::Store { ty, ptr, value, .. }
                    | Inst::AtomicStore { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            alloca_result,
                            &mut HashSet::new(),
                        ) {
                            return true;
                        }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::AtomicRMW { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            alloca_result,
                            &mut HashSet::new(),
                        ) {
                            return true;
                        }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::CmpXchg {
                        ty,
                        ptr,
                        expected,
                        desired,
                        ..
                    } => {
                        if self.any_value_derived_from_alloca([*expected, *desired], alloca_result)
                        {
                            return true;
                        }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::Call { callee, args } => {
                        for (arg_index, arg) in args.iter().enumerate() {
                            if self.value_definitely_derived_from_alloca(
                                *arg,
                                alloca_result,
                                &mut HashSet::new(),
                            ) && !self.direct_call_allows_stack_pointer_arg(
                                *callee,
                                arg_index,
                                *arg,
                                alloca_result,
                                static_size,
                            ) {
                                return true;
                            }
                        }
                    }
                    // CannotUnwind is not NoEscape or NoPanic. Until the
                    // boundary is modeled, do not derive a stack-use license
                    // from a direct callee's ordinary-call facts.
                    Inst::CallCannotUnwind { args, .. } => {
                        if self.any_value_derived_from_alloca(args.iter().copied(), alloca_result) {
                            return true;
                        }
                    }
                    Inst::CallIndirectCannotUnwind { callee, args, .. }
                    // v56: the unwinding indirect call, refused by the body
                    // floor; named so no wildcard reads it as no escape.
                    | Inst::InvokeIndirect { callee, args, .. } => {
                        if self.any_value_derived_from_alloca(
                            std::iter::once(*callee).chain(args.iter().copied()),
                            alloca_result,
                        ) {
                            return true;
                        }
                    }
                    // v55: a drop runs its type's glue on the place; refused
                    // by the body floor, and never a stack-use license.
                    Inst::Drop { ptr, .. } | Inst::DropInvoke { ptr, .. } => {
                        if self.any_value_derived_from_alloca([*ptr], alloca_result) {
                            return true;
                        }
                    }
                    Inst::CallIndirect { callee, args, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *callee,
                            alloca_result,
                            &mut HashSet::new(),
                        ) || args.iter().any(|arg| {
                            self.value_definitely_derived_from_alloca(
                                *arg,
                                alloca_result,
                                &mut HashSet::new(),
                            )
                        }) {
                            return true;
                        }
                    }
                    Inst::Return { values } => {
                        if self.any_value_derived_from_alloca(values.iter().copied(), alloca_result)
                        {
                            return true;
                        }
                    }
                    Inst::Br { args, .. } => {
                        if self.any_value_derived_from_alloca(args.iter().copied(), alloca_result) {
                            return true;
                        }
                    }
                    Inst::CondBr {
                        then_args,
                        else_args,
                        ..
                    } => {
                        if self.any_value_derived_from_alloca(
                            then_args.iter().chain(else_args).copied(),
                            alloca_result,
                        ) {
                            return true;
                        }
                    }
                    Inst::Switch {
                        default_args,
                        cases,
                        ..
                    } => {
                        if self.any_value_derived_from_alloca(
                            default_args
                                .iter()
                                .copied()
                                .chain(cases.iter().flat_map(|case| case.args.iter().copied())),
                            alloca_result,
                        ) {
                            return true;
                        }
                    }
                    Inst::Cast {
                        op: CastOp::PtrToInt,
                        operand,
                        ..
                    } if self.value_definitely_derived_from_alloca(
                        *operand,
                        alloca_result,
                        &mut HashSet::new(),
                    ) =>
                    {
                        return true;
                    }
                    Inst::BinOp { lhs, rhs, .. }
                    | Inst::ICmp { lhs, rhs, .. }
                    | Inst::Overflow { lhs, rhs, .. }
                        if self.any_value_derived_from_alloca([*lhs, *rhs], alloca_result) =>
                    {
                        return true;
                    }
                    Inst::Retain { ptr }
                    | Inst::Release { ptr }
                    | Inst::Dealloc { ptr }
                    | Inst::IsUnique { ptr }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) =>
                    {
                        return true;
                    }
                    // Placing the buffer's address in a register aggregate (a
                    // splatted or inserted lane, a constructed field, either
                    // fat-pointer part) lets it escape, exactly as a `Store` of
                    // the pointer does: an access through the value read back
                    // out is not traced to the buffer, so it is never bounds
                    // checked above.
                    Inst::ArraySplat { value, .. }
                    | Inst::InsertField { value, .. }
                    | Inst::InsertElement { value, .. }
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            alloca_result,
                            &mut HashSet::new(),
                        ) =>
                    {
                        return true;
                    }
                    Inst::PtrFromParts { data, metadata, .. }
                        if self
                            .any_value_derived_from_alloca([*data, *metadata], alloca_result) =>
                    {
                        return true;
                    }
                    Inst::MakeAggregate { fields, .. }
                    | Inst::MakeClosure { captures: fields, .. }
                        if self.any_value_derived_from_alloca(
                            fields.iter().copied(),
                            alloca_result,
                        ) =>
                    {
                        return true;
                    }
                    // trust-ir WS3.20 bulk memory into or out of the buffer is
                    // the classic overflow shape: it is safe only when its
                    // constant footprint stays inside the allocation.
                    Inst::MemCopy {
                        dst, src, bytes, ..
                    } => {
                        for pointer in [*dst, *src] {
                            match self.bulk_memory_alloca_end_bytes(alloca_result, pointer, *bytes)
                            {
                                BulkMemoryFootprint::Unrelated => {}
                                BulkMemoryFootprint::Bounded(end) if end <= static_size => {}
                                BulkMemoryFootprint::Bounded(_)
                                | BulkMemoryFootprint::Unbounded => return true,
                            }
                        }
                    }
                    Inst::MemSet { dst, bytes, .. } => {
                        match self.bulk_memory_alloca_end_bytes(alloca_result, *dst, *bytes) {
                            BulkMemoryFootprint::Unrelated => {}
                            BulkMemoryFootprint::Bounded(end) if end <= static_size => {}
                            BulkMemoryFootprint::Bounded(_) | BulkMemoryFootprint::Unbounded => {
                                return true;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }

        false
    }

    fn direct_call_allows_stack_pointer_arg(
        &self,
        callee: FuncId,
        arg_index: usize,
        arg: ValueId,
        alloca_result: ValueId,
        static_size: i128,
    ) -> bool {
        let callee_name = self.functions.name(callee).unwrap_or("");
        if is_stack_pointer_readonly_intrinsic(callee_name) {
            return true;
        }
        if self.external_func_ids.contains(&callee) {
            return false;
        }

        let Some(arg_offset) =
            self.pointer_offset_from_alloca_bytes(arg, alloca_result, &mut HashSet::new())
        else {
            return false;
        };
        let mut seen_direct_call_args = HashSet::new();
        let Some(callee_end) = self.infer_direct_callee_pointer_max_end_bytes(
            callee,
            arg_index,
            &mut seen_direct_call_args,
        ) else {
            return false;
        };
        arg_offset
            .checked_add(callee_end)
            .is_some_and(|end| end <= static_size)
    }

    fn any_value_derived_from_alloca<I>(&self, values: I, alloca_result: ValueId) -> bool
    where
        I: IntoIterator<Item = ValueId>,
    {
        values.into_iter().any(|value| {
            self.value_definitely_derived_from_alloca(value, alloca_result, &mut HashSet::new())
        })
    }

    fn value_definitely_derived_from_alloca(
        &self,
        value: ValueId,
        alloca_result: ValueId,
        seen: &mut HashSet<ValueId>,
    ) -> bool {
        if value == alloca_result {
            return true;
        }
        if !seen.insert(value) {
            return false;
        }

        let derived = match self.find_value_producer(value).map(|node| &node.inst) {
            Some(Inst::Copy { operand, .. })
            | Some(Inst::Cast { operand, .. })
            | Some(Inst::Borrow { ptr: operand })
            | Some(Inst::BorrowMut { ptr: operand }) => {
                self.value_definitely_derived_from_alloca(*operand, alloca_result, seen)
            }
            Some(Inst::GEP { base, .. }) => {
                self.value_definitely_derived_from_alloca(*base, alloca_result, seen)
            }
            Some(Inst::Select {
                then_val, else_val, ..
            }) => {
                self.value_definitely_derived_from_alloca(*then_val, alloca_result, seen)
                    || self.value_definitely_derived_from_alloca(*else_val, alloca_result, seen)
            }
            _ => false,
        };

        seen.remove(&value);
        derived
    }

    /// Look up the `Inst::Const` producer of a ValueId in the current trust_ir
    /// function. Returns `Some(value)` only when the producer is a statically
    /// foldable integer expression that fits in `i64`; otherwise returns
    /// `None` (producer is dynamic, non-integer, or out of i64 range).
    ///
    /// Cost: linear scan over the function body. Acceptable because Alloca
    /// counts are rare (one per aggregate construction) and `count` is always
    /// defined immediately before.
    fn lookup_const_int(&self, vid: ValueId) -> Option<i64> {
        let mut seen = HashSet::new();
        let value = self.lookup_const_int_inner(vid, &mut seen)?;
        i64::try_from(value).ok()
    }

    fn lookup_const_bool(&self, vid: ValueId) -> Option<bool> {
        let mut seen = HashSet::new();
        self.lookup_const_bool_inner(vid, &mut seen)
    }

    fn lookup_const_bool_inner(&self, vid: ValueId, seen: &mut HashSet<ValueId>) -> Option<bool> {
        if !seen.insert(vid) {
            return None;
        }
        let node = self.find_value_producer(vid)?;
        let value = match &node.inst {
            Inst::Const {
                value: Constant::Bool(value),
                ..
            } => Some(*value),
            Inst::Const {
                ty: Ty::Bool,
                value: Constant::Int(0),
            } => Some(false),
            Inst::Const {
                ty: Ty::Bool,
                value: Constant::Int(1),
            } => Some(true),
            Inst::Copy { operand, .. } => self.lookup_const_bool_inner(*operand, seen),
            _ => None,
        };
        seen.remove(&vid);
        value
    }

    /// Compute the byte size for a statically known alloca count, rejecting
    /// negative counts, overflow, and runaway frame sizes.
    fn checked_static_alloca_size(&self, element_size: u32, n: i64) -> Result<u32, AdapterError> {
        if n < 0 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Alloca with negative count {}",
                n
            )));
        }
        // Hard cap at 1 MiB per static allocation. Anything larger should go
        // through heap allocation; catching it here prevents runaway stack
        // frame sizes from a mis-lowered trust_ir program.
        const MAX_ALLOCA_BYTES: u128 = 1 << 20;
        let total = (element_size as u128)
            .checked_mul(n as u128)
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Alloca size overflow: {} * {}",
                    element_size, n
                ))
            })?;
        if total > MAX_ALLOCA_BYTES {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Alloca size {} exceeds {}-byte static limit",
                total, MAX_ALLOCA_BYTES
            )));
        }
        Ok(total as u32)
    }

    /// Find the defining instruction for a trust_ir `ValueId`.
    fn find_value_producer(&self, vid: ValueId) -> Option<&'a InstrNode> {
        self.value_producers.get(&vid).copied()
    }

    /// Recursively fold a small integer-expression DAG rooted at `vid`.
    ///
    /// This stays intentionally narrow: constants, copies, simple integer
    /// binops, and integer casts. That covers the non-direct-const count
    /// shapes ty emits around bounded aggregate temporaries without trying to
    /// become a general trust_ir evaluator inside the adapter.
    fn lookup_const_int_inner(&self, vid: ValueId, seen: &mut HashSet<ValueId>) -> Option<i128> {
        if !seen.insert(vid) {
            return None;
        }
        let node = self.find_value_producer(vid)?;
        let value = match &node.inst {
            Inst::Const {
                value: Constant::Int(v),
                ..
            } => Some(*v),
            Inst::Copy { operand, .. } => self.lookup_const_int_inner(*operand, seen),
            Inst::BinOp { op, lhs, rhs, .. } => {
                let lhs_val = self.lookup_const_int_inner(*lhs, seen)?;
                let rhs_val = self.lookup_const_int_inner(*rhs, seen)?;
                match op {
                    BinOp::Add => lhs_val.checked_add(rhs_val),
                    BinOp::Sub => lhs_val.checked_sub(rhs_val),
                    BinOp::Mul => lhs_val.checked_mul(rhs_val),
                    BinOp::UDiv | BinOp::SDiv => {
                        if rhs_val == 0 {
                            None
                        } else {
                            lhs_val.checked_div(rhs_val)
                        }
                    }
                    BinOp::URem | BinOp::SRem => {
                        if rhs_val == 0 {
                            None
                        } else {
                            lhs_val.checked_rem(rhs_val)
                        }
                    }
                    BinOp::And => Some(lhs_val & rhs_val),
                    BinOp::Or => Some(lhs_val | rhs_val),
                    BinOp::Xor => Some(lhs_val ^ rhs_val),
                    BinOp::Shl => {
                        let shift = u32::try_from(rhs_val).ok()?;
                        lhs_val.checked_shl(shift)
                    }
                    BinOp::LShr => {
                        let shift = u32::try_from(rhs_val).ok()?;
                        Some(((lhs_val as u128).checked_shr(shift)?) as i128)
                    }
                    BinOp::AShr => {
                        let shift = u32::try_from(rhs_val).ok()?;
                        lhs_val.checked_shr(shift)
                    }
                    _ => None,
                }
            }
            Inst::Cast {
                op,
                src_ty,
                dst_ty,
                operand,
            } => {
                let src_val = self.lookup_const_int_inner(*operand, seen)?;
                self.fold_integer_cast(*op, src_ty, dst_ty, src_val)
            }
            _ => None,
        };
        seen.remove(&vid);
        value
    }

    /// Fold an integer cast on a statically known value.
    fn fold_integer_cast(&self, op: CastOp, src_ty: &Ty, dst_ty: &Ty, value: i128) -> Option<i128> {
        let src_bits = Self::int_ty_bits(src_ty)?;
        let dst_bits = Self::int_ty_bits(dst_ty)?;
        match op {
            CastOp::Trunc => Some(Self::truncate_to_bits(value, dst_bits)),
            CastOp::ZExt => Some(Self::zero_extend_bits(value, src_bits)),
            CastOp::SExt => Some(Self::sign_extend_bits(value, src_bits)),
            CastOp::Bitcast | CastOp::PtrToInt | CastOp::IntToPtr => {
                if src_bits == dst_bits {
                    Some(Self::truncate_to_bits(value, dst_bits))
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// Infer a bounded static alloca size from the actual access pattern when
    /// the count expression itself is not directly foldable.
    ///
    /// This is a conservative escape hatch for ty aggregate temporaries:
    /// if every use stays inside a statically-known byte footprint, we can
    /// allocate that footprint as an ordinary fixed stack slot without adding
    /// a full runtime-sized frame path. In addition to in-function loads and
    /// stores, this follows direct same-module calls when the pointer argument
    /// remains bounded in the callee as well.
    fn infer_bounded_alloca_size_from_uses(&self, alloca_result: ValueId) -> Option<u32> {
        let mut seen_direct_call_args = HashSet::new();
        let max_end_bytes =
            self.infer_bounded_pointer_max_end_bytes(alloca_result, &mut seen_direct_call_args)?;
        if max_end_bytes <= 0 {
            return None;
        }

        u32::try_from(max_end_bytes).ok()
    }

    /// Compute the maximum end offset reached by all bounded uses of a root
    /// pointer inside the current function. `Some(0)` means the pointer never
    /// escaped or touched memory; `None` means a use escaped the bounded subset.
    fn infer_bounded_pointer_max_end_bytes(
        &self,
        root_ptr: ValueId,
        seen_direct_call_args: &mut HashSet<(FuncId, usize)>,
    ) -> Option<i128> {
        let func = self.trust_ir_func?;
        let mut max_end_bytes: i128 = 0;

        for block in &func.blocks {
            for node in &block.body {
                match &node.inst {
                    Inst::Load { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                    }
                    Inst::Store { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            return None;
                        }
                    }
                    Inst::AtomicLoad { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                    }
                    Inst::AtomicStore { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            return None;
                        }
                    }
                    Inst::AtomicRMW { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                    }
                    Inst::CmpXchg {
                        ty,
                        ptr,
                        expected,
                        desired,
                        ..
                    } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                        if self.any_value_derived_from_alloca([*expected, *desired], root_ptr) {
                            return None;
                        }
                    }
                    Inst::Call { callee, args } => {
                        for (arg_index, arg) in args.iter().enumerate() {
                            if !self.value_definitely_derived_from_alloca(
                                *arg,
                                root_ptr,
                                &mut HashSet::new(),
                            ) {
                                continue;
                            }
                            let arg_offset = self.pointer_offset_from_alloca_bytes(
                                *arg,
                                root_ptr,
                                &mut HashSet::new(),
                            )?;
                            let callee_end = self.infer_direct_callee_pointer_max_end_bytes(
                                *callee,
                                arg_index,
                                seen_direct_call_args,
                            )?;
                            let total_end = arg_offset.checked_add(callee_end)?;
                            max_end_bytes = max_end_bytes.max(total_end);
                        }
                    }
                    Inst::CallCannotUnwind { args, .. }
                        if self.any_value_derived_from_alloca(args.iter().copied(), root_ptr) =>
                    {
                        return None;
                    }
                    Inst::CallIndirectCannotUnwind { callee, args, .. }
                    | Inst::InvokeIndirect { callee, args, .. }
                        if self.any_value_derived_from_alloca(
                            std::iter::once(*callee).chain(args.iter().copied()),
                            root_ptr,
                        ) =>
                    {
                        return None;
                    }
                    Inst::Drop { ptr, .. } | Inst::DropInvoke { ptr, .. }
                        if self.any_value_derived_from_alloca([*ptr], root_ptr) =>
                    {
                        return None;
                    }
                    Inst::CallIndirect { callee, args, .. }
                        if self.value_definitely_derived_from_alloca(
                            *callee,
                            root_ptr,
                            &mut HashSet::new(),
                        ) || args.iter().any(|arg| {
                            self.value_definitely_derived_from_alloca(
                                *arg,
                                root_ptr,
                                &mut HashSet::new(),
                            )
                        }) =>
                    {
                        return None;
                    }
                    Inst::Return { values }
                        if values.iter().any(|value| {
                            self.value_definitely_derived_from_alloca(
                                *value,
                                root_ptr,
                                &mut HashSet::new(),
                            )
                        }) =>
                    {
                        return None;
                    }
                    // A root address placed in a register aggregate escapes
                    // into it, exactly like a stored pointer: the lowering
                    // writes it into the aggregate's storage, and an access
                    // through the lane read back out (`ExtractField`,
                    // `ExtractElement`, `PtrData`, `PtrMetadata`) is not traced
                    // to the root, so its footprint would go uncounted and the
                    // fixed slot would come out too small. Both fat-pointer
                    // parts are stored, so a root-derived `metadata` escapes
                    // as surely as a root-derived `data`.
                    Inst::ArraySplat { value, .. }
                    | Inst::InsertField { value, .. }
                    | Inst::InsertElement { value, .. }
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            root_ptr,
                            &mut HashSet::new(),
                        ) =>
                    {
                        return None;
                    }
                    Inst::PtrFromParts { data, metadata, .. }
                        if self.any_value_derived_from_alloca([*data, *metadata], root_ptr) =>
                    {
                        return None;
                    }
                    Inst::MakeAggregate { fields, .. }
                    | Inst::MakeClosure {
                        captures: fields, ..
                    } if self.any_value_derived_from_alloca(fields.iter().copied(), root_ptr) => {
                        return None;
                    }
                    // trust-ir WS3.20 bulk memory touches `bytes` bytes at each
                    // pointer. A use through the root is bounded only when both
                    // the offset and the count are constants; otherwise the
                    // footprint is unknown and the root leaves the bounded
                    // subset, exactly like an escaping call argument.
                    Inst::MemCopy {
                        dst, src, bytes, ..
                    } => {
                        for pointer in [*dst, *src] {
                            let end = self.bulk_memory_alloca_end_bytes(root_ptr, pointer, *bytes);
                            match end {
                                BulkMemoryFootprint::Unrelated => {}
                                BulkMemoryFootprint::Bounded(end) => {
                                    max_end_bytes = max_end_bytes.max(end);
                                }
                                BulkMemoryFootprint::Unbounded => return None,
                            }
                        }
                    }
                    Inst::MemSet { dst, bytes, .. } => {
                        match self.bulk_memory_alloca_end_bytes(root_ptr, *dst, *bytes) {
                            BulkMemoryFootprint::Unrelated => {}
                            BulkMemoryFootprint::Bounded(end) => {
                                max_end_bytes = max_end_bytes.max(end);
                            }
                            BulkMemoryFootprint::Unbounded => return None,
                        }
                    }
                    _ => {}
                }
            }
        }

        Some(max_end_bytes)
    }

    /// The footprint a trust-ir WS3.20 bulk-memory operand `pointer` of
    /// `bytes` bytes has in the allocation rooted at `root_ptr`.
    fn bulk_memory_alloca_end_bytes(
        &self,
        root_ptr: ValueId,
        pointer: ValueId,
        bytes: ValueId,
    ) -> BulkMemoryFootprint {
        if !self.value_definitely_derived_from_alloca(pointer, root_ptr, &mut HashSet::new()) {
            return BulkMemoryFootprint::Unrelated;
        }
        let offset = self.pointer_offset_from_alloca_bytes(pointer, root_ptr, &mut HashSet::new());
        match (offset, self.direct_int_const(bytes)) {
            (Some(offset), Some(count)) if offset >= 0 && count >= 0 => offset
                .checked_add(count)
                .map_or(BulkMemoryFootprint::Unbounded, BulkMemoryFootprint::Bounded),
            _ => BulkMemoryFootprint::Unbounded,
        }
    }

    /// Follow a direct same-module call and compute the bounded footprint of
    /// the callee parameter that receives the pointer argument.
    fn infer_direct_callee_pointer_max_end_bytes(
        &self,
        callee: FuncId,
        arg_index: usize,
        seen_direct_call_args: &mut HashSet<(FuncId, usize)>,
    ) -> Option<i128> {
        let module = self.module?;
        let callee_func = self.functions.unique(module, callee)?;
        let entry_block = callee_func
            .blocks
            .iter()
            .find(|block| block.id == callee_func.entry)
            .or_else(|| callee_func.blocks.first())?;
        let param_vid = entry_block.params.get(arg_index)?.0;
        let key = (callee, arg_index);
        if !seen_direct_call_args.insert(key) {
            return None;
        }

        let mut nested =
            TrustIrAdapter::new_with_types(self.structs, self.types, self.functions.clone());
        nested.module = self.module;
        nested.enums = self.enums;
        nested.trust_ir_func = Some(callee_func);
        let max_end = nested.infer_bounded_pointer_max_end_bytes(param_vid, seen_direct_call_args);
        seen_direct_call_args.remove(&key);
        max_end
    }

    /// Compute the end byte offset for a load/store-like access through a
    /// pointer derived from `alloca_result`.
    fn alloca_access_end_bytes(
        &self,
        alloca_result: ValueId,
        ptr: ValueId,
        ty: &Ty,
    ) -> Option<i128> {
        let offset =
            self.pointer_offset_from_alloca_bytes(ptr, alloca_result, &mut HashSet::new())?;
        if offset < 0 {
            return None;
        }
        let access_bytes = i128::from(self.translate_ty(ty).ok()?.bytes());
        offset.checked_add(access_bytes)
    }

    /// Resolve `ptr_vid` to a constant byte offset from `alloca_result`.
    fn pointer_offset_from_alloca_bytes(
        &self,
        ptr_vid: ValueId,
        alloca_result: ValueId,
        seen: &mut HashSet<ValueId>,
    ) -> Option<i128> {
        if ptr_vid == alloca_result {
            return Some(0);
        }
        if !seen.insert(ptr_vid) {
            return None;
        }

        let node = self.find_value_producer(ptr_vid)?;
        let offset = match &node.inst {
            Inst::Copy { operand, .. } => {
                self.pointer_offset_from_alloca_bytes(*operand, alloca_result, seen)
            }
            Inst::GEP {
                pointee_ty,
                base,
                indices,
                // Optimization hint only; offset-from-alloca analysis uses the
                // same conservative `base + index * elem_bytes` arithmetic
                // irrespective of `inbounds`. See the lowering site above.
                inbounds: _,
            } => match indices.as_slice() {
                [] => self.pointer_offset_from_alloca_bytes(*base, alloca_result, seen),
                [index] => {
                    let base_offset =
                        self.pointer_offset_from_alloca_bytes(*base, alloca_result, seen)?;
                    let idx = self.lookup_const_int(*index)?;
                    if idx < 0 {
                        None
                    } else {
                        let elem_bytes = i128::from(self.translate_ty(pointee_ty).ok()?.bytes());
                        base_offset.checked_add(i128::from(idx).checked_mul(elem_bytes)?)
                    }
                }
                _ => None,
            },
            _ => None,
        };

        seen.remove(&ptr_vid);
        offset
    }

    /// Integer bit width for the trust_ir scalar integer/pointer types used in
    /// count expressions.
    fn int_ty_bits(ty: &Ty) -> Option<u32> {
        match ty {
            Ty::Bool => Some(1),
            Ty::I8 | Ty::U8 => Some(8),
            Ty::I16 | Ty::U16 => Some(16),
            Ty::I32 | Ty::U32 => Some(32),
            Ty::I64 | Ty::U64 | Ty::Ptr => Some(64),
            Ty::I128 | Ty::U128 => Some(128),
            Ty::Isize | Ty::Usize => Some(64),
            Ty::Char => Some(32),
            Ty::Ref(_)
            | Ty::RefMut(_)
            | Ty::PtrConst(_)
            | Ty::PtrMut(_)
            | Ty::Rc(_)
            | Ty::Func(_) => Some(64),
            _ => None,
        }
    }

    fn truncate_to_bits(value: i128, bits: u32) -> i128 {
        if bits >= 128 {
            value
        } else if bits == 0 {
            0
        } else {
            let mask = (1u128 << bits) - 1;
            ((value as u128) & mask) as i128
        }
    }

    fn zero_extend_bits(value: i128, bits: u32) -> i128 {
        Self::truncate_to_bits(value, bits)
    }

    fn sign_extend_bits(value: i128, bits: u32) -> i128 {
        if bits >= 128 {
            value
        } else if bits == 0 {
            0
        } else {
            let truncated = Self::truncate_to_bits(value, bits) as u128;
            let sign_bit = 1u128 << (bits - 1);
            if truncated & sign_bit == 0 {
                truncated as i128
            } else {
                (truncated | !((1u128 << bits) - 1)) as i128
            }
        }
    }

    // -----------------------------------------------------------------------
    // Overflow-checked arithmetic (Inst::Overflow)
    // -----------------------------------------------------------------------

    /// Build the SIGNED i128 checked-multiply expansion:
    /// `result = a * b` (low 128 bits) and
    /// `flag = (b != 0 && result /s guarded_b != a) || (a == MIN && b == -1)`,
    /// where `guarded_b = (b == 0 || (a == MIN && b == -1)) ? 1 : b` avoids the
    /// __divti3 divide-by-zero AND MIN/-1 division-overflow UB. See
    /// translate_overflow for the correctness argument; every op is a proven
    /// primitive (Imul, i128 Iconst128/Icmp/Select/Sdiv, bool Band/Bor).
    fn build_i128_signed_mul_overflow(
        &mut self,
        a: Value,
        b: Value,
        result: Value,
        flag: Value,
    ) -> Vec<Instruction> {
        let mut instrs = Vec::new();
        let fresh_i128 = |this: &mut Self| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I128);
            v
        };
        let fresh_b1 = |this: &mut Self| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::B1);
            v
        };
        let icmp = |instrs: &mut Vec<Instruction>, cond, x, y, dst| {
            instrs.push(Instruction {
                opcode: Opcode::Icmp { cond },
                args: vec![x, y],
                results: vec![dst],
            });
        };
        let iconst128 = |instrs: &mut Vec<Instruction>, lo, hi, dst| {
            instrs.push(Instruction {
                opcode: Opcode::Iconst128 { lo, hi },
                args: vec![],
                results: vec![dst],
            });
        };
        let bool_op = |instrs: &mut Vec<Instruction>, opcode, x, y, dst| {
            instrs.push(Instruction {
                opcode,
                args: vec![x, y],
                results: vec![dst],
            });
        };

        // result = a *s b  (low 128 bits)
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![a, b],
            results: vec![result],
        });
        let zero = fresh_i128(self);
        iconst128(&mut instrs, 0, 0, zero);
        let one = fresh_i128(self);
        iconst128(&mut instrs, 1, 0, one);
        let min = fresh_i128(self);
        iconst128(&mut instrs, 0, i64::MIN, min); // i128::MIN = 0x8000..._0000...
        let neg1 = fresh_i128(self);
        iconst128(&mut instrs, -1, -1, neg1); // i128 -1

        let b_is_zero = fresh_b1(self);
        icmp(&mut instrs, IntCC::Equal, b, zero, b_is_zero);
        let a_is_min = fresh_b1(self);
        icmp(&mut instrs, IntCC::Equal, a, min, a_is_min);
        let b_is_neg1 = fresh_b1(self);
        icmp(&mut instrs, IntCC::Equal, b, neg1, b_is_neg1);
        // min_neg1 = (a == MIN) && (b == -1)  -- the division-overflow / smulo case
        let min_neg1 = fresh_b1(self);
        bool_op(&mut instrs, Opcode::Band, a_is_min, b_is_neg1, min_neg1);
        // avoid_div = (b == 0) || min_neg1
        let avoid_div = fresh_b1(self);
        bool_op(&mut instrs, Opcode::Bor, b_is_zero, min_neg1, avoid_div);
        // safe_b = avoid_div ? 1 : b
        let safe_b = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![avoid_div, one, b],
            results: vec![safe_b],
        });
        // q = result /s safe_b
        let q = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Sdiv,
            args: vec![result, safe_b],
            results: vec![q],
        });
        // div_ovf = (b != 0) && (q != a)
        let b_nz = fresh_b1(self);
        icmp(&mut instrs, IntCC::NotEqual, b, zero, b_nz);
        let q_ne_a = fresh_b1(self);
        icmp(&mut instrs, IntCC::NotEqual, q, a, q_ne_a);
        let div_ovf = fresh_b1(self);
        bool_op(&mut instrs, Opcode::Band, b_nz, q_ne_a, div_ovf);
        // flag = div_ovf || min_neg1
        bool_op(&mut instrs, Opcode::Bor, div_ovf, min_neg1, flag);
        instrs
    }

    /// Build the unsigned u128 checked-multiply expansion: `result = a * b`
    /// (low 128 bits) and `flag = (a != 0) && (result / max(a, 1) != b)`. See
    /// translate_overflow for the correctness argument; every op (Imul, i128
    /// Iconst128/Icmp/Select/Udiv, bool Band) is an already-proven primitive.
    fn build_u128_mul_overflow(
        &mut self,
        a: Value,
        b: Value,
        result: Value,
        flag: Value,
    ) -> Vec<Instruction> {
        let mut instrs = Vec::new();
        let fresh_i128 = |this: &mut Self| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I128);
            v
        };
        // result = a *u b  (low 128 bits)
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![a, b],
            results: vec![result],
        });
        let zero = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Iconst128 { lo: 0, hi: 0 },
            args: vec![],
            results: vec![zero],
        });
        let one = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Iconst128 { lo: 1, hi: 0 },
            args: vec![],
            results: vec![one],
        });
        // a_is_zero = (a == 0)
        let a_is_zero = self.fresh_value();
        self.define_value_type(a_is_zero, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp { cond: IntCC::Equal },
            args: vec![a, zero],
            results: vec![a_is_zero],
        });
        // safe_a = (a == 0) ? 1 : a   (avoid __udivti3 divide-by-zero UB)
        let safe_a = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![a_is_zero, one, a],
            results: vec![safe_a],
        });
        // q = result /u safe_a
        let q = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Udiv,
            args: vec![result, safe_a],
            results: vec![q],
        });
        // a_nz = (a != 0)
        let a_nz = self.fresh_value();
        self.define_value_type(a_nz, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp {
                cond: IntCC::NotEqual,
            },
            args: vec![a, zero],
            results: vec![a_nz],
        });
        // q_ne_b = (q != b)
        let q_ne_b = self.fresh_value();
        self.define_value_type(q_ne_b, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp {
                cond: IntCC::NotEqual,
            },
            args: vec![q, b],
            results: vec![q_ne_b],
        });
        // flag = a_nz && q_ne_b
        instrs.push(Instruction {
            opcode: Opcode::Band,
            args: vec![a_nz, q_ne_b],
            results: vec![flag],
        });
        instrs
    }

    /// Push `results = opcode args` with one fresh result of type `ty`.
    fn push_fresh(
        &mut self,
        instrs: &mut Vec<Instruction>,
        opcode: Opcode,
        args: Vec<Value>,
        ty: Type,
    ) -> Value {
        let result = self.fresh_value();
        self.define_value_type(result, ty);
        instrs.push(Instruction {
            opcode,
            args,
            results: vec![result],
        });
        result
    }

    /// The high 64-bit limb of the `I128` value `x`:
    /// `Trunc{I64}(Ushr(x, k64))`, with `k64` an `Iconst{I128, 64}`, spelled as
    /// `translate_i128_switch` spells it.
    fn push_i128_high_limb(
        &mut self,
        instrs: &mut Vec<Instruction>,
        x: Value,
        k64: Value,
    ) -> Value {
        let shifted = self.push_fresh(instrs, Opcode::Ushr, vec![x, k64], Type::I128);
        self.push_fresh(
            instrs,
            Opcode::Trunc { to_ty: Type::I64 },
            vec![shifted],
            Type::I64,
        )
    }

    /// The unsigned core of the division-free I128 checked multiply (OD-224):
    /// writes into the `B1` value `dst` whether the exact product `x * y` of
    /// two unsigned 128-bit values is at least `2^128`, given their 64-bit
    /// limbs `x = x1*2^64 + x0`, `y = y1*2^64 + y0` and `p1`, the high limb of
    /// `p = x * y mod 2^128`.
    ///
    /// LLVM's `ExpandIntRes_XMULO(UMULO)` limb check, with the carry read off
    /// `p`'s high limb:
    ///
    /// ```text
    /// m1, o1 = CheckedUmul x1, y0        lo(x1*y0), hi(x1*y0) != 0
    /// m2, o2 = CheckedUmul x0, y1        lo(x0*y1), hi(x0*y1) != 0
    /// t      = Iadd m1, m2               I64, wrapping
    /// c      = Icmp ult p1, t            the carry of hi(x0*y0) + t
    /// both   = (x1 != 0) & (y1 != 0)
    /// dst    = o1 | o2 | c | both
    /// ```
    ///
    /// Exact because `x*y = x1*y1*2^128 + (x1*y0 + x0*y1)*2^64 + x0*y0` is
    /// below `2^128` iff `x1*y1 = 0`, the one non-zero cross product fits 64
    /// bits, and `hi(x0*y0)` plus it does not carry. Once `both` is false one of
    /// `m1`/`m2` is 0, so `t` cannot wrap; `p1 = (hi(x0*y0) + t) mod 2^64`, so
    /// the add carried iff `p1 <u t`. Evidence: the design's exhaustive sweeps
    /// of the scaled analogs (8 bits with 4-bit limbs, 16 bits with 8-bit
    /// limbs; those widths only) and the adapter's own analog sweep in
    /// `adapter_i128_mulo_tests.rs`; at 128 bits L04-P10's obligations
    /// (`checked_mul_i128_proofs.rs`), whose class that module states.
    ///
    /// Emits 10 instructions: two `I64` `CheckedUmul`, `Iadd`, three `Icmp`,
    /// `Band`, three `Bor`. `z64` is an `Iconst{I64, 0}` the caller emitted.
    fn push_u128_mulo_core(
        &mut self,
        instrs: &mut Vec<Instruction>,
        [x0, x1]: [Value; 2],
        [y0, y1]: [Value; 2],
        p1: Value,
        z64: Value,
        dst: Value,
    ) {
        let mut checked_umul = |this: &mut Self, lhs: Value, rhs: Value| {
            let low = this.fresh_value();
            this.define_value_type(low, Type::I64);
            let overflow = this.fresh_value();
            this.define_value_type(overflow, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::CheckedUmul,
                args: vec![lhs, rhs],
                results: vec![low, overflow],
            });
            (low, overflow)
        };
        let (m1, o1) = checked_umul(self, x1, y0);
        let (m2, o2) = checked_umul(self, x0, y1);
        let t = self.push_fresh(instrs, Opcode::Iadd, vec![m1, m2], Type::I64);
        let carry = self.push_fresh(
            instrs,
            Opcode::Icmp {
                cond: IntCC::UnsignedLessThan,
            },
            vec![p1, t],
            Type::B1,
        );
        let not_equal = Opcode::Icmp {
            cond: IntCC::NotEqual,
        };
        let x1_nz = self.push_fresh(instrs, not_equal.clone(), vec![x1, z64], Type::B1);
        let y1_nz = self.push_fresh(instrs, not_equal, vec![y1, z64], Type::B1);
        let both = self.push_fresh(instrs, Opcode::Band, vec![x1_nz, y1_nz], Type::B1);
        let f1 = self.push_fresh(instrs, Opcode::Bor, vec![o1, o2], Type::B1);
        let f2 = self.push_fresh(instrs, Opcode::Bor, vec![f1, carry], Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![f2, both],
            results: vec![dst],
        });
    }

    /// The `Iconst{I128, 64}` and `Iconst{I64, 0}` the division-free checks read.
    fn push_mulo_constants(&mut self, instrs: &mut Vec<Instruction>) -> (Value, Value) {
        let k64 = self.push_fresh(
            instrs,
            Opcode::Iconst {
                ty: Type::I128,
                imm: 64,
            },
            vec![],
            Type::I128,
        );
        let z64 = self.push_fresh(
            instrs,
            Opcode::Iconst {
                ty: Type::I64,
                imm: 0,
            },
            vec![],
            Type::I64,
        );
        (k64, z64)
    }

    /// The two 64-bit limbs `[lo, hi]` of the `I128` value `x`.
    fn push_i128_limbs(
        &mut self,
        instrs: &mut Vec<Instruction>,
        x: Value,
        k64: Value,
    ) -> [Value; 2] {
        let lo = self.push_fresh(
            instrs,
            Opcode::Trunc { to_ty: Type::I64 },
            vec![x],
            Type::I64,
        );
        [lo, self.push_i128_high_limb(instrs, x, k64)]
    }

    /// The value of a 128-bit checked multiply's constant operand, when
    /// `vid` is a trust-ir constant (through copies): a non-negative
    /// `Constant::Int` or a `Constant::U128`. Anything else (a folded
    /// expression, a negative `Int`) is `None`, which keeps the general check.
    fn mulo_u128_constant(&self, vid: ValueId) -> Option<u128> {
        let mut vid = vid;
        let mut seen = HashSet::new();
        loop {
            if !seen.insert(vid) {
                return None;
            }
            match &self.find_value_producer(vid)?.inst {
                Inst::Const {
                    value: Constant::Int(raw),
                    ..
                } if *raw >= 0 => return Some(*raw as u128),
                Inst::Const {
                    value: Constant::U128(value),
                    ..
                } => return Some(*value),
                Inst::Copy { operand, .. } => vid = *operand,
                _ => return None,
            }
        }
    }

    /// The x86-64 unsigned u128 checked multiply (OD-224): `result = a * b`
    /// (`Imul`, the low 128 bits, as on every target) and `flag`, which is:
    ///
    /// * with a constant operand `C` (`constant = Some((x, C))`, `x` the other
    ///   operand): `x >u floor((2^128 - 1) / C)` (`2^128 - 1` for `C = 0`),
    ///   exact because `x * C < 2^128` iff `x <= floor((2^128 - 1) / C)`; the
    ///   division is the compiler's, at translation time. 3 instructions.
    /// * otherwise the unsigned core [`Self::push_u128_mulo_core`] of `(a, b)`
    ///   and the high limb of `result`. 21 instructions.
    ///
    /// Neither form divides at run time or calls a routine.
    fn build_u128_mul_overflow_divfree(
        &mut self,
        a: Value,
        b: Value,
        result: Value,
        flag: Value,
        constant: Option<(Value, u128)>,
    ) -> Vec<Instruction> {
        let mut instrs = Vec::new();
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![a, b],
            results: vec![result],
        });
        if let Some((x, c)) = constant {
            let limit = u128::MAX.checked_div(c).unwrap_or(u128::MAX);
            let k = self.push_fresh(
                &mut instrs,
                Opcode::Iconst128 {
                    lo: limit as u64 as i64,
                    hi: (limit >> 64) as u64 as i64,
                },
                vec![],
                Type::I128,
            );
            instrs.push(Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::UnsignedGreaterThan,
                },
                args: vec![x, k],
                results: vec![flag],
            });
            return instrs;
        }
        let (k64, z64) = self.push_mulo_constants(&mut instrs);
        let x = self.push_i128_limbs(&mut instrs, a, k64);
        let y = self.push_i128_limbs(&mut instrs, b, k64);
        let p1 = self.push_i128_high_limb(&mut instrs, result, k64);
        self.push_u128_mulo_core(&mut instrs, x, y, p1, z64, flag);
        instrs
    }

    /// `(x1 ^ m) - m - (((x0 | (0 - x0)) >> 63) & m)` with `m` all ones or 0
    /// (`[z64, k63]` an `Iconst{I64, 0}` and an `Iconst{I64, 63}`): the high
    /// limb of `m ? -x : x` for `x = x1*2^64 + x0`, as the limb arithmetic of a
    /// 128-bit negation (`-x = ~x + 1`: its high limb is `~x1` plus the carry
    /// of `~x0 + 1`, 1 iff `x0 == 0`). 7 instructions, every one an `I64` ALU
    /// operation; `0 - x0` is an `Isub` from zero, as the selector's 128-bit
    /// negation spells its low limb, not an `Ineg` (x86-64's `neg` row, which
    /// the body theorem spells apart from the source's `0 - x`).
    fn push_masked_negation_high(
        &mut self,
        instrs: &mut Vec<Instruction>,
        [x0, x1]: [Value; 2],
        m: Value,
        [z64, k63]: [Value; 2],
    ) -> Value {
        let neg0 = self.push_fresh(instrs, Opcode::Isub, vec![z64, x0], Type::I64);
        let either = self.push_fresh(instrs, Opcode::Bor, vec![x0, neg0], Type::I64);
        let nonzero = self.push_fresh(instrs, Opcode::Ushr, vec![either, k63], Type::I64);
        let borrow = self.push_fresh(instrs, Opcode::Band, vec![nonzero, m], Type::I64);
        let flipped = self.push_fresh(instrs, Opcode::Bxor, vec![x1, m], Type::I64);
        let plus = self.push_fresh(instrs, Opcode::Isub, vec![flipped, m], Type::I64);
        self.push_fresh(instrs, Opcode::Isub, vec![plus, borrow], Type::I64)
    }

    /// The limbs of `|x|` (as a u128; `|MIN| = 2^127` fits) for the signed
    /// `x = x1*2^64 + x0` whose sign mask is `m` (`x1 >>a 63`): the low limb
    /// `(x0 ^ m) - m`, the high limb [`Self::push_masked_negation_high`]. 9
    /// instructions, no select and no 128-bit operation.
    fn push_magnitude_limbs(
        &mut self,
        instrs: &mut Vec<Instruction>,
        x: [Value; 2],
        m: Value,
        constants: [Value; 2],
    ) -> [Value; 2] {
        let flipped = self.push_fresh(instrs, Opcode::Bxor, vec![x[0], m], Type::I64);
        let low = self.push_fresh(instrs, Opcode::Isub, vec![flipped, m], Type::I64);
        [low, self.push_masked_negation_high(instrs, x, m, constants)]
    }

    /// The x86-64 signed i128 checked multiply (OD-224): `result = a * b`
    /// (`Imul`, as on every target) and
    ///
    /// ```text
    /// ma, mb = a1 >>a 63, b1 >>a 63      sign masks (all ones iff negative)
    /// |a|, |b|                           limb by limb under the masks
    /// mn     = ma ^ mb                   all ones iff the product is negative
    /// pu1    = high limb of (mn ? -result : result)   = hi(|a| * |b| mod 2^128)
    /// ou     = core(|a|, |b|, pu1)       |a| * |b| >= 2^128
    /// bad    = ((r1 >>a 63) ^ mn) != 0 & (result != 0)
    /// flag   = ou | bad
    /// ```
    ///
    /// When `|a|*|b| < 2^128` the product is in range iff it is at most `2^127
    /// - 1 + neg`, which, since `result = ±|a|*|b| mod 2^128`, is "result is 0
    /// or its sign is the product's" (compiler-builtins' `__rust_i128_mulo`
    /// sign test; the `result != 0` conjunct replaces its early return on a
    /// zero operand, without which `0 * negative` would be flagged).
    ///
    /// The magnitudes are `I64` mask arithmetic (`sar`, `xor`, `sub`, `or`,
    /// `shr`, `and`), not a select of a 128-bit negation: x86-64 selects
    /// each as the one row of the same operation, so the body theorem spells
    /// the operands of the core's two `mul`s alike on both sides without
    /// OD-205's pairing (which a source stated path by path does not get).
    /// 58 instructions, no division and no runtime routine.
    fn build_i128_signed_mul_overflow_divfree(
        &mut self,
        a: Value,
        b: Value,
        result: Value,
        flag: Value,
    ) -> Vec<Instruction> {
        let mut instrs = Vec::new();
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![a, b],
            results: vec![result],
        });
        let (k64, z64) = self.push_mulo_constants(&mut instrs);
        let k63 = self.push_fresh(
            &mut instrs,
            Opcode::Iconst {
                ty: Type::I64,
                imm: 63,
            },
            vec![],
            Type::I64,
        );
        let a_limbs = self.push_i128_limbs(&mut instrs, a, k64);
        let b_limbs = self.push_i128_limbs(&mut instrs, b, k64);
        let r_limbs = self.push_i128_limbs(&mut instrs, result, k64);
        let ma = self.push_fresh(&mut instrs, Opcode::Sshr, vec![a_limbs[1], k63], Type::I64);
        let mb = self.push_fresh(&mut instrs, Opcode::Sshr, vec![b_limbs[1], k63], Type::I64);
        let ua = self.push_magnitude_limbs(&mut instrs, a_limbs, ma, [z64, k63]);
        let ub = self.push_magnitude_limbs(&mut instrs, b_limbs, mb, [z64, k63]);
        let mn = self.push_fresh(&mut instrs, Opcode::Bxor, vec![ma, mb], Type::I64);
        let pu1 = self.push_masked_negation_high(&mut instrs, r_limbs, mn, [z64, k63]);
        let ou = self.fresh_value();
        self.define_value_type(ou, Type::B1);
        self.push_u128_mulo_core(&mut instrs, ua, ub, pu1, z64, ou);
        let not_equal = Opcode::Icmp {
            cond: IntCC::NotEqual,
        };
        let r_sign = self.push_fresh(&mut instrs, Opcode::Sshr, vec![r_limbs[1], k63], Type::I64);
        let mismatch = self.push_fresh(&mut instrs, Opcode::Bxor, vec![r_sign, mn], Type::I64);
        let sign = self.push_fresh(
            &mut instrs,
            not_equal.clone(),
            vec![mismatch, z64],
            Type::B1,
        );
        let either = self.push_fresh(
            &mut instrs,
            Opcode::Bor,
            vec![r_limbs[0], r_limbs[1]],
            Type::I64,
        );
        let r_nz = self.push_fresh(&mut instrs, not_equal, vec![either, z64], Type::B1);
        let bad = self.push_fresh(&mut instrs, Opcode::Band, vec![sign, r_nz], Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![ou, bad],
            results: vec![flag],
        });
        instrs
    }

    /// Translate `Inst::Overflow { op, ty, lhs, rhs }` to a value +
    /// overflow-flag pair. The previous implementation hardcoded the flag to
    /// `Iconst B1 imm=0`, silently dropping every TLA+ runtime overflow check
    /// (issue #339). We now emit the actual overflow condition for signed
    /// integer arithmetic.
    ///
    /// Supported widths: I8, I16, I32, I64 and I128.
    ///
    /// Semantics (produce true iff overflow occurred):
    /// - Add: `overflow = (~(lhs ^ rhs) & (lhs ^ sum)) < 0`  (sign bit set)
    /// - Sub: `overflow = ((lhs ^ rhs) & (lhs ^ diff)) < 0`
    /// - Mul (narrow <=32-bit): sign-extend both operands to the next-wider
    ///   type, multiply there, and check that the wide product equals the
    ///   sign-extension of the narrow product.
    /// - I64 operations emit the corresponding Checked{S,U}{add,sub,mul}
    ///   opcode for target-specific selection. Multiply overflow uses the high
    ///   product, not division, so a zero multiplier never introduces a trap.
    /// - I128 multiply: the value is `Imul` (low 128 bits). The flag is the
    ///   division-free limb check on x86-64 (OD-224) and the guarded division
    ///   of the low product on every other target (see the I128 branch below).
    fn translate_overflow(
        &mut self,
        op: &OverflowOp,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
        results: &[ValueId],
        node: &InstrNode,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !Self::is_integer_scalar_ty(ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Overflow requires a TrustIr arithmetic integer type, got {ty:?}"
            )));
        }
        let lir_ty = self.translate_ty(ty)?;
        // i128/u128 checked MUL is decided from the low 128-bit product and
        // 64-bit limb products (the I128 branch below), never from a 256-bit
        // product. Checked ADD/SUB decompose into the width-generic bit-pattern
        // fallback below over i128 primitives — Iadd/Isub (register pair), i128
        // Icmp, and i128 Bxor/Bnot/Band (register-pair logic) — none of which
        // need a wider type, as for the I8/I16/I32 fallback at width 128.
        if !matches!(
            lir_ty,
            Type::I8 | Type::I16 | Type::I32 | Type::I64 | Type::I128
        ) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Overflow on non-integer type {:?}",
                ty
            )));
        }

        let lhs_val = self.map_value(lhs);
        let rhs_val = self.map_value(rhs);
        let result = self.map_result(results)?;
        let flag_vid = results.get(1).copied().ok_or(AdapterError::MissingResult)?;
        let flag = self.map_value(flag_vid);

        // usize and Char are unsigned (pointer-width / 32-bit Unicode-scalar
        // carriers); isize is signed. Getting this wrong flips the overflow
        // condition for the very common `usize` checked-add idiom.
        let is_unsigned = matches!(
            ty,
            Ty::U8 | Ty::U16 | Ty::U32 | Ty::U64 | Ty::U128 | Ty::Usize | Ty::Char
        );

        // i128/u128 checked MUL. The value is `Imul a, b` (the low 128 bits) on
        // every target; only the flag's expansion is chosen per target.
        //
        // * x86-64 (OD-224): the division-free limb check
        //   (`build_u128_mul_overflow_divfree`, LLVM's `ExpandIntRes_XMULO`
        //   UMULO form; the signed check runs it on the magnitudes, computed as
        //   `I64` mask arithmetic, and adds a sign check), and for an unsigned
        //   multiply by a constant `C` the compare of the other operand with
        //   `floor((2^128 - 1) / C)`. It needs no runtime routine.
        // * every other target (AArch64 today; RISC-V refuses I128 in its
        //   selector): the division check on the LOW 128-bit product, kept byte
        //   for byte. UNSIGNED: overflow iff `a != 0 && p/a != b` (with no
        //   overflow `p = a*b` so `p/a == b`; with overflow `p = a*b - k*2^128`,
        //   k>=1, and `a < 2^128` forces `floor(p/a) <= b-1 < b`). SIGNED:
        //   overflow iff `(b != 0 && p /s b != a) || (a == MIN && b == -1)`
        //   (same magnitude argument — `|k*2^128/b| >= 1` forces `p/s b != a` —
        //   plus the one division-overflow case). Both divide by a guarded
        //   operand to avoid the __udivti3/__divti3 divide-by-zero (and MIN/-1
        //   division-overflow) UB.
        //
        // The target is the adapter's ISA (`guard_carrier_arch`, which the
        // compile driver sets from the compile target); its default is AArch64,
        // so a caller that names no target keeps the division form.
        if lir_ty == Type::I128 && matches!(op, OverflowOp::MulOverflow) {
            let division_free = self.guard_carrier_arch == GuardCarrierArch::X86_64
                && !X86_I128_MULO_DIVISION_FORM.with(std::cell::Cell::get);
            // The unsigned check of a constant operand compares the other
            // operand with the constant's limit (`build_u128_mul_overflow_divfree`).
            let constant = || {
                self.mulo_u128_constant(rhs)
                    .map(|c| (lhs_val, c))
                    .or_else(|| self.mulo_u128_constant(lhs).map(|c| (rhs_val, c)))
            };
            return Ok(match (division_free, is_unsigned) {
                (true, true) => {
                    let constant = constant();
                    self.build_u128_mul_overflow_divfree(lhs_val, rhs_val, result, flag, constant)
                }
                (true, false) => {
                    self.build_i128_signed_mul_overflow_divfree(lhs_val, rhs_val, result, flag)
                }
                (false, true) => self.build_u128_mul_overflow(lhs_val, rhs_val, result, flag),
                (false, false) => {
                    self.build_i128_signed_mul_overflow(lhs_val, rhs_val, result, flag)
                }
            });
        }

        // ---------------------------------------------------------------------
        // Overflow-elimination production fast-exit (#29).
        //
        // Real Trust programs express checked add/sub via this `Inst::Overflow`
        // idiom. The legacy lowering below ALWAYS materializes a runtime overflow
        // CHECK (CheckedSadd/CSET for I64, bit-pattern for I8/16/32) entangled
        // with the value, so overflow elimination can never fire even when the
        // node carries a DISCHARGED no-overflow proof. When (and ONLY when) such
        // a proof is present, route the check through the self-contained
        // `GuardOverflow` carrier the kernel gate can eliminate, while keeping
        // the (value, did_overflow) contract: the value is a plain wrapping
        // Iadd/Isub and the flag is provably-false (the proof guarantees no
        // overflow, so the observable overflow boolean is definitively `false`).
        //
        // FAIL-SAFE / DEFAULT-TO-KEEP: this is a STRICT extension. The branch is
        // taken ONLY when EVERY one of these holds; on ANY failure we fall
        // through to the unchanged legacy lowering, which always traps/flags on a
        // genuine overflow (safe):
        //   (a) target == AArch64 — the ONLY arch with an overflow carrier
        //       (TrapOverflowExact). x86/RISC-V have none, so they MUST keep the
        //       legacy path (a GuardOverflow there would be unrepresentable).
        //   (b) op has a carrier op-tag: Add/Sub at width 32|64, or Mul at width
        //       64 ONLY (task #30; SMULH/UMULH are 64-bit-result-only, so I32 mul
        //       stays on the legacy wide-multiply bit-pattern path).
        //   (c) width is 32 or 64 — the only widths `pack_overflow_tag` accepts.
        //       I8/I16 have no carrier op-tag and stay on the legacy bit-pattern
        //       path. (lir_ty is already restricted to I8/I16/I32/I64 above.)
        //   (d) the node carries a genuine, signedness-MATCHING discharged
        //       no-overflow annotation (`NoOverflow` for signed, `NoWrap` for
        //       unsigned). `Wrapping` is NEVER treated as no-overflow.
        let carrier_width: Option<u16> = match lir_ty {
            Type::I32 => Some(32),
            Type::I64 => Some(64),
            _ => None,
        };
        let carrier_op = match (is_unsigned, op) {
            (false, OverflowOp::AddOverflow) => Some(trust_cg_ir::OverflowOp::SignedAdd),
            (false, OverflowOp::SubOverflow) => Some(trust_cg_ir::OverflowOp::SignedSub),
            (true, OverflowOp::AddOverflow) => Some(trust_cg_ir::OverflowOp::UnsignedAdd),
            (true, OverflowOp::SubOverflow) => Some(trust_cg_ir::OverflowOp::UnsignedSub),
            // Mul has a carrier (task #30) but ONLY at width 64: the KEPT expansion uses the
            // SMULH/UMULH mul-high idiom, and SMULH/UMULH are 64-bit-result-only (no 32-bit
            // variant). I32 (and narrower) mul therefore has NO correct SMULH-based expansion and
            // MUST stay on the legacy division-free wide-multiply bit-pattern path. Gating mul to
            // I64 here keeps `carrier_width`'s I32 => Some(32) from ever packing a width-32 mul tag.
            (false, OverflowOp::MulOverflow) if lir_ty == Type::I64 => {
                Some(trust_cg_ir::OverflowOp::SignedMul)
            }
            (true, OverflowOp::MulOverflow) if lir_ty == Type::I64 => {
                Some(trust_cg_ir::OverflowOp::UnsignedMul)
            }
            // Mul at any non-I64 width — keep legacy (no 32-bit SMULH/UMULH).
            (_, OverflowOp::MulOverflow) => None,
        };
        // The observable overflow flag (result[1]) is DEAD iff nothing in the
        // function consumes it. The carrier path folds the flag to constant-false
        // (sound under the discharged proof), but we ONLY take it when the flag is
        // dead so that any node whose overflow boolean is genuinely consumed keeps
        // the legacy entangled ADDS/SUBS+CSET lowering byte-for-byte (DEFAULT TO
        // KEEP). If the function context is unavailable (defensive), treat the flag
        // as live and keep legacy.
        let flag_is_dead = self
            .trust_ir_func
            .is_some_and(|f| !value_is_used_in_func(f, flag_vid));
        if flag_is_dead
            && self.guard_carrier_arch == GuardCarrierArch::AArch64
            && let (Some(width), Some(carrier_op)) = (carrier_width, carrier_op)
            && overflow_has_no_overflow_proof(node, is_unsigned)
            // Replacing an observable checked-overflow operation with a wrapping value plus a
            // proof-driven carrier is behavior-changing when the annotation is forged.  Keep the
            // legacy lowering until an exact validator replay capability is wired end to end.
            && (crate::guard_evidence::validator_guard_replay_authority_available() || cfg!(test))
        {
            let op_tag = trust_cg_ir::pack_overflow_tag(carrier_op, width);
            // Copy an explicit ProofRef only.  A NoOverflow/NoWrap label never synthesizes a
            // discharged obligation.
            //
            // Attach a QF_BV `ProofFormula` to the obligation. HONEST STATUS (downgraded
            // 2026-06-18): this is a REFLEXIVITY TAUTOLOGY `(not (= (bvop a b) (bvop a b)))`,
            // NOT a lowering-correctness identity — it is built from the IR op-tag only and
            // never references the machine instructions, so it cannot catch a lowering error
            // (see `overflow_carrier_reflexivity_formula`). The clean C1 path re-derives it to
            // `trust_count == 0`, but that count certifies a tautology and is VACUOUS as a
            // statement about lowering correctness. The `clean_cic_lineage_digest` derived from
            // it discriminates the (op,width) LABEL only, and no consumer gates on it.
            let was_synthesized_before = self.proof_ctx.synthesized_discharged.len();
            let obligation = self.overflow_no_overflow_obligation(node);
            if let Some(obligation_id) = obligation {
                // Record the formula only for ids the adapter SYNTHESIZED here (an upstream
                // ProofRef already owns a module obligation, with its own formula slot).
                let just_synthesized = self.proof_ctx.synthesized_discharged.len()
                    > was_synthesized_before
                    && self.proof_ctx.synthesized_discharged.last().copied() == Some(obligation_id);
                if just_synthesized {
                    let formula =
                        ProofContext::overflow_carrier_reflexivity_formula(carrier_op, width);
                    self.proof_ctx
                        .record_synthesized_obligation_formula(obligation_id, formula);
                }
            }

            // Seed the OPERAND value-proofs that the codegen proof-annotation binder
            // (`apply_guard_proof_annotations`) consumes: it stamps
            // `NoSignedOverflow`/`NoUnsignedOverflow` onto the `TrapOverflowExact` carrier ONLY when a
            // carrier-binding no-overflow proof is keyed to the carrier's lhs OR rhs vreg AND the
            // op-tag signedness matches. The trust-ir `NoOverflow`/`NoWrap` annotation lands on
            // result[0] (the sum), not the operands, so without this the binder never matches THIS
            // carrier and the kernel gate keeps it.
            //
            // NO OVER-ELIMINATION: we seed `Proof::CarrierNoOverflow` (NOT `Proof::NoOverflow`). The
            // carrier-only variant is EXCLUDED from the general value-proof loop
            // (`select_proof_annotation`), so it can NEVER be stamped onto an operand's *defining*
            // instruction — in particular it can never reach the legacy `apply_no_overflow`
            // ADDS/SUBS→ADD/SUB syntactic eliminator and delete an UNRELATED operation's overflow
            // check (e.g. the inner panic-add of `(a + b).overflowing_add(c)`). A genuine on-op
            // `Proof::NoOverflow` (keyed to the arithmetic op's own result) stays eligible for that
            // loop, so legacy overflow elimination is preserved exactly.
            //
            // SOUNDNESS: the seeded proof's `signed` flag is the SAME signedness folded into `op_tag`
            // (signed for a signed op, unsigned for an unsigned op), so a signed proof can never bind
            // an unsigned carrier and vice versa; and it is only seeded inside this branch, i.e. ONLY
            // when a genuine signedness-matching discharged no-overflow annotation is present on the
            // node. The carrier's AUTHORIZATION to be deleted is bound SEPARATELY by the op's
            // `obligation` field via ISel `guard_obligations` + the kernel gate; this seed only drives
            // candidate SELECTION (annotating the carrier), never authorization.
            let proof_signed = !is_unsigned;
            for operand in [lhs_val, rhs_val] {
                self.proof_ctx
                    .value_proofs
                    .entry(operand)
                    .or_default()
                    .push(Proof::CarrierNoOverflow {
                        signed: proof_signed,
                    });
            }

            let value_opcode = match op {
                OverflowOp::AddOverflow => Opcode::Iadd,
                OverflowOp::SubOverflow => Opcode::Isub,
                // Mul carrier (task #30): the value is a plain wrapping Imul (low 64 bits), the
                // same low product the MUL in the carrier's KEPT mul-high expansion computes. Only
                // reachable when carrier_op admitted a width-64 mul above.
                OverflowOp::MulOverflow => Opcode::Imul,
            };

            return Ok(vec![
                // 1. Plain wrapping value op into result[0] — NEVER touched by
                //    carrier elimination; identical wrap semantics to the legacy
                //    arithmetic op.
                Instruction {
                    opcode: value_opcode,
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                },
                // 2. The OVERFLOW check, decoupled into a self-contained carrier
                //    (no results). The kernel gate eliminates it iff the bound
                //    obligation is discharged; otherwise it expands to a trapping
                //    ADDS/SUBS+B.VC/B.VS+BRK that re-derives the overflow.
                Instruction {
                    opcode: Opcode::GuardOverflow { op_tag, obligation },
                    args: vec![lhs_val, rhs_val],
                    results: vec![],
                },
                // 3. The observable overflow flag (result[1], Ty::Bool -> B1).
                //    Under a DISCHARGED no-overflow proof the op provably never
                //    overflows, so the flag is definitively `false`. Binding it to
                //    a constant `0` preserves the (value, did_overflow=false)
                //    contract for any downstream flag consumer.
                Instruction {
                    opcode: Opcode::Iconst {
                        ty: Type::B1,
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![flag],
                },
            ]);
        }

        // Fast path (#474): I64/U64 overflow maps directly to a single
        // Checked{S,U}{add,sub,mul} LIR op that ISel lowers to the canonical
        // AArch64 idiom:
        //   sadd -> ADDS + CSET VS
        //   ssub -> SUBS + CSET VS
        //   smul -> MUL + SMULH + ASR + CMP + CSET NE
        //   uadd -> ADDS + CSET HS
        //   usub -> SUBS + CSET LO
        //   umul -> MUL + UMULH + CMP #0 + CSET NE
        // The bit-pattern fallback below is retained for I8/I16/I32 (which
        // the existing ISel patterns do not yet recognise for the native
        // flag idiom).
        if lir_ty == Type::I64 {
            let checked_opcode = match (is_unsigned, *op) {
                (false, OverflowOp::AddOverflow) => Opcode::CheckedSadd,
                (false, OverflowOp::SubOverflow) => Opcode::CheckedSsub,
                (false, OverflowOp::MulOverflow) => Opcode::CheckedSmul,
                (true, OverflowOp::AddOverflow) => Opcode::CheckedUadd,
                (true, OverflowOp::SubOverflow) => Opcode::CheckedUsub,
                (true, OverflowOp::MulOverflow) => Opcode::CheckedUmul,
            };
            return Ok(vec![Instruction {
                opcode: checked_opcode,
                args: vec![lhs_val, rhs_val],
                results: vec![result, flag],
            }]);
        }

        let mut instrs = Vec::new();
        let arith_opcode = match op {
            OverflowOp::AddOverflow => Opcode::Iadd,
            OverflowOp::SubOverflow => Opcode::Isub,
            OverflowOp::MulOverflow => Opcode::Imul,
        };

        // 1. Emit the value result (wrapping arithmetic).
        instrs.push(Instruction {
            opcode: arith_opcode,
            args: vec![lhs_val, rhs_val],
            results: vec![result],
        });

        if is_unsigned {
            match op {
                OverflowOp::AddOverflow => {
                    // Unsigned add overflows iff the wrapped result is below
                    // either operand. Compare against lhs.
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp {
                            cond: IntCC::UnsignedLessThan,
                        },
                        args: vec![result, lhs_val],
                        results: vec![flag],
                    });
                }
                OverflowOp::SubOverflow => {
                    // Unsigned sub overflows iff it borrows, i.e. lhs < rhs.
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp {
                            cond: IntCC::UnsignedLessThan,
                        },
                        args: vec![lhs_val, rhs_val],
                        results: vec![flag],
                    });
                }
                OverflowOp::MulOverflow => {
                    let wide_ty = match &lir_ty {
                        Type::I8 => Type::I16,
                        Type::I16 => Type::I32,
                        Type::I32 => Type::I64,
                        _ => unreachable!("unsigned overflow fallback is only used below U64"),
                    };

                    let lhs_wide = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Uextend {
                            from_ty: lir_ty.clone(),
                            to_ty: wide_ty.clone(),
                        },
                        args: vec![lhs_val],
                        results: vec![lhs_wide],
                    });
                    let rhs_wide = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Uextend {
                            from_ty: lir_ty.clone(),
                            to_ty: wide_ty.clone(),
                        },
                        args: vec![rhs_val],
                        results: vec![rhs_wide],
                    });
                    let product_wide = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Imul,
                        args: vec![lhs_wide, rhs_wide],
                        results: vec![product_wide],
                    });
                    let product_trunc = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Trunc {
                            to_ty: lir_ty.clone(),
                        },
                        args: vec![product_wide],
                        results: vec![product_trunc],
                    });
                    let product_roundtrip = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Uextend {
                            from_ty: lir_ty.clone(),
                            to_ty: wide_ty,
                        },
                        args: vec![product_trunc],
                        results: vec![product_roundtrip],
                    });
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp {
                            cond: IntCC::NotEqual,
                        },
                        args: vec![product_wide, product_roundtrip],
                        results: vec![flag],
                    });
                }
            }

            return Ok(instrs);
        }

        // 2. Emit the overflow flag using op-specific bit-pattern checks.
        match op {
            OverflowOp::AddOverflow => {
                // tmp1 = lhs XOR rhs
                let tmp1 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, rhs_val],
                    results: vec![tmp1],
                });
                // tmp2 = NOT tmp1
                let tmp2 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bnot,
                    args: vec![tmp1],
                    results: vec![tmp2],
                });
                // tmp3 = lhs XOR sum
                let tmp3 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, result],
                    results: vec![tmp3],
                });
                // tmp4 = tmp2 AND tmp3  (sign bit set iff overflow)
                let tmp4 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Band,
                    args: vec![tmp2, tmp3],
                    results: vec![tmp4],
                });
                // flag = Icmp Slt(tmp4, 0)  — produces B1
                let zero = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Iconst {
                        ty: lir_ty.clone(),
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![zero],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Icmp {
                        cond: IntCC::SignedLessThan,
                    },
                    args: vec![tmp4, zero],
                    results: vec![flag],
                });
            }
            OverflowOp::SubOverflow => {
                // tmp1 = lhs XOR rhs
                let tmp1 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, rhs_val],
                    results: vec![tmp1],
                });
                // tmp2 = lhs XOR diff
                let tmp2 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, result],
                    results: vec![tmp2],
                });
                // tmp3 = tmp1 AND tmp2  (sign bit set iff overflow)
                let tmp3 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Band,
                    args: vec![tmp1, tmp2],
                    results: vec![tmp3],
                });
                // flag = Icmp Slt(tmp3, 0)
                let zero = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Iconst {
                        ty: lir_ty.clone(),
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![zero],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Icmp {
                        cond: IntCC::SignedLessThan,
                    },
                    args: vec![tmp3, zero],
                    results: vec![flag],
                });
            }
            OverflowOp::MulOverflow => {
                // DIVISION-FREE signed multiply-overflow, mirroring the unsigned
                // wide-multiply check above with SIGN extension: sign-extend both
                // operands to the next-wider type, multiply there, truncate to the
                // narrow type and sign-extend back; overflow iff the wide product
                // differs from that round-trip.
                //
                // The previous check used the SDIV identity (`result / rhs != lhs`)
                // and relied on AArch64 SDIV-by-zero returning 0. On x86-64 IDIV
                // by zero TRAPS (#DE -> SIGFPE), so `x.overflowing_mul(0)` /
                // `x.checked_mul(0)` crashed instead of reporting no overflow
                // (MISCOMPILE #67). The wide-multiply check never divides and is
                // correct for every operand, including 0 and INT_MIN * -1 (I64 is
                // handled by the native CheckedSmul idiom above; I8/I16/I32 always
                // have a strictly-wider type to multiply in).
                let wide_ty = match &lir_ty {
                    Type::I8 => Type::I16,
                    Type::I16 => Type::I32,
                    Type::I32 => Type::I64,
                    _ => unreachable!("signed overflow mul fallback is only used below I64"),
                };
                let lhs_wide = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Sextend {
                        from_ty: lir_ty.clone(),
                        to_ty: wide_ty.clone(),
                    },
                    args: vec![lhs_val],
                    results: vec![lhs_wide],
                });
                let rhs_wide = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Sextend {
                        from_ty: lir_ty.clone(),
                        to_ty: wide_ty.clone(),
                    },
                    args: vec![rhs_val],
                    results: vec![rhs_wide],
                });
                let product_wide = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Imul,
                    args: vec![lhs_wide, rhs_wide],
                    results: vec![product_wide],
                });
                let product_trunc = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Trunc {
                        to_ty: lir_ty.clone(),
                    },
                    args: vec![product_wide],
                    results: vec![product_trunc],
                });
                let product_roundtrip = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Sextend {
                        from_ty: lir_ty.clone(),
                        to_ty: wide_ty,
                    },
                    args: vec![product_trunc],
                    results: vec![product_roundtrip],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Icmp {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![product_wide, product_roundtrip],
                    results: vec![flag],
                });
            }
        }

        Ok(instrs)
    }

    // -----------------------------------------------------------------------
    // Control flow
    // -----------------------------------------------------------------------

    fn translate_br(
        &mut self,
        target: &BlockId,
        args: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let mut instrs = Vec::new();

        // Emit copies for block arguments -> block parameters.
        instrs.extend(self.resolve_block_args(*target, args)?);

        let dest = self.map_block(*target);
        instrs.push(Instruction {
            opcode: Opcode::Jump { dest },
            args: vec![],
            results: vec![],
        });

        Ok(instrs)
    }

    fn translate_condbr(
        &mut self,
        cond: &ValueId,
        then_target: &BlockId,
        then_args: &[ValueId],
        else_target: &BlockId,
        else_args: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let mut instrs = Vec::new();
        let cond_val = self.map_value(*cond);

        // When block arguments are present, copies must only execute on the
        // correct control-flow edge. We create intermediate "copy blocks"
        // that perform the copies and then jump to the real target.
        //
        // BUG FIX (issue #302): Previously, copies for BOTH branches were
        // emitted unconditionally before the Brif. When different values
        // are passed to the same block parameter via different edges, the
        // last copy always wins — producing wrong code.

        let then_copies = self.resolve_block_args(*then_target, then_args)?;
        let else_copies = self.resolve_block_args(*else_target, else_args)?;

        let then_dest = if !then_copies.is_empty() {
            // Create an intermediate block for then-branch copies.
            let copy_block_id = self.fresh_block();
            let real_then_dest = self.map_block(*then_target);
            let mut copy_bb = BasicBlock {
                instructions: then_copies,
                ..Default::default()
            };
            copy_bb.instructions.push(Instruction {
                opcode: Opcode::Jump {
                    dest: real_then_dest,
                },
                args: vec![],
                results: vec![],
            });
            self.pending_extra_blocks.push((copy_block_id, copy_bb));
            copy_block_id
        } else {
            self.map_block(*then_target)
        };

        let else_dest = if !else_copies.is_empty() {
            // Create an intermediate block for else-branch copies.
            let copy_block_id = self.fresh_block();
            let real_else_dest = self.map_block(*else_target);
            let mut copy_bb = BasicBlock {
                instructions: else_copies,
                ..Default::default()
            };
            copy_bb.instructions.push(Instruction {
                opcode: Opcode::Jump {
                    dest: real_else_dest,
                },
                args: vec![],
                results: vec![],
            });
            self.pending_extra_blocks.push((copy_block_id, copy_bb));
            copy_block_id
        } else {
            self.map_block(*else_target)
        };

        instrs.push(Instruction {
            opcode: Opcode::Brif {
                cond: cond_val,
                then_dest,
                else_dest,
            },
            args: vec![cond_val],
            results: vec![],
        });

        Ok(instrs)
    }

    /// A value of unit `()` or never `!` type is zero-sized: it occupies no ABI
    /// slot and is dropped from argument/return lists.
    fn is_zero_sized_value(&self, v: ValueId) -> bool {
        matches!(self.lookup_value_ty(v), Some(Ty::Unit) | Some(Ty::Never))
    }

    /// A direct, sole-use C call result already carries the narrow Darwin
    /// return extension. Do not insert a second extension between that call
    /// and its immediate return: the existing machine tail-call pass can then
    /// judge the unchanged call/frame/liveness facts.
    fn forwards_extended_darwin_c_result(&self, value: ValueId, ret_ty: &Ty) -> bool {
        use crate::abi::AArch64AbiVariant;
        if self.guard_carrier_arch != GuardCarrierArch::AArch64
            || self.tls_dialect.aarch64_abi_variant() != Some(AArch64AbiVariant::Darwin)
            || !matches!(ret_ty, Ty::I8 | Ty::I16)
            || self.current_return_tys.as_slice() != std::slice::from_ref(ret_ty)
            || self.value_use_counts.get(&value) != Some(&1)
        {
            return false;
        }
        let (Some(module), Some(caller), Some(producer)) = (
            self.module,
            self.trust_ir_func,
            self.value_producers.get(&value),
        ) else {
            return false;
        };
        if caller.calling_conv != CallingConv::C || caller.attrs.naked {
            return false;
        }
        let Some(target) = &module.target_info else {
            return false;
        };
        if AArch64AbiVariant::from_target_triple(&target.triple).ok()
            != Some(AArch64AbiVariant::Darwin)
            || target.pointer_size != 8
            || target.endianness != trust_ir::Endianness::Little
        {
            return false;
        }
        let Inst::Call { callee, .. } = &producer.inst else {
            return false;
        };
        if producer.results.as_slice() != [value] {
            return false;
        }
        let Some(function) = self.functions.unique(module, *callee) else {
            return false;
        };
        let Some(signature) = self.lookup_callee_func_ty(*callee) else {
            return false;
        };
        if function.is_declaration()
            || function.calling_conv != CallingConv::C
            || function.attrs.naked
            || !matches!(
                function.linkage,
                Linkage::External | Linkage::Internal | Linkage::Private
            )
            || self.definition_is_preemptible(function.linkage, function.visibility)
            || signature.is_vararg
            || signature.abi.is_some()
            || signature.returns.as_slice() != std::slice::from_ref(ret_ty)
            || !matches!(self.lookup_callee_sret_param(*callee), Ok(None))
        {
            return false;
        }
        let name = self.functions.name(*callee).unwrap_or(&function.name);
        if !matches!(
            classify_direct_call(name, function, signature),
            Ok(NamedCallSemantics::Ordinary)
        ) {
            return false;
        }
        // Require exactly one definition and an adjacent Call/Return in the
        // source block. An indirect call, another use, intervening cleanup or
        // cross-block forwarding keeps the ordinary extension and call.
        let definitions = caller
            .blocks
            .iter()
            .flat_map(|b| &b.body)
            .filter(|node| node.results.contains(&value))
            .count();
        definitions == 1
            && caller.blocks.iter().any(|block| {
                let [.., call, ret] = block.body.as_slice() else {
                    return false;
                };
                std::ptr::eq(call, *producer)
                    && matches!(&ret.inst, Inst::Return { values } if values.as_slice() == [value])
            })
    }

    fn translate_return(&mut self, values: &[ValueId]) -> Result<Vec<Instruction>, AdapterError> {
        self.validate_return_signature(values)?;
        if let Some(buffer) = self.sequence_result_buffer {
            let [value] = values else {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{SEQUENCE_DIAGNOSTIC} a collection-returning function must return exactly \
                     one value, got {}",
                    values.len()
                )));
            };
            return self.translate_sequence_return(buffer, *value);
        }
        // Drop zero-sized (unit/never) return values: a `ret ()` is a void return
        // matching the unit-filtered signature (see translate_signature).
        let values: Vec<ValueId> = values
            .iter()
            .copied()
            .filter(|v| !self.is_zero_sized_value(*v))
            .collect();
        let values = values.as_slice();

        // Apple arm64 ABI: the CALLEE must extend a narrow integer return value
        // (i8/i16/u8/u16) to 32 bits — sign-extend for signed types (SXTB/SXTH),
        // zero-extend for unsigned (UXTB/UXTH) — so an LLVM-compiled caller reads
        // the canonical value. (Standard AAPCS64 makes the caller narrow; Apple
        // diverges.) trust-ir carries the signedness here via the return `Ty`
        // (Ty::I8 vs Ty::U8); it is gone once lowered to the machine `Type`, so
        // materialize the extension now. See e2e_aarch64_narrow_int_diff.rs.
        let return_tys = self.current_return_tys.clone();
        let mut instrs = Vec::new();
        let mut args: Vec<Value> = Vec::with_capacity(values.len());
        for (index, (vid, ret_ty)) in values.iter().zip(return_tys.iter()).enumerate() {
            self.refuse_bool_mask_carrier_mismatch(*vid, ret_ty, format!("Return value {index}"))?;
            let mapped = self.map_value(*vid);
            let ext = self.repr_ty(ret_ty)?.narrow_extension();
            match ext {
                Some(_) if self.forwards_extended_darwin_c_result(*vid, ret_ty) => {
                    // This sole use observes the callee's already extended
                    // physical ABI word. Keeping an i8/i16 carrier would hide
                    // that fact from the tail pass's width-preservation guard.
                    self.define_value_type(mapped, Type::I32);
                    args.push(mapped);
                }
                Some((from_ty, signed)) => {
                    let widened = self.fresh_value();
                    self.define_value_type(widened, Type::I32);
                    let opcode = if signed {
                        Opcode::Sextend {
                            from_ty,
                            to_ty: Type::I32,
                        }
                    } else {
                        Opcode::Uextend {
                            from_ty,
                            to_ty: Type::I32,
                        }
                    };
                    instrs.push(Instruction {
                        opcode,
                        args: vec![mapped],
                        results: vec![widened],
                    });
                    args.push(widened);
                }
                None => args.push(mapped),
            }
        }

        instrs.push(Instruction {
            opcode: Opcode::Return,
            args,
            results: vec![],
        });
        Ok(instrs)
    }

    fn validate_return_signature(&self, values: &[ValueId]) -> Result<(), AdapterError> {
        // Zero-sized (unit/never) return values carry no ABI slot and are dropped
        // (translate_return), so validate the arity/types of the REMAINING values
        // against the unit-filtered return-type list.
        let values: Vec<ValueId> = values
            .iter()
            .copied()
            .filter(|v| !self.is_zero_sized_value(*v))
            .collect();
        let values = values.as_slice();
        if values.len() != self.current_return_tys.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Return arity mismatch: got {}, expected {} from current function signature",
                values.len(),
                self.current_return_tys.len()
            )));
        }

        for (index, (value, expected)) in values.iter().zip(&self.current_return_tys).enumerate() {
            self.translate_ty(expected)?;
            let actual = self
                .lookup_value_ty(*value)
                .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
            // A by-value aggregate / slice-fat-pointer RETURN is carried by ADDRESS:
            // the returned value is the `Ptr` to the aggregate's slot bytes, and the
            // verified SysV aggregate-return classifier loads its lanes into RAX:RDX
            // (<=16 B) or copies via sret — exactly the caller-side
            // `is_aggregate_address_passed_ty` convention, just on the return edge.
            // Accept a `Ptr` for an aggregate-typed return; every other mismatch
            // still fails closed.
            if !Self::call_arg_ty_compatible(&actual, expected) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Inst::Return value {index} type mismatch: operand ValueId({}) has {:?}, expected {:?} from current function signature",
                    value.index(),
                    actual,
                    expected
                )));
            }
        }
        Ok(())
    }

    /// Lower `Inst::CoroSuspend { frame, state_slot, next_state, value }` — one
    /// coroutine `yield` — by MACRO-EXPANDING it into the already-verified
    /// store+return primitives (trust-ir inst.rs §coroutines). No new machine
    /// codegen is introduced: a `CoroSuspend` is operationally exactly
    ///
    /// ```text
    /// store i64 `next_state` into `frame[state_slot]`   ; record resume state
    /// return `value`                                    ; hand value to resumer
    /// ```
    ///
    /// The frame is a caller-owned aggregate of I64 elements, so the state field
    /// lives at byte offset `state_slot * 8` from `frame` — the same
    /// `base + index * sizeof(I64)` address arithmetic the single-index `GEP`
    /// arm emits, specialized here to the compile-time slot index. The trailing
    /// `Return` reuses `translate_return`, so the yielded value inherits the
    /// full return-signature validation (arity + type) every other return edge
    /// gets. Because this expands only into the I64 `Store` and `Return`
    /// lowerings, its correctness reduces to those per-instruction proofs.
    fn translate_coro_suspend(
        &mut self,
        frame: &ValueId,
        state_slot: u32,
        next_state: i64,
        value: &ValueId,
    ) -> Result<Vec<Instruction>, AdapterError> {
        const I64_BYTES: i64 = 8;

        let frame_ptr = self.map_value(*frame);
        let mut instrs = Vec::new();

        // Address of the state field: `frame + state_slot * 8`. A zero slot is
        // the frame base itself, so no address arithmetic is emitted; otherwise
        // materialize the constant byte offset and add it to the frame pointer,
        // mirroring the single-index GEP `base + index*elem_size` lowering.
        let slot_ptr = if state_slot == 0 {
            frame_ptr
        } else {
            let byte_offset = (state_slot as i64).checked_mul(I64_BYTES).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "CoroSuspend state_slot {state_slot} overflows an i64 byte offset"
                ))
            })?;
            let offset_val = self.fresh_value();
            self.define_value_type(offset_val, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: byte_offset,
                },
                args: vec![],
                results: vec![offset_val],
            });

            let addr = self.fresh_value();
            self.define_value_type(addr, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iadd,
                args: vec![frame_ptr, offset_val],
                results: vec![addr],
            });
            addr
        };

        // Materialize the i64 `next_state` constant and store it into the slot.
        // Frame state fields are I64 elements, so this is a plain 8-byte store —
        // the exact `Opcode::Store { ty: Type::I64 }` other I64 stores emit.
        let state_val = self.fresh_value();
        self.define_value_type(state_val, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: next_state,
            },
            args: vec![],
            results: vec![state_val],
        });
        instrs.push(Instruction {
            opcode: Opcode::Store {
                ty: Type::I64,
                align: None,
            },
            args: vec![state_val, slot_ptr],
            results: vec![],
        });

        // Return the yielded value. Reuse `translate_return` so the yielded
        // operand goes through the same return-signature validation as any
        // other return edge.
        instrs.extend(self.translate_return(std::slice::from_ref(value))?);
        Ok(instrs)
    }

    /// Select the EH personality for `func`
    /// ([`eh_personality_for_function`]): the Rust personality for a function
    /// the Rust frontend produced (`Producer::TRust`), else the module default
    /// ([`eh_personality_for_function_names`]). The frontend owns this choice
    /// through provenance and the declared symbol set, so no IR field or API
    /// change is needed.
    fn eh_personality_for(&self, func: &TrustIrFunction) -> String {
        eh_personality_override(func)
            .unwrap_or_else(|| self.functions.default_eh_personality())
            .to_string()
    }

    /// The personality `translate()` selected for the current function.
    fn selected_eh_personality(&self) -> Result<String, AdapterError> {
        self.eh_personality.clone().ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "exception-handling instruction encountered outside function translation"
                    .to_string(),
            )
        })
    }

    /// Bind the typed catch indices of a landing pad through the module's
    /// reserved EH type table (see [`crate::function::EH_TYPE_TABLE_GLOBAL`]),
    /// loading the table on first use and refusing any index it does not bind.
    ///
    /// Typed catches are bound only under `__gxx_personality_v0`:
    /// `rust_eh_personality` ignores the LSDA type table (it enters the pad
    /// for any positive first action and delivers selector 0), so a typed
    /// catch under it would silently become a catch-all whose selector never
    /// matches, and is refused by name. A function that catches no typed
    /// exception loads no table, so its catch-all selector is `1`; one that
    /// does carries the whole module table, so its catch-all selector is
    /// `N + 1` for the `N`-entry table, whichever pads survive optimization.
    ///
    /// The table is read from the module once per module translation (the
    /// shared `module_eh_type_table` cell) and bound here by an O(1) clone: a
    /// splat table stays one symbol and a length, a list is shared.
    fn bind_eh_type_table(&mut self, catch_type_indices: &[u32]) -> Result<(), AdapterError> {
        let Some(&typed_index) = catch_type_indices.iter().find(|&&index| index != 0) else {
            return Ok(());
        };
        let personality = self.selected_eh_personality()?;
        if personality != DEFAULT_EH_PERSONALITY {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "landing pad catch type index {typed_index} is typed, but the function unwinds under `{personality}`, which ignores the LSDA type table (it enters the pad for any positive first action and delivers selector 0); typed catches are bound only under `{DEFAULT_EH_PERSONALITY}` [TCG-EH-TTYPE]"
            )));
        }
        if self.eh_type_table.is_empty() {
            let table = match self.module_eh_type_table.get() {
                Some(table) => table.clone(),
                None => {
                    let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
                    let table = module_eh_type_table(module)?;
                    // The cell was empty just above and nothing else holds
                    // this adapter, so the set cannot lose a race.
                    let _ = self.module_eh_type_table.set(table.clone());
                    table
                }
            };
            self.eh_type_table = table;
        }
        if let Some(&index) = catch_type_indices
            .iter()
            .find(|&&index| u64::from(index) > self.eh_type_table.len())
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "landing pad catch type index {index} is not bound by the module's `{}` global ({} typeinfo entries) [TCG-EH-TTYPE]",
                crate::function::EH_TYPE_TABLE_GLOBAL,
                self.eh_type_table.len()
            )));
        }
        Ok(())
    }

    /// Why an invoke of a variadic callee has no known placement under the
    /// convention this adapter lowers for, or `None` when it has one.
    ///
    /// `Opcode::Invoke` carries neither a fixed-argument count nor a variadic
    /// flag, so every selector lowers it as an ordinary call and places each
    /// argument by the named-argument rules. That is the variadic placement
    /// only under base AAPCS64, whose anonymous arguments follow the
    /// named-argument rules exactly. Elsewhere it is not: DarwinPCS passes
    /// anonymous arguments on the stack; x86-64 SysV requires `AL` to bound
    /// the vector registers a variadic call uses (the x86 invoke selection
    /// writes no `AL`), and Win64 copies anonymous floating-point arguments
    /// into integer registers.
    ///
    /// The AAPCS64 claim needs both facts that choose a convention to name
    /// it: the TLS dialect, which this adapter classifies call arguments by,
    /// and the module's declared target triple when it has one, because
    /// instruction selection takes its variant from the compilation triple.
    /// The AOT compiler derives both from one triple; the lower-level public
    /// entries take them separately. A dialect that names no AArch64
    /// convention (`TlsDialect::RejectThreadLocals`), or an ELF dialect
    /// beside a declared Apple triple, is refused rather than resolved in
    /// favour of either side.
    fn variadic_invoke_convention_refusal(&self) -> Option<String> {
        use crate::abi::AArch64AbiVariant;
        let arch = self.guard_carrier_arch;
        match arch {
            GuardCarrierArch::X86_64 => {
                return Some(
                    "x86-64 SysV requires `AL` to bound the vector registers a variadic call \
                     uses and Win64 copies anonymous floating-point arguments into integer \
                     registers"
                        .to_string(),
                );
            }
            GuardCarrierArch::Riscv64 => {
                return Some(format!(
                    "the {arch} lowering models no anonymous-argument placement"
                ));
            }
            GuardCarrierArch::AArch64 => {}
        }
        let declared = self
            .module
            .and_then(|module| module.target_info.as_ref())
            .map(|target| {
                (
                    target.triple.as_str(),
                    AArch64AbiVariant::from_target_triple(&target.triple),
                )
            });
        match (self.tls_dialect.aarch64_abi_variant(), declared) {
            (Some(AArch64AbiVariant::Aapcs64), None)
            | (Some(AArch64AbiVariant::Aapcs64), Some((_, Ok(AArch64AbiVariant::Aapcs64)))) => None,
            (Some(AArch64AbiVariant::Darwin), _) => {
                Some("DarwinPCS passes anonymous arguments on the stack".to_string())
            }
            (None, _) => Some(
                "the TLS dialect names no AArch64 calling convention, and DarwinPCS would pass \
                 anonymous arguments on the stack"
                    .to_string(),
            ),
            (Some(AArch64AbiVariant::Aapcs64), Some((triple, Ok(AArch64AbiVariant::Darwin)))) => {
                Some(format!(
                    "the TLS dialect selects base AAPCS64 but the module declares the Apple \
                     triple `{triple}`, whose DarwinPCS passes anonymous arguments on the stack"
                ))
            }
            (Some(AArch64AbiVariant::Aapcs64), Some((_, Err(error)))) => Some(format!(
                "the module's declared triple selects no AArch64 calling convention ({error})"
            )),
        }
    }

    /// Lower `Inst::Invoke` — a call that may unwind to a landing pad.
    ///
    /// Emits the LIR `Opcode::Invoke { name, normal_dest, unwind_dest }`, which
    /// ISel lowers to the SAME `Bl` a `Call` lowers to plus a branch to the
    /// normal continuation (so it inherits the verified direct-call lowering),
    /// and records — in the function's `eh_info` — that this block's call site
    /// may unwind to `unwind_dest`. The codegen pipeline turns `eh_info` into
    /// the LSDA call-site table + compact unwind after block layout.
    ///
    /// The callee's return values bind `results` (same as `Inst::Call`); the
    /// normal edge carries `normal_args` to `normal_dest`'s block params. When
    /// `normal_args` is non-empty the copies must run only on the normal edge,
    /// so they go in a fresh edge block that the invoke's `normal_dest` points
    /// at, which then jumps to the real normal destination (mirroring the
    /// `condbr` edge-copy pattern).
    fn translate_invoke(
        &mut self,
        callee: FuncId,
        args: &[ValueId],
        normal_dest: BlockId,
        normal_args: &[ValueId],
        unwind_dest: BlockId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // Validate the call edge exactly as a direct `Call` would (arity +
        // callee convention + signature), so an invoke is held to the same
        // ABI guards as every other call site.
        let (callee_function, callee_signature) =
            self.validate_direct_call_signature(callee, args, results)?;
        if let Some(result) = callee_signature
            .returns
            .iter()
            .find(|ty| sequence_layout::is_collection(ty))
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{SEQUENCE_DIAGNOSTIC} invoke of `{}` returns {result:?}: the result buffer is \
                 lowered for direct calls only, not for a call that may unwind",
                callee_function.name
            )));
        }
        let requires_exact_module_binding = is_module_local_function_definition(callee_function);
        if requires_exact_module_binding && self.allow_exact_module_calls {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "generic invoke of non-preemptible module function `{}` cannot carry exact-module \
                 binding through Opcode::Invoke until its source/EH route is qualified",
                callee_function.name
            )));
        }

        let mut arg_vals: Vec<Value> = args.iter().map(|vid| self.map_value(*vid)).collect();
        let result_vals = self.map_results(results);
        let callee_name = self
            .functions
            .name(callee)
            .map(str::to_string)
            .unwrap_or_else(|| callee_function.name.clone());
        // An invoke lowers to the SAME `Bl` a direct call does, so it carries
        // the same indirect-return convention and must record it the same way.
        self.record_sret_arg_callee(callee, &callee_name)?;

        // Propagate callee return / aggregate-param types onto the result and
        // (via call-site-scoped Copy temps) the argument Values — same
        // reasoning as the direct-`Call` arm: keeps ISel's `value_type()` and
        // ABI classification correct. The Copies are plain instructions
        // prepended ahead of the `Invoke` terminator in the same block. LIR
        // handler rows remain block-keyed; machine EH preserves the selected
        // Invoke call's exact identity separately from argument construction.
        let ret_tys = self.lookup_callee_return_types(callee);
        for (val, ty) in result_vals.iter().zip(ret_tys.iter()) {
            self.define_value_type(*val, ty.clone());
        }
        let param_tys = self.lookup_callee_param_types(callee);
        let mut insts = self.record_aggregate_call_arg_types(&mut arg_vals, &param_tys)?;
        // By-reference composites become pointers to storage the callee may
        // own (see `pass_composites_by_reference`). The copy that makes such
        // storage may be a `memcpy` call, and so may the `Load` that produced
        // the argument. The adapter moves such an invoke into a block of its
        // own that this block jumps to, after every copy is complete. The
        // landing pad never sees a half-built copy: the copy is finished
        // before the protected call starts, and it is either a fresh slot or
        // storage no later instruction reads.
        //
        // `Opcode::Invoke` carries no fixed-argument count and no variadic
        // flag, so every selector places a variadic callee's anonymous
        // arguments by the named-argument rules (see
        // `variadic_invoke_convention_refusal`). Only base AAPCS64 places both
        // the same way; every other convention refuses the invoke.
        let anonymous_from = self
            .lookup_callee_func_ty(callee)
            .filter(|func_ty| func_ty.is_vararg)
            .map(|func_ty| func_ty.params.len());
        if anonymous_from.is_some()
            && let Some(convention) = self.variadic_invoke_convention_refusal()
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "[TCG-VARARG-ABI] invoke of variadic callee `{callee_name}`: {convention}, and \
                 an invoke carries no fixed-argument count or variadic flag to place them by \
                 (only base AAPCS64 places anonymous arguments as named ones); the invoke fails \
                 closed"
            )));
        }
        let passes_by_reference =
            self.pass_composites_by_reference(args, &mut arg_vals, anonymous_from, &mut insts)?;
        // An earlier call of this block would be a second call in the
        // protected block, so that invoke moves into a block of its own too.
        // The earlier call keeps a no-handler row: it was not an invoke, so an
        // unwind out of it runs none of this frame's pads. A call that
        // selection alone introduces (a copy lowered to `memcpy`) is not seen
        // here. Modern machine EH binds only the exact selected Invoke call;
        // that helper keeps its ordinary no-handler propagation policy.
        // Explicit legacy block-only metadata still refuses multiple calls.
        let follows_call = self.current_block_has_call;

        // The throwing call site is the trust_ir block we are translating (or
        // the block the invoke moved into). Map it and the landing-pad block to
        // their LIR blocks and record the EH call site so the pipeline can emit
        // the LSDA entry. The personality is function-level (not on the
        // Invoke); default it when EH first appears (see
        // `DEFAULT_EH_PERSONALITY`).
        // The LIR block being filled: the trust-ir block's own, or the
        // continuation a multi-block expansion earlier in it left.
        let current_block = match self.current_lir_block {
            Some(block) => Some(block),
            None => self.current_block_id.map(|bid| self.map_block(bid)),
        }
        .ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "Invoke encountered outside a block context".to_string(),
            )
        })?;
        let call_block = if passes_by_reference || follows_call {
            self.fresh_block()
        } else {
            current_block
        };
        let unwind_lir = self.map_block(unwind_dest);
        if self.eh_info.personality.is_none() {
            self.eh_info.personality = Some(self.selected_eh_personality()?);
        }
        self.eh_info.call_sites.push(crate::function::EhCallSite {
            call_block,
            landing_pad_block: unwind_lir,
        });

        // The normal continuation. When there are block args on the normal
        // edge, route through a fresh edge block that performs the copies and
        // then jumps to the real normal destination, so the copies execute
        // only on the non-throwing path.
        let normal_copies = self.resolve_block_args(normal_dest, normal_args)?;
        let real_normal_dest = self.map_block(normal_dest);
        let invoke_normal_dest = if normal_copies.is_empty() {
            real_normal_dest
        } else {
            let edge_block = self.fresh_block();
            let mut edge_bb = BasicBlock {
                instructions: normal_copies,
                ..Default::default()
            };
            edge_bb.instructions.push(Instruction {
                opcode: Opcode::Jump {
                    dest: real_normal_dest,
                },
                args: vec![],
                results: vec![],
            });
            self.pending_extra_blocks.push((edge_block, edge_bb));
            edge_block
        };

        // The source direct-call binding. An exact-module invoke was refused
        // above, so a module-local callee binds by name here. The generic
        // invoke retains no declared external's `FuncId`: neither selector
        // lowers a retained `DeclaredExternalFunction` invoke (each refuses
        // it, "requires a closed native/EH dependency pipeline"), so the
        // callee binds by name.
        let binding = self.source_direct_call_binding(callee, requires_exact_module_binding, false);
        let invoke = Instruction {
            opcode: Opcode::Invoke {
                binding,
                name: callee_name,
                normal_dest: invoke_normal_dest,
                unwind_dest: unwind_lir,
            },
            args: arg_vals,
            results: result_vals,
        };
        if call_block == current_block {
            insts.push(invoke);
            return Ok(insts);
        }
        let invoke_block = BasicBlock {
            instructions: vec![invoke],
            source_locs: vec![self.current_source_loc],
            ..Default::default()
        };
        self.pending_extra_block_origins
            .insert(call_block, vec![self.current_trust_ir_origin]);
        self.pending_extra_blocks.push((call_block, invoke_block));
        insts.push(Instruction {
            opcode: Opcode::Jump { dest: call_block },
            args: vec![],
            results: vec![],
        });
        Ok(insts)
    }

    /// Lower `Inst::LandingPad` — the entry of an exception handler / cleanup
    /// block. Emits the LIR `Opcode::LandingPad`, which ISel lowers to reads of
    /// the unwinder-provided exception pointer (X0) and type selector (X1) into
    /// the two results, and records the pad (catch types / cleanup flag) in the
    /// function's `eh_info` so the pipeline can build the LSDA action table.
    fn translate_landing_pad(
        &mut self,
        is_cleanup: bool,
        catch_type_indices: &[u32],
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // The pad produces (exception-ptr: Ptr/I64, selector: I32). Type them
        // so ISel's value_type() is correct for any downstream use.
        let result_vals = self.map_results(results);
        if let Some(exn) = result_vals.first() {
            self.define_value_type(*exn, Type::I64);
        }
        if let Some(sel) = result_vals.get(1) {
            self.define_value_type(*sel, Type::I32);
        }

        // Record this landing-pad block in the function EH info. The current
        // block is the pad block.
        let pad_block = self
            .current_block_id
            .map(|bid| self.map_block(bid))
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(
                    "LandingPad encountered outside a block context".to_string(),
                )
            })?;
        let personality = self.selected_eh_personality()?;
        let empty_filter = crate::function::validate_rust_eh_empty_filter(
            catch_type_indices,
            is_cleanup,
            &personality,
        )
        .map_err(|detail| AdapterError::UnsupportedInstruction(detail.to_string()))?;
        if !empty_filter {
            self.bind_eh_type_table(catch_type_indices)?;
        }
        self.eh_info
            .landing_pads
            .push(crate::function::EhLandingPad {
                block: pad_block,
                catch_type_indices: catch_type_indices.to_vec(),
                is_cleanup,
            });
        if self.eh_info.personality.is_none() {
            self.eh_info.personality = Some(self.selected_eh_personality()?);
        }

        Ok(vec![Instruction {
            opcode: Opcode::LandingPad {
                is_cleanup,
                catch_type_indices: catch_type_indices.to_vec(),
            },
            args: vec![],
            results: result_vals,
        }])
    }

    /// Lower `Inst::Resume` — re-raise the in-flight exception to the host
    /// unwinder. Emits the LIR `Opcode::Resume`, which ISel lowers to a call to
    /// `_Unwind_Resume(exn)` (it does not return).
    fn translate_resume(&mut self, exn: &ValueId) -> Result<Vec<Instruction>, AdapterError> {
        let exn_val = self.map_value(*exn);
        Ok(vec![Instruction {
            opcode: Opcode::Resume,
            args: vec![exn_val],
            results: vec![],
        }])
    }

    // Legacy helpers `translate_call` and `translate_phi` were removed during
    // the 2026-04-19 zero-warnings cleanup — Call and Phi are lowered inline
    // in `translate_instruction` above.

    // -----------------------------------------------------------------------
    // Aggregate operations
    // -----------------------------------------------------------------------

    // `translate_struct_construct` was removed during the 2026-04-19
    // zero-warnings cleanup — Struct construction is lowered inline in
    // `translate_instruction` above.

    /// Translate `Field { ty, value, index }` — extract a struct field.
    ///
    /// Lowering: compute field offset, add to struct base pointer, load the
    /// field value from that address.
    /// A struct with a non-standard (packed) layout: its field offsets differ
    /// from the machine `Type::Struct` model (standard C alignment), which the
    /// GEP/load offset computation uses. Field access on such a struct would
    /// read the wrong bytes, so callers fail closed rather than miscompile.
    fn is_packed_struct_ty(&self, ty: &Ty) -> bool {
        if let Ty::Struct(sid) = ty
            && let Some(sdef) = self.structs.iter().find(|s| s.id == *sid)
        {
            return matches!(sdef.repr, trust_ir::StructRepr::Packed(_));
        }
        false
    }

    /// The module tables the layout authority resolves field types through —
    /// the same tables [`Self::translate_ty`] uses, so the layout it computes
    /// is the layout of the LIR type the byte path actually builds.
    fn layout_tables(&self) -> LayoutTables<'_> {
        let (records, closures): (&[RecordDef], &[ClosureTy]) = match self.module {
            Some(module) => (&module.records, &module.closure_types),
            None => (&[], &[]),
        };
        LayoutTables {
            structs: self.structs,
            types: self.types,
            enums: self.enums,
            records,
            closures,
        }
    }

    /// WS7.8 PREFLIGHT: refuse `func` if it holds a value of, or reserves or
    /// addresses storage for, a type containing a struct whose complete
    /// declared layout the byte path cannot emit
    /// ([`AdapterError::DeclaredStructLayoutNotEmittable`]).
    ///
    /// The layout queries refuse such a struct where they are asked. This
    /// covers the consumers that never ask them and read the natural-C carrier
    /// instead — the `Alloca` / `HeapAlloc` slot, the ABI classifier over the
    /// signature and over every callee signature (`Call` / `Invoke` /
    /// `CallIndirect`, whose by-value aggregate arguments may be carried by
    /// address), an aggregate moved in SSA form — so the
    /// struct is never compiled at a size rustc does not give it (see
    /// [`refuse_undeclarable_struct_in`]). The field-access types
    /// (`ExtractField` / `InsertField`) are visited too, although their own
    /// address query would refuse later, so every refusal is raised here, once.
    /// Types are visited in a fixed order (signature, then each block's
    /// parameters and each instruction in program order), so the reported
    /// struct is deterministic.
    fn refuse_undeclarable_struct_layouts(
        &self,
        func: &TrustIrFunction,
        func_ty: &trust_ir::FuncTy,
    ) -> Result<(), AdapterError> {
        let tables = self.layout_tables();
        let mut checked = HashSet::new();
        let mut check = |ty: &Ty| refuse_undeclarable_struct_in(ty, tables, &mut checked);
        for ty in func_ty.params.iter().chain(&func_ty.returns) {
            check(ty)?;
        }
        for block in &func.blocks {
            for (_, ty) in &block.params {
                check(ty)?;
            }
            for node in &block.body {
                for result in &node.results {
                    if let Some(ty) = self.value_ty_map.get(result) {
                        check(ty)?;
                    }
                }
                match &node.inst {
                    Inst::Alloca { ty, .. } | Inst::GEP { pointee_ty: ty, .. } => {
                        if self.storage_geometry.resolve(self.module, ty)?.is_none() {
                            check(ty)?;
                        }
                    }
                    Inst::HeapAlloc { ty, .. }
                    | Inst::Load { ty, .. }
                    | Inst::Store { ty, .. }
                    | Inst::ExtractField { ty, .. }
                    | Inst::InsertField { ty, .. } => check(ty)?,
                    // The CALLEE's signature, not the argument's SSA type, is
                    // what the ABI classifier reads for a by-value aggregate
                    // argument or result: a constructed aggregate is carried
                    // by ADDRESS (`record_aggregate_call_arg_types`), so a
                    // `Ptr`-typed argument handed to a by-value `Mixed`
                    // parameter is classified as the 24-byte natural carrier
                    // where the rustc-compiled callee expects rustc's 16
                    // bytes. An unresolvable callee is left to the call's own
                    // translation, which refuses it.
                    Inst::Call { callee, .. } | Inst::Invoke { callee, .. } => {
                        if let Some(callee_ty) = self.lookup_callee_func_ty(*callee) {
                            for ty in callee_ty.params.iter().chain(&callee_ty.returns) {
                                check(ty)?;
                            }
                        }
                    }
                    Inst::CallIndirect { sig, .. } => {
                        if let Some(sig_ty) = self
                            .module
                            .and_then(|module| module.func_types.get(sig.index() as usize))
                        {
                            for ty in sig_ty.params.iter().chain(&sig_ty.returns) {
                                check(ty)?;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        Ok(())
    }

    /// The niche carrier `ty` lowers to, when `ty` is a `Ty::Enum` with a
    /// NICHE-encoded producer descriptor. `Ok(None)` for every other type.
    ///
    /// This runs the SAME [`niche_enum_carrier`] rule the type translation ran,
    /// with the same tables, so the field types it reports are the fields of the
    /// `Type::Struct` the byte path actually built. Re-running it rather than
    /// caching keeps one rule in one place.
    fn niche_carrier(&self, ty: &Ty) -> Result<Option<NicheCarrier>, AdapterError> {
        let Some(edef) = niche_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        let Some(layout) = edef.layout.as_ref() else {
            return Ok(None);
        };
        let tables = self.layout_tables();
        niche_enum_carrier(
            edef,
            layout,
            tables.structs,
            tables.types,
            tables.enums,
            tables.records,
            tables.closures,
            true,
            1,
        )
        .map(Some)
        .map_err(|reason| niche_enum_refusal(edef.id, edef, reason))
    }

    /// THE INDEX SHIFT — the translation from a trust-ir enum field index to the
    /// carrier field index the emitted code addresses.
    ///
    /// trust-ir indexes an enum aggregate FLATLY: element 0 is the
    /// DISCRIMINANT and element `i > 0` is payload field `i - 1`. The niche
    /// carrier is the payload ALONE, at indices `0..n`, because a niche encoding
    /// has no tag word to occupy element 0. So every field-access site that can
    /// see one must shift, and must answer element 0 through the niche codec.
    ///
    /// Missing the shift is not a diagnostic failure, it is a WRONG ADDRESS: a
    /// two-field payload would answer `ExtractField 1` with field 1's bytes
    /// instead of field 0's, silently, at an offset the producer never stated
    /// for it. (c) MEASURED over the 68-module corpus, across the functions this
    /// admission unblocks: `InsertField` at element `n > 0` 449 times,
    /// `ExtractField` at element `n > 0` 72 times, `ExtractField` at element 0
    /// 26 times, `InsertField` at element 0 never.
    ///
    /// `Inst::GEP` does not project enum fields: every index strides the
    /// whole pointee image, as specified by TrustIR's flat GEP semantics.
    /// It therefore needs no discriminant-to-payload index shift.
    ///
    /// * `Ok(None)` — `ty` is not a niche enum; the caller uses its index
    ///   unchanged. This is every struct, tuple, record, closure and
    ///   Direct-encoded enum, so nothing that worked before moves.
    /// * `Ok(Some(NicheFieldAccess::Discriminant(codec)))` — element 0. The
    ///   read caller decodes the niche lane through `codec`; writes refuse. The codec
    ///   [`niche_codec`] has validated against trust-cg's own layout.
    /// * `Ok(Some(NicheFieldAccess::Payload { .. }))` — address carrier field
    ///   `index`, whose trust-ir type is `payload_ty`.
    /// * `Err` — a niche descriptor the codec refuses, a field the descriptor
    ///   does not reach, or a field whose TYPE the variants do not agree on.
    fn niche_field_access(
        &self,
        ty: &Ty,
        field: u32,
    ) -> Result<Option<NicheFieldAccess>, AdapterError> {
        let Some(carrier) = self.niche_carrier(ty)? else {
            return Ok(None);
        };
        let Some(edef) = niche_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        // ELEMENT 0 IS THE DISCRIMINANT, AND A NICHE ENUM HAS NO TAG LANE.
        // Reading it range-tests the niche lane against `niche_start ..=
        // niche_start + (niche_variants_end - niche_variants_start)`; writing
        // it stores a reserved value. Both go through the validated codec, never
        // through byte 0 read as a tag — for `Option<&T>` byte 0 is the pointer.
        if field == 0 {
            let codec = niche_codec(edef, self.layout_tables(), 1)
                .map_err(|reason| niche_codec_refusal(edef, reason))?;
            return Ok(Some(NicheFieldAccess::Discriminant(Box::new(codec))));
        }
        let index = field - 1;
        let Some(payload_ty) = carrier.payload.get(index as usize) else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "element {field} of niche-encoded enum {:?} (`{}`) names payload field {index}, \
                 but the carrier (variant {} `{}`) has {} payload fields",
                edef.id,
                edef.name,
                carrier.variant,
                edef.variants[carrier.variant].name,
                carrier.payload.len()
            )));
        };
        if !carrier.resolvable[index as usize] {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "payload field {index} of niche-encoded enum {:?} (`{}`) is declared with \
                 DIFFERENT types by different variants, and ExtractField/InsertField name a field \
                 but not a variant; the carrier (variant {} `{}`) types it {:?}, so accessing it \
                 would hand out another variant's payload at the carrier's extent",
                edef.id,
                edef.name,
                carrier.variant,
                edef.variants[carrier.variant].name,
                payload_ty
            )));
        }
        Ok(Some(NicheFieldAccess::Payload {
            index,
            payload_ty: payload_ty.clone(),
        }))
    }

    /// A payload projection names a declared type, just as the direct-tag
    /// resolver does. Admit it only if EVERY matching variant places that lane
    /// at the same exact descriptor offset. Wrong-variant projections retain
    /// TrustIR's UB semantics; no tag is changed by a payload operation.
    fn niche_typed_field_access(
        &self,
        ty: &Ty,
        field: u32,
        declared: &Ty,
        write: bool,
    ) -> Result<Option<DirectEnumFieldAccess>, AdapterError> {
        if field == 0 {
            return Ok(None);
        }
        let Some(carrier) = self.niche_carrier(ty)? else {
            return Ok(None);
        };
        let lane = (field - 1) as usize;
        let legacy_resolved = carrier.resolvable.get(lane).copied().unwrap_or(false);
        // Preserve the existing carrier-index read stream wherever its address
        // and type were already unambiguous. Writes still check a replacement
        // that could occupy the niche lane before taking that original path.
        if legacy_resolved && !write {
            return Ok(None);
        }
        // Existing floating/vector carriers keep the pre-existing narrow path.
        if !integer_image_carrier(&carrier.lir) {
            return Ok(None);
        }
        let edef = self.enum_def(ty)?;
        let layout = edef.layout.as_ref().ok_or(AdapterError::ModuleNotSet)?;
        let mut offsets = Vec::new();
        for (vi, variant) in edef.variants.iter().enumerate() {
            if variant.fields.get(lane) == Some(declared) {
                offsets.push((vi, layout.variant_field_offsets[vi][lane]));
            }
        }
        let Some(&(_, offset)) = offsets.first() else {
            return Ok(None);
        };
        if offsets.iter().any(|&(_, other)| other != offset) {
            return Err(AdapterError::EnumProjectionOffsetAmbiguous {
                enum_id: edef.id.index(),
                enum_name: edef.name.clone(),
                lane: field,
                offsets: format!("typed niche candidates {offsets:?}"),
            });
        }
        let lir = self.aggregate_field_lir_ty(declared)?;
        let codec = self
            .niche_codec_for(ty)?
            .ok_or(AdapterError::ModuleNotSet)?;
        let extent = self.aggregate_value_extent(declared, &lir)?;
        if write
            && extent != 0
            && offset < codec.niche_offset + u64::from(codec.lane_bytes)
            && codec.niche_offset < offset + extent
            && offsets.iter().any(|&(vi, _)| vi == codec.untagged_variant)
            && codec.payload_validity.is_none()
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "InsertField into niche enum {:?} would replace its untagged niche lane without typed nonreserved validity",
                edef.id
            )));
        }
        if legacy_resolved {
            return Ok(None);
        }
        Ok(Some(DirectEnumFieldAccess::Payload {
            offset,
            field_ty: declared.clone(),
            field_lir: lir,
        }))
    }

    /// The validated codec of niche enum `ty`, for `Constant::Aggregate`
    /// construction. `Ok(None)` when `ty` is not a niche enum.
    fn niche_codec_for(&self, ty: &Ty) -> Result<Option<NicheCodec>, AdapterError> {
        let Some(edef) = niche_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        // The carrier rule first, so a declined carrier reports its own axis.
        self.niche_carrier(ty)?;
        niche_codec(edef, self.layout_tables(), 1)
            .map(Some)
            .map_err(|reason| niche_codec_refusal(edef, reason))
    }

    /// The untagged carrier `ty` lowers to, when `ty` is a `Ty::Enum` with a
    /// v37 UNTAGGED producer descriptor. `Ok(None)` for every other type.
    ///
    /// The twin of [`Self::niche_carrier`], and re-run for the same reason: it
    /// applies the SAME [`untagged_enum_carrier`] rule with the SAME tables the
    /// type translation used, so the fields it reports are the fields of the
    /// `Type::Struct` the byte path actually built. One rule, one place.
    fn untagged_carrier(&self, ty: &Ty) -> Result<Option<UntaggedCarrier>, AdapterError> {
        let Some(edef) = untagged_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        let Some(layout) = edef.layout.as_ref() else {
            return Ok(None);
        };
        let tables = self.layout_tables();
        untagged_enum_carrier(
            edef,
            layout,
            tables.structs,
            tables.types,
            tables.enums,
            tables.records,
            tables.closures,
            true,
            1,
        )
        .map(Some)
        .map_err(|reason| untagged_enum_refusal(edef.id, edef, reason))
    }

    /// THE INDEX SHIFT for an UNTAGGED enum — and, unlike the niche one, a
    /// CONSTANT answer for element 0 rather than a runtime lane decode.
    ///
    /// trust-ir indexes an enum aggregate FLATLY (element 0 is the
    /// discriminant, element `i > 0` is payload field `i - 1`) while the
    /// untagged carrier is the payload ALONE at `0..n`, so the payload indices
    /// shift exactly as they do in [`Self::niche_field_access`]; missing the
    /// shift is a WRONG ADDRESS, not a diagnostic.
    ///
    /// Element 0 is where the two encodings part. A niche discriminant is a
    /// runtime range test over one payload lane (`crate::niche_codec`). An
    /// UNTAGGED enum has exactly one variant, so its discriminant is a static
    /// fact of the TYPE: no byte of the image participates, and the honest
    /// lowering is a constant. That is not a widening — it is the same value
    /// the reference interpreter synthesizes for this encoding rather than
    /// loading (`interpret.rs`, `EnumByteView::Untagged` /
    /// `synthesized_tag_value`).
    ///
    /// * `Ok(None)` — `ty` is not an untagged enum; the caller uses its index
    ///   unchanged.
    /// * `Ok(Some(Discriminant { .. }))` — element 0; materialise the constant.
    /// * `Ok(Some(Payload { .. }))` — address carrier field `index`.
    /// * `Err` — a payload field the descriptor does not reach, or a carrier the
    ///   admission rule declined.
    fn untagged_field_access(
        &self,
        ty: &Ty,
        field: u32,
    ) -> Result<Option<UntaggedFieldAccess>, AdapterError> {
        let Some(carrier) = self.untagged_carrier(ty)? else {
            return Ok(None);
        };
        if field == 0 {
            return Ok(Some(UntaggedFieldAccess::Discriminant {
                value: carrier.discriminant,
                tag_ty: carrier.tag_ty,
                enum_id: carrier.enum_id,
                enum_name: carrier.enum_name,
                variant_name: carrier.variant_name,
            }));
        }
        let index = field - 1;
        let Some(payload_ty) = carrier.payload.get(index as usize) else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "element {field} of untagged enum {:?} (`{}`) names payload field {index}, but \
                 its sole variant (`{}`) has {} payload fields",
                carrier.enum_id,
                carrier.enum_name,
                carrier.variant_name,
                carrier.payload.len()
            )));
        };
        Ok(Some(UntaggedFieldAccess::Payload {
            index,
            payload_ty: payload_ty.clone(),
        }))
    }

    /// The [`DirectEnumImage`] of direct-tag enum `edef` (ledger L05-P5): the
    /// producer's descriptor read verbatim, or the canonical `Type::Enum`
    /// after [`crate::direct_enum::check_canonical_agreement`] against
    /// trust-ir's `enum_layout_shape`. Every direct-tag address the adapter
    /// emits — a tag read, a payload read, a constant's tag and field writes —
    /// comes from here, and the object writer's global initializer reads the
    /// same image through [`crate::direct_enum::module_direct_enum_image`].
    fn direct_enum_image(&self, edef: &EnumDef) -> Result<DirectEnumImage, AdapterError> {
        let lowered = self.translate_ty(&Ty::Enum(edef.id))?;
        let payload_offset = direct_enum::canonical_payload_offset(&lowered);
        direct_enum::direct_enum_image(
            edef,
            self.layout_tables(),
            &lowered,
            payload_offset,
            self.module,
        )
    }

    /// How element `field` of a DIRECT-TAG enum `ty` is projected at result
    /// type `declared` (WS7.6, F-112; producer layouts and tag-value tables
    /// since L05-P5). `Ok(None)` when `ty` is not a direct-tag enum (every
    /// non-enum type, and the niche and untagged carriers, which
    /// [`Self::niche_field_access`] and [`Self::untagged_field_access`] answer
    /// first).
    ///
    /// trust-ir's enum value is `[tag, fields of the ACTIVE variant..]`.
    ///
    /// * Element 0 is the tag word at the image's tag offset. Its type is the
    ///   enum's canonical tag repr, and `declared` must be exactly that type.
    /// * Element `i > 0` is payload field `i - 1` of the ACTIVE variant. The
    ///   instruction does not name the variant, so the candidates are every
    ///   variant with a field of type `declared` there. With none, the
    ///   projection is ill-typed (`EnumProjectionNoCandidate`). When the
    ///   candidates place it at one byte offset, that is a static load. When
    ///   they do not, it is refused (`EnumProjectionOffsetAmbiguous`) rather
    ///   than dispatched on the tag (roadmap WS7.6 DECIDE).
    ///
    /// A projection whose active variant is NOT a candidate reads another
    /// variant's bytes. That is sound because trust-ir ratifies a
    /// wrong-variant projection at a valid lane as undefined behaviour
    /// (`docs/ub-numerics-policy.md` §4, WS2.2): the reference interpreter
    /// answers `UndefinedBehavior`, and any native result refines it.
    fn direct_enum_field_access(
        &self,
        ty: &Ty,
        field: u32,
        declared: &Ty,
    ) -> Result<Option<DirectEnumFieldAccess>, AdapterError> {
        let Some(edef) = direct_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        let image = self.direct_enum_image(edef)?;
        if field == 0 {
            let tag_ty = image.tag.ty.clone();
            if declared != &tag_ty {
                return Err(AdapterError::UnsupportedType(format!(
                    "ExtractField result type {declared:?} does not match field 0 of {ty:?}: \
                     expected its canonical tag type {tag_ty:?}"
                )));
            }
            return Ok(Some(DirectEnumFieldAccess::Tag {
                tag_ty,
                tag_lir: image.tag.lir.clone(),
                offset: image.tag_offset,
            }));
        }
        let lane = (field - 1) as usize;
        let mut candidates: Vec<(usize, u64)> = Vec::new();
        let mut field_lir = None;
        for (vi, fields) in image.variants.iter().enumerate() {
            let Some(candidate) = fields.get(lane).filter(|f| &f.ty == declared) else {
                continue;
            };
            candidates.push((vi, candidate.offset));
            if field_lir.is_none() {
                field_lir = Some(candidate.lir.clone());
            }
        }
        let (Some(&(_, first)), Some(field_lir)) = (candidates.first(), field_lir) else {
            return Err(AdapterError::EnumProjectionNoCandidate {
                enum_id: edef.id.index(),
                enum_name: edef.name.clone(),
                lane: field,
                ty: format!("{declared:?}"),
            });
        };
        if candidates.iter().any(|&(_, offset)| offset != first) {
            let offsets = candidates
                .iter()
                .map(|&(vi, offset)| {
                    format!("variant {vi} `{}` at byte {offset}", edef.variants[vi].name)
                })
                .collect::<Vec<_>>()
                .join(", ");
            return Err(AdapterError::EnumProjectionOffsetAmbiguous {
                enum_id: edef.id.index(),
                enum_name: edef.name.clone(),
                lane: field,
                offsets,
            });
        }
        #[allow(unused_mut)]
        let mut offset = first;
        #[cfg(feature = "mutation-knobs")]
        if crate::mutation_knobs::enum_payload_off_by_one() {
            offset = offset.saturating_add(1);
        }
        Ok(Some(DirectEnumFieldAccess::Payload {
            offset,
            field_ty: declared.clone(),
            field_lir,
        }))
    }

    /// Lower `ExtractField` of a direct-tag enum through `access` (see
    /// [`Self::direct_enum_field_access`]).
    ///
    /// The tag is a load of the image's tag type at the image's tag offset.
    /// A scalar payload field is a load at its static offset. An aggregate payload field
    /// (struct, array, or enum) is carried by ADDRESS like every aggregate
    /// value in this backend, so its value is `base + offset` with no load.
    fn translate_direct_enum_extract(
        &mut self,
        access: DirectEnumFieldAccess,
        value: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let base_ptr = self.map_value(*value);
        let dst = self.map_result(results)?;
        let mut instrs = Vec::new();
        let (offset, load_ty) = match access {
            DirectEnumFieldAccess::Tag {
                tag_lir, offset, ..
            } => (offset, tag_lir),
            DirectEnumFieldAccess::Payload {
                offset, field_lir, ..
            } => (offset, field_lir),
        };
        if matches!(
            load_ty,
            Type::Struct(_) | Type::Array(_, _) | Type::Enum { .. }
        ) {
            let (opcode, args) = if offset == 0 {
                (Opcode::Copy, vec![base_ptr])
            } else {
                let imm = i64::try_from(offset).map_err(|_| {
                    AdapterError::UnsupportedInstruction(format!(
                        "enum field byte offset {offset} exceeds the i64 immediate lane"
                    ))
                })?;
                let off_val = self.emit_iconst_i64(imm, &mut instrs);
                (
                    Opcode::ArrayGep { elem_ty: Type::I8 },
                    vec![base_ptr, off_val],
                )
            };
            instrs.push(Instruction {
                opcode,
                args,
                results: vec![dst],
            });
            self.define_value_type(dst, load_ty);
            return Ok(instrs);
        }
        let field_ptr = self.byte_offset_address(base_ptr, offset, &mut instrs)?;
        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: load_ty,
                align: None,
            },
            args: vec![field_ptr],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// The layout the byte path emits for `ty`, when `ty` is a bare
    /// `Ty::Struct` the struct table resolves.
    ///
    /// Closure descriptors supply the same offset authority for captures.
    /// `None` for other shapes — `Ty::Tuple`, `Ty::Record`,
    /// `Ty::Array`, `Ty::Enum` — because the producer states no offsets for
    /// them and the byte path synthesizes their layout in declaration order.
    /// Those keep the natural-C fallback unchanged.
    fn emitted_layout(&self, ty: &Ty) -> Result<Option<EmittedStructLayout>, AdapterError> {
        if let Ty::Closure(id) = ty {
            return match self.module {
                Some(module) => crate::declared_closure_layout::layout(module, *id),
                None => Ok(None),
            };
        }
        let tables = self.layout_tables();
        match struct_def_for_ty(ty, tables.structs) {
            Some(sdef) => Ok(Some(emitted_struct_layout(sdef, tables)?)),
            None => Ok(None),
        }
    }

    /// The byte offset field `index` of `ty` sits at, **when the adapter has to
    /// materialise it itself** rather than leaving it to `Opcode::StructGep`.
    ///
    /// `StructGep` is resolved downstream by natural-C `Type::offset_of`
    /// (`isel.rs:9306`, `x86_64_isel.rs:13208`) on a LIR `Type::Struct` that
    /// carries no repr and no offsets, so it can only ever express the
    /// recomputed layout. Whenever the authority for `ty`
    /// ([`crate::declared_layout`]) puts the field somewhere else, the adapter
    /// must compute `base + offset` explicitly — exactly the move the packed
    /// lane already makes.
    ///
    /// * `Some(offset)` — emit `Iconst` + byte-stride
    ///   `ArrayGep { elem_ty: I8 }`. The authority is the
    ///   producer's declared layout, or the packed layout.
    /// * `None` — **THE NAMED FALLBACK**: emit `StructGep` unchanged. Either no
    ///   authority above natural C exists for `ty` (no declared layout, not
    ///   packed), or the declared offset is *provably the same address*
    ///   `StructGep` computes, in which case the existing encoding is kept so
    ///   the emitted stream stays byte-identical for the structs that already
    ///   agreed.
    ///
    /// A packed struct with no declared layout always takes the explicit form,
    /// unconditionally, exactly as it did before this method existed.
    fn explicit_field_offset(
        &self,
        ty: &Ty,
        lir_ty: &Type,
        index: u32,
    ) -> Result<Option<u64>, AdapterError> {
        let Some(layout) = self.emitted_layout(ty)? else {
            return Ok(None);
        };
        let offset = *layout.offsets.get(index as usize).ok_or_else(|| {
            AdapterError::UnsupportedType(format!(
                "field index {index} out of bounds for {ty:?} ({} fields laid out)",
                layout.offsets.len()
            ))
        })?;
        match layout.source {
            LayoutSource::NaturalC => Ok(None),
            LayoutSource::Packed => Ok(Some(offset)),
            LayoutSource::Declared => {
                if lir_ty.offset_of(index as usize).map(u64::from) == Some(offset) {
                    Ok(None)
                } else {
                    Ok(Some(offset))
                }
            }
        }
    }

    /// The element stride for an array of `ty`, **when the adapter has to
    /// materialise it itself** rather than leaving it to `Opcode::ArrayGep`.
    ///
    /// The `ArrayGep` twin of [`Self::explicit_field_offset`], with the same
    /// rule and the same named fallback: `ArrayGep` strides by natural-C
    /// `elem_ty.bytes()`, so an authority that sizes the element differently
    /// has to be spelled out as `base + index * stride`.
    ///
    /// `ty` is what one step of the index moves over — the pointee of a
    /// flat `GEP`, or the ELEMENT of the array an `ArrayGep` walks. It
    /// may itself be a `Ty::Array` (`&[[P; 2]]`, or every step of
    /// `GEP { pointee_ty: [P; 2], indices: [i, j] }`), which is why the array
    /// case is answered here rather than left to the struct table: an array's
    /// stride is its ELEMENT's authoritative stride times the count, and (c)
    /// MEASURED `size_of::<[P; 2]>() == 18` where the natural-C carrier is 32.
    fn explicit_element_stride(&self, ty: &Ty, lir_ty: &Type) -> Result<Option<u64>, AdapterError> {
        if matches!(ty, Ty::Array(_, _)) {
            // The authority for an array is entirely its element's. Spell the
            // stride out only when it actually differs from the natural-C one
            // `ArrayGep` would compute, so every array of natural-C elements
            // keeps the exact encoding it had.
            let extent = self.aggregate_value_extent(ty, lir_ty)?;
            return Ok((extent != u64::from(lir_ty.bytes())).then_some(extent));
        }
        let Some(layout) = self.emitted_layout(ty)? else {
            return Ok(None);
        };
        match layout.source {
            LayoutSource::NaturalC => Ok(None),
            LayoutSource::Packed => Ok(Some(layout.size)),
            LayoutSource::Declared if layout.size != u64::from(lir_ty.bytes()) => {
                Ok(Some(layout.size))
            }
            LayoutSource::Declared => Ok(None),
        }
    }

    /// Emit the address of element `index_val` of an array whose elements are
    /// `elem_ty` — as `Opcode::ArrayGep` when natural-C is the authority, and
    /// as explicit `base + index * stride` arithmetic when it is not.
    ///
    /// THE ONE PLACE the array-element stride is materialised for a runtime
    /// index. `ArrayGep` carries only a repr-less LIR `Type`, so the isel can
    /// resolve it no way but natural-C `elem_ty.bytes()`; whenever
    /// [`Self::explicit_element_stride`] names a different stride the opcode
    /// simply cannot express the address and the arithmetic has to be written
    /// out — exactly the move the single-index `Inst::GEP` path already makes.
    fn emit_array_element_ptr(
        &mut self,
        elem_ty: &Ty,
        lir_elem_ty: &Type,
        base_ptr: Value,
        index_val: Value,
        dst: Value,
        instrs: &mut Vec<Instruction>,
    ) -> Result<(), AdapterError> {
        let Some(stride) = self.explicit_element_stride(elem_ty, lir_elem_ty)? else {
            instrs.push(Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: lir_elem_ty.clone(),
                },
                args: vec![base_ptr, index_val],
                results: vec![dst],
            });
            return Ok(());
        };
        self.emit_byte_stride_ptr(stride, base_ptr, index_val, dst, instrs);
        Ok(())
    }

    /// Emit address arithmetic only: no LIR carrier for the pointee is minted.
    fn emit_byte_stride_ptr(
        &mut self,
        stride: u64,
        base_ptr: Value,
        index_val: Value,
        dst: Value,
        instrs: &mut Vec<Instruction>,
    ) {
        let size_val = self.fresh_value();
        self.define_value_type(size_val, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: stride as i64,
            },
            args: vec![],
            results: vec![size_val],
        });
        let scaled = self.fresh_value();
        self.define_value_type(scaled, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![index_val, size_val],
            results: vec![scaled],
        });
        instrs.push(Instruction {
            opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
            args: vec![base_ptr, scaled],
            results: vec![dst],
        });
    }

    /// How many bytes a BY-VALUE copy of an aggregate `ty` must move.
    ///
    /// The AUTHORITATIVE extent, from the one authority selector
    /// ([`crate::declared_layout::emitted_value_extent`]): the producer's
    /// declared size when it stated an emittable layout, else the
    /// [`packed_struct_layout`] size for a `#[repr(packed(N))]` struct, else
    /// natural-C `lir_ty.bytes()` — i.e. exactly the extent
    /// [`packed_struct_layout`] advances a containing packed struct's running
    /// offset by, since that walk now asks the same selector for each field.
    ///
    /// That equality is the point, and it is a SAFETY obligation, not tidiness.
    /// Before packed nesting was fixed, `packed_struct_layout` advanced by the
    /// natural `Type::bytes()`, so a natural-C-lengthed `Memmove` into a packed
    /// field landed exactly flush against the next sibling: `#[repr(packed)]
    /// { h: u8, inner: P, t: u8 }` put `t` at 17 and the 16-byte copy into
    /// `inner` at offset 1 covered bytes 1..17. Once the advance is `P`'s real
    /// 9 bytes, rustc's `t@10` is what gets emitted (measured) and that same
    /// 16-byte copy would CLOBBER `t`. So every write extent for an aggregate
    /// of packed type has to move with the layout, in the same change.
    ///
    /// Copying the packed extent rather than the natural one also leaves the
    /// destination's trailing padding stale. That is sound: those bytes are not
    /// part of the value under either authority, no read path addresses them,
    /// and the natural-C slot that holds them is still the larger of the two
    /// (the domination invariant), so nothing reads past the object.
    fn aggregate_value_extent(&self, ty: &Ty, lir_ty: &Type) -> Result<u64, AdapterError> {
        emitted_value_extent(ty, lir_ty, self.layout_tables())
    }

    /// Refuse an `InsertField` whose aggregate operand is not a VALUE of the
    /// declared aggregate type.
    ///
    /// trust-ir's `InsertField { ty, aggregate, .. }` is a pure value update:
    /// the validator requires `type(aggregate) == ty` and the reference
    /// interpreter answers `TypeError` for anything else. A POINTER operand is
    /// the "store form" — an in-place write through memory that trust-ir does
    /// not define. Under value semantics its write would land in the result's
    /// private copy and be silently LOST, so it is refused by name instead of
    /// being given either meaning (WS7.1 (b)). An operand of unknown type is
    /// refused for the same reason: without its type the two meanings cannot
    /// be told apart. trust-cg's own MIR lane spells a field write `GEP` +
    /// `Store` (`emit_aggregate_field_store`).
    fn require_value_form_insert(
        &self,
        op: &'static str,
        ty: &Ty,
        aggregate: ValueId,
    ) -> Result<(), AdapterError> {
        let base_ty = self.lookup_value_ty(aggregate);
        if base_ty.as_ref() == Some(ty) {
            return Ok(());
        }
        Err(AdapterError::AggregateInsertNotValueForm {
            function: self
                .trust_ir_func
                .map(|func| func.name.clone())
                .unwrap_or_default(),
            op,
            value: aggregate.index(),
            base_ty: base_ty.map(|base| format!("{base:?}")),
            ty: format!("{ty:?}"),
        })
    }

    /// Whether a value-semantic insert may write the storage of its `source`
    /// in place instead of a fresh copy.
    ///
    /// Three facts, each exact: (1) `source`'s storage is a slot its own
    /// defining lowering allocated for it alone (`owned_aggregate_storage`);
    /// (2) the insert being lowered is `source`'s ONLY SSA use in the whole
    /// function, so no other value was derived from it (a `Copy`, `Select`,
    /// block argument or interior `ExtractField` would each be a use); and
    /// (3) `source` is defined in the block being lowered, so every path from
    /// this use back to itself re-executes that definition first — `source`
    /// is dead once the insert has read it. Together they make the source's
    /// slot unshared and dead, so the insert may take it over. A loop-carried
    /// block parameter never holds such a slot from an earlier iteration,
    /// because aggregate block parameters own their storage
    /// (`value_semantic_block_param`).
    fn source_storage_is_reusable(&self, source: ValueId) -> bool {
        self.owned_aggregate_storage.contains(&source)
            && self.value_use_counts.get(&source).copied() == Some(1)
            && self.current_block_id.is_some()
            && self.value_def_blocks.get(&source) == self.current_block_id.as_ref()
    }

    /// The storage a value-semantic aggregate insert writes and returns: the
    /// source's own slot when `source_storage_is_reusable`, otherwise a fresh
    /// slot holding a byte copy of the source (the authoritative extent,
    /// exactly as an aggregate `Load` copies). Either way the result owns that
    /// storage.
    ///
    /// Under the `mutation-knobs` feature's `legacy_in_place_insert` knob this
    /// reverts to the historical in-place update (the result aliases the
    /// source and owns nothing); that knob exists only so differential tests
    /// can prove they catch the miscompile, and a default build cannot enable
    /// it.
    fn insert_destination(
        &mut self,
        ty: &Ty,
        lir_ty: &Type,
        source: ValueId,
        source_ptr: Value,
        results: &[ValueId],
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        if legacy_in_place_insert() {
            return Ok(source_ptr);
        }
        let (destination, slot) = if self.source_storage_is_reusable(source) {
            (source_ptr, self.owned_aggregate_slots.get(&source).copied())
        } else {
            let extent = self.aggregate_value_extent(ty, lir_ty)?;
            let size = Self::aggregate_slot_size(lir_ty, extent)?;
            let (fresh, slot) =
                self.copy_into_fresh_slot(source_ptr, size, lir_ty.align(), extent, instrs);
            self.define_value_type(fresh, lir_ty.clone());
            (fresh, Some(slot))
        };
        if let Some(result) = results.first().copied() {
            self.owned_aggregate_storage.insert(result);
            if let Some(slot) = slot {
                self.owned_aggregate_slots.insert(result, slot);
            }
        }
        Ok(destination)
    }

    /// Allocate a `size`-byte, `align`-aligned slot and emit `StackAddr` +
    /// `Memcpy` of `extent` bytes from `source_ptr` into it (a fresh slot
    /// overlaps no other storage). Returns the slot address and the slot.
    ///
    /// A zero-sized value (`()`, an empty struct) has no bytes to copy, so
    /// no `Memcpy` is emitted for it: selection lowers a zero-length copy to
    /// no machine instruction, and the dataflow-integrity gate refuses an
    /// effectful LIR instruction whose effect produced none.
    fn copy_into_fresh_slot(
        &mut self,
        source_ptr: Value,
        size: u32,
        align: u32,
        extent: u64,
        instrs: &mut Vec<Instruction>,
    ) -> (Value, u32) {
        let slot = self.alloc_stack_slot(size, align.max(1));
        let fresh = self.fresh_value();
        instrs.push(Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![fresh],
        });
        if extent != 0 {
            let len = self.emit_iconst_i64(extent as i64, instrs);
            instrs.push(Instruction {
                opcode: Opcode::Memcpy,
                args: vec![fresh, source_ptr, len],
                results: vec![],
            });
        }
        (fresh, slot)
    }

    fn translate_field_extract(
        &mut self,
        ty: &Ty,
        value: &ValueId,
        mut index: u32,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let (aggregate_ty, result_ty) = self.field_extract_types(ty, *value, index)?;
        let ty = &aggregate_ty;
        let struct_ty = self.translate_ty(ty)?;
        if let Some(access) = self.niche_typed_field_access(ty, index, &result_ty, false)? {
            return self.translate_direct_enum_extract(access, value, results);
        }

        // ELEMENT 0 OF AN UNTAGGED ENUM IS A CONSTANT, NOT A MEMORY READ. The
        // v37 untagged image stores no discriminant at all — with one variant
        // there is nothing to discriminate — so the value trust-ir's flat
        // aggregate carries at element 0 is a static fact of the TYPE, and the
        // honest lowering materialises it. Reading byte 0 instead would hand
        // back the first PAYLOAD field's bytes. (`Iconst` is the same
        // conclusion `interpret.rs` reaches: `EnumByteView::Untagged` decodes
        // the variant without touching memory and then synthesizes the tag.)
        if let Some(access) = self.untagged_field_access(ty, index)? {
            match access {
                UntaggedFieldAccess::Discriminant { value, tag_ty, .. } => {
                    let tag_lir = self.translate_ty(&tag_ty)?;
                    let imm = i64::try_from(value).map_err(|_| {
                        AdapterError::UnsupportedInstruction(format!(
                            "untagged enum {ty:?} has sole-variant discriminant {value}, \
                             which exceeds the i64 immediate lane"
                        ))
                    })?;
                    let dst = self.map_result(results)?;
                    self.define_value_type(dst, tag_lir.clone());
                    return Ok(vec![Instruction {
                        opcode: Opcode::Iconst { ty: tag_lir, imm },
                        args: vec![],
                        results: vec![dst],
                    }]);
                }
                // Payload fields shift exactly as a niche carrier's do.
                UntaggedFieldAccess::Payload { index: shifted, .. } => index = shifted,
            }
        }
        // THE INDEX SHIFT. A niche-encoded `Ty::Enum` lowers to the payload
        // struct ALONE, so trust-ir's flat element `i` is carrier field `i - 1`
        // and element 0 (the discriminant) has no carrier field at all. Without
        // this the arm below would take the `Type::Struct` path with trust-ir's
        // index and read the WRONG FIELD — see `niche_field_access`. Element 0
        // is the discriminant, decoded from the niche lane by the validated
        // codec. Every other type answers `None` and keeps its index untouched.
        let index = match self.niche_field_access(ty, index)? {
            Some(NicheFieldAccess::Discriminant(codec)) => {
                return self.translate_niche_discriminant_read(&codec, *value, results);
            }
            Some(NicheFieldAccess::Payload { index, .. }) => index,
            None => index,
        };
        // A DIRECT-TAG enum lowers to `Type::Enum`, which the struct arm below
        // cannot address: its tag word and each payload field sit at offsets
        // only the enum layout names (WS7.6).
        if let Some(access) = self.direct_enum_field_access(ty, index, &result_ty)? {
            return self.translate_direct_enum_extract(access, value, results);
        }
        let base_ptr = self.map_value(*value);
        let dst = self.map_result(results)?;
        let mut instrs = Vec::new();

        // Determine the field's scalar type for the load.
        let field_ty = match &struct_ty {
            Type::Struct(field_types) => {
                if (index as usize) < field_types.len() {
                    field_types[index as usize].clone()
                } else {
                    return Err(AdapterError::UnsupportedType(format!(
                        "field index {} out of bounds for struct with {} fields",
                        index,
                        field_types.len()
                    )));
                }
            }
            // The array spelling of a uniform struct -- see the `InsertField`
            // arm. Same element type, same offset, resolved by the same
            // `Type::offset_of` through `StructGep` below.
            Type::Array(elem, count) => {
                if index >= *count {
                    return Err(AdapterError::UnsupportedType(format!(
                        "array element {} out of bounds for array of {} elements",
                        index, count
                    )));
                }
                (**elem).clone()
            }
            _ => {
                return Err(AdapterError::UnsupportedType(format!(
                    "field extract on non-struct type: {:?}",
                    ty
                )));
            }
        };

        // The field sits at the AUTHORITATIVE offset — the producer's declared
        // one, or the PACKED one — which the machine `Type::Struct` layout
        // (declaration-ordered standard C alignment) does not reproduce.
        // Compute the offset explicitly and do a byte-offset load rather than a
        // type-offset StructGep + load; the load is marked possibly-UNALIGNED
        // only when the struct is packed, since a declared offset from rustc is
        // always properly aligned for the field's own type.
        if let Some(offset) = self.explicit_field_offset(ty, &struct_ty, index)? {
            let load_align = if self.is_packed_struct_ty(ty) {
                Some(1) // packed field may be unaligned
            } else {
                None
            };
            let off_val = self.fresh_value();
            self.define_value_type(off_val, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: offset as i64,
                },
                args: vec![],
                results: vec![off_val],
            });
            // An aggregate field's value IS its address (base + packed offset) —
            // no Load, like the non-packed nested case; subsequent accesses
            // recurse on the pointer using the inner struct's own layout. A
            // scalar field is loaded (possibly unaligned) from that address.
            // An ENUM field (`Type::Enum`) is an aggregate too: loading it as
            // a scalar would read its tag word and use it as an address.
            if field_ty.is_aggregate() {
                instrs.push(Instruction {
                    opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
                    args: vec![base_ptr, off_val],
                    results: vec![dst],
                });
                self.define_value_type(dst, field_ty);
                return Ok(instrs);
            }
            let field_ptr = self.fresh_value();
            self.define_value_type(field_ptr, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
                args: vec![base_ptr, off_val],
                results: vec![field_ptr],
            });
            instrs.push(Instruction {
                opcode: Opcode::Load {
                    ty: field_ty,
                    align: load_align,
                },
                args: vec![field_ptr],
                results: vec![dst],
            });
            return Ok(instrs);
        }

        // When the extracted field is ITSELF an aggregate (a nested struct/array
        // field), its value has no single-register representation — like every
        // aggregate value in this backend it is carried by ADDRESS. So compute
        // the field's address with StructGep and use it DIRECTLY as the result,
        // with NO Load. A subsequent ExtractField/Store/return on this value
        // recurses on the pointer (StructGep operates on the aggregate operand as
        // an address, exactly as it does for the incoming struct argument). A
        // scalar field, by contrast, is loaded into the destination register.
        // (Loading an aggregate field as a scalar previously read only part of it
        // and then accessed the rest out of bounds — a crash.) That includes an
        // ENUM field (`Type::Enum`): since WS7.6 lowers enum projections, a
        // struct's enum field is extracted and then projected, and a scalar
        // Load of it handed its tag word to the projection as an address — a
        // SIGSEGV (WS7.6 review, `enum_field_of_a_struct_*`).
        if field_ty.is_aggregate() {
            instrs.push(Instruction {
                opcode: Opcode::StructGep {
                    struct_ty,
                    field_index: index,
                },
                args: vec![base_ptr],
                results: vec![dst],
            });
            self.define_value_type(dst, field_ty);
            return Ok(instrs);
        }

        let load_ptr = self.fresh_value();
        instrs.push(Instruction {
            opcode: Opcode::StructGep {
                struct_ty,
                field_index: index,
            },
            args: vec![base_ptr],
            results: vec![load_ptr],
        });

        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: field_ty,
                align: None,
            },
            args: vec![load_ptr],
            results: vec![dst],
        });

        Ok(instrs)
    }

    // -----------------------------------------------------------------------
    // Niche discriminant codec (see `crate::niche_codec`)
    // -----------------------------------------------------------------------

    /// `base + offset` as an address, or `base` itself at offset 0.
    /// A byte-stride GEP preserves the explicit offset even when the base is
    /// an aggregate storage carrier; it never performs numeric aggregate math.
    fn byte_offset_address(
        &mut self,
        base: Value,
        offset: u64,
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        if offset == 0 {
            return Ok(base);
        }
        let imm = i64::try_from(offset).map_err(|_| {
            AdapterError::UnsupportedInstruction(format!(
                "byte offset {offset} exceeds the i64 immediate lane"
            ))
        })?;
        let off = self.emit_iconst_i64(imm, instrs);
        let ptr = self.fresh_value();
        self.define_value_type(ptr, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
            args: vec![base, off],
            results: vec![ptr],
        });
        Ok(ptr)
    }

    /// Load the niche lane at `lane_ptr` and zero-extend it to `I64`, so every
    /// later step computes on the lane's unsigned value whatever its width.
    fn load_niche_lane_i64(
        &mut self,
        codec: &NicheCodec,
        lane_ptr: Value,
        instrs: &mut Vec<Instruction>,
    ) -> Value {
        let lane_ty = codec.lane_lir_ty();
        let lane = self.fresh_value();
        self.define_value_type(lane, lane_ty.clone());
        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: lane_ty.clone(),
                align: None,
            },
            args: vec![lane_ptr],
            results: vec![lane],
        });
        if lane_ty == Type::I64 {
            return lane;
        }
        let wide = self.fresh_value();
        self.define_value_type(wide, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Uextend {
                from_ty: lane_ty,
                to_ty: Type::I64,
            },
            args: vec![lane],
            results: vec![wide],
        });
        wide
    }

    /// `ExtractField` element 0 of a niche enum: DECODE the discriminant.
    ///
    /// ```text
    /// lane     = zext(load lane_ty [base + niche_offset])
    /// relative = (lane - niche_start) & lane_mask
    /// is_niche = relative <=u span            (lane == niche_start when span == 0)
    /// disc     = is_niche ? disc(niche_variants_start) + relative
    ///                     : disc(untagged_variant)
    /// ```
    ///
    /// `disc(niche_variants_start) + relative` is the discriminant of variant
    /// `niche_variants_start + relative` because the codec admits only niche
    /// ranges whose discriminants step by one. The arithmetic runs in `I64`
    /// on the zero-extended lane and is truncated to the canonical tag type at
    /// the end, so no narrow-register convention is relied on.
    fn translate_niche_discriminant_read(
        &mut self,
        codec: &NicheCodec,
        aggregate: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let tag_lir = self.translate_ty(&codec.tag_ty)?;
        let base = self.map_value(aggregate);
        let dst = self.map_result(results)?;
        let mut instrs = Vec::new();
        let lane_ptr = self.byte_offset_address(base, codec.niche_offset, &mut instrs)?;
        let lane = self.load_niche_lane_i64(codec, lane_ptr, &mut instrs);
        let niche_start = self.emit_iconst_i64(codec.niche_start as u64 as i64, &mut instrs);
        let untagged = self.emit_iconst_i64(codec.untagged_discriminant() as i64, &mut instrs);
        let is_niche = self.fresh_value();
        self.define_value_type(is_niche, Type::B1);
        let tagged = if codec.span() == 0 {
            // One niche variant: a single equality, as rustc emits it.
            instrs.push(Instruction {
                opcode: Opcode::Icmp { cond: IntCC::Equal },
                args: vec![lane, niche_start],
                results: vec![is_niche],
            });
            self.emit_iconst_i64(codec.niche_base_discriminant() as i64, &mut instrs)
        } else {
            let difference = self.fresh_value();
            self.define_value_type(difference, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Isub,
                args: vec![lane, niche_start],
                results: vec![difference],
            });
            let relative = if codec.lane_bytes < 8 {
                let mask = self.emit_iconst_i64(codec.mask() as u64 as i64, &mut instrs);
                let masked = self.fresh_value();
                self.define_value_type(masked, Type::I64);
                instrs.push(Instruction {
                    opcode: Opcode::Band,
                    args: vec![difference, mask],
                    results: vec![masked],
                });
                masked
            } else {
                difference
            };
            let span = self.emit_iconst_i64(codec.span() as i64, &mut instrs);
            instrs.push(Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::UnsignedLessThanOrEqual,
                },
                args: vec![relative, span],
                results: vec![is_niche],
            });
            let base_disc =
                self.emit_iconst_i64(codec.niche_base_discriminant() as i64, &mut instrs);
            let tagged = self.fresh_value();
            self.define_value_type(tagged, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iadd,
                args: vec![relative, base_disc],
                results: vec![tagged],
            });
            tagged
        };
        let wide = if tag_lir == Type::I64 {
            dst
        } else {
            let wide = self.fresh_value();
            self.define_value_type(wide, Type::I64);
            wide
        };
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![is_niche, tagged, untagged],
            results: vec![wide],
        });
        if tag_lir != Type::I64 {
            instrs.push(Instruction {
                opcode: Opcode::Trunc {
                    to_ty: tag_lir.clone(),
                },
                args: vec![wide],
                results: vec![dst],
            });
        }
        self.define_value_type(dst, tag_lir);
        Ok(instrs)
    }

    // Legacy helpers `translate_array_index`, `translate_call_indirect`,
    // `translate_select`, and `translate_gep` were removed during the
    // 2026-04-19 zero-warnings cleanup — Index, CallIndirect, Select, and
    // GetElementPtr are lowered inline in `translate_instruction` above.

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------

    fn translate_const(
        &mut self,
        ty: &Ty,
        value: i64,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let dst = self.map_result(results)?;

        Ok(vec![Instruction {
            opcode: Opcode::Iconst {
                ty: lir_ty,
                imm: value,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Validate TrustIr's one-spelling rule for the wide unsigned carrier.
    fn validate_canonical_u128(ty: &Ty, value: u128) -> Result<(), AdapterError> {
        if !matches!(ty, Ty::U128) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Constant::U128 requires declared type U128, got {ty:?}"
            )));
        }
        if value <= i128::MAX as u128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "non-canonical Constant::U128({value}); values representable as i128 \
                 must use Constant::Int"
            )));
        }
        Ok(())
    }

    /// Materialize a canonical `Constant::U128` without routing its upper-half
    /// bit pattern through the signed `Constant::Int` validation path.
    fn translate_u128_const(
        &mut self,
        ty: &Ty,
        value: u128,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let dst = self.map_result(results)?;
        self.translate_u128_const_into(ty, value, dst)
    }

    fn translate_u128_const_into(
        &mut self,
        ty: &Ty,
        value: u128,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        Self::validate_canonical_u128(ty, value)?;
        let lo = (value & u128::from(u64::MAX)) as u64;
        let hi = (value >> 64) as u64;
        self.define_value_type(dst, Type::I128);
        Ok(vec![Instruction {
            opcode: Opcode::Iconst128 {
                lo: lo as i64,
                hi: hi as i64,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Translate an `Inst::Const { value: Constant::Int(i128), ty }` while
    /// validating that the value fits into the target type's representable
    /// range. The previous implementation did `*v as i64`, silently
    /// truncating any value outside `i64::MIN..=i64::MAX` — issue #339
    /// Finding 3.
    ///
    /// Values representable by one 64-bit carrier use `Opcode::Iconst`; wider
    /// I128/U128 values use `Opcode::Iconst128` with independent low/high
    /// halves. Canonical `Constant::U128` values take the dedicated unsigned
    /// path above instead of being reinterpreted as a signed `Constant::Int`.
    fn translate_int_const(
        &mut self,
        ty: &Ty,
        value: i128,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // Importers use this in-band encoding with thin pointer/reference
        // carriers and the legacy I64 address carrier (notably the rustc
        // bridge's vtable path). Restrict decoding to those deliberate
        // carriers so ordinary U64/U128/Usize constants whose high bits happen
        // to be `0xFADE` remain numeric data instead of becoming addresses.
        if Self::is_imported_global_addr_carrier(ty)
            && let Some((name, offset, is_external_import)) =
                self.decode_imported_global_addr(value)?
        {
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::I64);
            // An external DATA import (e.g. `@__stderrp` from libSystem) has no
            // link-time address in this object: a direct ADRP@PAGE+ADD@PAGEOFF
            // reference is a static-link error. Route it GOT-indirect via
            // `ExternRef` (ADRP@GOTPAGE + LDR@GOTPAGEOFF), exactly as
            // `translate_global_addr` does for the `Inst::GlobalAddr` form. A
            // DEFINED (initializer-bearing) global keeps the direct `GlobalRef`
            // unless the relocation model makes it preemptible, which also
            // selects the GOT form.
            let base_opcode = if is_external_import {
                Opcode::ExternRef { name }
            } else {
                Opcode::GlobalRef { name }
            };
            // Zero addend: the bare symbol address IS the result.
            if offset == 0 {
                return Ok(vec![Instruction {
                    opcode: base_opcode,
                    args: vec![],
                    results: vec![dst],
                }]);
            }
            // Non-zero addend (a GEP folded into the global-address stub, e.g.
            // `&extern_arr[3]`): the base reference materializes the symbol's
            // BASE address; the addend must be ADDED to that address AFTER it is
            // formed. It must NOT be folded into the relocation — for `ExternRef`
            // the @GOTPAGEOFF reloc addresses the GOT SLOT (not the symbol), so a
            // baked-in addend would displace the wrong thing, and for `GlobalRef`
            // the opcode carries no addend field at all. So emit the bare base
            // ref into a temp, materialize the offset as an ordinary `Iconst`,
            // and `Iadd` — the same base+const-offset shape the GEP lowering
            // uses. The offset is a `u32` BYTE offset (the importer's stub
            // synthesizer, `global_addr_stub`, restricts it to `0..=u32::MAX` and
            // fails closed on negatives / out-of-range), so `i64::from(offset)`
            // reproduces it exactly (non-negative, no sign extension) and `Iconst`
            // materialization (movz/movk) covers the whole range — there is no
            // add-immediate range limit and no residual fail-closed case.
            let base = self.fresh_value();
            self.define_value_type(base, Type::I64);
            let off_val = self.fresh_value();
            self.define_value_type(off_val, Type::I64);
            return Ok(vec![
                Instruction {
                    opcode: base_opcode,
                    args: vec![],
                    results: vec![base],
                },
                Instruction {
                    opcode: Opcode::Iconst {
                        ty: Type::I64,
                        imm: i64::from(offset),
                    },
                    args: vec![],
                    results: vec![off_val],
                },
                Instruction {
                    opcode: Opcode::Iadd,
                    args: vec![base, off_val],
                    results: vec![dst],
                },
            ]);
        }

        // Bounds check per target type. Signed types also accept the unsigned
        // bit-pattern range because the backend treats `Iconst.imm` as a raw
        // bit pattern (sign/zero extension happens at use sites based on
        // per-instruction signedness), and trust_ir frontends commonly emit
        // u64-typed constants such as hash mixing primes via `Ty::I64`.
        let (min, max): (i128, i128) = match ty {
            Ty::Bool => (0, 1),
            Ty::I8 => (i8::MIN as i128, u8::MAX as i128),
            Ty::I16 => (i16::MIN as i128, u16::MAX as i128),
            Ty::I32 => (i32::MIN as i128, u32::MAX as i128),
            Ty::I64 => (i64::MIN as i128, u64::MAX as i128),
            Ty::I128 => (i128::MIN, i128::MAX),
            Ty::U8 => (0, u8::MAX as i128),
            Ty::U16 => (0, u16::MAX as i128),
            Ty::U32 => (0, u32::MAX as i128),
            Ty::U64 => (0, u64::MAX as i128),
            // `Constant::Int` is the canonical U128 carrier only for the
            // non-negative half representable by i128. Values above i128::MAX
            // must use `Constant::U128`; negative Int values are not raw bits.
            Ty::U128 => (0, i128::MAX),
            // B1 pointer-width / char scalars: isize is signed 64-bit, usize is
            // unsigned 64-bit, and char is a Unicode scalar carrier here.
            Ty::Isize => (i64::MIN as i128, i64::MAX as i128),
            Ty::Usize => (0, u64::MAX as i128),
            Ty::Char => (0, 0x10FFFF),
            Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Rc(_) => {
                (i64::MIN as i128, u64::MAX as i128)
            }
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Constant::Int on non-integer type {:?}",
                    ty
                )));
            }
        };
        if value < min || value > max {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Constant::Int({}) does not fit in {:?} (range [{}, {}])",
                value, ty, min, max
            )));
        }
        if matches!(ty, Ty::Char) && (0xD800..=0xDFFF).contains(&value) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Constant::Int({value}) is not a Unicode scalar value for Char (surrogate range)"
            )));
        }

        // Materialize. For values that fit in i64 we pass through to the
        // existing `Opcode::Iconst { imm: i64 }` path, which sign-extends
        // (or for unsigned types, zero-extends at use sites — the backend
        // treats the imm as a bit-pattern and width truncation applies).
        match i64::try_from(value) {
            Ok(v64) => self.translate_const(ty, v64, results),
            Err(_) => {
                // Value fits in neither i64 nor u64 (as signed). Check
                // whether it fits as a u64 bit-pattern for 64-bit targets.
                if matches!(
                    ty,
                    Ty::I64
                        | Ty::U64
                        | Ty::Usize
                        | Ty::Ptr
                        | Ty::PtrConst(_)
                        | Ty::PtrMut(_)
                        | Ty::Ref(_)
                        | Ty::RefMut(_)
                        | Ty::Rc(_)
                ) && (0..=(u64::MAX as i128)).contains(&value)
                {
                    // Reinterpret the u64 bit pattern as i64 so Iconst carries
                    // the same 64 bits; the backend treats it as a raw
                    // bit-pattern for address-space constants.
                    let bits = value as u64;
                    return self.translate_const(ty, bits as i64, results);
                }
                // Wide 128-bit constant whose high 64 bits are NOT the sign
                // extension of the low 64 bits. The bounds check above already
                // proved `value` is a valid I128/U128 value, so split it into
                // its two independent 64-bit halves and emit `Iconst128`. The
                // x86 ISel lowers this to two `MovRI`s (one per half of the
                // i128 GPR pair), each an already-proven primitive. The
                // unsigned value `value as u128` reproduces `value` exactly:
                // for non-negative `value` the cast is identity; for negative
                // `value` (only reachable via Ty::I128) it is the two's
                // complement bit pattern, whose low/high u64 halves are the
                // physical register contents — exactly what the pair carries.
                if matches!(ty, Ty::I128 | Ty::U128) {
                    let bits = value as u128;
                    let lo = (bits & u128::from(u64::MAX)) as u64;
                    let hi = (bits >> 64) as u64;
                    let dst = self.map_result(results)?;
                    self.define_value_type(dst, Type::I128);
                    return Ok(vec![Instruction {
                        opcode: Opcode::Iconst128 {
                            lo: lo as i64,
                            hi: hi as i64,
                        },
                        args: vec![],
                        results: vec![dst],
                    }]);
                }
                Err(AdapterError::UnsupportedInstruction(format!(
                    "Constant::Int({}) outside i64 range and {:?} wide-imm \
                     materialization not supported for this type",
                    value, ty
                )))
            }
        }
    }

    /// Decode the importer's `0xFADE`-tagged global-address stub constant into
    /// `(symbol name, byte offset, is_external_data_import)`. The importer
    /// materializes the address of a module global (e.g. from `load ptr, ptr
    /// @g`) as a magic i64 `0xFADE_<idx:16>_<offset:32>`; the `is_external_data_import`
    /// flag mirrors [`global_is_external_data_import`] so the caller can route
    /// an external DATA import (like `@__stderrp`) through the GOT-indirect
    /// `ExternRef` sequence rather than a direct `GlobalRef` — the same
    /// definedness split [`translate_global_addr`] applies to `Inst::GlobalAddr`.
    fn decode_imported_global_addr(
        &self,
        value: i128,
    ) -> Result<Option<(String, u32, bool)>, AdapterError> {
        if !(0..=(u64::MAX as i128)).contains(&value) {
            return Ok(None);
        }
        let bits = value as u64;
        if bits >> 48 != 0xFADE {
            return Ok(None);
        }

        let idx = ((bits >> 32) & 0xFFFF) as usize;
        let offset = (bits & 0xFFFF_FFFF) as u32;
        let module = self.module.as_ref().ok_or(AdapterError::ModuleNotSet)?;
        let global = module.globals.get(idx).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "global address stub references missing global index {}",
                idx
            ))
        })?;
        // The flag selects the GOT-indirect form: an import, or a definition
        // the relocation model makes preemptible (see `translate_global_addr`).
        Ok(Some((
            global.name.clone(),
            offset,
            self.global_address_is_got_indirect(global),
        )))
    }

    fn translate_fconst(
        &mut self,
        ty: &Ty,
        value: f64,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let dst = self.map_result(results)?;

        Ok(vec![Instruction {
            opcode: Opcode::Fconst {
                ty: lir_ty,
                imm: value,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    fn translate_vector_pack_lanes_stack(
        &mut self,
        lanes: &[ValueId],
        lane_count: u32,
        lane_ty: Type,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let vector_ty = Type::V128;
        let total_lane_bytes = lane_ty.bytes().checked_mul(lane_count).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "vector.pack_lanes byte size overflows: {lane_count} lanes of {lane_ty:?}"
            ))
        })?;
        if total_lane_bytes != vector_ty.bytes() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector.pack_lanes lane storage is {total_lane_bytes} bytes, expected {} bytes",
                vector_ty.bytes()
            )));
        }

        let slot = self.alloc_stack_slot(vector_ty.bytes(), vector_ty.align());
        let base = self.fresh_value();
        self.define_value_type(base, Type::I64);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, vector_ty.clone());

        let mut instrs = Vec::with_capacity(lanes.len() * 3 + 2);
        instrs.push(Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![base],
        });

        for (idx, lane) in lanes.iter().enumerate() {
            let lane_index = self.fresh_value();
            self.define_value_type(lane_index, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: idx as i64,
                },
                args: vec![],
                results: vec![lane_index],
            });

            let lane_ptr = self.fresh_value();
            self.define_value_type(lane_ptr, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: lane_ty.clone(),
                },
                args: vec![base, lane_index],
                results: vec![lane_ptr],
            });

            instrs.push(Instruction {
                opcode: Opcode::Store {
                    ty: lane_ty.clone(),
                    align: None,
                },
                args: vec![self.map_value(*lane), lane_ptr],
                results: vec![],
            });
        }

        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: vector_ty,
                align: None,
            },
            args: vec![base],
            results: vec![dst],
        });

        Ok(instrs)
    }

    fn translate_v4i32_extract_lane_direct(
        &mut self,
        vector_val: Value,
        lane: u32,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if lane > 3 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector.extract_lane requires <4 x i32> lane 0..3, got {lane}"
            )));
        }
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I32);
        Ok(vec![Instruction {
            opcode: Opcode::V4I32ExtractLane { lane: lane as u8 },
            args: vec![vector_val],
            results: vec![dst],
        }])
    }

    fn translate_v4i32_insert_lane_direct(
        &mut self,
        vector_val: Value,
        elem_val: Value,
        lane: u32,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if lane > 3 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector.insert_lane requires <4 x i32> lane 0..3, got {lane}"
            )));
        }
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::V128);
        Ok(vec![Instruction {
            opcode: Opcode::V4I32InsertLane { lane: lane as u8 },
            args: vec![vector_val, elem_val],
            results: vec![dst],
        }])
    }

