    fn translate_vector_extract_lane_stack(
        &mut self,
        vector_val: Value,
        lane: u32,
        lane_ty: Type,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let vector_ty = Type::V128;
        let slot = self.alloc_stack_slot(vector_ty.bytes(), vector_ty.align());

        let base = self.fresh_value();
        self.define_value_type(base, Type::I64);
        let lane_index = self.fresh_value();
        self.define_value_type(lane_index, Type::I64);
        let lane_ptr = self.fresh_value();
        self.define_value_type(lane_ptr, Type::I64);

        let dst = self.map_result(results)?;
        self.define_value_type(dst, lane_ty.clone());

        Ok(vec![
            Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![base],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: vector_ty.clone(),
                    align: None,
                },
                args: vec![vector_val, base],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane as i64,
                },
                args: vec![],
                results: vec![lane_index],
            },
            Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: lane_ty.clone(),
                },
                args: vec![base, lane_index],
                results: vec![lane_ptr],
            },
            Instruction {
                opcode: Opcode::Load {
                    ty: lane_ty,
                    align: None,
                },
                args: vec![lane_ptr],
                results: vec![dst],
            },
        ])
    }

    fn translate_vector_insert_lane_stack(
        &mut self,
        vector_val: Value,
        elem_val: Value,
        lane: u32,
        lane_ty: Type,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let vector_ty = Type::V128;
        let slot = self.alloc_stack_slot(vector_ty.bytes(), vector_ty.align());

        let base = self.fresh_value();
        self.define_value_type(base, Type::I64);
        let lane_index = self.fresh_value();
        self.define_value_type(lane_index, Type::I64);
        let lane_ptr = self.fresh_value();
        self.define_value_type(lane_ptr, Type::I64);

        let dst = self.map_result(results)?;
        self.define_value_type(dst, vector_ty.clone());

        Ok(vec![
            Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![base],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: vector_ty.clone(),
                    align: None,
                },
                args: vec![vector_val, base],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane as i64,
                },
                args: vec![],
                results: vec![lane_index],
            },
            Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: lane_ty.clone(),
                },
                args: vec![base, lane_index],
                results: vec![lane_ptr],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: lane_ty,
                    align: None,
                },
                args: vec![elem_val, lane_ptr],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::Load {
                    ty: vector_ty,
                    align: None,
                },
                args: vec![base],
                results: vec![dst],
            },
        ])
    }

    fn translate_v4i32_extract_element(
        &mut self,
        elem_ty: &Ty,
        array: ValueId,
        index: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let array_ty = self.lookup_value_ty(array).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector ExtractElement requires <4 x i32> source, but source type is unknown"
                    .to_string(),
            )
        })?;
        if !Self::is_v4i32_ty(&array_ty) || elem_ty != &Ty::I32 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector ExtractElement requires <4 x i32> source and i32 result, got source={:?} result={:?}",
                array_ty, elem_ty
            )));
        }

        let lane = self.require_v4i32_lane_index(index, "vector ExtractElement")?;
        let vector_val = self.map_value(array);
        self.translate_v4i32_extract_lane_direct(vector_val, lane, results)
    }

    fn translate_v4i32_insert_element(
        &mut self,
        ty: &Ty,
        array: ValueId,
        index: ValueId,
        value: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let array_ty = self.lookup_value_ty(array).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector InsertElement requires <4 x i32> source, but source type is unknown"
                    .to_string(),
            )
        })?;
        let value_ty = self.lookup_value_ty(value).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector InsertElement requires i32 element, but element type is unknown"
                    .to_string(),
            )
        })?;
        if !Self::is_v4i32_ty(ty) || !Self::is_v4i32_ty(&array_ty) || value_ty != Ty::I32 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector InsertElement requires <4 x i32> source/result and i32 element, got result={:?} source={:?} element={:?}",
                ty, array_ty, value_ty
            )));
        }

        let lane = self.require_v4i32_lane_index(index, "vector InsertElement")?;
        let vector_val = self.map_value(array);
        let elem_val = self.map_value(value);
        self.translate_v4i32_insert_lane_direct(vector_val, elem_val, lane, results)
    }

    fn translate_v2i64_extract_element(
        &mut self,
        elem_ty: &Ty,
        array: ValueId,
        index: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let array_ty = self.lookup_value_ty(array).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector ExtractElement requires <2 x i64> source, but source type is unknown"
                    .to_string(),
            )
        })?;
        if !Self::is_v2i64_ty(&array_ty) || elem_ty != &Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector ExtractElement requires <2 x i64> source and i64 result, got source={:?} result={:?}",
                array_ty, elem_ty
            )));
        }

        let lane = self.require_v2i64_lane_index(index, "vector ExtractElement")?;
        let vector_val = self.map_value(array);
        self.translate_v2i64_extract_lane_direct(vector_val, lane, results)
    }

    fn translate_v2i64_insert_element(
        &mut self,
        ty: &Ty,
        array: ValueId,
        index: ValueId,
        value: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let array_ty = self.lookup_value_ty(array).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector InsertElement requires <2 x i64> source, but source type is unknown"
                    .to_string(),
            )
        })?;
        let value_ty = self.lookup_value_ty(value).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector InsertElement requires i64 element, but element type is unknown"
                    .to_string(),
            )
        })?;
        if !Self::is_v2i64_ty(ty) || !Self::is_v2i64_ty(&array_ty) || value_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector InsertElement requires <2 x i64> source/result and i64 element, got result={:?} source={:?} element={:?}",
                ty, array_ty, value_ty
            )));
        }

        let lane = self.require_v2i64_lane_index(index, "vector InsertElement")?;
        let vector_val = self.map_value(array);
        let elem_val = self.map_value(value);
        self.translate_v2i64_insert_lane_direct(vector_val, elem_val, lane, results)
    }

    /// Validate a constant lane index `0..=max_lane` (i64-typed) for a narrow
    /// integer vector extract/insert. Mirrors `require_v4i32/v2i64_lane_index`.
    fn require_const_lane_index(
        &self,
        index: ValueId,
        max_lane: u32,
        context: &str,
    ) -> Result<u32, AdapterError> {
        let index_ty = self.lookup_value_ty(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires an i64 constant lane index 0..={max_lane}, but index type is unknown"
            ))
        })?;
        if index_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires an i64 constant lane index 0..={max_lane}, got index type {index_ty:?}"
            )));
        }
        let lane = self.lookup_const_int(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires an i64 CONSTANT lane index 0..={max_lane}"
            ))
        })?;
        if lane < 0 || lane as u64 > u64::from(max_lane) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} lane index out of range 0..={max_lane}, got {lane}"
            )));
        }
        Ok(lane as u32)
    }

    fn translate_v16i8_extract_element(
        &mut self,
        elem_ty: &Ty,
        array: ValueId,
        index: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let array_ty = self.lookup_value_ty(array).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector ExtractElement <16 x i8>: source type unknown".to_string(),
            )
        })?;
        if !Self::is_v16i8_ty(&array_ty) || elem_ty != &Ty::I8 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector ExtractElement requires <16 x i8> source and i8 result, got source={array_ty:?} result={elem_ty:?}"
            )));
        }
        let lane = self.require_const_lane_index(index, 15, "vector ExtractElement <16 x i8>")?;
        let vector_val = self.map_value(array);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I8);
        Ok(vec![Instruction {
            opcode: Opcode::V16I8ExtractLane { lane: lane as u8 },
            args: vec![vector_val],
            results: vec![dst],
        }])
    }

