/// The per-function refusal CENSUS of the translation
/// [`translate_module_for_arch_with_access_model_and_stats_with_license`]
/// performs: the same module-level gates, rewrites and per-function adapter
/// configuration, but every bodied function is decided, instead of the
/// translation stopping at the first refusal. Diagnostic only: the LIR is
/// discarded and nothing here grants or withholds any authority.
///
/// * `Err` is a MODULE-level refusal (prerequisite validation, the v41 surface
///   gate, the Darwin narrow-FFI and x86-64 vector-compare gates, a backend
///   symbol shadow, an ambiguous function catalog, a module-local identity
///   that cannot cross an adapter-owned clone): the translation refuses it
///   before lowering any body, and it names no one function.
/// * `Ok(rows)` lists, in module order, each function the codegen `license`
///   refuses (decided on the caller's module, before any rewrite, and never
///   lowered) and each body the adapter refuses, with its error. A module the
///   translation admits has no row.
///
/// Bodies share module-wide adapter facts (sequence layouts, the EH type
/// table, the static-call statistics). The translation stops at its first
/// refusal, so a row after the first is the verdict the translation reaches
/// with the earlier refused bodies' partial facts in place: the same verdict
/// when those bodies are fixed, unless a fix changes the facts.
pub fn census_module_translation_with_access_model_and_license(
    module: &TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
    access_model: ObjectAccessModel,
    license: &CodegenLicensePolicy,
    policy: impl Into<ObjectSymbolPolicy>,
) -> Result<Vec<(FuncId, AdapterError)>, AdapterError> {
    census_module_translation_with_native_context(
        module,
        guard_carrier_arch,
        access_model,
        license,
        policy.into(),
        None,
    )
}

pub(crate) fn census_module_translation_with_native_context(
    module: &TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
    access_model: ObjectAccessModel,
    license: &CodegenLicensePolicy,
    policy: ObjectSymbolPolicy,
    native: Option<&crate::NativeAbiContext>,
) -> Result<Vec<(FuncId, AdapterError)>, AdapterError> {
    let mut rows = Vec::new();
    translate_module_with_backend_symbol_check(
        module,
        guard_carrier_arch,
        access_model,
        true,
        false,
        PreLirTransformPolicy::LegacyCompatibility,
        InputValidationPolicy::RunPrerequisites,
        license,
        policy,
        BackendSymbolCheck::Refuse,
        native,
        FunctionRefusals::Census(&mut rows),
    )?;
    Ok(rows)
}

/// Whether a module translation stops at its first per-function refusal (every
/// translation entry) or records each one and goes on (the diagnostic census,
/// [`census_module_translation_with_access_model_and_license`]).
enum FunctionRefusals<'rows> {
    /// Return the first license or adapter refusal.
    FailFast,
    /// Record every license and adapter refusal, in module order.
    Census(&'rows mut Vec<(FuncId, AdapterError)>),
}

/// Translate an ADMITTED module ([`crate::ingest::admit_module`], WS7.3) and
/// retain the lowering-owned sparse call-identity report, with devirtualization
/// statistics when `collect_static_call_stats`. The host JIT's entry; the
/// module is lowered under the license policy it was admitted under.
pub fn translate_admitted_module_for_arch_with_tls_and_validation<'module>(
    admitted: &'module AdmittedModule<'module>,
    guard_carrier_arch: GuardCarrierArch,
    tls_dialect: TlsDialect,
    collect_static_call_stats: bool,
) -> Result<ValidatedModuleTranslationWithOptionalStats<'module>, AdapterError> {
    translate_module_for_arch_with_tls_impl(
        admitted.module(),
        guard_carrier_arch,
        tls_dialect.into(),
        collect_static_call_stats,
        true,
        PreLirTransformPolicy::LegacyCompatibility,
        InputValidationPolicy::Admitted(admitted),
        admitted.license(),
        ObjectSymbolPolicy::default(),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PreLirTransformPolicy {
    LegacyCompatibility,
    IdentityOnly,
    PreparedCompatibility,
}

#[derive(Debug, Clone, Copy)]
enum InputValidationPolicy<'admission> {
    RunPrerequisites,
    ReuseCompleteReport,
    ReusePreparedPrerequisites,
    /// WS7.3: the caller admitted this exact module through
    /// [`crate::ingest::admit_module`], which ran trust-ir's composed codegen
    /// admission and refused EVERY finding — a strict superset of the
    /// prerequisites walk — so that walk is not repeated on it. The adapter's
    /// own definition-preserving transforms of it are checked by the
    /// prerequisites walk, as on every policy.
    Admitted(&'admission crate::ingest::AdmittedModule<'admission>),
}

#[cfg(test)]
thread_local! {
    static PREPARATION_VISITS: std::cell::Cell<[usize; 3]> = const { std::cell::Cell::new([0; 3]) };
}

#[cfg(test)]
fn record_preparation_visit(index: usize) {
    PREPARATION_VISITS.with(|visits| {
        let mut counts = visits.get();
        counts[index] += 1;
        visits.set(counts);
    });
}

/// Native lowering must not erase a semantic type, even in an unused table or
/// behind a pointer. The shared TrustIR visitor covers the complete inventory
/// once without following table IDs recursively (recursive types terminate).
fn reject_unlegalized_module_types(module: &TrustIrModule) -> Result<(), AdapterError> {
    let mut rejection = None;
    module.visit_types(|ty| {
        if rejection.is_some() {
            return;
        }
        rejection = match ty {
            Ty::Dialect(ty) => Some(AdapterError::UnsupportedType(format!(
                "dialect type {}.{}@{} requires semantic legalization before native lowering",
                ty.namespace, ty.name, ty.version
            ))),
            Ty::Tensor(_, _) => Some(AdapterError::UnsupportedType(
                "Ty::Tensor has no native layout or value ABI; tensor lowering is not implemented"
                    .into(),
            )),
            _ => None,
        };
    });
    rejection.map_or(Ok(()), Err)
}

/// Immutable owner of completed compatibility preparation and prerequisites.
///
/// This is not full canonical validation or source-equivalence evidence. Its
/// private fields prevent replacing the source or target architecture while
/// reusing the completed checks, and bind any Swift aggregate rewrite to its ABI.
/// A translation report borrows this owner; neither the report nor this type is
/// a Core/proof admission token.
#[derive(Debug)]
pub struct PreparedModuleForLir<'module> {
    module: std::borrow::Cow<'module, TrustIrModule>,
    architecture: GuardCarrierArch,
    swift_rewrite_abi: Option<crate::abi::AArch64AbiVariant>,
}

impl PreparedModuleForLir<'_> {
    pub fn module(&self) -> &TrustIrModule {
        self.module.as_ref()
    }

    pub fn architecture(&self) -> GuardCarrierArch {
        self.architecture
    }

    /// Lower the exact prepared source without repeating prerequisite checks
    /// or compatibility-transform preflights. Replay the returned report before
    /// mutating LIR; the owner must remain alive for that replay.
    pub fn translate_with_tls_and_validation(
        &self,
        tls_dialect: TlsDialect,
    ) -> Result<
        (
            Vec<(Function, ProofContext)>,
            ModuleTranslationValidationReport<'_>,
        ),
        AdapterError,
    > {
        self.translate_with_tls_and_validation_with_license(
            tls_dialect,
            &CodegenLicensePolicy::default(),
        )
    }

    /// [`Self::translate_with_tls_and_validation`] under an explicit
    /// codegen-license policy.
    pub fn translate_with_tls_and_validation_with_license(
        &self,
        tls_dialect: TlsDialect,
        license: &CodegenLicensePolicy,
    ) -> Result<
        (
            Vec<(Function, ProofContext)>,
            ModuleTranslationValidationReport<'_>,
        ),
        AdapterError,
    > {
        if let Some(variant) = self.swift_rewrite_abi
            && tls_dialect.aarch64_abi_variant() != Some(variant)
        {
            return Err(AdapterError::UnsupportedInstruction(
                "prepared Swift aggregate rewrite cannot be reused under a different target ABI"
                    .into(),
            ));
        }
        translate_module_for_arch_with_tls_impl(
            self.module(),
            self.architecture,
            tls_dialect.into(),
            false,
            true,
            PreLirTransformPolicy::PreparedCompatibility,
            InputValidationPolicy::ReusePreparedPrerequisites,
            license,
            ObjectSymbolPolicy::default(),
        )
        .map(|(functions, _, report)| (functions, report))
    }
}

impl AsRef<TrustIrModule> for PreparedModuleForLir<'_> {
    fn as_ref(&self) -> &TrustIrModule {
        self.module()
    }
}

/// Prepare a caller-owned source for compatibility LIR lowering.
///
/// Retains a borrowed module when the existing Swift-ABI and constant-divisor
/// transformations are dormant, otherwise retains their actual owned output.
/// Holding this owner lets a translation report borrow precisely the module
/// lowered. These are compatibility transformations, not checked source
/// equivalence; this API grants no Core or proof authority. Callers must still
/// replay the resulting translation report before LIR mutation. Swift changes
/// invalidate source manifests and summaries and remap positional scalar
/// attributes, but residual legacy proof/annotation transfer is not proved by
/// preparation; any canonical/Core consumer still needs its normal admission.
/// This legacy entry selects the Darwin object ABI. Drivers with an explicit
/// target should use [`prepare_module_for_lir_with_tls`].
pub fn prepare_module_for_lir(
    module: &TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
) -> Result<PreparedModuleForLir<'_>, AdapterError> {
    prepare_module_for_lir_with_tls(module, guard_carrier_arch, TlsDialect::default())
}

/// Prepare compatibility lowering for the driver's explicit object target.
///
/// The legacy [`prepare_module_for_lir`] entry selects Mach-O. Swift aggregate
/// rewriting is supported only on Darwin AArch64; a rewritten owner cannot be
/// translated under another ABI. Target-independent preparation remains reusable.
pub fn prepare_module_for_lir_with_tls(
    module: &TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
    tls_dialect: TlsDialect,
) -> Result<PreparedModuleForLir<'_>, AdapterError> {
    validate_codegen_prerequisites(module)?;
    // The prepared owner skips prerequisite re-checks at translation time,
    // so the v41 surface gate runs here, once, on the exact input. The
    // codegen LICENSE is policy-dependent and is decided at translation.
    reject_unconsumed_v41_surface(module, guard_carrier_arch)?;
    // byval/sret change the ABI, unlike discardable optimization hints. No
    // scalar-lane remapping contract exists for an aggregate with these attrs.
    // Refuse before any compatibility transform mutates an owned clone.
    if guard_carrier_arch == GuardCarrierArch::AArch64 {
        for function in &module.functions {
            if function.calling_conv != CallingConv::Swift || function.blocks.is_empty() {
                continue;
            }
            if let Some(signature) = module.func_types.get(function.ty.as_usize()) {
                for (index, (ty, attrs)) in signature
                    .params
                    .iter()
                    .zip(&function.attrs.params)
                    .enumerate()
                {
                    if TrustIrAdapter::trust_ir_ty_is_aggregate(ty) && (attrs.byval || attrs.sret) {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "Swift compatibility preparation cannot scalarize aggregate parameter {index} of `{}` with byval/sret ABI attributes",
                            function.name
                        )));
                    }
                }
            }
        }
    }
    let variant = tls_dialect.aarch64_abi_variant();
    let rewritten = match variant {
        Some(variant) if guard_carrier_arch == GuardCarrierArch::AArch64 => {
            swift_rewrite_module(module, variant)?
        }
        _ => None,
    };
    let swift_rewrite_abi = rewritten.as_ref().and(variant);
    let prepared = rewritten.as_ref().unwrap_or(module);
    let annotated = time_adapter_stage("div-nonzero-annotate", prepared, || {
        div_nonzero_const_annotate_module(prepared)
    });
    let prepared = match annotated.or(rewritten) {
        Some(mut module) => {
            drop_stale_source_manifests(&mut module);
            validate_codegen_prerequisites(&module)?;
            std::borrow::Cow::Owned(module)
        }
        None => std::borrow::Cow::Borrowed(module),
    };
    Ok(PreparedModuleForLir {
        module: prepared,
        architecture: guard_carrier_arch,
        swift_rewrite_abi,
    })
}

/// Whether a translation entry refuses a module definition that a reference
/// the backend makes by name on its own would reach.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BackendSymbolCheck {
    /// Every public entry.
    Refuse,
    /// Closed-JIT Core's planning path only ([`CoreQualificationFollows`]).
    CoreQualificationFollows,
}

/// Refuse `module` when one of its definitions would receive a reference the
/// backend makes by name on its own ([`crate::backend_symbol_shadow`]).
fn refuse_backend_symbol_shadow(module: &TrustIrModule) -> Result<(), AdapterError> {
    match crate::backend_symbol_shadow(module) {
        None => Ok(()),
        Some(crate::BackendSymbolShadow::ModuleLocalFunction { name, .. }) => {
            Err(AdapterError::BackendSymbolShadowed {
                kind: "module-local function",
                name: name.to_string(),
            })
        }
        Some(crate::BackendSymbolShadow::Data { name }) => {
            Err(AdapterError::BackendSymbolShadowed {
                kind: "data",
                name: name.to_string(),
            })
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn translate_module_for_arch_with_tls_impl<'module>(
    module: &'module TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
    access_model: ObjectAccessModel,
    collect_static_call_stats: bool,
    enable_exact_module_calls: bool,
    pre_lir_transform_policy: PreLirTransformPolicy,
    input_validation_policy: InputValidationPolicy<'_>,
    license: &CodegenLicensePolicy,
    object_symbols: ObjectSymbolPolicy,
) -> Result<ValidatedModuleTranslationWithOptionalStats<'module>, AdapterError> {
    translate_module_with_backend_symbol_check(
        module,
        guard_carrier_arch,
        access_model,
        collect_static_call_stats,
        enable_exact_module_calls,
        pre_lir_transform_policy,
        input_validation_policy,
        license,
        object_symbols,
        BackendSymbolCheck::Refuse,
        None,
        FunctionRefusals::FailFast,
    )
}

#[allow(clippy::too_many_arguments)]
fn translate_module_with_backend_symbol_check<'module>(
    module: &'module TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
    access_model: ObjectAccessModel,
    collect_static_call_stats: bool,
    enable_exact_module_calls: bool,
    pre_lir_transform_policy: PreLirTransformPolicy,
    input_validation_policy: InputValidationPolicy<'_>,
    license: &CodegenLicensePolicy,
    object_symbols: ObjectSymbolPolicy,
    backend_symbols: BackendSymbolCheck,
    native_scalar_c_abi: Option<&crate::NativeAbiContext>,
    mut refusals: FunctionRefusals<'_>,
) -> Result<ValidatedModuleTranslationWithOptionalStats<'module>, AdapterError> {
    if let Some(native) = native_scalar_c_abi {
        native.reconcile_driver(guard_carrier_arch, access_model)?;
    }
    match input_validation_policy {
        InputValidationPolicy::RunPrerequisites => {
            time_adapter_stage("validate-refinement", module, || {
                validate_codegen_prerequisites(module)
            })?;
            reject_unconsumed_v41_surface_with_imports_and_native(
                module,
                guard_carrier_arch,
                object_symbols,
                license.authenticated_imports(),
                native_scalar_c_abi,
            )?;
        }
        InputValidationPolicy::ReuseCompleteReport => {
            // Generic TrustIR validity does not establish native
            // representability, and `validate_module` deliberately lets a
            // module CARRY the v41 constructs this backend cannot consume,
            // so both gates run here too.
            reject_unlegalized_module_types(module)?;
            // ... and it admits a well-formed `Dealloc`: G18-1 is trust-ir's
            // CODEGEN verdict, read here from its own lowerability layer over
            // every body, as `validate_codegen_prerequisites` reads it.
            refuse_dealloc_by_trust_ir_verdict(module)?;
            reject_unconsumed_v41_surface_with_imports_and_native(
                module,
                guard_carrier_arch,
                object_symbols,
                license.authenticated_imports(),
                native_scalar_c_abi,
            )?;
        }
        // `prepare_module_for_lir` ran both gates on this exact owner.
        InputValidationPolicy::ReusePreparedPrerequisites => {}
        InputValidationPolicy::Admitted(admitted) => {
            // The typestate binds the admission to the module lowered here.
            if !std::ptr::eq(admitted.module(), module) {
                return Err(AdapterError::InvalidTrustIr(
                    "an admitted-module entry was handed a module other than the one admitted"
                        .into(),
                ));
            }
            // Admission ran trust-ir's full codegen admission (a superset of
            // the prerequisites walk's VALIDATOR findings); the
            // native-representability gates are this backend's own and still
            // run, and so do the prerequisites walk's two non-validator rules
            // (the source Switch-literal funnel and the v61 license-evidence
            // rule), which the admission does not run.
            reject_unlegalized_module_types(module)?;
            if let Some(error) = trust_ir_build::codegen_switch_case_literal_errors(module)
                .into_iter()
                .next()
            {
                return Err(AdapterError::TrustIrAdmissionRefused {
                    error: error.to_string(),
                });
            }
            refuse_unevidenced_gates(module)?;
            reject_unconsumed_v41_surface_with_imports_and_native(
                module,
                guard_carrier_arch,
                object_symbols,
                license.authenticated_imports(),
                native_scalar_c_abi,
            )?;
        }
    }
    // DarwinPCS: a narrow FFI argument whose extension is unrecorded is
    // refused rather than extended by a guess (see the fn). Decided here, on
    // every module entry and every validation policy, because it depends on
    // the exact object target and not on the ISA alone.
    if guard_carrier_arch == GuardCarrierArch::AArch64
        && matches!(
            access_model.tls_dialect().aarch64_abi_variant(),
            Some(crate::abi::AArch64AbiVariant::Darwin)
        )
    {
        reject_unrecorded_narrow_ffi_extension_on_darwin(module)?;
    }
    // x86-64 vector compares follow trust-ir's per-cell rule (`docs/
    // dialects.md`): a vector `ICmp` on a cell the `chc_x86` manifest
    // publishes as fail-closed is refused on every x86-64 module entry and
    // every validation policy, through trust-ir's one reader (see the fn).
    if guard_carrier_arch == GuardCarrierArch::X86_64 {
        reject_x86_vector_icmp_cell_not_available(
            module,
            trust_ir::chc_x86_vector_icmp_cell_status,
        )?;
    }
    // The codegen LICENSE (trust-ir v41 `body_gate`) is decided on the
    // caller's module BEFORE any adapter-owned rewrite can touch it: a clone
    // that dropped `Ungated` to `None` would launder a below-tier body into
    // a claim-less state a Permit policy admits, and a rewritten body would
    // no longer be the one its TV certificate was replayed against. Every
    // entry point reaches this line. The census decides it per function, on
    // the same caller's module, and never lowers a body it refuses.
    let license_refused: HashSet<FuncId> = match &mut refusals {
        FunctionRefusals::FailFast => {
            license.enforce_module(module)?;
            HashSet::new()
        }
        FunctionRefusals::Census(rows) => {
            let mut refused = HashSet::new();
            for (id, error) in license.census_module(module)? {
                refused.insert(id);
                rows.push((id, error));
            }
            refused
        }
    };
    // Every object writer and the JIT resolve a name the backend references on
    // its own through the module's own symbols first, so a definition such a
    // reference would reach is refused here, on every public entry, strict
    // ones included. Only closed-JIT Core's planning path skips it: Core's
    // qualification refuses every such backend call itself.
    if backend_symbols == BackendSymbolCheck::Refuse {
        refuse_backend_symbol_shadow(module)?;
    }
    let original_module = module;
    let original_functions = Rc::new(ModuleFunctionCatalog::new(original_module));
    reject_ambiguous_function_catalog(&original_functions)?;

    if pre_lir_transform_policy == PreLirTransformPolicy::IdentityOnly {
        reject_pre_lir_transform_triggers(module, guard_carrier_arch, access_model.tls_dialect())?;
    }

    // Scalarize any Swift function with aggregate params/returns in the sound
    // subset into an equivalent flat-scalar-signature function BEFORE the
    // adapter runs, so the already-verified scalar-swiftcc path (byte-identical
    // to clang's `swiftcall`) lowers the aggregate case with no ISel change.
    // Out-of-subset aggregate swiftcc signatures are left untouched here and
    // stay fail-closed at the per-function / call guards below. Returns `None`
    // (no clone) when there is nothing to rewrite.
    //
    // The field-wise Swift aggregate register lowering this reproduces is the
    // aarch64-apple-darwin (Apple ARM64) swiftcall ABI. On every other target
    // the Swift aggregate ABI differs, so the scalarization is NOT applied
    // there and those aggregate swiftcc signatures stay fail-closed.
    let mut rewritten = if pre_lir_transform_policy == PreLirTransformPolicy::LegacyCompatibility
        && guard_carrier_arch == GuardCarrierArch::AArch64
    {
        match access_model.tls_dialect().aarch64_abi_variant() {
            Some(variant) => swift_rewrite_module(module, variant)?,
            None => None,
        }
    } else {
        None
    };
    // A transformed clone keeps no source manifest its new module image
    // cannot back (see `drop_stale_source_manifests`).
    if let Some(clone) = rewritten.as_mut() {
        drop_stale_source_manifests(clone);
    }
    let module = rewritten.as_ref().unwrap_or(module);

    // PRODUCER: attach `ProofAnnotation::DivNonZero` to div/rem nodes whose
    // divisor is a proven-nonzero compile-time integer literal, BEFORE the
    // per-function adapter runs (the adapter reads `node.proofs` to decide
    // whether to synthesize the eliminable `GuardDivZero` carrier vs. the real
    // trap). Runs on the post-swift-rewrite module and, like the swift rewrite,
    // clones only when there is something to annotate. Arch-independent: the
    // annotation licenses guard elision on every target (x86 is the measured
    // win; AArch64 benefits identically).
    let mut div_annotated = (pre_lir_transform_policy
        == PreLirTransformPolicy::LegacyCompatibility)
        .then(|| {
            time_adapter_stage("div-nonzero-annotate", module, || {
                div_nonzero_const_annotate_module(module)
            })
        })
        .flatten();
    if let Some(clone) = div_annotated.as_mut() {
        drop_stale_source_manifests(clone);
    }
    let module = div_annotated.as_ref().unwrap_or(module);

    // Validation facts are tied to the exact module value that was checked.
    // The Swift and division annotation passes are definition-preserving today,
    // but treating that implementation detail as transferable authority would
    // make a future transform change silently unsound.  Revalidate only on the
    // rare cloned path; the overwhelmingly common identity path keeps the one
    // validation pass it had above.
    if !std::ptr::eq(module, original_module) {
        // The adapter's OWN definition-preserving transforms (Swift ABI
        // scalarization, divisor annotation) are part of this lowering, not an
        // ingestion: their output is held to the prerequisites walk on every
        // policy, an admitted module's included. (A pre-adapter rewrite that
        // PRODUCES new core IR — the codegen crate's dialect lowering — is
        // re-admitted by its caller, `AdmittedModule::readmit_rewritten`.)
        time_adapter_stage("validate-transformed-prerequisites", module, || {
            validate_codegen_prerequisites(module)
        })?;
    }

    // Swift ABI scalarization and constant-divisor annotation clone the
    // TrustIR module.  Their transformed value is revalidated above, but the
    // public validation report borrows the caller-owned input.  Until the
    // report can own and authenticate the exact transformed source value, a
    // validated translation must not mint or retain any identity whose JIT or
    // object binding depends on that clone.  This is intentionally broader
    // than compatible recovered calls: direct Invoke/variadic edges and
    // escaped or incompatible function constants carry the same identity.
    if enable_exact_module_calls && !std::ptr::eq(module, original_module) {
        let census = module_local_function_identity_census(module);
        if !census.is_empty() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "validated translation cannot preserve module-local function identity across an adapter-owned module clone: {} direct edge(s), {} materialized function identity value(s)",
                census.direct_edges, census.materialized_identities
            )));
        }
    }

    // Reuse the exact input catalog when transforms were dormant. A rewritten
    // module gets its own catalog and duplicate audit; authority never crosses
    // a cloned module merely because its coordinates happen to look alike.
    let functions = if std::ptr::eq(module, original_module) {
        original_functions
    } else {
        drop(original_functions);
        let functions = Rc::new(ModuleFunctionCatalog::new(module));
        reject_ambiguous_function_catalog(&functions)?;
        functions
    };
    // The report is replayed against the caller-owned input module. Until the
    // returned bundle owns an adapter-transformed clone, exact authority must
    // neither cross that value boundary nor be minted by legacy APIs that
    // return LIR without a report.
    let enable_exact_module_calls =
        enable_exact_module_calls && std::ptr::eq(module, original_module);
    let native_nominal_values = native_scalar_c_abi
        .map(|native| crate::native_nominal_values::ModuleValues::native(module, native))
        .transpose()?
        .filter(|values| !values.is_empty())
        .map(Rc::new);

    // Precompute the set of pure functions in the module. Each adapter
    // instance is seeded with this set so Call translation can tag
    // pure-callee names without re-scanning. #456.
    let pure_func_ids = Rc::new(collect_pure_func_ids_for_access_model(module, access_model));
    let libm_pure_func_ids = Rc::new(collect_libm_pure_func_ids(module));
    let external_func_ids = Rc::new(collect_bodyless_external_func_ids(module));
    let mut results = Vec::new();
    let static_call_stats = collect_static_call_stats
        .then(|| Rc::new(RefCell::new(StaticCallDevirtualizationStats::default())));
    let mut validation = ModuleTranslationValidationReport::new(original_module);
    let sequence_module_facts = Rc::default();
    let eh_type_table_cell = Rc::default();
    // One module-local geometry/reach memo, not one graph index per function.
    let storage_geometry = Rc::new(crate::storage_geometry::Resolver::default());
    for func in &module.functions {
        if is_bodyless_external_declaration(func) || license_refused.contains(&func.id) {
            continue;
        }
        let mut adapter =
            TrustIrAdapter::new_with_types(&module.structs, &module.types, functions.clone());
        adapter.module = Some(module);
        adapter.storage_geometry = Rc::clone(&storage_geometry);
        adapter.enums = &module.enums;
        adapter.set_guard_carrier_arch(guard_carrier_arch);
        adapter.set_object_access_model(access_model);
        adapter.native_scalar_c_abi = native_scalar_c_abi.cloned();
        adapter.native_nominal_values = native_nominal_values.clone();
        adapter.share_sequence_module_facts(Rc::clone(&sequence_module_facts));
        adapter.share_module_eh_type_table(Rc::clone(&eh_type_table_cell));
        if enable_exact_module_calls {
            adapter.enable_exact_module_calls();
        }
        if pre_lir_transform_policy == PreLirTransformPolicy::IdentityOnly {
            adapter.retain_declared_external_function_ids();
        }
        adapter.seed_pure_function_ids(pure_func_ids.clone());
        adapter.seed_libm_pure_function_ids(libm_pure_func_ids.clone());
        adapter.seed_external_function_ids(external_func_ids.clone());
        if let Some(stats) = &static_call_stats {
            adapter.seed_static_call_devirtualization_stats(stats.clone());
        }
        let translated = adapter.translate(func).and_then(|(lir_func, proofs)| {
            validation.record_translated_function(
                results.len(),
                func.id,
                &lir_func,
                PendingDirectCallAuthorizations::new(
                    adapter.exact_module_calls_lowered,
                    std::mem::take(&mut adapter.exact_module_call_authorizations),
                    adapter.declared_external_calls_lowered,
                    std::mem::take(&mut adapter.declared_external_call_authorizations),
                ),
            )?;
            Ok((lir_func, proofs))
        });
        match (translated, &mut refusals) {
            (Ok(translated), _) => results.push(translated),
            (Err(error), FunctionRefusals::FailFast) => return Err(error),
            (Err(error), FunctionRefusals::Census(rows)) => rows.push((func.id, error)),
        }
    }
    let static_call_stats = static_call_stats.map(|stats| *stats.borrow());
    Ok((results, static_call_stats, validation))
}

/// An inline-only candidate that was not translated, and why. Every call to
/// it stays the external call the module entries already lower.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InlineOnlyWithheld {
    /// The candidate's symbol name.
    pub name: String,
    /// Why it was withheld (stable prose, for evidence and diagnostics).
    pub reason: String,
}

/// LIR translations of a module's inline-only bodies
/// ([`translate_inline_only_bodies`]).
#[derive(Debug, Default)]
pub struct InlineOnlyBodies {
    /// Translated bodies, in module order. None of them is a codegen unit:
    /// they are templates for a module inliner, never selected, emitted or
    /// published.
    pub bodies: Vec<(Function, ProofContext)>,
    /// Candidates not translated, in module order.
    pub withheld: Vec<InlineOnlyWithheld>,
}

/// Translate the bodies of `module`'s bodied `AvailableExternally` functions
/// into LIR as INLINE-ONLY candidates.
///
/// trust-ir `AvailableExternally` (LLVM `available_externally`) means "the
/// body is available for inlining; the definition is emitted elsewhere". The
/// module entries keep treating every such function as a codegen declaration
/// ([`is_bodyless_external_declaration`]): no body is emitted and every call
/// or address-take resolves to the external symbol. This entry adds the other
/// half: a body a module inliner may splice into a direct call instead of
/// calling the symbol. Using one rests on the one-definition-rule premise
/// that the body computes what the bound definition computes; the consumer
/// discloses it (or withholds the bodies where it cannot).
///
/// `module` must be the exact module a translation entry of this crate
/// admitted (the prerequisite and v41-surface gates are not repeated here).
/// Nothing here fails: a candidate this backend cannot or must not use is
/// withheld with a reason, and its calls stay external calls. Withheld:
///
/// * a body another object may replace at load time under `access_model`
///   ([`RelocationModel::definition_is_preemptible`] — a default-visibility
///   symbol in shared-object code), so the call must reach the symbol;
/// * a `swiftcc` body: the compatibility Swift rewrite may re-sign its call
///   sites, and the body is translated here from the unrewritten module;
/// * a body the codegen `license` refuses, or one the adapter cannot lower;
/// * a body that names a module-local (`Internal`/`Private`) symbol of THIS
///   module: the body is the defining object's, and those names are not its.
pub fn translate_inline_only_bodies(
    module: &TrustIrModule,
    guard_carrier_arch: GuardCarrierArch,
    access_model: ObjectAccessModel,
    license: &CodegenLicensePolicy,
) -> InlineOnlyBodies {
    let mut out = InlineOnlyBodies::default();
    let candidates: Vec<&TrustIrFunction> = module
        .functions
        .iter()
        .filter(|func| func.linkage == Linkage::AvailableExternally && func.has_body())
        .collect();
    if candidates.is_empty() {
        return out;
    }
    let withhold = |out: &mut InlineOnlyBodies, func: &TrustIrFunction, reason: String| {
        out.withheld.push(InlineOnlyWithheld {
            name: func.name.clone(),
            reason,
        });
    };
    let functions = Rc::new(ModuleFunctionCatalog::new(module));
    if let Err(error) = reject_ambiguous_function_catalog(&functions) {
        for func in candidates {
            withhold(
                &mut out,
                func,
                format!("ambiguous function catalog: {error}"),
            );
        }
        return out;
    }
    let pure_func_ids = Rc::new(collect_pure_func_ids_for_access_model(module, access_model));
    let libm_pure_func_ids = Rc::new(collect_libm_pure_func_ids(module));
    let external_func_ids = Rc::new(collect_bodyless_external_func_ids(module));
    // Symbols only this module can name: an inline-only body naming one would
    // bind it to this module's definition, not the defining object's.
    let storage_geometry = Rc::new(crate::storage_geometry::Resolver::default());
    let module_local_symbols: HashSet<&str> = module
        .functions
        .iter()
        .filter(|function| is_module_local_function_definition(function))
        .map(|function| function.name.as_str())
        .chain(
            module
                .globals
                .iter()
                .filter(|global| is_module_local_data_definition(global))
                .map(|global| global.name.as_str()),
        )
        .collect();
    for func in candidates {
        if definition_body_is_replaceable(func, access_model) {
            withhold(
                &mut out,
                func,
                "preemptible at load time under this relocation model: the call must reach the \
                 symbol"
                    .into(),
            );
            continue;
        }
        if func.calling_conv == CallingConv::Swift {
            withhold(
                &mut out,
                func,
                "swiftcc: the compatibility Swift rewrite may re-sign its call sites".into(),
            );
            continue;
        }
        // The license is decided on the MODULE (an evidence-bound authority's
        // evidence lives there); `func` is one of `module.functions`.
        if let Err(error) = license.verdict(module, func.id) {
            withhold(&mut out, func, format!("codegen license: {error}"));
            continue;
        }
        let mut adapter =
            TrustIrAdapter::new_with_types(&module.structs, &module.types, functions.clone());
        adapter.module = Some(module);
        adapter.storage_geometry = Rc::clone(&storage_geometry);
        adapter.enums = &module.enums;
        adapter.set_guard_carrier_arch(guard_carrier_arch);
        adapter.set_object_access_model(access_model);
        adapter.share_sequence_module_facts(Rc::default());
        adapter.share_module_eh_type_table(Rc::default());
        adapter.seed_pure_function_ids(pure_func_ids.clone());
        adapter.seed_libm_pure_function_ids(libm_pure_func_ids.clone());
        adapter.seed_external_function_ids(external_func_ids.clone());
        match adapter.translate(func) {
            Ok(translated) => match lir_names_one_of(&translated.0, &module_local_symbols) {
                Some(symbol) => withhold(
                    &mut out,
                    func,
                    format!(
                        "names the module-local symbol `{symbol}`: the body is the defining \
                         object's, whose module-local symbols are not this module's"
                    ),
                ),
                None => out.bodies.push(translated),
            },
            Err(error) => withhold(&mut out, func, format!("not lowerable: {error}")),
        }
    }
    out
}

/// Translate the body of `func`, a bodied function of `module`, into LIR the
/// way [`translate_inline_only_bodies`] translates an inline-only candidate:
/// same adapter configuration, same codegen `license` check, and the same
/// refusal of a body that names one of `module`'s module-local symbols.
///
/// This is the other half of authenticating an inline-only body: the
/// definition an authenticated dependency exports is translated in ITS module
/// by this entry and compared with the inline-only body's translation
/// ([`Function::canonical_body_identity`]). The two agree only when the same
/// adapter lowers both to the same LIR. Returns why it cannot, as prose.
pub fn translate_body_template(
    module: &TrustIrModule,
    func: &TrustIrFunction,
    guard_carrier_arch: GuardCarrierArch,
    access_model: ObjectAccessModel,
    license: &CodegenLicensePolicy,
) -> Result<(Function, ProofContext), String> {
    if !func.has_body() {
        return Err("no body".into());
    }
    let functions = Rc::new(ModuleFunctionCatalog::new(module));
    reject_ambiguous_function_catalog(&functions)
        .map_err(|error| format!("ambiguous function catalog: {error}"))?;
    // Decided on the value that holds exactly `func`, as
    // `translate_function_with_license` does.
    license
        .verdict(&module_holding_function(func, module), func.id)
        .map_err(|error| format!("codegen license: {error}"))?;
    let module_local_symbols: HashSet<&str> = module
        .functions
        .iter()
        .filter(|function| is_module_local_function_definition(function))
        .map(|function| function.name.as_str())
        .chain(
            module
                .globals
                .iter()
                .filter(|global| is_module_local_data_definition(global))
                .map(|global| global.name.as_str()),
        )
        .collect();
    let mut adapter =
        TrustIrAdapter::new_with_types(&module.structs, &module.types, functions.clone());
    adapter.module = Some(module);
    adapter.enums = &module.enums;
    adapter.set_guard_carrier_arch(guard_carrier_arch);
    adapter.set_object_access_model(access_model);
    adapter.share_sequence_module_facts(Rc::default());
    adapter.share_module_eh_type_table(Rc::default());
    adapter.seed_pure_function_ids(Rc::new(collect_pure_func_ids_for_access_model(
        module,
        access_model,
    )));
    adapter.seed_libm_pure_function_ids(Rc::new(collect_libm_pure_func_ids(module)));
    adapter.seed_external_function_ids(Rc::new(collect_bodyless_external_func_ids(module)));
    let translated = adapter
        .translate(func)
        .map_err(|error| format!("not lowerable: {error}"))?;
    if let Some(symbol) = lir_names_one_of(&translated.0, &module_local_symbols) {
        return Err(format!(
            "names the module-local symbol `{symbol}` of its module"
        ));
    }
    Ok(translated)
}

/// The first symbol among `symbols` that an instruction of `func` names (a
/// call, an address, a thread-local or global reference), if any.
fn lir_names_one_of(func: &Function, symbols: &HashSet<&str>) -> Option<String> {
    func.blocks
        .values()
        .flat_map(|block| &block.instructions)
        .find_map(|instruction| match &instruction.opcode {
            Opcode::GlobalRef { name }
            | Opcode::ExternRef { name }
            | Opcode::TlsRef { name, .. }
            | Opcode::Call { name, .. }
            | Opcode::CallVariadic { name, .. }
            | Opcode::Invoke { name, .. }
            | Opcode::FunctionAddr { name, .. }
                if symbols.contains(name.as_str()) =>
            {
                Some(name.clone())
            }
            _ => None,
        })
}

/// Translate a single trust_ir function to internal LIR + proof context.
///
/// When called standalone (not from `translate_module`), a minimal module
/// is constructed to provide the func_types table. For proper symbol
/// resolution, prefer `translate_module` which builds a function name table.
pub fn translate_function(
    func: &TrustIrFunction,
    module: &TrustIrModule,
) -> Result<(Function, ProofContext), AdapterError> {
    translate_function_with_license(func, module, &CodegenLicensePolicy::default())
}

/// [`translate_function`] under an explicit codegen-license policy. The
/// license is decided for `func` alone (only it is lowered); the v41 surface
/// gate runs on the whole module against the arch-neutral default carrier
/// architecture, exactly as this entry's guard-carrier default does. A
/// function the module entries would SKIP as a codegen declaration (bodyless
/// `External`, or `AvailableExternally` whatever its body) is refused here
/// (`AdapterError::DeclarationNotLowerable`) rather than lowered.
pub fn translate_function_with_license(
    func: &TrustIrFunction,
    module: &TrustIrModule,
    license: &CodegenLicensePolicy,
) -> Result<(Function, ProofContext), AdapterError> {
    validate_function_codegen_prerequisites(func, module)?;
    reject_unconsumed_v41_surface(module, GuardCarrierArch::default())?;
    refuse_backend_symbol_shadow(module)?;
    reject_codegen_declaration(func)?;
    // The license needs the MODULE (the evidence an evidence-bound authority
    // names lives there), decided on the value that holds exactly `func`.
    license.verdict(&module_holding_function(func, module), func.id)?;

    let functions = Rc::new(ModuleFunctionCatalog::new(module));
    reject_ambiguous_function_catalog(&functions)?;
    let mut adapter = TrustIrAdapter::new_with_types(&module.structs, &module.types, functions);
    adapter.module = Some(module);
    adapter.enums = &module.enums;
    // Seed pure-callees from the module even when translating a single
    // function; this lets tests exercise purity propagation without going
    // through `translate_module`. #456.
    adapter.seed_pure_function_ids(Rc::new(collect_pure_func_ids(module)));
    adapter.seed_libm_pure_function_ids(Rc::new(collect_libm_pure_func_ids(module)));
    adapter.seed_external_function_ids(Rc::new(collect_bodyless_external_func_ids(module)));
    adapter.translate(func)
}

/// Translate a single trust_ir function with an explicit function name table,
/// under the DEFAULT codegen-license policy (claim-less bodies refused,
/// DG-73). [`translate_function_with_names_and_license`] takes an explicit
/// one.
pub fn translate_function_with_names(
    func: &TrustIrFunction,
    module: &TrustIrModule,
    func_names: &HashMap<FuncId, String>,
) -> Result<(Function, ProofContext), AdapterError> {
    translate_function_with_names_and_license(
        func,
        module,
        func_names,
        &CodegenLicensePolicy::default(),
    )
}

/// [`translate_function_with_names`] under an explicit codegen-license
/// policy, decided for `func` against the module that holds it.
pub fn translate_function_with_names_and_license(
    func: &TrustIrFunction,
    module: &TrustIrModule,
    func_names: &HashMap<FuncId, String>,
    license: &CodegenLicensePolicy,
) -> Result<(Function, ProofContext), AdapterError> {
    validate_function_codegen_prerequisites(func, module)?;
    reject_unconsumed_v41_surface(module, GuardCarrierArch::default())?;
    refuse_backend_symbol_shadow(module)?;
    reject_codegen_declaration(func)?;
    license.verdict(&module_holding_function(func, module), func.id)?;

    let functions = Rc::new(ModuleFunctionCatalog::new_with_names(
        module,
        Some(func_names),
    ));
    reject_ambiguous_function_catalog(&functions)?;
    let mut adapter = TrustIrAdapter::new_with_types(&module.structs, &module.types, functions);
    adapter.module = Some(module);
    adapter.enums = &module.enums;
    adapter.seed_pure_function_ids(Rc::new(collect_pure_func_ids(module)));
    adapter.seed_libm_pure_function_ids(Rc::new(collect_libm_pure_func_ids(module)));
    adapter.seed_external_function_ids(Rc::new(collect_bodyless_external_func_ids(module)));
    adapter.translate(func)
}

/// Extract proof annotations from a trust_ir instruction node.
///
/// Translates `TrustIrProof` annotations from the trust_ir instruction into
/// the adapter's internal `Proof` representation. Operand-sensitive proofs
/// are decoded from the instruction that carries the annotation.
///
/// Algebraic properties (Pure, Associative, Commutative, Idempotent) are
/// extracted at instruction level when attached to individual instructions
/// (e.g., "this add is associative"). They also appear at function level
/// via `extract_function_proofs`.
pub fn extract_proofs(node: &InstrNode) -> Vec<Proof> {
    extract_proof_metadata(node).proofs
}

/// Extract rich proof facts from a trust_ir instruction node.
pub fn extract_proof_facts(node: &InstrNode) -> Vec<ProofFact> {
    extract_proof_metadata(node).facts
}

/// Extract typed diagnostics for trust_ir proof annotations intentionally not
/// represented in Trust Codegen proof metadata.
pub fn extract_proof_diagnostics(node: &InstrNode) -> Vec<ProofDropDiagnostic> {
    extract_proof_metadata(node).diagnostics
}

/// Extract all proof metadata from a trust_ir instruction node.
pub fn extract_proof_metadata(node: &InstrNode) -> ExtractedProofMetadata {
    extract_proof_metadata_from_node(node)
}

/// Extract function-level proof annotations from a trust_ir function.
///
/// Translatable function-level proofs describe properties of the entire
/// function (for example, that its operation is commutative) and are stored in
/// `ProofContext::function_proofs`. Raw `Pure` is deliberately not translated
/// because it is a producer claim rather than replayed authority.
pub fn extract_function_proofs(func: &TrustIrFunction) -> Vec<Proof> {
    extract_function_proof_metadata(func).proofs
}

/// Extract rich function-level proof facts from a trust_ir function.
pub fn extract_function_proof_facts(func: &TrustIrFunction) -> Vec<ProofFact> {
    extract_function_proof_metadata(func).facts
}

/// Extract function-level proof drop diagnostics from a trust_ir function.
pub fn extract_function_proof_diagnostics(func: &TrustIrFunction) -> Vec<ProofDropDiagnostic> {
    extract_function_proof_metadata(func).diagnostics
}

/// Extract all function-level proof metadata from a trust_ir function.
pub fn extract_function_proof_metadata(func: &TrustIrFunction) -> ExtractedProofMetadata {
    extract_proof_metadata_from_annotations(&func.proofs)
}

/// Get the proof obligation summary for a trust_ir module.
///
/// Returns the `ProofSummary` from trust_ir's `Module::proof_summary()` API
/// (added in trust_ir rev 1357fbd). Trust Codegen uses this to decide whether
/// cross-target synthesis (GPU/ANE/SIMD) should be attempted. Modules
/// with pending or failed proof obligations should be treated conservatively
/// by the heterogeneous dispatch pipeline.
pub fn module_proof_summary(module: &TrustIrModule) -> trust_ir::ProofSummary {
    module.proof_summary()
}

/// Check if a trust_ir function carries a raw `Pure` claim.
///
/// Delegates to trust_ir's `Function::is_pure()` method (added in trust_ir rev 1357fbd),
/// which checks for `ProofAnnotation::Pure` in the function's proof annotations.
/// This report-only query does not authorize optimization or cross-target
/// dispatch; the adapter derives call purity from the function body instead.
pub fn function_is_pure(func: &TrustIrFunction) -> bool {
    func.is_pure()
}

fn alloca_debug_provenance_var_id(slot: u32) -> Option<TrustIrVarId> {
    (slot & !DEBUG_PROVENANCE_VAR_INDEX_MASK == 0)
        .then_some(TrustIrVarId(ALLOCA_DEBUG_PROVENANCE_VAR_TAG | slot))
}

fn const_value_debug_provenance_var_id(origin: TrustIrInstId) -> Option<TrustIrVarId> {
    (origin.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK == 0).then_some(TrustIrVarId(
        CONST_VALUE_DEBUG_PROVENANCE_VAR_TAG | origin.0,
    ))
}

fn value_debug_provenance_var_id(origin: TrustIrInstId) -> Option<TrustIrVarId> {
    (origin.0 & !DEBUG_PROVENANCE_VAR_INDEX_MASK == 0)
        .then_some(TrustIrVarId(VALUE_DEBUG_PROVENANCE_VAR_TAG | origin.0))
}

fn const_value_debug_local(node: &InstrNode, origin: TrustIrInstId) -> Option<DebugLocalVariable> {
    let span = node.span.as_ref()?;
    let Inst::Const { ty, value } = &node.inst else {
        return None;
    };
    match value {
        Constant::Ext(e) => e.unreachable(),
        Constant::Int(_) | Constant::Bool(_) => {}
        // trust-ir v24 U128: value lowering exists, but debug provenance for a
        // two-register 128-bit materialization is not modeled yet.
        Constant::U128(_)
        | Constant::TensorBlob { .. }
        | Constant::Bytes { .. }
        | Constant::Float(_)
        | Constant::Aggregate(_)
        | Constant::Array(_)
        | Constant::Splat { .. }
        | Constant::Vector(_)
        | Constant::Sequence(_)
        | Constant::Set(_)
        | Constant::Record(_)
        | Constant::Closure { .. }
        | Constant::FnItem(_)
        | Constant::FnDef(_)
        | Constant::SymbolAddr { .. }
        | Constant::PhantomData
        | Constant::Uninit => return None,
    }
    let debug_ty = debug_base_type_from_trust_ir(ty)?;
    let var_id = const_value_debug_provenance_var_id(origin)?;
    Some(DebugLocalVariable {
        name: format!("const_{}", origin.0),
        ty: debug_ty,
        storage: DebugVariableStorage::ProvenanceVar(var_id),
        decl_line: span.line,
    })
}

fn source_spanned_value_debug_local(
    node: &InstrNode,
    origin: TrustIrInstId,
) -> Option<DebugLocalVariable> {
    let span = node.span.as_ref()?;
    if node.results.len() != 1 {
        return None;
    }
    let Inst::BinOp { ty, .. } = &node.inst else {
        return None;
    };
    let debug_ty = debug_base_type_from_trust_ir(ty)?;
    if debug_base_type_size(debug_ty) > 8 {
        return None;
    }
    let var_id = value_debug_provenance_var_id(origin)?;
    Some(DebugLocalVariable {
        name: format!("value_{}", origin.0),
        ty: debug_ty,
        storage: DebugVariableStorage::ProvenanceVar(var_id),
        decl_line: span.line,
    })
}

/// Filter a trust_ir instruction node's proof annotations to only GPU-relevant ones.
///
/// Uses trust_ir's `ProofAnnotation::is_gpu_relevant()` classification method
/// (added in trust_ir rev 1357fbd) to identify proofs relevant for cross-target
/// synthesis (GPU/ANE/SIMD). GPU-relevant annotations are: Pure, InBounds,
/// NoOverflow, Commutative, Associative, Deterministic, ValidBorrow.
///
/// Returns translated `Proof` values (adapter-internal representation) for
/// only the GPU-relevant subset of the instruction's proof annotations. Raw
/// `Pure` claims are intentionally withheld by the translator until an exact
/// authorization carrier exists.
pub fn gpu_relevant_proofs(node: &InstrNode) -> Vec<Proof> {
    node.proofs
        .iter()
        .filter(|p| p.is_gpu_relevant())
        .filter_map(|p| translate_trust_ir_proof_for_node(p, node))
        .collect()
}

// ---------------------------------------------------------------------------
// Source debug info extraction
// ---------------------------------------------------------------------------

fn debug_base_type_from_trust_ir(ty: &Ty) -> Option<DebugBaseType> {
    match ty {
        Ty::I8 => Some(DebugBaseType::I8),
        Ty::I16 => Some(DebugBaseType::I16),
        Ty::I32 => Some(DebugBaseType::I32),
        Ty::I64 => Some(DebugBaseType::I64),
        Ty::I128 => Some(DebugBaseType::I128),
        Ty::U8 => Some(DebugBaseType::U8),
        Ty::U16 => Some(DebugBaseType::U16),
        Ty::U32 => Some(DebugBaseType::U32),
        Ty::U64 => Some(DebugBaseType::U64),
        Ty::U128 => Some(DebugBaseType::U128),
        // B1 pointer-width / char scalars: DWARF-model isize/usize as the
        // 64-bit signed/unsigned base types, char as unsigned 32-bit.
        Ty::Isize => Some(DebugBaseType::I64),
        Ty::Usize => Some(DebugBaseType::U64),
        Ty::Char => Some(DebugBaseType::U32),
        Ty::F32 => Some(DebugBaseType::F32),
        Ty::F64 => Some(DebugBaseType::F64),
        Ty::Bool => Some(DebugBaseType::Bool),
        Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Rc(_) => {
            Some(DebugBaseType::Ptr)
        }
        Ty::Func(_) => Some(DebugBaseType::Ptr),
        _ => None,
    }
}

fn debug_base_type_size(ty: DebugBaseType) -> u32 {
    match ty {
        DebugBaseType::Bool | DebugBaseType::I8 | DebugBaseType::U8 => 1,
        DebugBaseType::I16 | DebugBaseType::U16 => 2,
        DebugBaseType::I32 | DebugBaseType::U32 | DebugBaseType::F32 => 4,
        DebugBaseType::I64 | DebugBaseType::U64 | DebugBaseType::F64 | DebugBaseType::Ptr => 8,
        DebugBaseType::I128 | DebugBaseType::U128 => 16,
    }
}

fn debug_align_to(offset: u32, align: u32) -> u32 {
    if align <= 1 {
        offset
    } else {
        let rem = offset % align;
        if rem == 0 {
            offset
        } else {
            offset + (align - rem)
        }
    }
}

fn debug_base_type_align(ty: DebugBaseType) -> u32 {
    debug_base_type_size(ty).min(8)
}

fn extract_debug_struct_types(module: &TrustIrModule) -> Vec<DebugStructType> {
    module
        .structs
        .iter()
        .filter_map(|sdef| {
            let mut next_offset = 0u32;
            let mut max_align = 1u32;
            let mut members = Vec::with_capacity(sdef.fields.len());

            for field in &sdef.fields {
                let ty = debug_base_type_from_trust_ir(&field.ty)?;
                let align = debug_base_type_align(ty);
                max_align = max_align.max(align);

                let offset = match field.offset {
                    Some(offset) => u32::try_from(offset).ok()?,
                    None => debug_align_to(next_offset, align),
                };

                members.push(DebugStructMember {
                    name: field.name.clone(),
                    offset,
                    ty,
                });
                next_offset = offset.checked_add(debug_base_type_size(ty))?;
            }

            let byte_size = match sdef.size {
                Some(size) => u32::try_from(size).ok()?,
                None => debug_align_to(next_offset, max_align),
            };

            Some(DebugStructType {
                name: sdef.name.clone(),
                byte_size,
                members,
            })
        })
        .collect()
}

fn extract_debug_enum_types(enums: &[EnumDef]) -> Vec<DebugEnumType> {
    enums
        .iter()
        .map(|edef| DebugEnumType {
            name: edef.name.clone(),
            byte_size: debug_base_type_size(DebugBaseType::U32),
            underlying_type: DebugBaseType::U32,
            enumerators: edef
                .variants
                .iter()
                .enumerate()
                .map(|(idx, variant)| DebugEnumerator {
                    name: variant.name.clone(),
                    value: idx as i64,
                })
                .collect(),
        })
        .collect()
}

/// Debug information extracted from a trust_ir function for DWARF emission.
///
/// This is a lightweight summary of source-level metadata that the adapter
/// extracts from the trust_ir representation. The compilation pipeline carries
/// it through to the codegen for populating DWARF debug sections.
#[derive(Debug, Clone, Default)]
pub struct SourceDebugInfo {
    /// Parameter names (generated as "arg0", "arg1", ... since trust_ir
    /// does not carry parameter names in the IR).
    pub param_names: Vec<String>,
    /// Source line where the function is declared (1-based, 0 = unknown).
    /// Derived from the first instruction span in the entry block.
    pub decl_line: u32,
    /// Source spans collected from all instructions: (line, col, block_index, instr_index).
    /// Used to generate DWARF line number program entries.
    pub source_spans: Vec<SourceSpanEntry>,
    /// Resolved source file PATH for this function, looked up in the module's
    /// `files` debug-info table via the entry-block span's `file` index. This is
    /// the real path the frontend stamped (e.g. `.../wholeprog23_slice.rs`), so
    /// DWARF `.debug_line`/`DW_AT_name` names the true source rather than a
    /// synthetic `<module>.rs`. `None` when the function carries no span (or the
    /// index is out of range) — the caller then falls back to a synthetic name.
    pub source_file: Option<String>,
    /// Aggregate type definitions available in the trust_ir module.
    pub struct_types: Vec<DebugStructType>,
    /// Enum type definitions available in the trust_ir module.
    pub enum_types: Vec<DebugEnumType>,
}

/// A single source span entry from a trust_ir instruction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SourceSpanEntry {
    /// Source file index (from trust_ir SourceSpan.file).
    pub file: u32,
    /// Source line number (1-based).
    pub line: u32,
    /// Source column number (0 = unknown).
    pub col: u32,
    /// Block index in the trust_ir function's block list.
    pub block_idx: usize,
    /// Instruction index within the block.
    pub instr_idx: usize,
}

/// Extract source debug information from a trust_ir function.
///
/// Walks the trust_ir function to collect:
/// - Parameter names (generated from the function signature param count)
/// - Declaration line (first span in the entry block)
/// - All instruction source spans for line number program generation
///
/// This information is carried on [`trust_cg_ir::function::FunctionDebugMeta`]
/// through the pipeline and consumed by DWARF emission.
pub fn extract_source_debug_info(
    func: &TrustIrFunction,
    module: &TrustIrModule,
) -> SourceDebugInfo {
    let mut info = SourceDebugInfo {
        struct_types: extract_debug_struct_types(module),
        enum_types: extract_debug_enum_types(&module.enums),
        ..Default::default()
    };

    // Extract parameter names from the function signature.
    // trust_ir doesn't carry parameter names, so generate synthetic ones.
    let func_ty_idx = func.ty.0 as usize;
    if func_ty_idx < module.func_types.len() {
        let func_ty = &module.func_types[func_ty_idx];
        for i in 0..func_ty.params.len() {
            info.param_names.push(format!("arg{}", i));
        }
    }

    // Find the entry block and extract the declaration line AND source file
    // from its first span. The span's `file` is an index into the module's
    // `files` debug-info table (populated by the frontend `intern_file`); resolve
    // it to the real path so DWARF names the true source, not a synthetic name.
    if let Some(entry_block) = func.blocks.iter().find(|b| b.id == func.entry) {
        for node in &entry_block.body {
            if let Some(span) = &node.span {
                info.decl_line = span.line;
                info.source_file = module.files.get(span.file as usize).cloned();
                break;
            }
        }
    }

    // Collect all source spans from all blocks.
    for (block_idx, block) in func.blocks.iter().enumerate() {
        for (instr_idx, node) in block.body.iter().enumerate() {
            if let Some(span) = &node.span {
                info.source_spans.push(SourceSpanEntry {
                    file: span.file,
                    line: span.line,
                    col: span.col,
                    block_idx,
                    instr_idx,
                });
            }
        }
    }

    info
}

/// Translate a context-free trust_ir ProofAnnotation to the adapter's Proof
/// representation. Proofs that require operands are handled by
/// `translate_trust_ir_proof_for_node` so we never fabricate placeholder ValueIds.
fn translate_trust_ir_proof(p: &ProofAnnotation) -> Option<Proof> {
    match p {
        ProofAnnotation::InBounds
        | ProofAnnotation::NotNull
        | ProofAnnotation::ValidBorrow
        | ProofAnnotation::UniqueBorrow
        | ProofAnnotation::SharedBorrow
        | ProofAnnotation::DivNonZero
        | ProofAnnotation::ShiftInRange => None,
        ProofAnnotation::ValidDealloc => None,
        // trust_ir information-flow + codegen-hint annotations carry no CPU
        // `Proof`: `Tainted`/`TrustedSink` are non-interference markers enforced
        // by the verifier (`trust-ir-build`), not codegen; `BranchWeights` is a
        // block-layout hint with no operational semantics (the reference
        // interpreter ignores it). Drop them here — they remain available to the
        // verifier via `trust_ir::ProofAnnotation`.
        ProofAnnotation::Tainted
        | ProofAnnotation::TrustedSink
        | ProofAnnotation::BranchWeights(_) => None,
        ProofAnnotation::NoOverflow => Some(Proof::NoOverflow { signed: true }),
        ProofAnnotation::NoWrap => Some(Proof::NoOverflow { signed: false }),
        // `Wrapping` (trust_ir 64473f7) marks modular arithmetic: two's-complement
        // wrap-around IS the defined result of the annotated `BinOp`, so the
        // verifier must not generate a no-overflow obligation for it. It is a
        // semantic marker, not a dischargeable claim. The CPU lowering already
        // implements exactly that semantics — plain `BinOp::Add/Sub/Mul` lower to
        // plain machine ops (`Iadd`/`Isub`/`Imul`), which wrap in two's
        // complement, and no overflow check is emitted for unannotated BinOps.
        // There is therefore nothing for the CPU `Proof` enum to carry. It MUST
        // NOT map to `Proof::NoOverflow`: that asserts the opposite fact ("this
        // op never wraps") and licenses overflow-check elision and range
        // reasoning that are unsound for intentionally-wrapping ops.
        ProofAnnotation::Wrapping => None,
        // Raw `Pure` is a producer claim with no replayed, module-bound
        // authority. Keep it in trust_ir for reporting, but never translate it
        // into behavior-authorizing Trust Codegen proof metadata. Function-call
        // purity is independently recovered by the fail-closed structural
        // fixpoint in `compute_structural_pure_func_ids`.
        ProofAnnotation::Pure => None,
        ProofAnnotation::Terminates => None,
        ProofAnnotation::Deterministic => None,
        ProofAnnotation::Associative => Some(Proof::Associative),
        ProofAnnotation::Commutative => Some(Proof::Commutative),
        ProofAnnotation::DataRaceFree => None,
        ProofAnnotation::AtomicOrdering(_) => None,
        ProofAnnotation::BoundedOutput { lo, hi } => Some(Proof::InRange {
            lo: lo.floor() as i128,
            hi: hi.ceil() as i128,
        }),
        ProofAnnotation::Monotonic => None,
        ProofAnnotation::NoAlias => None,
        ProofAnnotation::Aligned(_) => None,
        ProofAnnotation::NoPanic => None,
        ProofAnnotation::NoUndef => None,
        // A public, forgeable marker on an `Undef` saying that the producer
        // intends a fresh unconstrained symbolic value. It proves and narrows
        // nothing, and the machine-code adapter already lowers `Undef` without
        // consulting annotations. Keep it inert here: mapping it to any CPU
        // `Proof` would accidentally turn producer metadata into authority.
        ProofAnnotation::FreshSymbolicHavoc => None,
        // A verifier-model marker selecting whole-region havoc semantics. It
        // cannot mint a CPU proof, and `translate_instruction` fails closed on
        // every occurrence because LIR has no sound whole-region lowering.
        ProofAnnotation::RegionHavocStore => None,
        // trust_ir#30 additions: GPU memory-role hints, parallel/bounded-loop
        // annotations, and divergence classification. These are consumed by
        // the heterogeneous compute planner (`target_analysis.rs` /
        // `dispatch.rs`) rather than by the CPU Proof enum. The CPU adapter
        // currently has no Proof variants to map them to, so drop them here;
        // GPU-relevant lookups should go through `trust_ir::ProofAnnotation`
        // directly (see `is_gpu_relevant`) not through this CPU adapter.
        ProofAnnotation::ReadonlyTable
        | ProofAnnotation::AppendOnlyBuffer
        | ProofAnnotation::AtomicSetInsert
        | ProofAnnotation::ParallelMap
        | ProofAnnotation::BoundedLoop(_)
        | ProofAnnotation::DivergenceClass(_) => None,
        ProofAnnotation::Custom(_) => None,
        // Goal annotations describe proof obligations to be solved; they are not proof evidence and
        // cannot authorize a CPU transform.  Preserve them in Trust-IR/reporting and drop them at
        // this behavior-changing adapter boundary.
        ProofAnnotation::Goal(_) => None,
        // trust_ir fast-1: proof-backed annotation referencing a module-level
        // obligation. The CPU adapter's `Proof` enum has no corresponding
        // variant, so drop it here (validation of the backing obligation is the
        // verifier's job); fail closed by mapping to no CPU proof.
        ProofAnnotation::ProofRef(_) => None,
        // trust_ir fast-3 value-fact annotations. `ValueRange` is exactly the
        // adapter's InRange value-range proof. `KnownBits` (zero/one bit masks)
        // has no corresponding CPU `Proof` variant, so it is dropped here
        // (still available to the verifier via `trust_ir::ProofAnnotation`).
        ProofAnnotation::ValueRange { lo, hi } => Some(Proof::InRange { lo: *lo, hi: *hi }),
        ProofAnnotation::KnownBits { .. } => None,
    }
}

fn translate_trust_ir_proof_for_node(p: &ProofAnnotation, node: &InstrNode) -> Option<Proof> {
    match p {
        ProofAnnotation::InBounds => translate_in_bounds_proof(node),
        ProofAnnotation::NotNull => translate_not_null_proof(node),
        ProofAnnotation::ValidBorrow
        | ProofAnnotation::UniqueBorrow
        | ProofAnnotation::SharedBorrow => translate_valid_borrow_proof(node),
        ProofAnnotation::DivNonZero => translate_div_nonzero_proof(node),
        ProofAnnotation::ShiftInRange => translate_shift_in_range_proof(node),
        _ => translate_trust_ir_proof(p),
    }
}

fn translate_in_bounds_proof(node: &InstrNode) -> Option<Proof> {
    match &node.inst {
        Inst::GEP { base, indices, .. } => match indices.as_slice() {
            [index] => Some(Proof::InBounds {
                base: *base,
                index: *index,
            }),
            _ => None,
        },
        Inst::ExtractElement { array, index, .. } | Inst::InsertElement { array, index, .. } => {
            Some(Proof::InBounds {
                base: *array,
                index: *index,
            })
        }
        _ => None,
    }
}

fn translate_not_null_proof(node: &InstrNode) -> Option<Proof> {
    pointer_proof_value(node).map(|ptr| Proof::NotNull { ptr })
}

fn translate_valid_borrow_proof(node: &InstrNode) -> Option<Proof> {
    pointer_proof_value(node).map(|borrow| Proof::ValidBorrow { borrow })
}

fn integer_div_or_rem_has_nonzero_proof(op: BinOp, node: &InstrNode) -> bool {
    matches!(op, BinOp::UDiv | BinOp::SDiv | BinOp::URem | BinOp::SRem)
        && node
            .proofs
            .iter()
            .any(|proof| matches!(proof, ProofAnnotation::DivNonZero))
}

fn shift_has_in_range_proof(op: BinOp, ty: &Ty, node: &InstrNode) -> Option<u16> {
    matches!(op, BinOp::Shl | BinOp::LShr | BinOp::AShr)
        .then(|| supported_shift_guard_bitwidth(ty))
        .flatten()
        .filter(|_| {
            node.proofs
                .iter()
                .any(|proof| matches!(proof, ProofAnnotation::ShiftInRange))
        })
}

fn memory_ptr_has_not_null_proof(node: &InstrNode) -> bool {
    matches!(node.inst, Inst::Load { .. } | Inst::Store { .. })
        && node
            .proofs
            .iter()
            .any(|proof| matches!(proof, ProofAnnotation::NotNull))
}

/// Decide whether an `Inst::Overflow` node carries a genuine, *signedness-matching* discharged
/// no-overflow annotation that licenses routing its overflow check through the eliminable
/// `GuardOverflow` carrier.
///
/// Returns `true` ONLY when the node is an `Inst::Overflow` AND its `node.proofs` contains the
/// annotation whose signedness matches `is_unsigned`:
///   * signed op   (`is_unsigned == false`) requires `ProofAnnotation::NoOverflow` (maps to
///     `Proof::NoOverflow { signed: true }`),
///   * unsigned op (`is_unsigned == true`)  requires `ProofAnnotation::NoWrap`     (maps to
///     `Proof::NoOverflow { signed: false }`).
///
/// FAIL-SAFE / SOUNDNESS: `ProofAnnotation::Wrapping` is NEVER treated as no-overflow — it means
/// intentional two's-complement wrap, the OPPOSITE of "never overflows" (see
/// `translate_trust_ir_proof`). A signed proof must never license eliding an unsigned check and vice
/// versa, so the signedness must match exactly; the carrier's op-tag signedness is keyed to the same
/// `is_unsigned`, so a mismatch here would also fail to bind downstream — but we reject it up front so
/// no carrier is even emitted. Any other / absent annotation returns `false` → keep the legacy path.
fn overflow_has_no_overflow_proof(node: &InstrNode, is_unsigned: bool) -> bool {
    matches!(node.inst, Inst::Overflow { .. })
        && node.proofs.iter().any(|proof| {
            if is_unsigned {
                matches!(proof, ProofAnnotation::NoWrap)
            } else {
                matches!(proof, ProofAnnotation::NoOverflow)
            }
        })
}

/// True iff `target` is used as a VALUE OPERAND anywhere in `func` (block params are SSA defs, not
/// uses, so they are not counted).
///
/// This drives the overflow-carrier rewrite's flag-liveness gate: the rewrite replaces the entangled
/// (value, overflow-flag) lowering with a plain wrapping op + a self-contained `GuardOverflow` carrier
/// + a CONSTANT-FALSE flag. Folding the observable overflow boolean to `false` is only emitted when a
///   genuine DISCHARGED no-overflow proof is present (so the flag is provably false), but to keep the
///   rewrite a STRICT, conservative extension we additionally REFUSE to rewrite while the flag value is
///   still consumed — those nodes keep the legacy ADDS/SUBS+CSET path byte-for-byte. The result is that
///   the carrier path only fires for the dead-flag idiom (e.g. `overflowing_add` whose flag is unused,
///   or a checked op that only returns the wrapped value).
///
/// SOUNDNESS / FAIL-SAFE: operand identity comes from TrustIR's canonical,
/// exhaustive [`Inst::uses_value`] walk. New value-bearing instructions must
/// update that single IR-owned definition before TrustIR compiles, so backend
/// liveness cannot silently drift from validator semantics.
fn value_is_used_in_func(func: &TrustIrFunction, target: ValueId) -> bool {
    func.blocks
        .iter()
        .flat_map(|block| block.body.iter())
        .any(|node| node.inst.uses_value(target))
}

fn supported_shift_guard_bitwidth(ty: &Ty) -> Option<u16> {
    match ty {
        Ty::I32 => Some(32),
        Ty::I64 => Some(64),
        _ => None,
    }
}

fn translate_div_nonzero_proof(node: &InstrNode) -> Option<Proof> {
    match &node.inst {
        Inst::BinOp {
            op: BinOp::UDiv | BinOp::SDiv | BinOp::URem | BinOp::SRem,
            rhs,
            ..
        } => Some(Proof::NonZeroDivisor { divisor: *rhs }),
        _ => None,
    }
}

fn translate_shift_in_range_proof(node: &InstrNode) -> Option<Proof> {
    match &node.inst {
        Inst::BinOp {
            op: BinOp::Shl | BinOp::LShr | BinOp::AShr,
            ty,
            rhs,
            ..
        } => {
            let bitwidth = supported_shift_guard_bitwidth(ty)?;
            Some(Proof::ValidShift {
                amount: *rhs,
                bitwidth,
            })
        }
        _ => None,
    }
}

fn pointer_proof_value(node: &InstrNode) -> Option<ValueId> {
    match &node.inst {
        Inst::Load { ptr, .. }
        | Inst::Store { ptr, .. }
        | Inst::AtomicLoad { ptr, .. }
        | Inst::AtomicStore { ptr, .. }
        | Inst::AtomicRMW { ptr, .. }
        | Inst::CmpXchg { ptr, .. } => Some(*ptr),
        Inst::GEP { .. } | Inst::Alloca { .. } | Inst::Cast { .. } => node.results.first().copied(),
        _ => None,
    }
}

fn proof_attachment_value_ids(node: &InstrNode, proof: &Proof) -> Vec<ValueId> {
    match proof {
        Proof::NoOverflow { .. } => match node.inst {
            Inst::Overflow { .. } => node.results.first().copied().into_iter().collect(),
            _ => node.results.clone(),
        },
        // Synthetic carrier-only seed: `translate_overflow` inserts it DIRECTLY onto the carrier's
        // operand vregs in `proof_ctx.value_proofs`, so it never flows through this node→value
        // attachment helper. It is intentionally NOT attached to any node result here (doing so would
        // route it through the general value-proof loop, the exact leak this variant exists to avoid).
        Proof::CarrierNoOverflow { .. } => Vec::new(),
        Proof::InRange { .. }
        | Proof::Pure
        | Proof::Associative
        | Proof::Commutative
        | Proof::Idempotent => node.results.clone(),
        Proof::ExactInBounds { .. } => Vec::new(),
        // A refinement is a fact about a VALUE's declared type, not about this node; the adapter
        // records it directly against the mapped LIR value at the end of `translate`, so it never
        // flows through this node -> value attachment helper.
        Proof::Refinement { .. } => Vec::new(),
        Proof::InBounds { index, .. } => {
            let mut values = vec![*index];
            if matches!(node.inst, Inst::GEP { .. }) {
                values.extend(node.results.iter().copied());
            }
            values
        }
        Proof::NotNull { ptr } => vec![*ptr],
        Proof::ValidBorrow { borrow } => vec![*borrow],
        Proof::NonZeroDivisor { divisor } => vec![*divisor],
        Proof::ValidShift { amount, .. } => vec![*amount],
    }
}

fn extract_proof_metadata_from_node(node: &InstrNode) -> ExtractedProofMetadata {
    let mut metadata = ExtractedProofMetadata::default();
    for annotation in &node.proofs {
        let proof = translate_trust_ir_proof_for_node(annotation, node);
        let proof_translated = proof.is_some();
        if let Some(proof) = proof {
            metadata.proofs.push(proof);
        }
        if matches!(annotation, ProofAnnotation::InBounds)
            && proof_translated
            && matches!(node.inst, Inst::GEP { .. })
        {
            metadata.facts.push(ProofFact::InBounds);
        } else if let Some(fact) = translate_trust_ir_proof_fact(annotation) {
            metadata.facts.push(fact);
        } else if !proof_translated
            && let Some(diagnostic) = proof_drop_diagnostic_for_node(annotation, Some(node))
        {
            metadata.diagnostics.push(diagnostic);
        }
    }
    metadata
}

fn extract_proof_metadata_from_annotations(
    annotations: &[ProofAnnotation],
) -> ExtractedProofMetadata {
    let mut metadata = ExtractedProofMetadata::default();
    for annotation in annotations {
        if let Some(proof) = translate_trust_ir_proof(annotation) {
            metadata.proofs.push(proof);
        }
        if let Some(fact) = translate_trust_ir_proof_fact(annotation) {
            metadata.facts.push(fact);
        } else if let Some(diagnostic) = proof_drop_diagnostic_for_node(annotation, None) {
            metadata.diagnostics.push(diagnostic);
        }
    }
    metadata
}

fn translate_trust_ir_proof_fact(p: &ProofAnnotation) -> Option<ProofFact> {
    match p {
        ProofAnnotation::ValidDealloc => Some(ProofFact::ValidDealloc),
        ProofAnnotation::Terminates => Some(ProofFact::Terminates),
        ProofAnnotation::Deterministic => Some(ProofFact::Deterministic),
        ProofAnnotation::DataRaceFree => Some(ProofFact::DataRaceFree),
        ProofAnnotation::Monotonic => Some(ProofFact::Monotonic),
        ProofAnnotation::NoAlias => Some(ProofFact::NoAlias),
        ProofAnnotation::Aligned(bytes) => Some(ProofFact::Aligned(*bytes)),
        ProofAnnotation::NoPanic => Some(ProofFact::NoPanic),
        ProofAnnotation::NoUndef => Some(ProofFact::NoUndef),
        ProofAnnotation::ReadonlyTable => Some(ProofFact::ReadonlyTable),
        ProofAnnotation::AppendOnlyBuffer => Some(ProofFact::AppendOnlyBuffer),
        ProofAnnotation::AtomicSetInsert => Some(ProofFact::AtomicSetInsert),
        ProofAnnotation::ParallelMap => Some(ProofFact::ParallelMap),
        ProofAnnotation::BoundedLoop(bound) => Some(ProofFact::BoundedLoop(*bound)),
        ProofAnnotation::DivergenceClass(divergence) => Some(ProofFact::DivergenceClass(
            translate_trust_ir_divergence(*divergence),
        )),
        _ => None,
    }
}

fn translate_trust_ir_divergence(divergence: TrustIrDivergence) -> ProofDivergence {
    match divergence {
        TrustIrDivergence::Uniform => ProofDivergence::Uniform,
        TrustIrDivergence::Low => ProofDivergence::Low,
        TrustIrDivergence::High => ProofDivergence::High,
    }
}

fn proof_drop_diagnostic_for_node(
    p: &ProofAnnotation,
    node: Option<&InstrNode>,
) -> Option<ProofDropDiagnostic> {
    match p {
        ProofAnnotation::InBounds if node.is_some() => Some(ProofDropDiagnostic::new(
            "InBounds",
            ProofDropCode::Unrepresentable,
            "InBounds requires a GEP or element instruction with exactly one index operand",
        )),
        ProofAnnotation::InBounds => Some(ProofDropDiagnostic::new(
            "InBounds",
            ProofDropCode::Unrepresentable,
            "function-level InBounds has no instruction operands to bind",
        )),
        ProofAnnotation::NotNull if node.is_some() => Some(ProofDropDiagnostic::new(
            "NotNull",
            ProofDropCode::Unrepresentable,
            "NotNull requires a pointer-carrying instruction operand or result",
        )),
        ProofAnnotation::NotNull => Some(ProofDropDiagnostic::new(
            "NotNull",
            ProofDropCode::Unrepresentable,
            "function-level NotNull has no pointer operand to bind",
        )),
        ProofAnnotation::DivNonZero if node.is_some() => Some(ProofDropDiagnostic::new(
            "DivNonZero",
            ProofDropCode::Unrepresentable,
            "DivNonZero requires an integer division or remainder instruction divisor",
        )),
        ProofAnnotation::DivNonZero => Some(ProofDropDiagnostic::new(
            "DivNonZero",
            ProofDropCode::Unrepresentable,
            "function-level DivNonZero has no divisor operand to bind",
        )),
        ProofAnnotation::ShiftInRange if node.is_some() => Some(ProofDropDiagnostic::new(
            "ShiftInRange",
            ProofDropCode::Unrepresentable,
            "ShiftInRange requires a supported I32/I64 scalar shift",
        )),
        ProofAnnotation::ShiftInRange => Some(ProofDropDiagnostic::new(
            "ShiftInRange",
            ProofDropCode::Unrepresentable,
            "function-level ShiftInRange has no shift operand to bind",
        )),
        ProofAnnotation::ValidBorrow
        | ProofAnnotation::UniqueBorrow
        | ProofAnnotation::SharedBorrow
            if node.is_some() =>
        {
            Some(ProofDropDiagnostic::new(
                "ValidBorrow",
                ProofDropCode::Unrepresentable,
                "borrow proof requires a pointer-carrying instruction operand or result",
            ))
        }
        ProofAnnotation::ValidBorrow
        | ProofAnnotation::UniqueBorrow
        | ProofAnnotation::SharedBorrow => Some(ProofDropDiagnostic::new(
            "ValidBorrow",
            ProofDropCode::Unrepresentable,
            "function-level borrow proof has no pointer operand to bind",
        )),
        ProofAnnotation::AtomicOrdering(ordering) => Some(ProofDropDiagnostic::with_payload(
            "AtomicOrdering",
            ordering.to_string(),
            ProofDropCode::Unrepresentable,
            "atomic ordering payload is not represented in Trust Codegen proof facts yet",
        )),
        ProofAnnotation::Custom(tag)
            if tag.index() == LLVM_STACK_PROTECTOR_FUNCTION_ATTR_TAG
                || tag.index() == LLVM_STACK_PROTECTOR_REQUIRED_FUNCTION_ATTR_TAG =>
        {
            None
        }
        // U10 stack-limit tags are consumed (or refused) by
        // `admit_stack_limit_request`, never dropped.
        ProofAnnotation::Custom(tag) if crate::stack_limit::is_stack_limit_tag(tag.index()) => None,
        ProofAnnotation::Custom(tag) => Some(ProofDropDiagnostic::with_payload(
            "Custom",
            tag.to_string(),
            ProofDropCode::Custom,
            "custom proof tags are outside the stable Trust Codegen proof vocabulary",
        )),
        // Not a drop: `Wrapping` promises two's-complement wrap-around, which is
        // exactly what the unannotated machine lowering (Iadd/Isub/Imul) already
        // produces. There is no lost information to diagnose.
        ProofAnnotation::Wrapping => None,
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// Memory intrinsic detection
// ---------------------------------------------------------------------------

/// Check if a function name is a memcpy intrinsic.
///
/// Recognizes both the bare libc name and LLVM intrinsic variants
/// (e.g., `llvm.memcpy.p0.p0.i64`).
fn is_memcpy_intrinsic(name: &str) -> bool {
    name == RuntimeSymbol::Memcpy.name() || name.starts_with("llvm.memcpy")
}

/// Check if a function name is a memmove intrinsic.
fn is_memmove_intrinsic(name: &str) -> bool {
    name == RuntimeSymbol::Memmove.name() || name.starts_with("llvm.memmove")
}

/// Check if a function name is a memset intrinsic.
fn is_memset_intrinsic(name: &str) -> bool {
    name == RuntimeSymbol::Memset.name() || name.starts_with("llvm.memset")
}

fn bitreverse_intrinsic_bitwidth(name: &str) -> Option<u16> {
    match name {
        "llvm.bitreverse.i32" => Some(32),
        "llvm.bitreverse.i64" => Some(64),
        _ => None,
    }
}

fn objectsize_intrinsic_bitwidth(name: &str) -> Option<u16> {
    let rest = name.strip_prefix("llvm.objectsize.i")?;
    let (bits, ptr_suffix) = rest.split_once('.')?;
    if ptr_suffix != "p0" {
        return None;
    }
    bits.parse().ok()
}

/// The scalar FP type and source rounding contract of an `llvm.fma` /
/// `llvm.fmuladd` intrinsic, or `None` for any other name (fail-closed).
/// `bool == true` means fusion is optional (`llvm.fmuladd`); false means IEEE
/// fused rounding is required (`llvm.fma`). Keeping this bit through ISel is
/// load-bearing: conflating the names would let a profitability pass silently
/// double-round strict `llvm.fma`.
fn fma_intrinsic_contract(name: &str) -> Option<(Type, bool)> {
    match name {
        "llvm.fmuladd.f32" => Some((Type::F32, true)),
        "llvm.fmuladd.f64" => Some((Type::F64, true)),
        "llvm.fma.f32" => Some((Type::F32, false)),
        "llvm.fma.f64" => Some((Type::F64, false)),
        _ => None,
    }
}

/// The PACKED multiply-add opcode for an intrinsic name, or `None`.
///
/// Separate from [`fma_intrinsic_contract`] rather than folded into it: that
/// function returns the scalar `Type` plus a fusion flag, which cannot name a
/// vector opcode, and the two shapes select genuinely different machine
/// arrangements.
///
/// Only the fusion-OPTIONAL `llvm.fmuladd` appears here, and there is no
/// `may_unfuse` flag to return because every opcode this yields is licensed by
/// construction. Strict `llvm.fma.v*` is deliberately absent: it REQUIRES
/// fusion, so giving it an opcode that a later pass is permitted to split back
/// into `fmul`+`fadd` would round TWICE — a bit-level miscompile. It stays
/// scalarized. MUST mirror `parser::is_lowered_passthrough_intrinsic` exactly,
/// or an un-rewritten intrinsic survives as an unresolved symbol and fails to
/// link.
fn fma_vector_intrinsic_contract(name: &str) -> Option<Opcode> {
    match name {
        "llvm.fmuladd.v4f32" => Some(Opcode::V4F32Fmuladd),
        "llvm.fmuladd.v2f64" => Some(Opcode::V2F64Fmuladd),
        _ => None,
    }
}

/// Complete name-dependent semantics of a direct TrustIR call.
///
/// A static indirect-call recovery is permitted only for [`Self::Ordinary`].
/// Keeping the refusal decision and the direct lowering on this one classifier
/// makes the policy exhaustive: a newly recognized intrinsic must enter this
/// enum before it can change either path.
enum NamedCallSemantics {
    Ordinary,
    Memcpy,
    Memmove,
    Memset,
    Bitreverse(u16),
    Objectsize(u16),
    Fma { fp_ty: Type, may_unfuse: bool },
    PackedFma(Opcode),
    Crc32 { bytes: u8, castagnoli: bool },
}

/// Public, payload-free classification of direct-call names for which the
/// TrustIR adapter substitutes intrinsic LIR semantics.
///
/// Admission boundaries use this exact classifier to reject undeclared
/// semantic replacement.  It is intentionally derived from the adapter's
/// private payload-bearing classifier below, so adding a new name-sensitive
/// lowering variant requires updating this exhaustive match.
///
/// Callers must first apply the adapter's exact-module-binding rule: a bodied
/// `Internal` or `Private` callee is always ordinary and its module-local body
/// wins even when its spelling resembles an intrinsic. This function
/// classifies names only; it cannot see that binding context.
///
/// A name's claim is not the lowering: the adapter keeps it only for a callee
/// declared with the prototype the claim needs
/// ([`classify_adapter_direct_call`]). [`classify_adapter_named_call`] is the
/// claim alone, the superset an admission boundary may refuse by name.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AdapterNamedCallSemantics {
    Ordinary,
    Memcpy,
    Memmove,
    Memset,
    Bitreverse,
    Objectsize,
    Fma,
    PackedFma,
    Crc32,
}

impl AdapterNamedCallSemantics {
    fn of(semantics: &NamedCallSemantics) -> Self {
        match semantics {
            NamedCallSemantics::Ordinary => Self::Ordinary,
            NamedCallSemantics::Memcpy => Self::Memcpy,
            NamedCallSemantics::Memmove => Self::Memmove,
            NamedCallSemantics::Memset => Self::Memset,
            NamedCallSemantics::Bitreverse(_) => Self::Bitreverse,
            NamedCallSemantics::Objectsize(_) => Self::Objectsize,
            NamedCallSemantics::Fma { .. } => Self::Fma,
            NamedCallSemantics::PackedFma(_) => Self::PackedFma,
            NamedCallSemantics::Crc32 { .. } => Self::Crc32,
        }
    }
}

/// The semantics a direct-call NAME claims, after exact local binding has
/// been ruled out, whatever the callee's declared prototype: the superset of
/// what the adapter lowers by name. The lowering itself is
/// [`classify_adapter_direct_call`].
#[must_use]
pub fn classify_adapter_named_call(name: &str) -> AdapterNamedCallSemantics {
    AdapterNamedCallSemantics::of(&classify_named_call(name))
}

/// What the adapter lowers a direct call of `callee` to, named `name` (the
/// symbol the adapter's function catalog gives it) and declared with
/// `signature`: the one decision its `Inst::Call` lowering takes
/// (`classify_direct_call`). `Ok(Ordinary)` for a module-local definition,
/// for a name that claims nothing, and for a C library memory routine
/// declared with another prototype (an ordinary call of that symbol);
/// `Err` with the refusal for an LLVM intrinsic name declared with another
/// type, which the adapter refuses by name.
pub fn classify_adapter_direct_call(
    name: &str,
    callee: &TrustIrFunction,
    signature: &trust_ir::FuncTy,
) -> Result<AdapterNamedCallSemantics, String> {
    classify_direct_call(name, callee, signature)
        .map(|semantics| AdapterNamedCallSemantics::of(&semantics))
}

fn classify_named_call(name: &str) -> NamedCallSemantics {
    if is_memcpy_intrinsic(name) {
        NamedCallSemantics::Memcpy
    } else if is_memmove_intrinsic(name) {
        NamedCallSemantics::Memmove
    } else if is_memset_intrinsic(name) {
        NamedCallSemantics::Memset
    } else if let Some(bitwidth) = bitreverse_intrinsic_bitwidth(name) {
        NamedCallSemantics::Bitreverse(bitwidth)
    } else if let Some(bitwidth) = objectsize_intrinsic_bitwidth(name) {
        NamedCallSemantics::Objectsize(bitwidth)
    } else if let Some((fp_ty, may_unfuse)) = fma_intrinsic_contract(name) {
        NamedCallSemantics::Fma { fp_ty, may_unfuse }
    } else if let Some(opcode) = fma_vector_intrinsic_contract(name) {
        NamedCallSemantics::PackedFma(opcode)
    } else if let Some((bytes, castagnoli)) = crc32_intrinsic_contract(name) {
        NamedCallSemantics::Crc32 { bytes, castagnoli }
    } else {
        NamedCallSemantics::Ordinary
    }
}

/// The data width (bytes) and polynomial of an exact `llvm.aarch64.crc32*`
/// intrinsic name (rustc's `core::arch::aarch64::__crc32*` bodies call these
/// through `link_name`). Exact spellings only: a near miss is an ordinary call.
fn crc32_intrinsic_contract(name: &str) -> Option<(u8, bool)> {
    Some(match name {
        "llvm.aarch64.crc32b" => (1, false),
        "llvm.aarch64.crc32h" => (2, false),
        "llvm.aarch64.crc32w" => (4, false),
        "llvm.aarch64.crc32x" => (8, false),
        "llvm.aarch64.crc32cb" => (1, true),
        "llvm.aarch64.crc32ch" => (2, true),
        "llvm.aarch64.crc32cw" => (4, true),
        "llvm.aarch64.crc32cx" => (8, true),
        _ => return None,
    })
}

// ---------------------------------------------------------------------------
// The declared prototype of a name-classified call
// ---------------------------------------------------------------------------

/// A thin data pointer, C's `void *` at a call edge: `Ptr` and the typed raw
/// and reference pointers, each one machine word (trust-ir spells a fat
/// pointer `FatPtr`). A function pointer (`Func`) is not one. The same set as
/// the wasm32 memory-call pass's `thin` (OD-141).
fn is_c_data_pointer(ty: &Ty) -> bool {
    matches!(
        ty,
        Ty::Ptr | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Ref(_) | Ty::RefMut(_)
    )
}

/// The width of an integer type of either signedness; `Isize` and `Usize` are
/// 64 bits on every target this adapter lowers for. trust-ir integers carry a
/// signedness that LLVM's integers and the C calling conventions of these
/// targets do not (a 32- or 64-bit argument is passed the same either way), so
/// a prototype is read by width.
fn integer_width(ty: &Ty) -> Option<u32> {
    Some(match ty {
        Ty::I8 | Ty::U8 => 8,
        Ty::I16 | Ty::U16 => 16,
        Ty::I32 | Ty::U32 => 32,
        Ty::I64 | Ty::U64 | Ty::Isize | Ty::Usize => 64,
        Ty::I128 | Ty::U128 => 128,
        _ => return None,
    })
}

/// Whether `callee` is declared with the C prototype of `memcpy` and
/// `memmove` (`set == false`) or `memset` (`set == true`) on this backend's
/// LP64 targets (AArch64 and x86-64):
///
/// * `void *memcpy(void *, const void *, size_t)` (and `memmove`);
/// * `void *memset(void *, int, size_t)`;
///
/// a pointer being [`is_c_data_pointer`], `int` a 32-bit integer and `size_t`
/// a 64-bit integer ([`integer_width`]), C's calling convention
/// (`CallingConv::C`), not variadic. Any other declaration (another width or
/// count of parameters, another or no result, a variadic, `fastcc` or other
/// convention) is not the library routine. LLVM reads such a declaration as
/// an ordinary function (its `TargetLibraryInfo` checks the prototype before
/// it reads a call as the library's) and llc calls it.
fn has_c_memory_prototype(
    set: bool,
    callee: &TrustIrFunction,
    signature: &trust_ir::FuncTy,
) -> bool {
    let ([destination, second, count], [result]) =
        (signature.params.as_slice(), signature.returns.as_slice())
    else {
        return false;
    };
    let second_is_c = if set {
        integer_width(second) == Some(32)
    } else {
        is_c_data_pointer(second)
    };
    callee.calling_conv == CallingConv::C
        && !signature.is_vararg
        && is_c_data_pointer(destination)
        && second_is_c
        && integer_width(count) == Some(64)
        && is_c_data_pointer(result)
}

/// Whether `signature` is LLVM's `llvm.memcpy`/`llvm.memmove` (`set ==
/// false`) or `llvm.memset` (`set == true`) type as the adapter's producers
/// state it: `(ptr, ptr | i8, i32 | i64) -> void`, not variadic, the trailing
/// `i1 <volatile>` dropped (trust-cg-llvm-import drops a literal `false` and
/// refuses `true`). LLVM reads an intrinsic by its name and type and ignores
/// the declaration's calling convention (llc 22.1.2 lowered a `fastcc`
/// `llvm.memcpy.p0.p0.i64` as the intrinsic), so the convention is not read.
fn has_llvm_memory_intrinsic_type(set: bool, signature: &trust_ir::FuncTy) -> bool {
    let [destination, second, count] = signature.params.as_slice() else {
        return false;
    };
    let second_is_llvm = if set {
        integer_width(second) == Some(8)
    } else {
        is_c_data_pointer(second)
    };
    !signature.is_vararg
        && signature.returns.is_empty()
        && is_c_data_pointer(destination)
        && second_is_llvm
        && matches!(integer_width(count), Some(32 | 64))
}

/// The adapter's one reading of a direct call of `callee`, named `name` and
/// declared with `signature`: the semantics its name claims
/// ([`classify_named_call`]), kept only when the declaration has the
/// prototype that claim needs.
///
/// * A module-local definition (`Internal`/`Private` with a body) keeps its
///   body, whatever its name: `Ordinary`.
/// * `memcpy`, `memmove` and `memset` are the C library's routines only with
///   the C prototype ([`has_c_memory_prototype`]). Declared otherwise each is
///   an ordinary function of that name, called as one: `Ordinary` (llc calls
///   it too; another object of the link may define it).
/// * An LLVM intrinsic name (`llvm.mem*`, `llvm.bitreverse.*`,
///   `llvm.objectsize.*`, `llvm.fma.*`/`llvm.fmuladd.*`,
///   `llvm.aarch64.crc32*`) means the intrinsic only at the type its name
///   states; LLVM's verifier refuses any other declaration of it. Declared
///   otherwise it is refused by name (`Err`): an ordinary call would name a
///   symbol no library defines.
fn classify_direct_call(
    name: &str,
    callee: &TrustIrFunction,
    signature: &trust_ir::FuncTy,
) -> Result<NamedCallSemantics, String> {
    if is_module_local_function_definition(callee) {
        return Ok(NamedCallSemantics::Ordinary);
    }
    let claim = classify_named_call(name);
    let int = |ty: &Ty, bits: u32| integer_width(ty) == Some(bits);
    let (params, returns) = (signature.params.as_slice(), signature.returns.as_slice());
    let (admitted, expected) = match &claim {
        NamedCallSemantics::Ordinary => return Ok(claim),
        NamedCallSemantics::Memcpy | NamedCallSemantics::Memmove | NamedCallSemantics::Memset => {
            let set = matches!(claim, NamedCallSemantics::Memset);
            if !name.starts_with("llvm.") {
                return Ok(if has_c_memory_prototype(set, callee, signature) {
                    claim
                } else {
                    NamedCallSemantics::Ordinary
                });
            }
            (
                has_llvm_memory_intrinsic_type(set, signature),
                format!(
                    "(ptr, {}, i32 or i64) -> void",
                    if set { "i8" } else { "ptr" }
                ),
            )
        }
        NamedCallSemantics::Bitreverse(bits) => {
            let bits = u32::from(*bits);
            (
                matches!((params, returns), ([operand], [result])
                    if int(operand, bits) && int(result, bits)),
                format!("(i{bits}) -> i{bits}"),
            )
        }
        NamedCallSemantics::Objectsize(bits) => {
            let bits = u32::from(*bits);
            (
                matches!((params, returns), ([pointer, min, null_unknown, dynamic], [result])
                    if is_c_data_pointer(pointer)
                        && [min, null_unknown, dynamic].iter().all(|flag| **flag == Ty::Bool)
                        && int(result, bits)),
                format!("(ptr, i1, i1, i1) -> i{bits}"),
            )
        }
        NamedCallSemantics::Fma { fp_ty, .. } => {
            let fp = match fp_ty {
                Type::F32 => Ty::F32,
                Type::F64 => Ty::F64,
                other => return Err(format!("`{name}`: no fused multiply-add of {other:?}")),
            };
            (
                params.len() == 3
                    && params.iter().all(|param| *param == fp)
                    && returns == [fp.clone()],
                format!("({fp:?}, {fp:?}, {fp:?}) -> {fp:?}"),
            )
        }
        NamedCallSemantics::PackedFma(opcode) => {
            let lanes = match opcode {
                Opcode::V4F32Fmuladd => Ty::Vector(Box::new(Ty::F32), 4),
                Opcode::V2F64Fmuladd => Ty::Vector(Box::new(Ty::F64), 2),
                other => return Err(format!("`{name}`: no packed multiply-add {other:?}")),
            };
            (
                params.len() == 3
                    && params.iter().all(|param| *param == lanes)
                    && returns == [lanes.clone()],
                format!("({lanes:?}, {lanes:?}, {lanes:?}) -> {lanes:?}"),
            )
        }
        NamedCallSemantics::Crc32 { bytes, .. } => {
            // Exactly 32- and 64-bit integers (rustc declares them
            // `u32`/`u64`), not the pointer-width `Isize`/`Usize`.
            let is_int = |ty: &Ty, bits: u32| match bits {
                32 => matches!(ty, Ty::I32 | Ty::U32),
                _ => matches!(ty, Ty::I64 | Ty::U64),
            };
            let data_bits = if *bytes == 8 { 64 } else { 32 };
            if signature.is_vararg
                || !matches!((params, returns), ([crc, data], [result])
                    if is_int(crc, 32) && is_int(data, data_bits) && is_int(result, 32))
            {
                return Err(format!(
                    "[TCG-CRC32-INTRINSIC] `{name}` must be declared (i32 crc, i{data_bits} \
                     data) -> i32, not variadic; got params {params:?} -> {returns:?}{}",
                    if signature.is_vararg {
                        ", variadic"
                    } else {
                        ""
                    }
                ));
            }
            return Ok(claim);
        }
    };
    if admitted && !signature.is_vararg {
        Ok(claim)
    } else {
        Err(format!(
            "[TCG-NAMED-CALL-PROTOTYPE] `{name}` names an LLVM intrinsic of type {expected}, but \
             it is declared {params:?} -> {returns:?}{}; LLVM reads that name only at that type, \
             and this backend does not lower a call by its callee's name alone",
            if signature.is_vararg {
                ", variadic"
            } else {
                ""
            }
        ))
    }
}

