    use super::*;

    #[test]
    fn v58_nominal_origin_floor_refuses_all_duplicate_tables_and_shapes() {
        let structure = |id: u32, origin| TrustIrStructDef {
            id: StructId::new(id),
            name: format!("Struct{id}"),
            fields: vec![FieldDef {
                name: "value".into(),
                ty: Ty::I64,
                offset: Some(0),
            }],
            size: Some(8),
            align: Some(8),
            repr: trust_ir::StructRepr::C,
            origin,
        };
        let enumeration = |id: u32, origin| {
            let mut definition = EnumDef::new(
                EnumId::new(id),
                format!("Enum{id}"),
                vec![EnumVariant {
                    name: "Value".into(),
                    fields: vec![Ty::I64],
                    field_names: Vec::new(),
                }],
            );
            definition.origin = origin;
            definition
        };
        let origin = trust_ir::ty::TypeOrigin::Rust {
            stable_crate_id: 7,
            def_path_hash: [8; 16],
            args_digest: trust_ir::proof::ProofDigest::sha256([9; 32]),
        };
        for mutation in 0..5 {
            let mut module = Module::new("unused_nominal_claims");
            let (first_table, first, second_table, second) = match mutation {
                0 | 1 => {
                    module.structs = vec![
                        structure(0, Some(origin.clone())),
                        structure(1, Some(origin.clone())),
                    ];
                    if mutation == 1 {
                        module.structs[1].fields[0].ty = Ty::U32;
                    }
                    ("struct", "Struct0", "struct", "Struct1")
                }
                2 | 3 => {
                    module.enums = vec![
                        enumeration(0, Some(origin.clone())),
                        enumeration(1, Some(origin.clone())),
                    ];
                    if mutation == 3 {
                        module.enums[1].variants[0].fields[0] = Ty::U32;
                    }
                    ("enum", "Enum0", "enum", "Enum1")
                }
                4 => {
                    module.structs.push(structure(0, Some(origin.clone())));
                    module.enums.push(enumeration(0, Some(origin.clone())));
                    ("struct", "Struct0", "enum", "Enum0")
                }
                _ => unreachable!(),
            };
            let before = module.clone();
            let expected = trust_ir_build::ValidationError::TypeOriginConflict {
                origin: origin.to_string(),
                first_module: None,
                first_table,
                first: first.to_string(),
                second_module: None,
                second_table,
                second: second.to_string(),
            }
            .to_string();
            for error in [
                reject_unconsumed_v41_target_neutral_surface(&module).unwrap_err(),
                translate_type_in_module(&module, &Ty::I64).unwrap_err(),
                validate_codegen_prerequisites(&module).unwrap_err(),
            ] {
                let AdapterError::TrustIrAdmissionRefused { error } = error else {
                    panic!("an exact shared nominal-origin refusal is required");
                };
                assert_eq!(error, expected, "duplicate mutation {mutation}");
            }
            assert_eq!(module, before, "unused source metadata remains intact");
        }
    }

    #[test]
    fn v58_nominal_origin_floor_keeps_unkeyed_and_distinct_key_positives() {
        let mut module = Module::new("ordinary_distinct_nominal_claims");
        let mut first = TrustIrStructDef {
            id: StructId::new(0),
            name: "First".into(),
            fields: vec![],
            size: Some(0),
            align: Some(1),
            repr: trust_ir::StructRepr::C,
            origin: None,
        };
        let mut second = first.clone();
        second.id = StructId::new(1);
        second.name = "Second".into();
        module.structs = vec![first.clone(), second.clone()];
        reject_unconsumed_v41_target_neutral_surface(&module).unwrap();
        translate_type_in_module(&module, &Ty::I64).unwrap();
        validate_codegen_prerequisites(&module).unwrap();
        for clean in [false, true] {
            let key = |byte| {
                if clean {
                    trust_ir::ty::TypeOrigin::Clean {
                        decl: "Same.Declaration".into(),
                        env_digest: trust_ir::proof::ProofDigest::sha256([byte; 32]),
                    }
                } else {
                    trust_ir::ty::TypeOrigin::Rust {
                        stable_crate_id: 7,
                        def_path_hash: [8; 16],
                        args_digest: trust_ir::proof::ProofDigest::sha256([byte; 32]),
                    }
                }
            };
            first.origin = Some(key(9));
            second.origin = Some(key(10));
            module.structs = vec![first.clone(), second.clone()];
            let before = module.clone();
            reject_unconsumed_v41_target_neutral_surface(&module).unwrap();
            translate_type_in_module(&module, &Ty::I64).unwrap();
            validate_codegen_prerequisites(&module).unwrap();
            assert_eq!(module, before);
        }
    }

    #[test]
    fn v58_declared_closure_offsets_are_honored_and_abi_totals_stay_guarded() {
        let mut module = Module::new("declared_closure_image");
        module.target_info = Some(trust_ir::TargetInfo {
            triple: "aarch64-apple-darwin".into(),
            pointer_size: 8,
            endianness: trust_ir::Endianness::Little,
            abi: None,
            struct_passing: trust_ir::StructPassingPolicy::NativeC,
        });
        let signature = module
            .add_func_type(trust_ir::FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        module.closure_types.push(trust_ir::ClosureTy {
            func: signature,
            captures: vec![Ty::U64, Ty::U8],
        });
        reject_unconsumed_v41_target_neutral_surface(&module).unwrap();
        let closure = Ty::Closure(trust_ir::ClosureTyId::new(0));
        let legacy_type = translate_type_in_module(&module, &closure).unwrap();
        module
            .closure_layouts
            .push(trust_ir::ClosureLayoutDescriptor {
                origin: None,
                closure: trust_ir::ClosureTyId::new(0),
                size: 16,
                align: 8,
                capture_offsets: vec![8, 0],
            });
        module.validate_closure_layouts().unwrap();
        let before = module.clone();
        reject_unconsumed_v41_target_neutral_surface(&module).unwrap();
        assert_eq!(
            translate_type_in_module(&module, &closure).unwrap(),
            legacy_type
        );
        let layout = crate::declared_closure_layout::layout(&module, trust_ir::ClosureTyId::new(0))
            .unwrap()
            .unwrap();
        assert_eq!(layout.offsets, vec![8, 0]);
        assert_eq!((layout.size, layout.align), (16, 8));
        assert_eq!(module, before);
        // A larger physical frame still needs a different downstream ABI.
        module.closure_layouts[0].size = 24;
        let before = module.clone();
        let error = reject_unconsumed_v41_target_neutral_surface(&module).unwrap_err();
        assert!(matches!(
            error,
            AdapterError::DeclaredClosureLayoutUnsupported { layouts: 1, .. }
        ));
        assert!(matches!(
            translate_type_in_module(&module, &closure).unwrap_err(),
            AdapterError::DeclaredClosureLayoutUnsupported { layouts: 1, .. }
        ));
        assert_eq!(module, before);
        module.closure_layouts.clear();
        reject_unconsumed_v41_target_neutral_surface(&module).unwrap();
        assert_eq!(
            translate_type_in_module(&module, &closure).unwrap(),
            legacy_type
        );
    }

    /// This file's fixtures are hand-built and carry no codegen license
    /// (`body_gate: None`), which trust-cg REFUSES by default (roadmap WS7.5,
    /// decision gate DG-73). Its compiles state `Permit` explicitly, so none of
    /// them passes because it was silently refused.
    fn permit_unlicensed() -> crate::CodegenLicensePolicy {
        crate::CodegenLicensePolicy::default().with_unlicensed(crate::UnlicensedBodyPolicy::Permit)
    }

    /// `translate_module` under [`permit_unlicensed`].
    fn permit_translate_module(
        module: &trust_ir::Module,
    ) -> Result<Vec<(crate::Function, crate::ProofContext)>, crate::AdapterError> {
        crate::translate_module_for_arch_with_tls_with_license(
            module,
            crate::GuardCarrierArch::default(),
            crate::TlsDialect::default(),
            &permit_unlicensed(),
        )
    }

    /// `translate_module_for_arch` under [`permit_unlicensed`].
    fn permit_translate_module_for_arch(
        module: &trust_ir::Module,
        arch: crate::GuardCarrierArch,
    ) -> Result<Vec<(crate::Function, crate::ProofContext)>, crate::AdapterError> {
        crate::translate_module_for_arch_with_tls_with_license(
            module,
            arch,
            crate::TlsDialect::default(),
            &permit_unlicensed(),
        )
    }

    /// The Swift aggregate classifier decides an array from its element and
    /// never enumerates past the leaf that decides it: a byte array small
    /// enough to fit four lanes decomposes exactly, and the same element at
    /// 2^31 lanes is refused after 33 leaves (an enumeration of 2^31 would
    /// allocate 2^31 leaf records first). An array of zero-sized elements has
    /// no leaves, whatever its length.
    #[test]
    fn swift_array_classification_stops_at_the_deciding_leaf() {
        let small = Type::Array(Box::new(Type::I8), 16);
        let lanes = swift_decompose_aggregate(&small).expect("[i8; 16] is two GPR words");
        assert_eq!(
            lanes.iter().map(|lane| lane.offset).collect::<Vec<_>>(),
            [0, 8]
        );
        let mut leaves = Vec::new();
        assert!(
            swift_flatten_leaves(&Type::Array(Box::new(Type::I8), 1 << 31), 0, &mut leaves)
                .is_none()
        );
        assert_eq!(leaves.len(), SWIFT_DECOMPOSABLE_MAX_LEAVES + 1);
        assert!(swift_decompose_aggregate(&Type::Array(Box::new(Type::I8), 1 << 31)).is_none());
        let doubles = Type::Array(Box::new(Type::F64), 4);
        assert_eq!(
            swift_decompose_aggregate(&doubles).map(|lanes| lanes.len()),
            Some(4)
        );
        assert!(swift_decompose_aggregate(&Type::Array(Box::new(Type::F64), 5)).is_none());
        let mut none = Vec::new();
        assert_eq!(
            swift_flatten_leaves(
                &Type::Array(Box::new(Type::Struct(vec![])), u32::MAX),
                0,
                &mut none
            ),
            Some(())
        );
        assert!(none.is_empty());
    }

    #[test]
    fn extraction_index_rejects_non_extraction_producers() {
        let node = InstrNode::new(Inst::Const {
            ty: Ty::I64,
            value: Constant::Int(1),
        })
        .with_result(ValueId::new(0));
        let mut adapter = TrustIrAdapter::new(&[], HashMap::new());
        let error = adapter.index_field_extract_types(&[&node]).unwrap_err();
        assert!(error.to_string().contains("non-ExtractField producer"));
        assert!(adapter.value_ty_map.is_empty());
    }

    #[test]
    fn prepared_owner_reuses_prerequisites_and_arch_specific_preflights() {
        for architecture in [GuardCarrierArch::AArch64, GuardCarrierArch::X86_64] {
            for transformed in [false, true] {
                let mut builder = trust_ir_build::ModuleBuilder::new("prepared_reuse");
                let sig = builder.add_func_type(vec![Ty::I64], vec![Ty::I64]);
                let mut function = builder.function("identity", sig);
                let entry = function.create_block();
                let input = function.add_block_param(entry, Ty::I64);
                function.switch_to_block(entry);
                let result = if transformed {
                    let two = function.iconst(Ty::I64, 2);
                    function.binop(BinOp::UDiv, Ty::I64, input, two)
                } else {
                    input
                };
                function.ret(vec![result]);
                function.build();
                let module = builder.build().expect("ModuleBuilder::build: test fixture");
                PREPARATION_VISITS.with(|visits| visits.set([0; 3]));
                let prepared = prepare_module_for_lir(&module, architecture).unwrap();
                assert_eq!(prepared.architecture(), architecture);
                assert_eq!(std::ptr::eq(prepared.module(), &module), !transformed);
                let expected = [
                    if transformed { 2 } else { 1 },
                    usize::from(architecture == GuardCarrierArch::AArch64),
                    1,
                ];
                assert_eq!(PREPARATION_VISITS.with(|visits| visits.get()), expected);
                for _ in 0..2 {
                    let (lir, report) = prepared
                        .translate_with_tls_and_validation_with_license(
                            TlsDialect::default(),
                            &permit_unlicensed(),
                        )
                        .unwrap();
                    report.replay_exact_module_bindings(&lir).unwrap();
                    assert_eq!(
                        PREPARATION_VISITS.with(|visits| visits.get()),
                        expected,
                        "translation must not rerun preparation or prerequisites"
                    );
                }
            }
        }
    }
    #[test]
    fn relocation_model_names_dialects_and_access_models_are_consistent() {
        for model in RelocationModel::ALL {
            assert_eq!(model.name().parse::<RelocationModel>(), Ok(model));
            assert_eq!(model.to_string(), model.name());
            let access = ObjectAccessModel::elf(model);
            assert_eq!(access.relocation_model(), model);
            assert_eq!(access.tls_dialect(), model.elf_tls_dialect());
        }
        assert!("PIC".parse::<RelocationModel>().is_err());
        assert_eq!(RelocationModel::default(), RelocationModel::Static);
        assert_eq!(
            RelocationModel::Pic.elf_tls_dialect(),
            TlsDialect::ElfSharedObject
        );
        for model in [RelocationModel::Static, RelocationModel::Pie] {
            assert_eq!(model.elf_tls_dialect(), TlsDialect::ElfExecutable);
            assert!(!model.definitions_are_preemptible());
        }
        assert!(RelocationModel::Pic.definitions_are_preemptible());
        // Every pre-existing TLS-dialect entry point keeps the static model.
        for dialect in [
            TlsDialect::MachOTlv,
            TlsDialect::ElfLocalExec,
            TlsDialect::ElfInitialExec,
            TlsDialect::RejectThreadLocals,
        ] {
            let access = ObjectAccessModel::from(dialect);
            assert_eq!(access.tls_dialect(), dialect);
            assert_eq!(access.relocation_model(), RelocationModel::Static);
        }
    }

    /// The relocation model decides GOT-indirect (`ExternRef`) versus
    /// PC-relative (`GlobalRef`) access for every address form, and the TLS
    /// model for thread-locals.
    #[test]
    fn relocation_model_selects_preemptible_symbol_access_and_tls_models() {
        let mut module = TrustIrModule::new("relocation_model");
        let global = |name: &str, linkage, visibility, defined: bool, tls: bool| trust_ir::Global {
            name: name.to_string(),
            ty: Ty::I64,
            mutable: true,
            initializer: defined.then_some(Constant::Int(7)),
            linkage,
            tls: tls.then_some(trust_ir::TlsModel::GeneralDynamic),
            align: None,
            section: None,
            visibility,
            retained: false,
        };
        module.globals = vec![
            global(
                "pub_data",
                Linkage::External,
                Visibility::Default,
                true,
                false,
            ),
            global(
                "hid_data",
                Linkage::External,
                Visibility::Hidden,
                true,
                false,
            ),
            global(
                "prot_data",
                Linkage::External,
                Visibility::Protected,
                true,
                false,
            ),
            global(
                "loc_data",
                Linkage::Internal,
                Visibility::Default,
                true,
                false,
            ),
            global("weak_data", Linkage::Weak, Visibility::Default, true, false),
            global(
                "ext_data",
                Linkage::External,
                Visibility::Default,
                false,
                false,
            ),
            global(
                "tls_def",
                Linkage::External,
                Visibility::Default,
                true,
                true,
            ),
            global(
                "tls_imp",
                Linkage::External,
                Visibility::Default,
                false,
                true,
            ),
            global(
                "weakref_data",
                Linkage::ExternalWeak,
                Visibility::Default,
                false,
                false,
            ),
            global(
                "weak_hid_data",
                Linkage::Weak,
                Visibility::Hidden,
                true,
                false,
            ),
            global(
                "odr_data",
                Linkage::LinkOnceOdr,
                Visibility::Protected,
                true,
                false,
            ),
        ];
        let unit = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let returns_ptr = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![Ty::Ptr],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let returns_fn = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![Ty::Func(unit)],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let body = |node: InstrNode| {
            vec![TrustIrBlock {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    node.with_result(ValueId::new(0)),
                    InstrNode::new(Inst::Return {
                        values: vec![ValueId::new(0)],
                    }),
                ],
            }]
        };
        let mut callee = TrustIrFunction::new(FuncId::new(0), "pub_fn", unit, BlockId::new(0));
        callee.linkage = Linkage::External;
        callee.blocks = vec![TrustIrBlock {
            id: BlockId::new(0),
            params: vec![],
            body: vec![InstrNode::new(Inst::Return { values: vec![] })],
        }];
        let mut local = TrustIrFunction::new(FuncId::new(1), "loc_fn", unit, BlockId::new(0));
        local.linkage = Linkage::Internal;
        local.blocks = callee.blocks.clone();
        let mut weak_fn = TrustIrFunction::new(FuncId::new(2), "weak_fn", unit, BlockId::new(0));
        weak_fn.linkage = Linkage::Weak;
        weak_fn.blocks = callee.blocks.clone();
        // v45 function visibility: ids 3..=6.
        let bound_functions = [
            ("hid_fn", Linkage::External, Visibility::Hidden),
            ("prot_fn", Linkage::External, Visibility::Protected),
            ("weak_hid_fn", Linkage::Weak, Visibility::Hidden),
            ("weak_prot_fn", Linkage::Weak, Visibility::Protected),
        ]
        .into_iter()
        .enumerate()
        .map(|(index, (name, linkage, visibility))| {
            let mut function =
                TrustIrFunction::new(FuncId::new(3 + index as u32), name, unit, BlockId::new(0));
            function.linkage = linkage;
            function.visibility = visibility;
            function.blocks = callee.blocks.clone();
            function
        })
        .collect::<Vec<_>>();
        module
            .try_add_function(callee)
            .expect("Module::try_add_function: test fixture");
        module
            .try_add_function(local)
            .expect("Module::try_add_function: test fixture");
        module
            .try_add_function(weak_fn)
            .expect("Module::try_add_function: test fixture");
        for function in bound_functions {
            module
                .try_add_function(function)
                .expect("Module::try_add_function: test fixture");
        }
        let mut add = |name: &str, ty, node: InstrNode| {
            let id = FuncId::new(module.functions.len() as u32);
            let mut function = TrustIrFunction::new(id, name, ty, BlockId::new(0));
            function.linkage = Linkage::External;
            function.blocks = body(node);
            module
                .try_add_function(function)
                .expect("Module::try_add_function: test fixture");
        };
        for index in 0..11u32 {
            add(
                &format!("addr_{index}"),
                returns_ptr,
                InstrNode::new(Inst::GlobalAddr {
                    global: GlobalId::new(index),
                }),
            );
        }
        add(
            "fn_addr",
            returns_fn,
            InstrNode::new(Inst::Const {
                ty: Ty::Func(unit),
                value: Constant::FnDef(FuncId::new(0)),
            }),
        );
        add(
            "weak_fn_addr",
            returns_fn,
            InstrNode::new(Inst::Const {
                ty: Ty::Func(unit),
                value: Constant::FnDef(FuncId::new(2)),
            }),
        );
        add(
            "sym_addr",
            returns_ptr,
            InstrNode::new(Inst::Const {
                ty: Ty::Ptr,
                value: Constant::SymbolAddr {
                    symbol: "pub_data".into(),
                    addend: 0,
                },
            }),
        );
        add(
            "stub_addr",
            returns_ptr,
            InstrNode::new(Inst::Const {
                ty: Ty::Ptr,
                value: Constant::Int(0xFADE_i128 << 48),
            }),
        );
        // Every address form of the v45 hidden/protected functions and of
        // the hidden/protected data.
        for (index, name) in ["hid_fn", "prot_fn", "weak_hid_fn", "weak_prot_fn"]
            .into_iter()
            .enumerate()
        {
            add(
                &format!("{name}_addr"),
                returns_fn,
                InstrNode::new(Inst::Const {
                    ty: Ty::Func(unit),
                    value: Constant::FnDef(FuncId::new(3 + index as u32)),
                }),
            );
            add(
                &format!("{name}_sym_addr"),
                returns_ptr,
                InstrNode::new(Inst::Const {
                    ty: Ty::Ptr,
                    value: Constant::SymbolAddr {
                        symbol: name.into(),
                        addend: 0,
                    },
                }),
            );
        }
        for (index, name) in [(1u32, "hid_data"), (2, "prot_data")] {
            add(
                &format!("{name}_sym_addr"),
                returns_ptr,
                InstrNode::new(Inst::Const {
                    ty: Ty::Ptr,
                    value: Constant::SymbolAddr {
                        symbol: name.into(),
                        addend: 0,
                    },
                }),
            );
            add(
                &format!("{name}_stub_addr"),
                returns_ptr,
                InstrNode::new(Inst::Const {
                    ty: Ty::Ptr,
                    value: Constant::Int((0xFADE_i128 << 48) | (i128::from(index) << 32)),
                }),
            );
        }
        let bound_address_forms = [
            ("hid_fn_addr", "hid_fn"),
            ("hid_fn_sym_addr", "hid_fn"),
            ("prot_fn_addr", "prot_fn"),
            ("prot_fn_sym_addr", "prot_fn"),
            ("weak_hid_fn_addr", "weak_hid_fn"),
            ("weak_hid_fn_sym_addr", "weak_hid_fn"),
            ("weak_prot_fn_addr", "weak_prot_fn"),
            ("weak_prot_fn_sym_addr", "weak_prot_fn"),
            ("hid_data_sym_addr", "hid_data"),
            ("hid_data_stub_addr", "hid_data"),
            ("prot_data_sym_addr", "prot_data"),
            ("prot_data_stub_addr", "prot_data"),
        ];

        let first_opcode = |access: ObjectAccessModel| -> HashMap<String, Opcode> {
            let (functions, _) =
                translate_module_for_arch_with_access_model_and_stats_with_license(
                    &module,
                    GuardCarrierArch::AArch64,
                    access,
                    &permit_unlicensed(),
                    ObjectSymbolPolicy::AARCH64_ELF_MODULE,
                )
                .unwrap_or_else(|error| panic!("{access:?}: {error}"));
            functions
                .into_iter()
                .filter_map(|(function, _)| {
                    let entry = &function.blocks[&function.entry_block];
                    entry
                        .instructions
                        .first()
                        .map(|inst| (function.name.clone(), inst.opcode.clone()))
                })
                .collect()
        };
        let got = |name: &str| Opcode::ExternRef { name: name.into() };
        let direct = |name: &str| Opcode::GlobalRef { name: name.into() };
        let tls = |name: &str, model| Opcode::TlsRef {
            name: name.into(),
            model,
            local_exec_offset: None,
        };
        for model in [RelocationModel::Static, RelocationModel::Pie] {
            let opcodes = first_opcode(ObjectAccessModel::elf(model));
            for (index, name) in ["pub_data", "hid_data", "prot_data", "loc_data", "weak_data"]
                .iter()
                .enumerate()
            {
                assert_eq!(opcodes[&format!("addr_{index}")], direct(name), "{model}");
            }
            assert_eq!(opcodes["addr_5"], got("ext_data"), "{model}");
            // A weak undefined reference is GOT-indirect under every model:
            // its slot reads null when nothing defines the symbol.
            assert_eq!(opcodes["addr_8"], got("weakref_data"), "{model}");
            assert_eq!(
                opcodes["addr_6"],
                tls("tls_def", TlsModel::LocalExec),
                "{model}"
            );
            assert_eq!(
                opcodes["addr_7"],
                tls("tls_imp", TlsModel::InitialExec),
                "{model}"
            );
            assert_eq!(opcodes["fn_addr"], direct("pub_fn"), "{model}");
            assert_eq!(opcodes["sym_addr"], direct("pub_data"), "{model}");
            assert_eq!(opcodes["stub_addr"], direct("pub_data"), "{model}");
            assert_eq!(opcodes["addr_9"], direct("weak_hid_data"), "{model}");
            assert_eq!(opcodes["addr_10"], direct("odr_data"), "{model}");
            assert_eq!(opcodes["weak_fn_addr"], direct("weak_fn"), "{model}");
            for (form, name) in bound_address_forms {
                assert_eq!(opcodes[form], direct(name), "{model} `{form}`");
            }
        }
        // The legacy Mach-O entry point (a bare TLS dialect) keeps every
        // definition direct.
        let legacy = first_opcode(ObjectAccessModel::from(TlsDialect::MachOTlv));
        assert_eq!(legacy["addr_4"], direct("weak_data"));
        assert_eq!(legacy["weak_fn_addr"], direct("weak_fn"));
        // Under dyld weak coalescing every non-hidden weak or link-once
        // definition (protected is default on Mach-O) is GOT-indirect; strong,
        // hidden and local definitions stay direct.
        let macho = first_opcode(ObjectAccessModel::macho_dyld());
        assert!(ObjectAccessModel::macho_dyld().dyld_coalesces_weak_definitions());
        assert_eq!(
            ObjectAccessModel::macho_dyld().tls_dialect(),
            TlsDialect::MachOTlv
        );
        assert_eq!(
            ObjectAccessModel::macho_dyld().relocation_model(),
            RelocationModel::Static
        );
        for (index, name, coalesced) in [
            (0, "pub_data", false),
            (1, "hid_data", false),
            (2, "prot_data", false),
            (3, "loc_data", false),
            (4, "weak_data", true),
            (5, "ext_data", true),
            (8, "weakref_data", true),
            (9, "weak_hid_data", false),
            (10, "odr_data", true),
        ] {
            let want = if coalesced { got(name) } else { direct(name) };
            assert_eq!(macho[&format!("addr_{index}")], want, "macho `{name}`");
        }
        assert_eq!(macho["fn_addr"], direct("pub_fn"));
        assert_eq!(macho["weak_fn_addr"], got("weak_fn"));
        assert_eq!(macho["sym_addr"], direct("pub_data"));
        // dyld coalesces a non-hidden weak definition whatever its protected
        // spelling (Mach-O has no protected visibility).
        for (form, name) in bound_address_forms {
            let want = if name == "weak_prot_fn" {
                got(name)
            } else {
                direct(name)
            };
            assert_eq!(macho[form], want, "macho `{form}`");
        }
        let opcodes = first_opcode(ObjectAccessModel::elf(RelocationModel::Pic));
        for (index, name, preemptible) in [
            (0, "pub_data", true),
            (1, "hid_data", false),
            (2, "prot_data", false),
            (3, "loc_data", false),
            (4, "weak_data", true),
            (5, "ext_data", true),
            (8, "weakref_data", true),
            (9, "weak_hid_data", false),
            (10, "odr_data", false),
        ] {
            let want = if preemptible { got(name) } else { direct(name) };
            assert_eq!(opcodes[&format!("addr_{index}")], want, "pic `{name}`");
        }
        assert_eq!(opcodes["weak_fn_addr"], got("weak_fn"));
        assert_eq!(opcodes["addr_6"], tls("tls_def", TlsModel::GeneralDynamic));
        assert_eq!(opcodes["addr_7"], tls("tls_imp", TlsModel::GeneralDynamic));
        assert_eq!(opcodes["fn_addr"], got("pub_fn"));
        assert_eq!(opcodes["sym_addr"], got("pub_data"));
        assert_eq!(opcodes["stub_addr"], got("pub_data"));
        // Hidden and protected definitions, functions and data, strong and
        // weak, bind inside the shared object: every address form of them is
        // PC-relative.
        for (form, name) in bound_address_forms {
            assert_eq!(opcodes[form], direct(name), "pic `{form}`");
        }
    }

    /// `RelocationModel::definition_is_preemptible` over every relocation
    /// model, trust-ir linkage and visibility, and the adapter's address
    /// choice for a function and a global of each admissible pair: the
    /// address is GOT-indirect exactly when the shared predicate says so.
    #[test]
    fn every_address_form_reads_the_shared_preemption_predicate() {
        let linkages = [
            Linkage::External,
            Linkage::Internal,
            Linkage::Private,
            Linkage::Weak,
            Linkage::LinkOnce,
            Linkage::WeakOdr,
            Linkage::LinkOnceOdr,
        ];
        let visibilities = [
            Visibility::Default,
            Visibility::Hidden,
            Visibility::Protected,
        ];
        for model in RelocationModel::ALL {
            for linkage in linkages {
                for visibility in visibilities {
                    let local = matches!(linkage, Linkage::Internal | Linkage::Private);
                    assert_eq!(
                        model.definition_is_preemptible(
                            DefinitionBinding::for_trust_ir_linkage(linkage),
                            visibility
                        ),
                        model == RelocationModel::Pic
                            && !local
                            && visibility == Visibility::Default,
                        "{model} {linkage:?} {visibility:?}"
                    );
                    if local && visibility != Visibility::Default {
                        // trust-ir calls this pair contradictory; the object
                        // symbol rows refuse it.
                        continue;
                    }
                    let mut module = TrustIrModule::new("preemption_predicate");
                    let unit = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    let returns_ptr = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![Ty::Ptr],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    module.globals = vec![trust_ir::Global {
                        name: "g".into(),
                        ty: Ty::I64,
                        mutable: true,
                        initializer: Some(Constant::Int(7)),
                        linkage,
                        tls: None,
                        align: None,
                        section: None,
                        visibility,
                        retained: false,
                    }];
                    let mut target =
                        TrustIrFunction::new(FuncId::new(0), "f", unit, BlockId::new(0));
                    target.linkage = linkage;
                    target.visibility = visibility;
                    target.blocks = vec![TrustIrBlock {
                        id: BlockId::new(0),
                        params: vec![],
                        body: vec![InstrNode::new(Inst::Return { values: vec![] })],
                    }];
                    module
                        .try_add_function(target)
                        .expect("Module::try_add_function: test fixture");
                    let returns_fn = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![Ty::Func(unit)],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    for (index, (name, value)) in [
                        ("fn_addr", Constant::FnDef(FuncId::new(0))),
                        (
                            "fn_sym_addr",
                            Constant::SymbolAddr {
                                symbol: "f".into(),
                                addend: 0,
                            },
                        ),
                        (
                            "data_sym_addr",
                            Constant::SymbolAddr {
                                symbol: "g".into(),
                                addend: 0,
                            },
                        ),
                        ("data_stub_addr", Constant::Int(0xFADE_i128 << 48)),
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        let (ty, signature) = if name == "fn_addr" {
                            (Ty::Func(unit), returns_fn)
                        } else {
                            (Ty::Ptr, returns_ptr)
                        };
                        let mut function = TrustIrFunction::new(
                            FuncId::new(1 + index as u32),
                            name,
                            signature,
                            BlockId::new(0),
                        );
                        function.blocks = vec![TrustIrBlock {
                            id: BlockId::new(0),
                            params: vec![],
                            body: vec![
                                InstrNode::new(Inst::Const { ty, value })
                                    .with_result(ValueId::new(0)),
                                InstrNode::new(Inst::Return {
                                    values: vec![ValueId::new(0)],
                                }),
                            ],
                        }];
                        module
                            .try_add_function(function)
                            .expect("Module::try_add_function: test fixture");
                    }
                    let mut function = TrustIrFunction::new(
                        FuncId::new(5),
                        "data_addr",
                        returns_ptr,
                        BlockId::new(0),
                    );
                    function.blocks = vec![TrustIrBlock {
                        id: BlockId::new(0),
                        params: vec![],
                        body: vec![
                            InstrNode::new(Inst::GlobalAddr {
                                global: GlobalId::new(0),
                            })
                            .with_result(ValueId::new(0)),
                            InstrNode::new(Inst::Return {
                                values: vec![ValueId::new(0)],
                            }),
                        ],
                    }];
                    module
                        .try_add_function(function)
                        .expect("Module::try_add_function: test fixture");
                    let (functions, _) =
                        translate_module_for_arch_with_access_model_and_stats_with_license(
                            &module,
                            GuardCarrierArch::AArch64,
                            ObjectAccessModel::elf(model),
                            &permit_unlicensed(),
                            ObjectSymbolPolicy::AARCH64_ELF_MODULE,
                        )
                        .unwrap_or_else(|error| {
                            panic!("{model} {linkage:?} {visibility:?}: {error}")
                        });
                    let preemptible = model.definition_is_preemptible(
                        DefinitionBinding::for_trust_ir_linkage(linkage),
                        visibility,
                    );
                    let mut checked = 0;
                    for (function, _) in functions {
                        let Some(symbol) = function
                            .name
                            .strip_prefix("fn_")
                            .map(|_| "f")
                            .or_else(|| function.name.strip_prefix("data_").map(|_| "g"))
                        else {
                            continue;
                        };
                        let first = &function.blocks[&function.entry_block].instructions[0];
                        let want = if preemptible {
                            Opcode::ExternRef {
                                name: symbol.into(),
                            }
                        } else {
                            Opcode::GlobalRef {
                                name: symbol.into(),
                            }
                        };
                        assert_eq!(
                            first.opcode, want,
                            "{model} {linkage:?} {visibility:?} `{}`",
                            function.name
                        );
                        checked += 1;
                    }
                    assert_eq!(checked, 5, "{model} {linkage:?} {visibility:?}");
                }
            }
        }
    }

    /// `RelocationModel::symbol_address_is_got_indirect`, pinned row by row:
    /// a definition only under `pic` and only when global and default-visible,
    /// and every undefined reference, strong or weak, under every model and
    /// whatever its visibility (its definition may be a GNU IFUNC). The
    /// definition wrapper `definition_is_preemptible` agrees on every
    /// definition row.
    #[test]
    fn symbol_address_is_got_indirect_truth_table() {
        for model in RelocationModel::ALL {
            for visibility in [
                Visibility::Default,
                Visibility::Hidden,
                Visibility::Protected,
            ] {
                let default = visibility == Visibility::Default;
                let pic = model == RelocationModel::Pic;
                for (binding, expected) in [
                    (SymbolBinding::Defined(DefinitionBinding::Local), false),
                    (
                        SymbolBinding::Defined(DefinitionBinding::Global),
                        pic && default,
                    ),
                    (SymbolBinding::Undefined { weak: false }, true),
                    (SymbolBinding::Undefined { weak: true }, true),
                ] {
                    let label = format!("{model} {binding:?} {visibility:?}");
                    assert_eq!(
                        model.symbol_address_is_got_indirect(binding, visibility),
                        expected,
                        "{label}"
                    );
                    if let SymbolBinding::Defined(definition) = binding {
                        assert_eq!(
                            model.definition_is_preemptible(definition, visibility),
                            expected,
                            "{label}: the definition wrapper"
                        );
                    }
                }
            }
        }
    }

    /// Every address form of a codegen DECLARATION reads the shared
    /// predicate through `SymbolBinding::for_trust_ir_function`: a bodyless
    /// `External` import, an `AvailableExternally` function with a body (never
    /// emitted) and a bodyless `ExternalWeak` reference, each default, hidden
    /// and protected, under every relocation model. `FnDef` and `SymbolAddr`
    /// are GOT-indirect (`ExternRef`) on every row: a hidden or protected
    /// declaration's definition may be a GNU IFUNC, whose canonical address
    /// a PC-relative form would miss. A direct call names the symbol whatever
    /// its visibility, and no declaration body is emitted.
    #[test]
    fn every_declaration_address_form_reads_the_shared_address_predicate() {
        let return_block = || TrustIrBlock {
            id: BlockId::new(0),
            params: vec![],
            body: vec![InstrNode::new(Inst::Return { values: vec![] })],
        };
        let (mut rows, mut checked) = (0, 0);
        for model in RelocationModel::ALL {
            for (linkage, bodied) in [
                (Linkage::External, false),
                (Linkage::AvailableExternally, true),
                (Linkage::ExternalWeak, false),
            ] {
                for visibility in [
                    Visibility::Default,
                    Visibility::Hidden,
                    Visibility::Protected,
                ] {
                    let label = format!("{model} {linkage:?} {visibility:?}");
                    let mut module = TrustIrModule::new("declaration_predicate");
                    let unit = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    let returns_ptr = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![Ty::Ptr],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    let returns_fn = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![Ty::Func(unit)],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    let mut target =
                        TrustIrFunction::new(FuncId::new(0), "f", unit, BlockId::new(0));
                    target.linkage = linkage;
                    target.visibility = visibility;
                    if bodied {
                        target.blocks = vec![return_block()];
                    }
                    module
                        .try_add_function(target)
                        .expect("Module::try_add_function: test fixture");
                    for (index, (name, ty, signature, value)) in [
                        (
                            "fn_addr",
                            Ty::Func(unit),
                            returns_fn,
                            Constant::FnDef(FuncId::new(0)),
                        ),
                        (
                            "fn_sym_addr",
                            Ty::Ptr,
                            returns_ptr,
                            Constant::SymbolAddr {
                                symbol: "f".into(),
                                addend: 0,
                            },
                        ),
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        let mut function = TrustIrFunction::new(
                            FuncId::new(1 + index as u32),
                            name,
                            signature,
                            BlockId::new(0),
                        );
                        function.blocks = vec![TrustIrBlock {
                            id: BlockId::new(0),
                            params: vec![],
                            body: vec![
                                InstrNode::new(Inst::Const { ty, value })
                                    .with_result(ValueId::new(0)),
                                InstrNode::new(Inst::Return {
                                    values: vec![ValueId::new(0)],
                                }),
                            ],
                        }];
                        module
                            .try_add_function(function)
                            .expect("Module::try_add_function: test fixture");
                    }
                    let mut caller =
                        TrustIrFunction::new(FuncId::new(3), "call_f", unit, BlockId::new(0));
                    caller.blocks = vec![TrustIrBlock {
                        id: BlockId::new(0),
                        params: vec![],
                        body: vec![
                            InstrNode::new(Inst::Call {
                                callee: FuncId::new(0),
                                args: vec![],
                            }),
                            InstrNode::new(Inst::Return { values: vec![] }),
                        ],
                    }];
                    module
                        .try_add_function(caller)
                        .expect("Module::try_add_function: test fixture");

                    let binding = SymbolBinding::for_trust_ir_function(&module.functions[0]);
                    assert_eq!(
                        binding,
                        SymbolBinding::Undefined {
                            weak: linkage == Linkage::ExternalWeak
                        },
                        "{label}"
                    );
                    let got_indirect = model.symbol_address_is_got_indirect(binding, visibility);
                    assert!(got_indirect, "{label}: the predicate");
                    let (functions, _) =
                        translate_module_for_arch_with_access_model_and_stats_with_license(
                            &module,
                            GuardCarrierArch::AArch64,
                            ObjectAccessModel::elf(model),
                            &permit_unlicensed(),
                            ObjectSymbolPolicy::AARCH64_ELF_MODULE,
                        )
                        .unwrap_or_else(|error| panic!("{label}: {error}"));
                    let names: Vec<&str> = functions
                        .iter()
                        .map(|(function, _)| function.name.as_str())
                        .collect();
                    assert_eq!(
                        names,
                        ["fn_addr", "fn_sym_addr", "call_f"],
                        "{label}: a declaration emits no body"
                    );
                    for (function, _) in &functions {
                        let instructions = &function.blocks[&function.entry_block].instructions;
                        if function.name == "call_f" {
                            assert!(
                                instructions.iter().any(|instruction| matches!(
                                    &instruction.opcode,
                                    Opcode::Call { name, .. } if name == "f"
                                )),
                                "{label}: the call names `f`: {instructions:?}"
                            );
                            continue;
                        }
                        assert_eq!(
                            instructions[0].opcode,
                            Opcode::ExternRef { name: "f".into() },
                            "{label} `{}`",
                            function.name
                        );
                        checked += 1;
                    }
                    rows += 1;
                }
            }
        }
        // 3 models x 3 declaration shapes x 3 visibilities, two address forms
        // each, every one GOT-indirect.
        assert_eq!((rows, checked), (27, 54));
    }

    /// L02-P6: a DATA declaration (a data import) reads the shared address
    /// predicate as a function declaration does. Under the AArch64 ELF module
    /// policy an initializer-less `External` import, an `AvailableExternally`
    /// global with an initializer (never emitted) and an `ExternalWeak`
    /// reference, each default, hidden and protected, are admitted, and their
    /// `GlobalAddr`, raw `SymbolAddr` and in-band stub forms are GOT-indirect
    /// (`ExternRef`) under every relocation model: the name may be a GNU
    /// IFUNC function, whose canonical address a PC-relative form would miss
    /// in a PIE, a static PIE or a shared object. A hidden or protected
    /// thread-local import takes the model's TLS path (initial-exec in an
    /// executable, a TLS descriptor in a shared object). The weak-reference
    /// policy alone refuses the non-default ones by name
    /// (`ImportVisibilityUnsupported`), and so does the ELF module policy for
    /// an `Internal`/`Private` thread-local import.
    #[test]
    fn every_data_declaration_address_form_reads_the_shared_address_predicate() {
        let (mut rows, mut checked) = (0, 0);
        for model in RelocationModel::ALL {
            for (linkage, initialized, thread_local) in [
                (Linkage::External, false, false),
                (Linkage::AvailableExternally, true, false),
                (Linkage::ExternalWeak, false, false),
                (Linkage::External, false, true),
            ] {
                for visibility in [
                    Visibility::Default,
                    Visibility::Hidden,
                    Visibility::Protected,
                ] {
                    let label = format!("{model} {linkage:?} tls={thread_local} {visibility:?}");
                    let mut module = TrustIrModule::new("data_declaration_predicate");
                    let returns_ptr = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![Ty::Ptr],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    module.globals = vec![trust_ir::Global {
                        name: "g".into(),
                        ty: Ty::I64,
                        mutable: true,
                        initializer: initialized.then_some(Constant::Int(7)),
                        linkage,
                        tls: thread_local.then_some(trust_ir::TlsModel::GeneralDynamic),
                        align: None,
                        section: None,
                        visibility,
                        retained: false,
                    }];
                    let mut forms = vec![(
                        "data_addr",
                        InstrNode::new(Inst::GlobalAddr {
                            global: GlobalId::new(0),
                        }),
                    )];
                    if !thread_local {
                        forms.push((
                            "data_sym_addr",
                            InstrNode::new(Inst::Const {
                                ty: Ty::Ptr,
                                value: Constant::SymbolAddr {
                                    symbol: "g".into(),
                                    addend: 0,
                                },
                            }),
                        ));
                        forms.push((
                            "data_stub_addr",
                            InstrNode::new(Inst::Const {
                                ty: Ty::Ptr,
                                value: Constant::Int(0xFADE_i128 << 48),
                            }),
                        ));
                    }
                    let form_count = forms.len();
                    for (index, (name, node)) in forms.into_iter().enumerate() {
                        let mut function = TrustIrFunction::new(
                            FuncId::new(index as u32),
                            name,
                            returns_ptr,
                            BlockId::new(0),
                        );
                        function.blocks = vec![TrustIrBlock {
                            id: BlockId::new(0),
                            params: vec![],
                            body: vec![
                                node.with_result(ValueId::new(0)),
                                InstrNode::new(Inst::Return {
                                    values: vec![ValueId::new(0)],
                                }),
                            ],
                        }];
                        module
                            .try_add_function(function)
                            .expect("Module::try_add_function: test fixture");
                    }
                    let (functions, _) =
                        translate_module_for_arch_with_access_model_and_stats_with_license(
                            &module,
                            GuardCarrierArch::AArch64,
                            ObjectAccessModel::elf(model),
                            &permit_unlicensed(),
                            ObjectSymbolPolicy::AARCH64_ELF_MODULE,
                        )
                        .unwrap_or_else(|error| panic!("{label}: {error}"));
                    assert_eq!(functions.len(), form_count, "{label}");
                    let want = if thread_local {
                        Opcode::TlsRef {
                            name: "g".into(),
                            model: if model == RelocationModel::Pic {
                                TlsModel::GeneralDynamic
                            } else {
                                TlsModel::InitialExec
                            },
                            local_exec_offset: None,
                        }
                    } else {
                        assert!(
                            model.symbol_address_is_got_indirect(
                                SymbolBinding::Undefined {
                                    weak: linkage == Linkage::ExternalWeak
                                },
                                visibility
                            ),
                            "{label}: the predicate"
                        );
                        Opcode::ExternRef { name: "g".into() }
                    };
                    for (function, _) in &functions {
                        let instructions = &function.blocks[&function.entry_block].instructions;
                        assert_eq!(instructions[0].opcode, want, "{label} `{}`", function.name);
                        checked += 1;
                    }
                    if visibility != Visibility::Default {
                        assert!(
                            matches!(
                                reject_unconsumed_v41_surface_with_weak_references(
                                    &module,
                                    GuardCarrierArch::AArch64,
                                    WeakUndefinedReferencePolicy::AdmitDeclarations,
                                ),
                                Err(AdapterError::ImportVisibilityUnsupported { ref global, visibility: refused })
                                    if global == "g" && refused == visibility
                            ),
                            "{label}: the weak-reference policy alone"
                        );
                    }
                    rows += 1;
                }
            }
        }
        // 3 models x 4 declaration shapes x 3 visibilities; three address
        // forms per non-TLS row and one per thread-local row.
        assert_eq!((rows, checked), (36, 3 * 3 * (3 * 3 + 1)));
        // A module-local thread-local import names no symbol another object
        // defines: its visibility stays refused under the ELF module policy.
        for linkage in [Linkage::Internal, Linkage::Private] {
            let mut module = TrustIrModule::new("local_tls_import");
            module.globals = vec![trust_ir::Global {
                name: "t".into(),
                ty: Ty::I64,
                mutable: true,
                initializer: None,
                linkage,
                tls: Some(trust_ir::TlsModel::GeneralDynamic),
                align: None,
                section: None,
                visibility: Visibility::Hidden,
                retained: false,
            }];
            assert!(
                matches!(
                    reject_unconsumed_v41_surface_with_weak_references(
                        &module,
                        GuardCarrierArch::AArch64,
                        ObjectSymbolPolicy::AARCH64_ELF_MODULE,
                    ),
                    Err(AdapterError::ImportVisibilityUnsupported { .. })
                ),
                "{linkage:?} thread-local import"
            );
        }
    }

    /// A function-body `Constant::SymbolAddr` naming a thread-local the module
    /// declares (a definition or an import, with or without an addend) is
    /// refused by name under every ELF relocation model and on Mach-O; the
    /// same reference to a plain data global still lowers to a symbol
    /// reference.
    #[test]
    fn body_symbol_addr_naming_a_thread_local_is_refused_by_name() {
        let global = |name: &str, defined: bool, tls: bool| trust_ir::Global {
            name: name.to_string(),
            ty: Ty::I64,
            mutable: true,
            initializer: defined.then_some(Constant::Int(7)),
            linkage: Linkage::External,
            tls: tls.then_some(trust_ir::TlsModel::GeneralDynamic),
            align: None,
            section: None,
            visibility: Visibility::Default,
            retained: false,
        };
        let module_naming = |symbol: &str, addend: i64| {
            let mut module = TrustIrModule::new("tls_symbol_addr");
            module.globals = vec![
                global("tls_def", true, true),
                global("tls_imp", false, true),
                global("plain", true, false),
            ];
            let returns_ptr = module
                .add_func_type(FuncTy {
                    params: vec![],
                    returns: vec![Ty::Ptr],
                    abi: None,
                    is_vararg: false,
                })
                .expect("Module::add_func_type: test fixture");
            let mut function =
                TrustIrFunction::new(FuncId::new(0), "addr", returns_ptr, BlockId::new(0));
            function.linkage = Linkage::External;
            function.blocks = vec![TrustIrBlock {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    InstrNode::new(Inst::Const {
                        ty: Ty::Ptr,
                        value: Constant::SymbolAddr {
                            symbol: symbol.to_string(),
                            addend,
                        },
                    })
                    .with_result(ValueId::new(0)),
                    InstrNode::new(Inst::Return {
                        values: vec![ValueId::new(0)],
                    }),
                ],
            }];
            module
                .try_add_function(function)
                .expect("Module::try_add_function: test fixture");
            module
        };
        let translate = |module: &TrustIrModule, access: ObjectAccessModel| {
            translate_module_for_arch_with_access_model_and_stats_with_license(
                module,
                GuardCarrierArch::AArch64,
                access,
                &permit_unlicensed(),
                WeakUndefinedReferencePolicy::AdmitDeclarations,
            )
        };
        let access_models = [
            ObjectAccessModel::elf(RelocationModel::Static),
            ObjectAccessModel::elf(RelocationModel::Pie),
            ObjectAccessModel::elf(RelocationModel::Pic),
            ObjectAccessModel::macho_dyld(),
        ];
        for access in access_models {
            for (symbol, addend) in [("tls_def", 0), ("tls_def", 8), ("tls_imp", 0)] {
                let error = match translate(&module_naming(symbol, addend), access) {
                    Ok(_) => panic!("{access:?}: SymbolAddr naming `{symbol}` was lowered"),
                    Err(error) => error.to_string(),
                };
                assert!(
                    error.contains("[TCG-TLS-SYMBOL-ADDR]")
                        && error.contains(&format!("thread-local `{symbol}`"))
                        && error.contains(&format!("addend {addend}"))
                        && error.contains("fail-closed"),
                    "{access:?} `{symbol}`+{addend}: {error}"
                );
            }
            let (functions, _) = translate(&module_naming("plain", 8), access)
                .unwrap_or_else(|error| panic!("{access:?}: plain data refused: {error}"));
            let entry = &functions[0].0.blocks[&functions[0].0.entry_block];
            assert!(
                entry.instructions.iter().any(|inst| matches!(
                    &inst.opcode,
                    Opcode::GlobalRef { name } | Opcode::ExternRef { name } if name == "plain"
                )),
                "{access:?}: {:?}",
                entry.instructions
            );
        }
    }

    use trust_ir::{
        Block as TrustIrBlockDef, BlockId, CallingConv, Constant, EnumDef, EnumId, EnumVariant,
        FatPtrKind, FieldDef, FuncId, FuncTy, FuncTyId, Function as TrustIrFunc, Linkage, Module,
        SourceSpan, StructDef as TrustIrStructDef, StructId, Ty, TyId, ValueId,
    };

    /// Helper: create a TrustIrFunc from the old test-style inline FuncTy.
    ///
    /// Old tests constructed functions with `ty: FuncTy { ... }` directly, but
    /// the new trust_ir uses `ty: FuncTyId`. This helper registers the FuncTy in a
    /// module and returns the function with the correct FuncTyId.
    fn make_func(
        id: FuncId,
        name: &str,
        func_ty: FuncTy,
        entry: BlockId,
        blocks: Vec<TrustIrBlockDef>,
        proofs: Vec<ProofAnnotation>,
    ) -> (TrustIrFunc, Module) {
        let mut module = Module::new("test");
        let ft_id = module
            .add_func_type(func_ty)
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(id, name, ft_id, entry);
        func.blocks = blocks;
        func.proofs = proofs;
        module
            .try_add_function(func.clone())
            .expect("Module::try_add_function: test fixture");
        (func, module)
    }

    /// Helper: wraps translate_function with a module containing just the function's FuncTy.
    fn translate_func_test(
        func: &TrustIrFunc,
        module: &Module,
    ) -> Result<(Function, ProofContext), AdapterError> {
        crate::translate_function_with_license(func, module, &permit_unlicensed())
    }

    #[test]
    fn optional_static_call_state_stays_pointer_sized_when_unused() {
        assert_eq!(
            std::mem::size_of::<Option<Box<StaticCallFunctionState<'static>>>>(),
            std::mem::size_of::<usize>(),
        );
        assert_eq!(
            std::mem::size_of::<Option<Rc<RefCell<StaticCallDevirtualizationStats>>>>(),
            std::mem::size_of::<usize>(),
        );
    }

    #[test]
    fn atomic_rmw_min_max_ops_map_to_dedicated_lir_ops() {
        // Signed/unsigned min/max atomic RMW have a dedicated, fully-lowered LIR
        // mapping (AArch64 LDSMAXAL/LDSMINAL/LDUMAXAL/LDUMINAL + LSE/x86 CAS
        // loop). They must map to their corresponding LIR op — NOT fail closed
        // and NOT collapse to Add — matching the conformance contract.
        for (op, expected) in [
            (TrustIrAtomicRmwOp::Max, AtomicRmwOp::Max),
            (TrustIrAtomicRmwOp::Min, AtomicRmwOp::Min),
            (TrustIrAtomicRmwOp::UMax, AtomicRmwOp::UMax),
            (TrustIrAtomicRmwOp::UMin, AtomicRmwOp::UMin),
        ] {
            let mapped = translate_atomic_rmw_op(&op)
                .unwrap_or_else(|err| panic!("AtomicRMW {op:?} must map to a LIR op, got {err:?}"));
            assert_eq!(mapped, expected, "AtomicRMW {op:?} mapped to wrong LIR op");
        }
    }

    #[test]
    fn extract_source_debug_info_collects_aggregate_and_enum_types() {
        let mut module = Module::new("debug_types");
        module.add_struct(TrustIrStructDef {
            id: StructId::new(0),
            name: "Pair".to_string(),
            fields: vec![
                FieldDef {
                    name: "left".to_string(),
                    ty: Ty::I32,
                    offset: Some(0),
                },
                FieldDef {
                    name: "right".to_string(),
                    ty: Ty::U32,
                    offset: Some(4),
                },
            ],
            size: Some(8),
            align: Some(4),
            repr: Default::default(),
            origin: None,
        });
        module.add_enum(EnumDef {
            id: EnumId::new(0),
            name: "Color".to_string(),
            variants: vec![
                EnumVariant {
                    name: "Red".to_string(),
                    fields: vec![],
                    field_names: Vec::new(),
                },
                EnumVariant {
                    name: "Green".to_string(),
                    fields: vec![],
                    field_names: Vec::new(),
                },
            ],
            discriminants: Vec::new(),
            repr: None,
            layout: None,
            origin: None,
        });
        let func_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let func = TrustIrFunc::new(FuncId::new(0), "debug_types", func_ty, BlockId::new(0));

        let info = extract_source_debug_info(&func, &module);

        assert_eq!(info.struct_types.len(), 1);
        assert_eq!(info.struct_types[0].name, "Pair");
        assert_eq!(info.struct_types[0].byte_size, 8);
        assert_eq!(info.struct_types[0].members.len(), 2);
        assert_eq!(info.struct_types[0].members[0].offset, 0);
        assert_eq!(info.struct_types[0].members[1].offset, 4);
        assert_eq!(
            info.struct_types[0].members[1].ty,
            trust_cg_ir::function::DebugBaseType::U32
        );

        assert_eq!(info.enum_types.len(), 1);
        assert_eq!(info.enum_types[0].name, "Color");
        assert_eq!(
            info.enum_types[0].underlying_type,
            trust_cg_ir::function::DebugBaseType::U32
        );
        assert_eq!(info.enum_types[0].enumerators[0].value, 0);
        assert_eq!(info.enum_types[0].enumerators[1].name, "Green");
    }

    /// Helper: build a Module from a TrustIrFunc by inferring FuncTy from block params.
    /// This replaces the old pattern of `translate_function(&func, &[])`.
    fn make_module_for_func(func: &TrustIrFunc) -> Module {
        // Infer param types from entry block params
        let params: Vec<Ty> = func
            .blocks
            .first()
            .map(|b| b.params.iter().map(|(_, ty)| ty.clone()).collect())
            .unwrap_or_default();

        // Build a value -> trust_ir type map from every block parameter and
        // every instruction result so that `returns` reflects the ACTUAL type
        // of each returned value (not a crude "first param type" guess). This
        // keeps the synthesized function signature consistent with the body so
        // the adapter's return-signature validation accepts well-typed fixtures.
        let mut value_tys: HashMap<ValueId, Ty> = HashMap::new();
        for block in &func.blocks {
            for (vid, ty) in &block.params {
                value_tys.insert(*vid, ty.clone());
            }
            for node in &block.body {
                for (idx, result) in node.results.iter().enumerate() {
                    if let Some(ty) = trust_ir_result_type_for_test(&node.inst, idx) {
                        value_tys.insert(*result, ty);
                    }
                }
            }
        }

        // Infer return types from the first Return instruction by resolving the
        // declared type of each returned value.
        let mut returns = Vec::new();
        'outer: for block in &func.blocks {
            for node in &block.body {
                if let Inst::Return { values } = &node.inst {
                    for value in values {
                        if let Some(ty) = value_tys.get(value) {
                            returns.push(ty.clone());
                        }
                    }
                    break 'outer;
                }
            }
        }

        let mut module = Module::new("test");
        module
            .add_func_type(FuncTy {
                params,
                returns,
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        module
            .try_add_function(func.clone())
            .expect("Module::try_add_function: test fixture");
        module
    }

    /// Resolve the trust_ir result type of an instruction result for the test
    /// module synthesizer. Mirrors the adapter's own `trust_ir_result_type` for
    /// the scalar/control instructions used by the adapter unit-test fixtures.
    fn trust_ir_result_type_for_test(inst: &Inst, result_index: usize) -> Option<Ty> {
        match inst {
            Inst::BinOp { ty, .. }
            | Inst::UnOp { ty, .. }
            | Inst::Cast { dst_ty: ty, .. }
            | Inst::Load { ty, .. }
            | Inst::AtomicLoad { ty, .. }
            | Inst::AtomicRMW { ty, .. }
            | Inst::Const { ty, .. }
            | Inst::Copy { ty, .. }
            | Inst::Select { ty, .. } => Some(ty.clone()),
            Inst::ICmp { ty, .. } | Inst::FCmp { ty, .. } => Some(ty.comparison_result_ty()),
            Inst::Overflow { ty, .. } => match result_index {
                0 => Some(ty.clone()),
                1 => Some(Ty::Bool),
                _ => None,
            },
            Inst::Alloca { .. }
            | Inst::GEP { .. }
            | Inst::NullPtr
            | Inst::Borrow { .. }
            | Inst::BorrowMut { .. } => Some(Ty::Ptr),
            _ => None,
        }
    }

    /// Build a minimal trust_ir module: fn add(a: i32, b: i32) -> i32 { a + b }
    fn build_add_module() -> Module {
        let mut module = Module::new("test");
        let ft = module
            .add_func_type(FuncTy {
                params: vec![Ty::I32, Ty::I32],
                returns: vec![Ty::I32],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(FuncId::new(0), "add", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![
                (ValueId::new(0), Ty::I32), // param a
                (ValueId::new(1), Ty::I32), // param b
            ],
            body: vec![
                InstrNode {
                    inst: Inst::BinOp {
                        op: BinOp::Add,
                        ty: Ty::I32,
                        lhs: ValueId::new(0),
                        rhs: ValueId::new(1),
                    },
                    results: vec![ValueId::new(2)],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
                InstrNode {
                    inst: Inst::Return {
                        values: vec![ValueId::new(2)],
                    },
                    results: vec![],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
            ],
        }];
        module
            .try_add_function(func)
            .expect("Module::try_add_function: test fixture");
        module
    }

    #[test]
    fn test_translate_type_scalars() {
        assert_eq!(translate_type(&Ty::Bool).unwrap(), Type::B1);
        assert_eq!(translate_type(&Ty::I8).unwrap(), Type::I8);
        assert_eq!(translate_type(&Ty::I16).unwrap(), Type::I16);
        assert_eq!(translate_type(&Ty::I32).unwrap(), Type::I32);
        assert_eq!(translate_type(&Ty::I64).unwrap(), Type::I64);
        assert_eq!(translate_type(&Ty::I128).unwrap(), Type::I128);
        assert_eq!(translate_type(&Ty::I32).unwrap(), Type::I32);
        assert_eq!(translate_type(&Ty::I64).unwrap(), Type::I64);
        assert_eq!(translate_type(&Ty::F32).unwrap(), Type::F32);
        assert_eq!(translate_type(&Ty::F64).unwrap(), Type::F64);
    }

    #[test]
    fn test_translate_type_contracted_vector_shapes() {
        assert_eq!(
            translate_type(&Ty::Vector(Box::new(Ty::I32), 4)).unwrap(),
            Type::V128
        );
        assert_eq!(
            translate_type(&Ty::Vector(Box::new(Ty::I64), 2)).unwrap(),
            Type::V128
        );
        assert_eq!(
            translate_type(&Ty::Vector(Box::new(Ty::I8), 16)).unwrap(),
            Type::V128
        );
        assert_eq!(
            translate_type(&Ty::Vector(Box::new(Ty::I16), 8)).unwrap(),
            Type::V128
        );
        assert_eq!(
            translate_type(&Ty::Vector(Box::new(Ty::Bool), 4)).unwrap(),
            Type::V128
        );
        assert_eq!(
            translate_type(&Ty::Vector(Box::new(Ty::Bool), 2)).unwrap(),
            Type::V128
        );

        let err = translate_type(&Ty::Vector(Box::new(Ty::I32), 1)).unwrap_err();
        assert!(matches!(
            err,
            AdapterError::UnsupportedType(msg) if msg.contains("only contracted 64-bit and 128-bit")
        ));

        let err = translate_type(&Ty::Vector(Box::new(Ty::Unit), 4)).unwrap_err();
        assert!(matches!(
            err,
            AdapterError::UnsupportedType(msg) if msg.contains("fixed bit width")
        ));
    }

    #[test]
    fn test_translate_type_unsupported_128_bit_vector_shapes_fail_closed() {
        for ty in [
            Ty::Vector(Box::new(Ty::Vector(Box::new(Ty::I32), 2)), 2),
            Ty::Vector(Box::new(Ty::Ptr), 2),
        ] {
            // FAIL-CLOSED is the invariant under test: an unsupported 128-bit
            // vector shape must be rejected as UnsupportedType. The exact
            // diagnostic depends on trust-ir's Ty::bit_width — a lane type with no
            // fixed bit width (e.g. Ptr, whose bit_width is None in the current
            // pinned trust-ir) reports "does not have a fixed bit width" while a
            // contracted-shape mismatch reports "unsupported vector shape". Assert
            // the fail-closed CATEGORY, not a brittle message substring that breaks
            // on a trust-ir bit_width change.
            let err = translate_type(&ty).unwrap_err();
            assert!(
                matches!(err, AdapterError::UnsupportedType(_)),
                "unsupported vector shape must fail closed as UnsupportedType for {ty:?}: {err:?}"
            );
        }
    }

