    #[test]
    fn test_translate_refinement_rejects_failed_consumption_before_erasure() {
        let mut module = Module::new("invalid_refinement_consumption");
        let base = module
            .add_type(Ty::I32)
            .expect("Module::add_type: test fixture");
        let nonzero = module
            .intern_pred(trust_ir::Pred::NonZero)
            .expect("Module::intern_pred: test fixture")
            .expect("NonZero is canonical");
        let refined = Ty::Refine(base, nonzero);
        let func_ty = module
            .add_func_type(FuncTy {
                // The caller promises only plain i32 (Top), but the entry binding
                // tries to assume NonZero.
                params: vec![Ty::I32],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(
            FuncId::new(0),
            "invalid_consumption",
            func_ty,
            BlockId::new(0),
        );
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), refined)],
            body: vec![InstrNode {
                inst: Inst::Return { values: vec![] },
                results: vec![],
                proofs: vec![],
                span: None,
                proof_context: None,
                scope: None,
            }],
        }];
        module
            .try_add_function(func)
            .expect("Module::try_add_function: test fixture");

        let err = permit_translate_module(&module).unwrap_err();
        assert!(matches!(
            err,
            AdapterError::InvalidRefinement(msg) if msg.contains("does not imply")
        ));
    }

