    /// An in-i64-range i128 constant must still use the compact single-immediate
    /// `Opcode::Iconst { ty: I128 }` path (the high half is the sign extension).
    #[test]
    fn test_translate_in_range_i128_const_keeps_single_iconst() {
        let func = const_func("small_i128", Ty::I128, 7);
        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        match &entry.instructions[0].opcode {
            Opcode::Iconst { ty, imm } => {
                assert_eq!(*ty, Type::I128);
                assert_eq!(*imm, 7);
            }
            other => panic!("expected single Iconst, got {:?}", other),
        }
    }

