    #[test]
    fn test_translate_const_fndef_is_global_ref() {
        let (mut func, mut module) = make_func(
            FuncId::new(0),
            "fndef_const",
            FuncTy {
                params: vec![],
                returns: vec![Ty::Func(FuncTyId::new(0))],
                abi: None,
                is_vararg: false,
            },
            BlockId::new(0),
            vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    InstrNode {
                        inst: Inst::Const {
                            ty: Ty::Func(FuncTyId::new(0)),
                            value: Constant::FnDef(FuncId::new(99)),
                        },
                        results: vec![ValueId::new(0)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(0)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            vec![],
        );

        // The referenced function must be REGISTERED for the FnDef constant to
        // lower: an unregistered FuncId fails closed (no relocation backing).
        // Register FuncId(99) so the FnDef resolves to a real defined symbol.
        let target_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut target = TrustIrFunc::new(FuncId::new(99), "target_fn", target_ty, BlockId::new(0));
        target.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![],
            body: vec![InstrNode {
                inst: Inst::Return { values: vec![] },
                results: vec![],
                proofs: vec![],
                span: None,
                proof_context: None,
                scope: None,
            }],
        }];
        module
            .try_add_function(target)
            .expect("Module::try_add_function: test fixture");

        // Retain the original malformed signature as a named public refusal:
        // the item names target_ty, not this caller's returning-item signature.
        let err = translate_func_test(&func, &module).unwrap_err();
        assert!(
            matches!(err, AdapterError::TrustIrAdmissionRefused { ref error }
            if error.contains("fndef_const")
                && error.contains(&format!("expected functy.{} for func.99", target_ty.index()))
                && error.contains(&format!("got functy.{}", func.ty.index())))
        );
        let item_ty = Ty::Func(target_ty);
        module.func_types[func.ty.as_usize()].returns = vec![item_ty.clone()];
        let Inst::Const { ty, .. } = &mut func.blocks[0].body[0].inst else {
            panic!("FnDef fixture must begin with its item constant")
        };
        *ty = item_ty;
        *module
            .functions
            .iter_mut()
            .find(|candidate| candidate.id == func.id)
            .expect("the module must own the repaired caller") = func.clone();

        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];
        match &entry.instructions[0].opcode {
            Opcode::GlobalRef { name } => assert_eq!(name, "target_fn"),
            other => panic!("expected GlobalRef, got {:?}", other),
        }
    }

