    #[test]
    fn test_translate_cast_zext_bool_to_i8() {
        // `zext i1 to i8` (Bool -> I8): the byte-model widens Bool to 8 bits, so
        // the shape guard must special-case a Bool source (machine `B1 -> I8` IS a
        // genuine widening) rather than reject it as a same-width no-op. Verifies
        // the guard admits it AND the translation emits a real `Uextend B1 -> I8`.
        let func = TrustIrFunc {
            section: None,
            visibility: Default::default(),
            retained: false,
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            body_gate: None,
            display_path: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "zext_bool".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::Bool)],
                body: vec![
                    InstrNode {
                        inst: Inst::Cast {
                            op: CastOp::ZExt,
                            src_ty: Ty::Bool,
                            dst_ty: Ty::I8,
                            operand: ValueId::new(0),
                        },
                        results: vec![ValueId::new(1)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(1)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        match &entry.instructions[0].opcode {
            Opcode::Uextend { from_ty, to_ty } => {
                assert_eq!(*from_ty, Type::B1);
                assert_eq!(*to_ty, Type::I8);
            }
            other => panic!("expected Uextend B1->I8, got {:?}", other),
        }
    }

