    // ---------------------------------------------------------------------
    // DivNonZero PRODUCER (constant-divisor guard elision) unit tests.
    //
    // The producer (`div_nonzero_const_annotate_module`) attaches
    // `ProofAnnotation::DivNonZero` to a div/rem node whose divisor is a
    // proven-nonzero compile-time integer literal, so the eliminable
    // `GuardDivZero` carrier replaces the real div-by-zero trap. Below:
    //   * a POSITIVE case per op (const nonzero -> annotated + guard elided),
    //   * REFUTATION cases (non-constant / zero / truncates-to-zero -> NOT
    //     annotated, guard kept — the fail-safe holds),
    //   * the signed `-1` edge (annotated for the div-ZERO guard; the SEPARATE
    //     INT_MIN/-1 overflow guard is untouched by this pass).
    // ---------------------------------------------------------------------

    /// Build a single-block function: `cN = const(k : ty); r = op(param0, cN)`
    /// returning `r`. `k` is the LITERAL divisor. No proofs are pre-attached, so
    /// the producer alone decides whether to annotate.
    fn div_by_const_func(op: BinOp, ty: Ty, k: i128) -> TrustIrFunc {
        let param0 = ValueId::new(0);
        let cval = ValueId::new(1);
        let res = ValueId::new(2);
        TrustIrFunc {
            section: None,
            visibility: Default::default(),
            retained: false,
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            body_gate: None,
            display_path: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "div_by_const".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(param0, ty.clone())],
                body: vec![
                    InstrNode {
                        inst: Inst::Const {
                            ty: ty.clone(),
                            value: Constant::Int(k),
                        },
                        results: vec![cval],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::BinOp {
                            op,
                            ty,
                            lhs: param0,
                            rhs: cval,
                        },
                        results: vec![res],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return { values: vec![res] },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        }
    }

    #[test]
    fn strict_adapter_rejects_implicit_div_nonzero_annotation() {
        let func = div_by_const_func(BinOp::SDiv, Ty::I64, 7);
        let module = make_module_for_func(&func);

        let error = crate::translate_module_strict_for_arch_with_tls_and_validation_with_license(
            &module,
            GuardCarrierArch::AArch64,
            TlsDialect::MachOTlv,
            &permit_unlicensed(),
        )
        .expect_err("strict lowering must not annotate a constant divisor behind the caller");

        assert!(matches!(
            error,
            AdapterError::PreLirTransformForbidden {
                transform: PreLirTransform::DivNonZeroConstAnnotation,
                ref function,
            } if function == "div_by_const"
        ));
        assert!(
            module.functions[0].blocks[0].body[1].proofs.is_empty(),
            "rejection must leave the caller-owned TrustIR unchanged"
        );
    }

    #[test]
    fn strict_adapter_accepts_explicit_div_nonzero_annotation() {
        let mut func = div_by_const_func(BinOp::SDiv, Ty::I64, 7);
        func.blocks[0].body[1]
            .proofs
            .push(ProofAnnotation::DivNonZero);
        let module = make_module_for_func(&func);

        let (functions, validation) =
            crate::translate_module_strict_for_arch_with_tls_and_validation_with_license(
                &module,
                GuardCarrierArch::AArch64,
                TlsDialect::MachOTlv,
                &permit_unlicensed(),
            )
            .expect("an explicit frontend/legalizer annotation is visible input, not a rewrite");
        validation
            .replay_exact_module_calls(&functions)
            .expect("strict result must replay against its exact source module");
        assert_eq!(functions.len(), 1);
    }

