    #[test]
    fn test_translate_inbounds_array_extract_prepends_exact_bounds_guard() {
        let mut module = Module::new("test");
        let elem_ty = module
            .add_type(Ty::I64)
            .expect("Module::add_type: test fixture");
        let array_ty = Ty::Array(elem_ty, 8);
        let ft = module
            .add_func_type(FuncTy {
                params: vec![array_ty.clone(), Ty::I64],
                returns: vec![Ty::I64],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(FuncId::new(0), "proven_extract", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), array_ty), (ValueId::new(1), Ty::I64)],
            body: vec![
                InstrNode {
                    inst: Inst::ExtractElement {
                        ty: Ty::I64,
                        array: ValueId::new(0),
                        index: ValueId::new(1),
                    },
                    results: vec![ValueId::new(2)],
                    proofs: vec![ProofAnnotation::InBounds],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
                InstrNode {
                    inst: Inst::Return {
                        values: vec![ValueId::new(2)],
                    },
                    results: vec![],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
            ],
        }];
        module
            .try_add_function(func.clone())
            .expect("Module::try_add_function: test fixture");

        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        // No ProofRef on the node => the adapter SYNTHESIZES a Discharged obligation from InBounds.
        let synth = ProofContext::SYNTHESIZED_OBLIGATION_BASE;
        assert_eq!(
            entry.instructions[0].opcode,
            Opcode::GuardBoundsCheck {
                bound: 8,
                obligation: Some(synth)
            }
        );
        assert_eq!(entry.instructions[0].args, vec![Value(0), Value(1)]);
        assert_eq!(proof_ctx.synthesized_discharged, vec![synth]);
        assert!(
            proof_ctx
                .value_proofs
                .get(&Value(1))
                .is_some_and(|proofs| proofs.iter().any(|proof| {
                    matches!(
                        proof,
                        Proof::ExactInBounds {
                            base: Value(0),
                            index: Value(1),
                            bound: 8
                        }
                    )
                }))
        );
    }

