    #[test]
    fn test_translate_inbounds_large_bound_records_drop_diagnostic() {
        let mut module = Module::new("test");
        // A one-byte element, so the array's natural EXTENT stays inside the
        // u32 LIR carrier and the type is constructible; the subject is the
        // BOUND, not the element width. See `inbounds_bound_for_arch`.
        let elem_ty = module
            .add_type(Ty::U8)
            .expect("Module::add_type: test fixture");
        // A bound ABOVE the AArch64 carrier cap (i32::MAX) — the default arch used
        // by `translate_func_test` — still fails closed with a drop diagnostic
        // (the MOVZ/MOVK companion covers up to i32::MAX, not beyond).
        let array_ty = Ty::Array(elem_ty, i32::MAX as u64 + 1);
        let ft = module
            .add_func_type(FuncTy {
                params: vec![array_ty.clone(), Ty::I64],
                returns: vec![Ty::U8],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(FuncId::new(0), "large_bound_extract", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), array_ty), (ValueId::new(1), Ty::I64)],
            body: vec![InstrNode {
                inst: Inst::ExtractElement {
                    ty: Ty::U8,
                    array: ValueId::new(0),
                    index: ValueId::new(1),
                },
                results: vec![ValueId::new(2)],
                proofs: vec![ProofAnnotation::InBounds],
                span: None,
                proof_context: None,
                scope: None,
            }],
        }];
        module
            .try_add_function(func.clone())
            .expect("Module::try_add_function: test fixture");

        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        assert!(
            entry
                .instructions
                .iter()
                .all(|inst| !matches!(inst.opcode, Opcode::GuardBoundsCheck { .. }))
        );
        assert!(proof_ctx.value_proofs.values().all(|proofs| {
            proofs
                .iter()
                .all(|proof| !matches!(proof, Proof::ExactInBounds { .. }))
        }));
        assert_eq!(proof_ctx.diagnostics().len(), 1);
        assert_eq!(proof_ctx.diagnostics()[0].fact, "InBounds");
        assert_eq!(
            proof_ctx.diagnostics()[0].payload.as_deref(),
            Some("bound=2147483648")
        );
        assert_eq!(
            proof_ctx.diagnostics()[0].code,
            ProofDropCode::Unrepresentable
        );
        assert!(
            proof_ctx.diagnostics()[0]
                .reason
                .contains("CMP immediate carrier range")
        );
    }

    // -----------------------------------------------------------------------
    // Sentinel S5 hardening: arch-aware exact-bound carrier cap.
    // -----------------------------------------------------------------------

    /// Build a single-function module doing `array[index]` on `Array(I64, bound)`
    /// with an `InBounds` annotation (no ProofRef), translate it for `arch`, and
    /// return the entry block's first opcode's bound (if it emitted a
    /// `GuardBoundsCheck`) plus the diagnostics count.
    fn inbounds_bound_for_arch(bound: u64, arch: GuardCarrierArch) -> (Option<u64>, usize) {
        let mut module = Module::new("arch_bound");
        // A ONE-BYTE element, deliberately. The subject here is the guard
        // carrier's ceiling on the BOUND — the array's length — and a wider
        // element would put the array's natural EXTENT past the u32 LIR
        // carrier, where `translate_type_*` refuses the type outright and the
        // guard logic under test is never reached. With `u8` the whole bound
        // range up to `u32::MAX` stays constructible, so the caps below are
        // still exercised at their exact boundaries.
        let elem_ty = module
            .add_type(Ty::U8)
            .expect("Module::add_type: test fixture");
        let array_ty = Ty::Array(elem_ty, bound);
        let ft = module
            .add_func_type(FuncTy {
                params: vec![array_ty.clone(), Ty::I64],
                returns: vec![Ty::U8],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(FuncId::new(0), "arch_bound_extract", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), array_ty), (ValueId::new(1), Ty::I64)],
            body: vec![
                InstrNode {
                    inst: Inst::ExtractElement {
                        ty: Ty::U8,
                        array: ValueId::new(0),
                        index: ValueId::new(1),
                    },
                    results: vec![ValueId::new(2)],
                    proofs: vec![ProofAnnotation::InBounds],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
                InstrNode {
                    inst: Inst::Return {
                        values: vec![ValueId::new(2)],
                    },
                    results: vec![],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
            ],
        }];
        module
            .try_add_function(func.clone())
            .expect("Module::try_add_function: test fixture");

        let results = permit_translate_module_for_arch(&module, arch).unwrap();
        let (lir_func, proof_ctx) = &results[0];
        let entry = &lir_func.blocks[&lir_func.entry_block];
        let emitted = entry
            .instructions
            .iter()
            .find_map(|inst| match inst.opcode {
                Opcode::GuardBoundsCheck { bound, .. } => Some(bound),
                _ => None,
            });
        (emitted, proof_ctx.diagnostics().len())
    }

    #[test]
    fn arch_cap_aarch64_carries_bound_above_imm12_via_movz_movk() {
        // AArch64 now carries a bound above the 12-bit CMP immediate: the late
        // expander (`expand_trap_bounds_check_exact`) materializes it with
        // MOVZ/MOVK + CMP reg,reg. So 0x1000 (> imm12) is carried, not dropped.
        let (emitted, diags) = inbounds_bound_for_arch(0x1000, GuardCarrierArch::AArch64);
        assert_eq!(emitted, Some(0x1000), "AArch64 carries a bound above imm12");
        assert_eq!(diags, 0);
        // A 12-bit bound is still carried (single CMP #imm12).
        let (emitted_ok, diags_ok) = inbounds_bound_for_arch(0x0fff, GuardCarrierArch::AArch64);
        assert_eq!(emitted_ok, Some(0x0fff));
        assert_eq!(diags_ok, 0);
        // Exactly at the cap (i32::MAX) is carried; above it fails closed.
        let (at_cap, d_at) = inbounds_bound_for_arch(i32::MAX as u64, GuardCarrierArch::AArch64);
        assert_eq!(at_cap, Some(i32::MAX as u64));
        assert_eq!(d_at, 0);
        let (above, d_above) =
            inbounds_bound_for_arch(i32::MAX as u64 + 1, GuardCarrierArch::AArch64);
        assert_eq!(above, None, "AArch64 fails closed above i32::MAX");
        assert_eq!(d_above, 1);
    }

    #[test]
    fn arch_cap_x86_carries_bound_above_aarch64_limit() {
        // x86 expands via MOV r64,imm64 + CMP, so it carries bounds AArch64 cannot.
        // (The LIR array-length type ceiling is u32::MAX, so an array bound never
        // exceeds that; x86's wider i64 cap is a superset and never the binding
        // constraint — see `guard_carrier_arch_max_bounds_are_ordered`.)
        let (emitted, diags) = inbounds_bound_for_arch(0x1000, GuardCarrierArch::X86_64);
        assert_eq!(emitted, Some(0x1000), "x86 must carry a bound above imm12");
        assert_eq!(diags, 0, "no fail-closed diagnostic on x86 for this bound");
        // A large (but constructible, < u32::MAX) bound is still carried on x86.
        let big = 0x0100_0000; // 16M
        let (emitted_big, diags_big) = inbounds_bound_for_arch(big, GuardCarrierArch::X86_64);
        assert_eq!(emitted_big, Some(big));
        assert_eq!(diags_big, 0);
    }

    #[test]
    fn arch_cap_riscv_carries_up_to_32_bits() {
        // RISC-V LUI+ADDI reconstructs any 32-bit value, so it carries a bound
        // AArch64 cannot, and its cap (u32::MAX) exactly matches the LIR
        // array-length type ceiling — i.e. it covers every constructible array.
        let (emitted, diags) = inbounds_bound_for_arch(0x1000, GuardCarrierArch::Riscv64);
        assert_eq!(
            emitted,
            Some(0x1000),
            "RISC-V must carry a bound above imm12"
        );
        assert_eq!(diags, 0);

        // u32::MAX is exactly the largest array length the type system permits
        // for a one-byte element — a wider element hits the u32 EXTENT carrier
        // first — and exactly the RISC-V cap, so it is carried (not failed
        // closed).
        let at_cap = u32::MAX as u64;
        let (emitted_cap, diags_cap) = inbounds_bound_for_arch(at_cap, GuardCarrierArch::Riscv64);
        assert_eq!(emitted_cap, Some(at_cap), "RISC-V carries exactly u32::MAX");
        assert_eq!(diags_cap, 0);
    }

    #[test]
    fn guard_carrier_arch_max_bounds_are_ordered() {
        assert_eq!(GuardCarrierArch::AArch64.max_exact_bound(), i32::MAX as u64);
        assert_eq!(GuardCarrierArch::Riscv64.max_exact_bound(), u32::MAX as u64);
        assert_eq!(GuardCarrierArch::X86_64.max_exact_bound(), i64::MAX as u64);
        // The default (used by the arch-neutral entry points) is the most
        // restrictive, so legacy callers never widen behaviour.
        assert_eq!(GuardCarrierArch::default(), GuardCarrierArch::AArch64);
    }

    // -----------------------------------------------------------------------
    // Sentinel S5 hardening: synthesized-obligation-id range defensive guard.
    // -----------------------------------------------------------------------

    #[test]
    fn synthesized_ids_stay_in_reserved_high_range() {
        let mut ctx = ProofContext::default();
        let a = ctx.synthesize_discharged_obligation().unwrap();
        let b = ctx.synthesize_discharged_obligation().unwrap();
        assert_eq!(a, ProofContext::SYNTHESIZED_OBLIGATION_BASE);
        assert_eq!(b, ProofContext::SYNTHESIZED_OBLIGATION_BASE + 1);
        assert!(
            (ProofContext::SYNTHESIZED_OBLIGATION_BASE..ProofContext::SYNTHESIZED_OBLIGATION_MAX)
                .contains(&a)
        );
        assert!(
            (ProofContext::SYNTHESIZED_OBLIGATION_BASE..ProofContext::SYNTHESIZED_OBLIGATION_MAX)
                .contains(&b)
        );
        assert_eq!(ctx.synthesized_discharged, vec![a, b]);
    }

    #[test]
    fn synthesized_id_exhaustion_fails_closed_without_wrapping() {
        // Park the counter one below the ceiling: the next id is the last valid one
        // (MAX is the reserved "exhausted" sentinel and is never handed out), and
        // the call after that returns None WITHOUT wrapping into the low range.
        let mut ctx = ProofContext {
            next_synthesized_obligation: ProofContext::SYNTHESIZED_OBLIGATION_MAX - 1,
            ..ProofContext::default()
        };

        let last = ctx.synthesize_discharged_obligation();
        assert_eq!(
            last,
            Some(ProofContext::SYNTHESIZED_OBLIGATION_MAX - 1),
            "the last valid id below the ceiling is still handed out"
        );

        // Exhausted from here on: fail closed, no wrap, no duplicate, no low-range id.
        for _ in 0..4 {
            let exhausted = ctx.synthesize_discharged_obligation();
            assert_eq!(
                exhausted, None,
                "exhausted range must fail closed (carrier left unbound -> kernel keeps guard)"
            );
        }
        // The exhausted sentinel (u64::MAX) was never recorded as a real id, and no
        // id ever dropped below the reserved base.
        assert!(ctx.synthesized_discharged.iter().all(|&id| {
            (ProofContext::SYNTHESIZED_OBLIGATION_BASE..ProofContext::SYNTHESIZED_OBLIGATION_MAX)
                .contains(&id)
        }));
    }

    #[test]
    fn test_translate_bounded_output_does_not_emit_exact_bounds_guard() {
        let mut module = Module::new("test");
        let elem_ty = module
            .add_type(Ty::I64)
            .expect("Module::add_type: test fixture");
        let array_ty = Ty::Array(elem_ty, 8);
        let ft = module
            .add_func_type(FuncTy {
                params: vec![array_ty.clone(), Ty::I64],
                returns: vec![Ty::I64],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = TrustIrFunc::new(FuncId::new(0), "range_extract", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), array_ty), (ValueId::new(1), Ty::I64)],
            body: vec![InstrNode {
                inst: Inst::ExtractElement {
                    ty: Ty::I64,
                    array: ValueId::new(0),
                    index: ValueId::new(1),
                },
                results: vec![ValueId::new(2)],
                proofs: vec![ProofAnnotation::BoundedOutput { lo: 0.0, hi: 7.0 }],
                span: None,
                proof_context: None,
                scope: None,
            }],
        }];
        module
            .try_add_function(func.clone())
            .expect("Module::try_add_function: test fixture");

        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        assert!(
            entry
                .instructions
                .iter()
                .all(|inst| !matches!(inst.opcode, Opcode::GuardBoundsCheck { .. }))
        );
        assert!(proof_ctx.value_proofs.values().all(|proofs| {
            proofs
                .iter()
                .all(|proof| !matches!(proof, Proof::ExactInBounds { .. }))
        }));
    }

