    #[test]
    fn trust_ir_narrow_i8_i16_select_rejects_noncanonical_masks() {
        let cases = [
            (
                "v16_arbitrary_logical",
                Ty::Vector(Box::new(Ty::I8), 16),
                Ty::Vector(Box::new(Ty::Bool), 16),
                None,
                "must be produced by a <16 x i8> ICmp",
            ),
            (
                "v8_arbitrary_logical",
                Ty::Vector(Box::new(Ty::I16), 8),
                Ty::Vector(Box::new(Ty::Bool), 8),
                None,
                "must be produced by a <8 x i16> ICmp",
            ),
            (
                "v16_physical_mask",
                Ty::Vector(Box::new(Ty::I8), 16),
                Ty::Vector(Box::new(Ty::I8), 16),
                None,
                "requires canonical logical <16 x bool> condition",
            ),
            (
                "v8_physical_mask",
                Ty::Vector(Box::new(Ty::I16), 8),
                Ty::Vector(Box::new(Ty::I16), 8),
                None,
                "requires canonical logical <8 x bool> condition",
            ),
            (
                "v16_mismatched_mask_lanes",
                Ty::Vector(Box::new(Ty::I8), 16),
                Ty::Vector(Box::new(Ty::Bool), 8),
                None,
                "requires canonical logical <16 x bool> condition",
            ),
            (
                "v8_mismatched_mask_lanes",
                Ty::Vector(Box::new(Ty::I16), 8),
                Ty::Vector(Box::new(Ty::Bool), 16),
                None,
                "requires canonical logical <8 x bool> condition",
            ),
            (
                "v16_noncanonical_const",
                Ty::Vector(Box::new(Ty::I8), 16),
                Ty::Vector(Box::new(Ty::Bool), 16),
                Some(Constant::Vector(
                    (0..16)
                        .map(|lane| {
                            if lane == 5 {
                                Constant::Int(2)
                            } else {
                                Constant::Bool(lane % 2 == 0)
                            }
                        })
                        .collect(),
                )),
                "canonical logical bool mask constant lanes",
            ),
            (
                "v8_noncanonical_const",
                Ty::Vector(Box::new(Ty::I16), 8),
                Ty::Vector(Box::new(Ty::Bool), 8),
                Some(Constant::Vector(
                    (0..8)
                        .map(|lane| {
                            if lane == 3 {
                                Constant::Int(-1)
                            } else {
                                Constant::Bool(lane % 2 == 1)
                            }
                        })
                        .collect(),
                )),
                "canonical logical bool mask constant lanes",
            ),
            (
                "v16_int_zero_one_const",
                Ty::Vector(Box::new(Ty::I8), 16),
                Ty::Vector(Box::new(Ty::Bool), 16),
                Some(Constant::Vector(
                    (0..16)
                        .map(|lane| Constant::Int(if lane % 2 == 0 { 1 } else { 0 }))
                        .collect(),
                )),
                "canonical logical bool mask constant lanes",
            ),
            (
                "v8_int_zero_one_const",
                Ty::Vector(Box::new(Ty::I16), 8),
                Ty::Vector(Box::new(Ty::Bool), 8),
                Some(Constant::Vector(
                    (0..8)
                        .map(|lane| Constant::Int(if lane < 4 { 1 } else { 0 }))
                        .collect(),
                )),
                "canonical logical bool mask constant lanes",
            ),
        ];

        for (name, payload_ty, cond_ty, const_mask, expected_message) in cases {
            let is_constant_mask = const_mask.is_some();
            if let Some(Constant::Vector(lanes)) = &const_mask
                && lanes
                    .iter()
                    .any(|lane| matches!(lane, Constant::Int(2 | -1)))
            {
                // Keep the old local 2/-1 lane backstops covered separately.
                // Integer 0/1 is also invalid at source Bool, but this legacy
                // component still accepts it below the public typed gate.
                let mut adapter = TrustIrAdapter::new(&[], HashMap::new());
                let err = adapter
                    .translate_bool_mask_vector_const_into(&cond_ty, lanes, Value(0))
                    .unwrap_err();
                assert!(
                    matches!(err, AdapterError::UnsupportedInstruction(ref message)
                    if message.contains(expected_message))
                );
            }
            let mut body = Vec::new();
            if let Some(value) = const_mask {
                body.push(InstrNode {
                    inst: Inst::Const {
                        ty: cond_ty.clone(),
                        value,
                    },
                    results: vec![ValueId::new(0)],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                });
            }
            body.push(InstrNode {
                inst: Inst::Select {
                    ty: payload_ty.clone(),
                    cond: ValueId::new(0),
                    then_val: ValueId::new(1),
                    else_val: ValueId::new(2),
                },
                results: vec![ValueId::new(3)],
                proofs: vec![],
                span: None,
                proof_context: None,
                scope: None,
            });

            let params = if body.len() == 1 {
                vec![
                    (ValueId::new(0), cond_ty),
                    (ValueId::new(1), payload_ty.clone()),
                    (ValueId::new(2), payload_ty.clone()),
                ]
            } else {
                vec![
                    (ValueId::new(1), payload_ty.clone()),
                    (ValueId::new(2), payload_ty.clone()),
                ]
            };

            let func = TrustIrFunc {
                section: None,
                visibility: Default::default(),
                retained: false,
                summary: None,
                producer: None,
                value_names: None,
                scopes: None,
                source_provenance: None,
                body_gate: None,
                display_path: None,
                attrs: Default::default(),
                id: FuncId::new(0),
                name: name.to_string(),
                ty: FuncTyId::new(0),
                entry: BlockId::new(0),
                blocks: vec![TrustIrBlockDef {
                    id: BlockId::new(0),
                    params,
                    body,
                }],
                proofs: vec![],
                calling_conv: CallingConv::default(),
                linkage: Linkage::default(),
            };

            let module = make_module_for_func(&func);
            let err = match translate_func_test(&func, &module) {
                Ok(_) => panic!("{name} select mask must fail closed"),
                Err(err) => err,
            };
            if is_constant_mask {
                assert!(
                    matches!(err, AdapterError::TrustIrAdmissionRefused { ref error }
                    if error.contains(name)
                        && error.contains("const type mismatch: expected bool, got int")),
                    "unexpected typed constant diagnostic for {name}: {err:?}"
                );
            } else {
                assert!(
                    matches!(err, AdapterError::UnsupportedInstruction(ref message)
                        if message.contains(expected_message)),
                    "unexpected narrow select diagnostic for {name}: {err:?}"
                );
            }
        }
    }

