    #[test]
    fn test_translate_type_dialect_and_nested_pointers_fail_closed() {
        let dialect = Ty::Dialect(Box::new(trust_ir::DialectTy::new("tla", "Value", 1)));
        for ty in [
            dialect.clone(),
            Ty::Ref(Box::new(dialect.clone())),
            Ty::RefMut(Box::new(dialect.clone())),
            Ty::PtrConst(Box::new(dialect.clone())),
            Ty::PtrMut(Box::new(Ty::Tuple(vec![Ty::I64, dialect.clone()]))),
            Ty::Tuple(vec![Ty::I64, dialect]),
        ] {
            assert!(
                matches!(translate_type(&ty), Err(AdapterError::UnsupportedType(message)) if message.contains("dialect type")),
                "unexpected translation for {ty:?}"
            );
        }
    }

