    #[test]
    fn test_combined_function_and_instruction_proofs() {
        // Function has a raw Pure claim; the instruction has translatable
        // Associative + Commutative proofs.
        let func = TrustIrFunc {
            section: None,
            visibility: Default::default(),
            retained: false,
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            body_gate: None,
            display_path: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "combined_proofs".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I32), (ValueId::new(1), Ty::I32)],
                body: vec![
                    InstrNode {
                        inst: Inst::BinOp {
                            op: BinOp::Add,
                            ty: Ty::I32,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![
                            ProofAnnotation::Associative,
                            ProofAnnotation::Commutative,
                            ProofAnnotation::NoOverflow,
                        ],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![ProofAnnotation::Pure],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (_, proof_ctx) = translate_func_test(&func, &module).unwrap();

        // Function-level raw Pure is withheld from optimizer metadata.
        assert!(!proof_ctx.is_function_pure());
        assert!(!proof_ctx.is_function_associative());

        // Instruction-level: Associative, Commutative, NoOverflow on result value
        let val = proof_ctx
            .value_proofs
            .keys()
            .find(|v| proof_ctx.has_associative(v))
            .expect("Should have value with Associative");
        assert!(proof_ctx.has_associative(val));
        assert!(proof_ctx.has_commutative(val));
        assert!(proof_ctx.has_no_overflow(val));
        assert!(!proof_ctx.has_pure(val)); // Raw Pure is not optimizer authority.
    }

