    #[test]
    fn structural_purity_fixpoint_ignores_forged_raw_pure_claims() {
        // Piece 1 of the pure-call hoist: recover purity of user functions the
        // rustc frontend never annotates. Validates the optimistic-start
        // call-graph fixpoint on the four canonical shapes.
        use trust_ir::Ty;
        let node = |inst: Inst| InstrNode::new(inst);
        let ret = || node(Inst::Return { values: vec![] });
        let block = |body: Vec<InstrNode>| TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![],
            body,
        };
        let mut module = Module::new("purity_fixpoint_test");
        let ft = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        // F0: pure leaf (only Return).
        let mut f0 = TrustIrFunc::new(FuncId::new(0), "pure_leaf", ft, BlockId::new(0));
        f0.blocks = vec![block(vec![ret()])];
        // F1: self-recursive but otherwise pure (ICmp + CondBr shape + self Call).
        let mut f1 = TrustIrFunc::new(FuncId::new(1), "pure_rec", ft, BlockId::new(0));
        f1.blocks = vec![block(vec![
            node(Inst::ICmp {
                op: trust_ir::ICmpOp::Eq,
                ty: Ty::I64,
                lhs: ValueId::new(0),
                rhs: ValueId::new(0),
            }),
            node(Inst::Call {
                callee: FuncId::new(1),
                args: vec![],
            }),
            ret(),
        ])];
        // F2: impure — writes memory.
        let mut f2 = TrustIrFunc::new(FuncId::new(2), "impure_store", ft, BlockId::new(0));
        f2.blocks = vec![block(vec![
            node(Inst::Store {
                ty: Ty::I64,
                ptr: ValueId::new(0),
                value: ValueId::new(1),
                volatile: false,
                align: None,
            }),
            ret(),
        ])];
        f2.proofs = vec![ProofAnnotation::Pure];
        // F3: transitively impure — calls the impure F2.
        let mut f3 = TrustIrFunc::new(FuncId::new(3), "caller_of_impure", ft, BlockId::new(0));
        f3.blocks = vec![block(vec![
            node(Inst::Call {
                callee: FuncId::new(2),
                args: vec![],
            }),
            ret(),
        ])];
        f3.proofs = vec![ProofAnnotation::Pure];
        // F4: calls a bodyless external declaration — impure.
        let mut f4 = TrustIrFunc::new(FuncId::new(4), "caller_of_extern", ft, BlockId::new(0));
        f4.blocks = vec![block(vec![
            node(Inst::Call {
                callee: FuncId::new(5),
                args: vec![],
            }),
            ret(),
        ])];
        f4.proofs = vec![ProofAnnotation::Pure];
        // F5: the bodyless external itself is also forged Pure. Bodyless
        // declarations never enter structural purity analysis.
        let mut f5 = TrustIrFunc::new(FuncId::new(5), "external", ft, BlockId::new(0));
        f5.proofs = vec![ProofAnnotation::Pure];
        for f in [f0, f1, f2, f3, f4, f5] {
            module
                .try_add_function(f)
                .expect("Module::try_add_function: test fixture");
        }

        let pure = compute_structural_pure_func_ids(&module, |_| false);
        assert!(pure.contains(&FuncId::new(0)), "pure_leaf must be pure");
        assert!(
            pure.contains(&FuncId::new(1)),
            "self-recursive pure_rec must stay pure (optimistic fixpoint)"
        );
        assert!(
            !pure.contains(&FuncId::new(2)),
            "impure_store must be demoted (Store)"
        );
        assert!(
            !pure.contains(&FuncId::new(3)),
            "caller_of_impure must be transitively demoted"
        );
        assert!(
            !pure.contains(&FuncId::new(4)),
            "caller of bodyless external callee must be demoted"
        );
        assert!(
            !pure.contains(&FuncId::new(5)),
            "bodyless external declaration must not be structurally pure"
        );

        // The production collector must not union producer-asserted Pure back
        // into the structural result. These three forged/stale claims cover a
        // direct store, a transitive call, and an unknown/external call.
        let authorized = collect_pure_func_ids(&module);
        assert!(
            !authorized.contains(&FuncId::new(2)),
            "raw Pure must not authorize a function that stores"
        );
        assert!(
            !authorized.contains(&FuncId::new(3)),
            "raw Pure must not authorize a transitively impure function"
        );
        assert!(
            !authorized.contains(&FuncId::new(4)),
            "raw Pure must not authorize a function calling an external"
        );
        assert!(
            !authorized.contains(&FuncId::new(5)),
            "raw Pure must not authorize a bodyless external declaration"
        );
    }

    #[test]
    fn an_available_externally_body_grants_its_callers_no_purity() {
        // A bodied `AvailableExternally` function is a codegen declaration:
        // every call reaches the definition emitted elsewhere, so a pure-looking
        // body (an inline-only template) must not make its calls hoistable or
        // removable — nor demote-proof a caller — without the disclosed
        // one-definition premise the inliner rests on.
        let node = |inst: Inst| InstrNode::new(inst);
        let block = |body: Vec<InstrNode>| TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![],
            body,
        };
        let mut module = Module::new("available_externally_purity");
        let ft = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        // F0: a pure-looking body (only Return), available externally.
        let mut fast_path = TrustIrFunc::new(FuncId::new(0), "helper", ft, BlockId::new(0));
        fast_path.blocks = vec![block(vec![node(Inst::Return { values: vec![] })])];
        fast_path.linkage = Linkage::AvailableExternally;
        // F1: a module definition that only calls it.
        let mut caller = TrustIrFunc::new(FuncId::new(1), "caller", ft, BlockId::new(0));
        caller.blocks = vec![block(vec![
            node(Inst::Call {
                callee: FuncId::new(0),
                args: vec![],
            }),
            node(Inst::Return { values: vec![] }),
        ])];
        // F2: the same body as a module definition, the control.
        let mut defined = TrustIrFunc::new(FuncId::new(2), "defined", ft, BlockId::new(0));
        defined.blocks = vec![block(vec![node(Inst::Return { values: vec![] })])];
        for f in [fast_path, caller, defined] {
            module
                .try_add_function(f)
                .expect("Module::try_add_function: test fixture");
        }

        for pure in [
            compute_structural_pure_func_ids(&module, |_| false),
            collect_pure_func_ids(&module),
        ] {
            assert!(
                !pure.contains(&FuncId::new(0)),
                "an AvailableExternally body is not the body its callers reach"
            );
            assert!(
                !pure.contains(&FuncId::new(1)),
                "a call to an AvailableExternally function is a call to an unknown definition"
            );
            assert!(
                pure.contains(&FuncId::new(2)),
                "the same body as a module definition stays pure"
            );
        }
    }

    /// A body another object may replace grants no purity: interposable
    /// `Weak`/`LinkOnce` definitions always, and every default-visibility,
    /// non-local definition under the shared-object relocation model. Their
    /// ODR twins, local definitions and (under `pic`) strong or ODR hidden
    /// and protected definitions keep their authority, and a caller of a
    /// replaceable definition is demoted with it.
    #[test]
    fn structural_purity_excludes_replaceable_definitions() {
        let ret = || InstrNode::new(Inst::Return { values: vec![] });
        let mut module = Module::new("purity_replaceable_test");
        let ft = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let body = |calls: Option<u32>| TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![],
            body: calls
                .map(|callee| {
                    InstrNode::new(Inst::Call {
                        callee: FuncId::new(callee),
                        args: vec![],
                    })
                })
                .into_iter()
                .chain([ret()])
                .collect(),
        };
        let linkages = [
            Linkage::External,
            Linkage::Weak,
            Linkage::LinkOnce,
            Linkage::WeakOdr,
            Linkage::LinkOnceOdr,
            Linkage::Internal,
        ];
        for (index, linkage) in linkages.into_iter().enumerate() {
            let mut func = TrustIrFunc::new(
                FuncId::new(index as u32),
                format!("leaf_{index}"),
                ft,
                BlockId::new(0),
            );
            func.linkage = linkage;
            func.blocks = vec![body(None)];
            module
                .try_add_function(func)
                .expect("Module::try_add_function: test fixture");
        }
        // An internal caller of the interposable `Weak` leaf.
        let mut caller = TrustIrFunc::new(FuncId::new(6), "caller", ft, BlockId::new(0));
        caller.linkage = Linkage::Internal;
        caller.blocks = vec![body(Some(1))];
        module
            .try_add_function(caller)
            .expect("Module::try_add_function: test fixture");
        // v45 visibility rows (ids 7-10) and internal callers of the hidden
        // leaf (11) and of the default `External` leaf (12, the negative).
        for (index, (linkage, visibility)) in [
            (Linkage::External, Visibility::Hidden),
            (Linkage::External, Visibility::Protected),
            (Linkage::Weak, Visibility::Hidden),
            (Linkage::WeakOdr, Visibility::Protected),
        ]
        .into_iter()
        .enumerate()
        {
            let id = 7 + index as u32;
            let mut func =
                TrustIrFunc::new(FuncId::new(id), format!("leaf_{id}"), ft, BlockId::new(0));
            func.linkage = linkage;
            func.visibility = visibility;
            func.blocks = vec![body(None)];
            module
                .try_add_function(func)
                .expect("Module::try_add_function: test fixture");
        }
        for (id, callee) in [(11u32, 7u32), (12, 0)] {
            let mut caller =
                TrustIrFunc::new(FuncId::new(id), format!("caller_{id}"), ft, BlockId::new(0));
            caller.linkage = Linkage::Internal;
            caller.blocks = vec![body(Some(callee))];
            module
                .try_add_function(caller)
                .expect("Module::try_add_function: test fixture");
        }

        let executable = collect_pure_func_ids(&module);
        let expected: HashSet<FuncId> = [0, 3, 4, 5, 7, 8, 10, 11, 12]
            .into_iter()
            .map(FuncId::new)
            .collect();
        assert_eq!(
            executable, expected,
            "only Weak/LinkOnce bodies are replaceable"
        );

        let shared = collect_pure_func_ids_for_access_model(
            &module,
            ObjectAccessModel::elf(RelocationModel::Pic),
        );
        let expected: HashSet<FuncId> = [5, 7, 8, 10, 11].into_iter().map(FuncId::new).collect();
        assert_eq!(
            shared, expected,
            "under pic the Internal leaf and the strong or ODR hidden/protected leaves (and the \
             hidden leaf's caller) keep their authority; the default leaves and the caller of \
             the default External leaf do not"
        );
    }

    /// Structural purity inference reads exactly the two shared predicates,
    /// on every relocation model, definition linkage and visibility: a body
    /// is withheld iff [`definition_is_link_replaceable`] or
    /// [`RelocationModel::definition_is_preemptible`] names it. The compiler's
    /// module inliner reads the same two (see its
    /// `inliner_interposable_function_names`), so a copy that drifts in
    /// either consumer fails this row or the inliner's.
    #[test]
    fn structural_purity_reads_the_shared_replacement_predicates() {
        let linkages = [
            Linkage::External,
            Linkage::Internal,
            Linkage::Private,
            Linkage::Weak,
            Linkage::LinkOnce,
            Linkage::WeakOdr,
            Linkage::LinkOnceOdr,
        ];
        // The static-link predicate's own table, stated independently.
        for linkage in linkages
            .into_iter()
            .chain([Linkage::AvailableExternally, Linkage::ExternalWeak])
        {
            assert_eq!(
                definition_is_link_replaceable(linkage),
                matches!(linkage, Linkage::Weak | Linkage::LinkOnce),
                "{linkage:?}"
            );
            // And its one deliberate difference from trust-ir's proved
            // interposition table: `ExternalWeak`, a declaration-only linkage.
            assert_eq!(
                definition_is_link_replaceable(linkage),
                linkage.is_interposable() && linkage != Linkage::ExternalWeak,
                "{linkage:?}"
            );
        }
        let mut rows = 0;
        for model in RelocationModel::ALL {
            for linkage in linkages {
                for visibility in [
                    Visibility::Default,
                    Visibility::Hidden,
                    Visibility::Protected,
                ] {
                    if matches!(linkage, Linkage::Internal | Linkage::Private)
                        && visibility != Visibility::Default
                    {
                        continue;
                    }
                    let mut module = Module::new("purity_predicate");
                    let ft = module
                        .add_func_type(FuncTy {
                            params: vec![],
                            returns: vec![],
                            abi: None,
                            is_vararg: false,
                        })
                        .expect("Module::add_func_type: test fixture");
                    let mut leaf = TrustIrFunc::new(FuncId::new(0), "leaf", ft, BlockId::new(0));
                    leaf.linkage = linkage;
                    leaf.visibility = visibility;
                    leaf.blocks = vec![TrustIrBlockDef {
                        id: BlockId::new(0),
                        params: vec![],
                        body: vec![InstrNode::new(Inst::Return { values: vec![] })],
                    }];
                    module
                        .try_add_function(leaf)
                        .expect("Module::try_add_function: test fixture");
                    let replaceable = definition_is_link_replaceable(linkage)
                        || model.definition_is_preemptible(
                            DefinitionBinding::for_trust_ir_linkage(linkage),
                            visibility,
                        );
                    let pure = collect_pure_func_ids_for_access_model(
                        &module,
                        ObjectAccessModel::elf(model),
                    );
                    assert_eq!(
                        pure.contains(&FuncId::new(0)),
                        !replaceable,
                        "{model} {linkage:?} {visibility:?}"
                    );
                    rows += 1;
                }
            }
        }
        assert_eq!(rows, 51);
    }

    #[test]
    fn structural_purity_requires_a_body_for_every_declaration_linkage() {
        let node = |inst: Inst| InstrNode::new(inst);
        let ret = || node(Inst::Return { values: vec![] });
        let block = |body: Vec<InstrNode>| TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![],
            body,
        };
        let mut module = Module::new("bodyless_purity_candidates");
        let ft = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        // A structurally inspectable leaf and its caller remain positive.
        let mut pure_leaf = TrustIrFunc::new(FuncId::new(0), "pure_leaf", ft, BlockId::new(0));
        pure_leaf.blocks = vec![block(vec![ret()])];
        let mut pure_caller = TrustIrFunc::new(FuncId::new(1), "pure_caller", ft, BlockId::new(0));
        pure_caller.blocks = vec![block(vec![
            node(Inst::Call {
                callee: pure_leaf.id,
                args: vec![],
            }),
            ret(),
        ])];
        module
            .try_add_function(pure_leaf)
            .expect("Module::try_add_function: test fixture");
        module
            .try_add_function(pure_caller)
            .expect("Module::try_add_function: test fixture");

        // Exercise every current linkage and both declaration shapes: an opaque
        // external (no summary) plus contract declarations (summary present).
        // Raw Pure is deliberately forged on each declaration too.
        let declaration_cases = [
            (FuncId::new(2), "opaque_external", Linkage::External, false),
            (FuncId::new(3), "contract_external", Linkage::External, true),
            (FuncId::new(4), "contract_internal", Linkage::Internal, true),
            (FuncId::new(5), "contract_private", Linkage::Private, true),
            (FuncId::new(6), "contract_weak", Linkage::Weak, true),
            (FuncId::new(7), "contract_linkonce", Linkage::LinkOnce, true),
        ];
        let mut declaration_ids = Vec::new();
        for (id, name, linkage, with_summary) in declaration_cases {
            let mut declaration = TrustIrFunc::new(id, name, ft, BlockId::new(0));
            declaration.linkage = linkage;
            declaration.proofs = vec![ProofAnnotation::Pure];
            if with_summary {
                declaration.summary = Some(trust_ir::FunctionSummary::new());
            }
            assert!(!declaration.has_body(), "{name} must be a declaration");
            declaration_ids.push(id);
            module
                .try_add_function(declaration)
                .expect("Module::try_add_function: test fixture");
        }

        // Any call to any bodyless declaration must also demote the caller.
        let declaration_calls = declaration_ids.iter().copied().map(|callee| {
            node(Inst::Call {
                callee,
                args: vec![],
            })
        });
        let mut caller_body: Vec<InstrNode> = declaration_calls.collect();
        caller_body.push(ret());
        let declaration_caller_id = FuncId::new(8);
        let mut declaration_caller = TrustIrFunc::new(
            declaration_caller_id,
            "declaration_caller",
            ft,
            BlockId::new(0),
        );
        declaration_caller.blocks = vec![block(caller_body)];
        module
            .try_add_function(declaration_caller)
            .expect("Module::try_add_function: test fixture");

        let pure = collect_pure_func_ids(&module);
        assert!(pure.contains(&FuncId::new(0)), "pure leaf must remain pure");
        assert!(
            pure.contains(&FuncId::new(1)),
            "caller of a structurally pure bodied function must remain pure"
        );
        for declaration_id in declaration_ids {
            assert!(
                !pure.contains(&declaration_id),
                "bodyless declaration {declaration_id:?} must never be a purity candidate"
            );
        }
        assert!(
            !pure.contains(&declaration_caller_id),
            "a caller of bodyless declarations must be transitively impure"
        );
    }

